  /// profile or status changes.
  updated_at DateTime

  //----
  // RELATIONS
  //----
  todo_app_memberuser_sessions todo_app_memberuser_sessions[]
  todo_app_todos todo_app_todos[]

  @@unique([email])
  @@index([status, created_at])
