import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";

/**
 * Validate minimal guest user registration and token issuance.
 *
 * Business purpose:
 *
 * - Ensure that an anonymous visitor can create a guestUser concept via
 *   /auth/guestUser/join without providing any external_ref metadata.
 * - Confirm that the backend issues a valid ITodoAppGuestUser.IAuthorized payload
 *   with consistent token information and timestamps.
 * - Verify that repeated minimal joins yield distinct guest ids and independent
 *   token sets, ensuring proper UUID and token generation.
 *
 * Steps:
 *
 * 1. Perform a minimal join request with an empty body (no external_ref).
 * 2. Assert the response type with typia.assert and check key business rules
 *    around timestamps and token lifetimes.
 * 3. Perform a second minimal join request and confirm that ids and tokens do not
 *    collide with the first response.
 */
export async function test_api_guest_user_join_minimal_registration(
  connection: api.IConnection,
) {
  // 1. First minimal guest join with empty body
  const firstJoin = await api.functional.auth.guestUser.join(connection, {
    body: {},
  });
  typia.assert<ITodoAppGuestUser.IAuthorized>(firstJoin);

  // Validate convenience token mirrors when present
  TestValidator.equals(
    "accessToken mirrors token.access when present",
    firstJoin.accessToken ?? null,
    firstJoin.accessToken !== undefined ? firstJoin.token.access : null,
  );
  TestValidator.equals(
    "refreshToken mirrors token.refresh when present",
    firstJoin.refreshToken ?? null,
    firstJoin.refreshToken !== undefined ? firstJoin.token.refresh : null,
  );

  // external_ref should be undefined or null when not supplied
  TestValidator.predicate(
    "external_ref is undefined or null on minimal join",
    firstJoin.external_ref === undefined || firstJoin.external_ref === null,
  );

  // created_at and updated_at should be valid date-time strings and ordered logically
  const createdAtFirst = new Date(firstJoin.created_at);
  const updatedAtFirst = new Date(firstJoin.updated_at);
  TestValidator.predicate(
    "created_at is a valid date",
    !Number.isNaN(createdAtFirst.getTime()),
  );
  TestValidator.predicate(
    "updated_at is a valid date",
    !Number.isNaN(updatedAtFirst.getTime()),
  );
  TestValidator.predicate(
    "updated_at is not before created_at",
    updatedAtFirst.getTime() >= createdAtFirst.getTime(),
  );

  // Token lifetime checks
  const expiredAtFirst = new Date(firstJoin.token.expired_at);
  const refreshableUntilFirst = new Date(firstJoin.token.refreshable_until);
  const now = new Date();
  TestValidator.predicate(
    "expired_at is not in the past",
    expiredAtFirst.getTime() >= now.getTime(),
  );
  TestValidator.predicate(
    "refreshable_until is not before expired_at",
    refreshableUntilFirst.getTime() >= expiredAtFirst.getTime(),
  );

  // 2. Second minimal guest join
  const secondJoin = await api.functional.auth.guestUser.join(connection, {
    body: {},
  });
  typia.assert<ITodoAppGuestUser.IAuthorized>(secondJoin);

  // Ensure different guest ids
  TestValidator.notEquals(
    "second join yields a different guest id",
    firstJoin.id,
    secondJoin.id,
  );

  // Ensure different access tokens
  TestValidator.notEquals(
    "second join yields a different access token",
    firstJoin.token.access,
    secondJoin.token.access,
  );

  // Ensure different refresh tokens
  TestValidator.notEquals(
    "second join yields a different refresh token",
    firstJoin.token.refresh,
    secondJoin.token.refresh,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";

/**
 * Validate guest user join with external_ref correlation identifiers.
 *
 * Business purpose:
 *
 * - Ensure that POST /auth/guestUser/join correctly accepts a client-supplied
 *   external_ref, persists it for the created guest concept, and echoes it back
 *   in the ITodoAppGuestUser.IAuthorized response.
 * - Verify that token payloads and timestamps are coherent and that separate join
 *   calls yield distinct guest identities without cross-contamination.
 *
 * Scenario steps:
 *
 * 1. Generate a first opaque external_ref value (e.g., tracking-abc-123).
 * 2. Call api.functional.auth.guestUser.join with this external_ref and assert
 *    that:
 *
 *    - The response type matches ITodoAppGuestUser.IAuthorized.
 *    - Id is a non-empty UUID string.
 *    - External_ref in the response equals the supplied value when present.
 *    - Created_at and updated_at are valid date-time strings and updated_at is
 *         greater than or equal to created_at.
 *    - Token.access and token.refresh are non-empty strings.
 *    - Token.expired_at and token.refreshable_until are valid future dates.
 *    - Top-level accessToken and refreshToken, when present, mirror token.access and
 *         token.refresh.
 * 3. Generate a second, different external_ref value (e.g., experiment-xyz-456)
 *    and perform another join call.
 * 4. Repeat the above validations for the second guest.
 * 5. Cross-check that:
 *
 *    - The two guests have different id values.
 *    - When both responses carry non-null/defined external_ref, they reflect the
 *         respective input external_ref strings and differ from each other.
 */
export async function test_api_guest_user_join_with_external_reference(
  connection: api.IConnection,
) {
  // Prepare two distinct external reference identifiers to mimic different
  // tracking or A/B test keys coming from the client side.
  const externalRef1 = "tracking-abc-123";
  const externalRef2 = "experiment-xyz-456";

  // 1) First guest join with externalRef1
  const firstGuest = await api.functional.auth.guestUser.join(connection, {
    body: {
      external_ref: externalRef1,
    } satisfies ITodoAppGuestUser.IJoinRequest,
  });
  typia.assert(firstGuest);

  // Basic id and token integrity checks for the first guest
  TestValidator.predicate(
    "first guest id should be a non-empty string",
    firstGuest.id.length > 0,
  );
  TestValidator.predicate(
    "first guest token.access should be a non-empty string",
    firstGuest.token.access.length > 0,
  );
  TestValidator.predicate(
    "first guest token.refresh should be a non-empty string",
    firstGuest.token.refresh.length > 0,
  );

  // Timestamp consistency for the first guest
  const firstCreatedAt = new Date(firstGuest.created_at);
  const firstUpdatedAt = new Date(firstGuest.updated_at);
  TestValidator.predicate(
    "first guest updated_at should be greater than or equal to created_at",
    firstUpdatedAt.getTime() >= firstCreatedAt.getTime(),
  );

  const firstNow = Date.now();
  const firstExpiredAt = new Date(firstGuest.token.expired_at);
  const firstRefreshableUntil = new Date(firstGuest.token.refreshable_until);
  TestValidator.predicate(
    "first guest token.expired_at should be in the future",
    firstExpiredAt.getTime() > firstNow,
  );
  TestValidator.predicate(
    "first guest token.refreshable_until should be in the future",
    firstRefreshableUntil.getTime() > firstNow,
  );

  // external_ref echo and top-level token mirrors for the first guest
  if (
    firstGuest.external_ref !== null &&
    firstGuest.external_ref !== undefined
  ) {
    TestValidator.equals(
      "first guest external_ref should match the supplied value",
      firstGuest.external_ref,
      externalRef1,
    );
  }

  if (firstGuest.accessToken !== undefined) {
    TestValidator.equals(
      "first guest accessToken should mirror token.access",
      firstGuest.accessToken,
      firstGuest.token.access,
    );
  }
  if (firstGuest.refreshToken !== undefined) {
    TestValidator.equals(
      "first guest refreshToken should mirror token.refresh",
      firstGuest.refreshToken,
      firstGuest.token.refresh,
    );
  }

  // 2) Second guest join with externalRef2
  const secondGuest = await api.functional.auth.guestUser.join(connection, {
    body: {
      external_ref: externalRef2,
    } satisfies ITodoAppGuestUser.IJoinRequest,
  });
  typia.assert(secondGuest);

  // Basic id and token integrity checks for the second guest
  TestValidator.predicate(
    "second guest id should be a non-empty string",
    secondGuest.id.length > 0,
  );
  TestValidator.predicate(
    "second guest token.access should be a non-empty string",
    secondGuest.token.access.length > 0,
  );
  TestValidator.predicate(
    "second guest token.refresh should be a non-empty string",
    secondGuest.token.refresh.length > 0,
  );

  // Timestamp consistency for the second guest
  const secondCreatedAt = new Date(secondGuest.created_at);
  const secondUpdatedAt = new Date(secondGuest.updated_at);
  TestValidator.predicate(
    "second guest updated_at should be greater than or equal to created_at",
    secondUpdatedAt.getTime() >= secondCreatedAt.getTime(),
  );

  const secondNow = Date.now();
  const secondExpiredAt = new Date(secondGuest.token.expired_at);
  const secondRefreshableUntil = new Date(secondGuest.token.refreshable_until);
  TestValidator.predicate(
    "second guest token.expired_at should be in the future",
    secondExpiredAt.getTime() > secondNow,
  );
  TestValidator.predicate(
    "second guest token.refreshable_until should be in the future",
    secondRefreshableUntil.getTime() > secondNow,
  );

  if (
    secondGuest.external_ref !== null &&
    secondGuest.external_ref !== undefined
  ) {
    TestValidator.equals(
      "second guest external_ref should match the supplied value",
      secondGuest.external_ref,
      externalRef2,
    );
  }

  if (secondGuest.accessToken !== undefined) {
    TestValidator.equals(
      "second guest accessToken should mirror token.access",
      secondGuest.accessToken,
      secondGuest.token.access,
    );
  }
  if (secondGuest.refreshToken !== undefined) {
    TestValidator.equals(
      "second guest refreshToken should mirror token.refresh",
      secondGuest.refreshToken,
      secondGuest.token.refresh,
    );
  }

  // 3) Cross-guest consistency: ids and external_refs must not be mixed.
  TestValidator.notEquals(
    "guest ids must differ across separate join calls",
    firstGuest.id,
    secondGuest.id,
  );

  if (
    firstGuest.external_ref !== null &&
    firstGuest.external_ref !== undefined &&
    secondGuest.external_ref !== null &&
    secondGuest.external_ref !== undefined
  ) {
    TestValidator.notEquals(
      "external_ref values for different guests should differ",
      firstGuest.external_ref,
      secondGuest.external_ref,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";

/**
 * Validate guestUser join idempotency and abuse characteristics.
 *
 * Business goal:
 *
 * - Repeatedly call POST /auth/guestUser/join with the same external_ref and
 *   verify that:
 *
 *   - Each call succeeds and returns a structurally valid
 *       ITodoAppGuestUser.IAuthorized payload.
 *   - The external_ref echo in the response is consistent with the provided value
 *       when present.
 *   - Multiple calls issue distinct guest ids and token sets, i.e., the operation
 *       behaves as a non-idempotent "create" by external_ref.
 *   - No validation errors occur solely because the same external_ref is reused
 *       across calls.
 *
 * Test outline:
 *
 * 1. Define a stable external_ref string identifying a logical client/device.
 * 2. Call api.functional.auth.guestUser.join 5 times in a loop with the same
 *    external_ref in the body.
 * 3. For each response, assert type correctness and basic invariants.
 * 4. After the loop, compare responses cross-call to ensure ids and token values
 *    differ and that the external_ref echo is consistent.
 */
export async function test_api_guest_user_join_idempotency_and_abuse_potential(
  connection: api.IConnection,
) {
  // 1. Stable external_ref for all join calls
  const externalRef = "client-xyz-device-001";

  // 2. Execute multiple join calls sequentially with the same external_ref
  const iterations = 5;
  const outputs: ITodoAppGuestUser.IAuthorized[] = [];

  for (let i = 0; i < iterations; ++i) {
    const output = await api.functional.auth.guestUser.join(connection, {
      body: {
        external_ref: externalRef,
      } satisfies ITodoAppGuestUser.IJoinRequest,
    });
    typia.assert<ITodoAppGuestUser.IAuthorized>(output);
    outputs.push(output);
  }

  // 3. Per-response validation
  for (let i = 0; i < outputs.length; ++i) {
    const out = outputs[i];

    // Ensure created_at and updated_at are valid date-time strings via typia.assert (already done),
    // here we just do basic logical predicates if desired.
    TestValidator.predicate(
      `guest[${i}] id should be non-empty`,
      typeof out.id === "string" && out.id.length > 0,
    );

    // external_ref is optional string | null | undefined. If backend echoes it,
    // ensure match. If backend stores null/undefined instead, allow that but
    // ensure stability across calls.
    if (out.external_ref !== null && out.external_ref !== undefined) {
      TestValidator.equals(
        `guest[${i}] external_ref should equal request value when present`,
        out.external_ref,
        externalRef,
      );
    }

    // Top-level accessToken/refreshToken are optional, but token.access/refresh
    // must be present per IAuthorizationToken.
    TestValidator.predicate(
      `guest[${i}] token.access should be non-empty string`,
      typeof out.token.access === "string" && out.token.access.length > 0,
    );
    TestValidator.predicate(
      `guest[${i}] token.refresh should be non-empty string`,
      typeof out.token.refresh === "string" && out.token.refresh.length > 0,
    );
  }

  // 4. Cross-call uniqueness checks
  const ids = outputs.map((o) => o.id);
  const accessTokens = outputs.map((o) => o.token.access);
  const refreshTokens = outputs.map((o) => o.token.refresh);

  const uniqueIds = new Set(ids);
  const uniqueAccessTokens = new Set(accessTokens);
  const uniqueRefreshTokens = new Set(refreshTokens);

  TestValidator.equals(
    "all guest join calls should return the same count as outputs",
    outputs.length,
    iterations,
  );

  // Expectation: each join call creates a distinct guest id.
  TestValidator.equals(
    "guest ids should be unique across repeated joins",
    uniqueIds.size,
    ids.length,
  );

  // Token sets should also be unique; at minimum access tokens should differ.
  TestValidator.equals(
    "access tokens should be unique across repeated joins",
    uniqueAccessTokens.size,
    accessTokens.length,
  );

  TestValidator.equals(
    "refresh tokens should be unique across repeated joins",
    uniqueRefreshTokens.size,
    refreshTokens.length,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";

/**
 * Validate guestUser token refresh flow with a valid refresh token.
 *
 * Business context:
 *
 * - Guest users are anonymous visitors represented by a stable guest UUID in the
 *   todo_app_guestusers table.
 * - The /auth/guestUser/join endpoint creates this guest concept and issues
 *   initial access and refresh tokens encapsulated in
 *   ITodoAppGuestUser.IAuthorized.
 * - The /auth/guestUser/refresh endpoint should accept a previously issued
 *   refresh token and return a new ITodoAppGuestUser.IAuthorized while keeping
 *   the guest id stable and rotating token values.
 *
 * This test covers the happy-path refresh flow and a chained refresh.
 *
 * Steps:
 *
 * 1. Call POST /auth/guestUser/join with a minimal ITodoAppGuestUser.IJoinRequest
 *    (optionally providing an external_ref) to obtain an initial
 *    ITodoAppGuestUser.IAuthorized object.
 * 2. Validate the join response shape using typia.assert and basic invariants like
 *    non-empty token strings and well-formed timestamps.
 * 3. Extract the canonical refresh token from authorized.token.refresh and verify
 *    that the top-level refreshToken mirror matches it when present.
 * 4. Build an ITodoAppGuestUser.IRefreshRequest using that refresh token and
 *    include deterministic clientId and tokenFamily strings to simulate a
 *    concrete client/device.
 * 5. Call POST /auth/guestUser/refresh with the constructed body.
 * 6. Assert that:
 *
 *    - Response is a valid ITodoAppGuestUser.IAuthorized (typia.assert).
 *    - The id in the refresh response equals the id from the original join response,
 *         ensuring continuity of the guest concept.
 *    - External_ref and created_at are preserved, while updated_at is equal to or
 *         later than the original updated_at.
 *    - The embedded token.access and token.refresh strings differ from the previous
 *         values, demonstrating token rotation.
 *    - The top-level accessToken and refreshToken mirrors, when defined, match the
 *         nested token.access and token.refresh values.
 *    - The new token.expired_at and token.refreshable_until timestamps are not
 *         earlier than the previous ones (refresh should not shorten the
 *         window).
 * 7. Perform a second refresh call, using the latest refresh token from step 6, to
 *    confirm that chained refresh within the refreshable window continues to
 *    work and again rotates token values while keeping id stable.
 */
export async function test_api_guest_user_refresh_with_valid_token(
  connection: api.IConnection,
) {
  // 1. Join as a new guest user with optional external_ref
  const joinBody = {
    external_ref: RandomGenerator.alphaNumeric(16),
  } satisfies ITodoAppGuestUser.IJoinRequest;

  const joined: ITodoAppGuestUser.IAuthorized =
    await api.functional.auth.guestUser.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppGuestUser.IAuthorized>(joined);

  // Validate basic invariants of join result
  TestValidator.predicate(
    "joined guest id is non-empty UUID",
    () => typeof joined.id === "string" && joined.id.length > 0,
  );
  TestValidator.predicate(
    "joined guest token.access is non-empty",
    () =>
      typeof joined.token.access === "string" && joined.token.access.length > 0,
  );
  TestValidator.predicate(
    "joined guest token.refresh is non-empty",
    () =>
      typeof joined.token.refresh === "string" &&
      joined.token.refresh.length > 0,
  );

  // When top-level mirrors exist, they must match nested token values
  if (joined.accessToken !== undefined) {
    TestValidator.equals(
      "top-level accessToken mirrors token.access in join",
      joined.accessToken,
      joined.token.access,
    );
  }
  if (joined.refreshToken !== undefined) {
    TestValidator.equals(
      "top-level refreshToken mirrors token.refresh in join",
      joined.refreshToken,
      joined.token.refresh,
    );
  }

  // Keep original values for comparison
  const originalId = joined.id;
  const originalExternalRef = joined.external_ref ?? null;
  const originalCreatedAt = joined.created_at;
  const originalUpdatedAt = joined.updated_at;
  const originalToken: IAuthorizationToken = joined.token;

  // 2. Build refresh request using the canonical refresh token
  const clientId = `guest-client-${RandomGenerator.alphaNumeric(8)}`;
  const tokenFamily = `guest-family-${RandomGenerator.alphaNumeric(8)}`;

  const firstRefreshRequest = {
    refreshToken: originalToken.refresh,
    clientId,
    tokenFamily,
  } satisfies ITodoAppGuestUser.IRefreshRequest;

  const refreshed: ITodoAppGuestUser.IAuthorized =
    await api.functional.auth.guestUser.refresh(connection, {
      body: firstRefreshRequest,
    });
  typia.assert<ITodoAppGuestUser.IAuthorized>(refreshed);

  // 3. Validate invariants between original join and first refresh
  TestValidator.equals("refresh preserves guest id", refreshed.id, originalId);

  // external_ref may be nullable/undefined, but when present should match
  TestValidator.equals(
    "refresh preserves external_ref (including null/undefined semantics)",
    refreshed.external_ref ?? null,
    originalExternalRef,
  );

  // created_at should remain the same
  TestValidator.equals(
    "refresh preserves created_at timestamp",
    refreshed.created_at,
    originalCreatedAt,
  );

  // updated_at should be equal or later than original
  TestValidator.predicate(
    "refresh updated_at is not earlier than original",
    () =>
      new Date(refreshed.updated_at).getTime() >=
      new Date(originalUpdatedAt).getTime(),
  );

  // Token rotation: new access/refresh tokens should differ from originals
  TestValidator.notEquals(
    "access token is rotated on refresh",
    refreshed.token.access,
    originalToken.access,
  );
  TestValidator.notEquals(
    "refresh token is rotated on refresh",
    refreshed.token.refresh,
    originalToken.refresh,
  );

  // Top-level mirrors must match nested token values when defined
  if (refreshed.accessToken !== undefined) {
    TestValidator.equals(
      "top-level accessToken mirrors token.access after refresh",
      refreshed.accessToken,
      refreshed.token.access,
    );
  }
  if (refreshed.refreshToken !== undefined) {
    TestValidator.equals(
      "top-level refreshToken mirrors token.refresh after refresh",
      refreshed.refreshToken,
      refreshed.token.refresh,
    );
  }

  // Token lifetime window: refreshed tokens should not have earlier expiry
  TestValidator.predicate(
    "refreshed token.expired_at is not earlier than original",
    () =>
      new Date(refreshed.token.expired_at).getTime() >=
      new Date(originalToken.expired_at).getTime(),
  );
  TestValidator.predicate(
    "refreshed token.refreshable_until is not earlier than original",
    () =>
      new Date(refreshed.token.refreshable_until).getTime() >=
      new Date(originalToken.refreshable_until).getTime(),
  );

  // 4. Perform a second chained refresh using the latest refresh token
  const secondRefreshRequest = {
    refreshToken: refreshed.token.refresh,
    clientId,
    tokenFamily,
  } satisfies ITodoAppGuestUser.IRefreshRequest;

  const refreshedAgain: ITodoAppGuestUser.IAuthorized =
    await api.functional.auth.guestUser.refresh(connection, {
      body: secondRefreshRequest,
    });
  typia.assert<ITodoAppGuestUser.IAuthorized>(refreshedAgain);

  // Validate that id remains stable across chained refresh
  TestValidator.equals(
    "chained refresh preserves guest id",
    refreshedAgain.id,
    originalId,
  );

  // Validate that tokens rotate again
  TestValidator.notEquals(
    "access token rotates again on chained refresh",
    refreshedAgain.token.access,
    refreshed.token.access,
  );
  TestValidator.notEquals(
    "refresh token rotates again on chained refresh",
    refreshedAgain.token.refresh,
    refreshed.token.refresh,
  );

  // Ensure the newest expiry window is not earlier than previous refresh
  TestValidator.predicate(
    "chained refresh token.expired_at is not earlier than previous",
    () =>
      new Date(refreshedAgain.token.expired_at).getTime() >=
      new Date(refreshed.token.expired_at).getTime(),
  );
  TestValidator.predicate(
    "chained refresh token.refreshable_until is not earlier than previous",
    () =>
      new Date(refreshedAgain.token.refreshable_until).getTime() >=
      new Date(refreshed.token.refreshable_until).getTime(),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";

/**
 * Validate guestUser token refresh behavior with explicit client and token
 * family metadata.
 *
 * Business objective:
 *
 * - Ensure that the `/auth/guestUser/refresh` endpoint correctly accepts an
 *   `ITodoAppGuestUser.IRefreshRequest` containing optional `clientId` and
 *   `tokenFamily` values.
 * - Verify that refresh does not change the underlying guest identity (`id`),
 *   while issuing a fresh set of authorization tokens.
 * - Demonstrate that subsequent refreshes using the newly issued refresh token
 *   and the same clientId/tokenFamily continue to work and preserve identity.
 *
 * Scenario steps:
 *
 * 1. Create a guest concept via `/auth/guestUser/join` using
 *    `ITodoAppGuestUser.IJoinRequest` with an explicit `external_ref`.
 * 2. From the returned `ITodoAppGuestUser.IAuthorized`, capture:
 *
 *    - `id` (guest id)
 *    - `token` (IAuthorizationToken)
 *    - Top-level `accessToken` and `refreshToken` convenience mirrors.
 * 3. Build an `ITodoAppGuestUser.IRefreshRequest` payload that includes:
 *
 *    - `refreshToken`: taken from the join response (prefer top-level
 *         `refreshToken`, but fall back to `token.refresh` when needed).
 *    - `clientId`: a stable, realistic client identifier string (e.g., "web-spa-1").
 *    - `tokenFamily`: a logical family identifier string (e.g., "fam-guest-001").
 * 4. Call `/auth/guestUser/refresh` with this payload and validate:
 *
 *    - The response is a valid `ITodoAppGuestUser.IAuthorized` via `typia.assert`.
 *    - `id` matches the original guest id.
 *    - The returned `token` field is a valid `IAuthorizationToken` and
 *         access/refresh values are strings.
 *    - If present, `accessToken` equals `token.access`, and `refreshToken` equals
 *         `token.refresh`.
 *    - At least one of `token.access` or `token.refresh` differs from the original
 *         token set to reflect rotation.
 * 5. Perform a second refresh call using the newly issued `refreshToken` and the
 *    same `clientId`/`tokenFamily` and validate:
 *
 *    - The second response is `ITodoAppGuestUser.IAuthorized`.
 *    - `id` remains stable across all generations.
 *    - The latest token set differs from the previous token set to demonstrate
 *         ongoing rotation.
 * 6. Use `TestValidator` helpers only for business-focused assertions:
 *
 *    - `TestValidator.equals` for equality of guest id and mirror consistency.
 *    - `TestValidator.notEquals` to confirm token rotation.
 *    - `TestValidator.predicate` for boolean or structural conditions.
 */
export async function test_api_guest_user_refresh_with_explicit_client_and_family_context(
  connection: api.IConnection,
) {
  // 1. Join as a new guest user with an explicit external_ref.
  const joinRequestBody = {
    external_ref: `guest-corr-${RandomGenerator.alphaNumeric(8)}`,
  } satisfies ITodoAppGuestUser.IJoinRequest;

  const joined: ITodoAppGuestUser.IAuthorized =
    await api.functional.auth.guestUser.join(connection, {
      body: joinRequestBody,
    });
  typia.assert(joined);

  const originalGuestId = joined.id;
  const originalToken: IAuthorizationToken = joined.token;
  const originalAccessMirror: string | undefined = joined.accessToken;
  const originalRefreshMirror: string | undefined = joined.refreshToken;

  // Ensure mirrors (when present) match the canonical token fields.
  if (originalAccessMirror !== undefined) {
    TestValidator.equals(
      "initial accessToken mirror matches token.access",
      originalAccessMirror,
      originalToken.access,
    );
  }
  if (originalRefreshMirror !== undefined) {
    TestValidator.equals(
      "initial refreshToken mirror matches token.refresh",
      originalRefreshMirror,
      originalToken.refresh,
    );
  }

  // Determine the refresh token to use, preferring the top-level mirror.
  const firstRefreshTokenSource =
    originalRefreshMirror !== undefined
      ? originalRefreshMirror
      : originalToken.refresh;

  // 2. First refresh with explicit clientId and tokenFamily.
  const clientId = "web-spa-1";
  const tokenFamily = "fam-guest-001";

  const firstRefreshBody = {
    refreshToken: firstRefreshTokenSource,
    clientId,
    tokenFamily,
  } satisfies ITodoAppGuestUser.IRefreshRequest;

  const refreshed1: ITodoAppGuestUser.IAuthorized =
    await api.functional.auth.guestUser.refresh(connection, {
      body: firstRefreshBody,
    });
  typia.assert(refreshed1);

  // Validate identity stability.
  TestValidator.equals(
    "first refresh preserves guest id",
    refreshed1.id,
    originalGuestId,
  );

  const refreshedToken1: IAuthorizationToken = refreshed1.token;

  // Validate mirrors on the first refresh response.
  if (refreshed1.accessToken !== undefined) {
    TestValidator.equals(
      "first refresh accessToken mirror matches token.access",
      refreshed1.accessToken,
      refreshedToken1.access,
    );
  }
  if (refreshed1.refreshToken !== undefined) {
    TestValidator.equals(
      "first refresh refreshToken mirror matches token.refresh",
      refreshed1.refreshToken,
      refreshedToken1.refresh,
    );
  }

  // Ensure some rotation has occurred on token values.
  TestValidator.predicate(
    "first refresh should rotate access or refresh token",
    refreshedToken1.access !== originalToken.access ||
      refreshedToken1.refresh !== originalToken.refresh,
  );

  // 3. Second refresh using the newly issued refresh token and same context.
  const secondRefreshTokenSource =
    refreshed1.refreshToken !== undefined
      ? refreshed1.refreshToken
      : refreshedToken1.refresh;

  const secondRefreshBody = {
    refreshToken: secondRefreshTokenSource,
    clientId,
    tokenFamily,
  } satisfies ITodoAppGuestUser.IRefreshRequest;

  const refreshed2: ITodoAppGuestUser.IAuthorized =
    await api.functional.auth.guestUser.refresh(connection, {
      body: secondRefreshBody,
    });
  typia.assert(refreshed2);

  const refreshedToken2: IAuthorizationToken = refreshed2.token;

  // Identity must remain stable across all refreshes.
  TestValidator.equals(
    "second refresh preserves guest id",
    refreshed2.id,
    originalGuestId,
  );

  // Validate mirrors on the second refresh response.
  if (refreshed2.accessToken !== undefined) {
    TestValidator.equals(
      "second refresh accessToken mirror matches token.access",
      refreshed2.accessToken,
      refreshedToken2.access,
    );
  }
  if (refreshed2.refreshToken !== undefined) {
    TestValidator.equals(
      "second refresh refreshToken mirror matches token.refresh",
      refreshed2.refreshToken,
      refreshedToken2.refresh,
    );
  }

  // Ensure ongoing rotation between first and second refresh token sets.
  TestValidator.predicate(
    "second refresh should rotate access or refresh token again",
    refreshedToken2.access !== refreshedToken1.access ||
      refreshedToken2.refresh !== refreshedToken1.refresh,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";

/**
 * Verify guestUser refresh behavior with invalid or reused refresh tokens.
 *
 * Business goals:
 *
 * - Ensure /auth/guestUser/refresh succeeds for valid refresh tokens.
 * - Ensure /auth/guestUser/refresh fails for malformed, random, or reused refresh
 *   tokens.
 *
 * Steps:
 *
 * 1. Call /auth/guestUser/join to obtain an ITodoAppGuestUser.IAuthorized payload
 *    with a valid refresh token.
 * 2. Perform a baseline successful refresh using the issued refresh token and
 *    validate the returned ITodoAppGuestUser.IAuthorized response.
 * 3. Attempt to refresh with a clearly malformed token string ("not-a-jwt") and
 *    assert that the call fails.
 * 4. Attempt to refresh with a random long string token and assert that the call
 *    fails.
 * 5. Attempt to reuse the original refresh token again after it has already been
 *    used and assert that the call fails (replay attack scenario).
 */
export async function test_api_guest_user_refresh_with_invalid_or_reused_refresh_token(
  connection: api.IConnection,
) {
  // 1. Join as a guest user to obtain initial authorized context
  const joinBody = {
    external_ref: RandomGenerator.alphaNumeric(16),
  } satisfies ITodoAppGuestUser.IJoinRequest;

  const joined: ITodoAppGuestUser.IAuthorized =
    await api.functional.auth.guestUser.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppGuestUser.IAuthorized>(joined);
  typia.assert<IAuthorizationToken>(joined.token);

  const originalRefreshToken: string | undefined = joined.refreshToken;

  // 2. Baseline successful refresh using the real refresh token
  if (originalRefreshToken !== undefined) {
    const refreshRequest = {
      refreshToken: originalRefreshToken,
    } satisfies ITodoAppGuestUser.IRefreshRequest;

    const refreshed: ITodoAppGuestUser.IAuthorized =
      await api.functional.auth.guestUser.refresh(connection, {
        body: refreshRequest,
      });
    typia.assert<ITodoAppGuestUser.IAuthorized>(refreshed);
    typia.assert<IAuthorizationToken>(refreshed.token);
  }

  // 3. Variant A: malformed refresh token string
  const malformedRefreshBody = {
    refreshToken: "not-a-jwt",
  } satisfies ITodoAppGuestUser.IRefreshRequest;

  await TestValidator.error(
    "guestUser refresh with malformed token must fail",
    async () => {
      await api.functional.auth.guestUser.refresh(connection, {
        body: malformedRefreshBody,
      });
    },
  );

  // 4. Variant B: random, non-issued refresh token
  const randomToken: string = RandomGenerator.alphaNumeric(128);
  const randomRefreshBody = {
    refreshToken: randomToken,
  } satisfies ITodoAppGuestUser.IRefreshRequest;

  await TestValidator.error(
    "guestUser refresh with random non-issued token must fail",
    async () => {
      await api.functional.auth.guestUser.refresh(connection, {
        body: randomRefreshBody,
      });
    },
  );

  // 5. Variant C: replay original refresh token after successful use
  if (originalRefreshToken !== undefined) {
    const replayBody = {
      refreshToken: originalRefreshToken,
    } satisfies ITodoAppGuestUser.IRefreshRequest;

    await TestValidator.error(
      "guestUser refresh with reused (replayed) refresh token must fail",
      async () => {
        await api.functional.auth.guestUser.refresh(connection, {
          body: replayBody,
        });
      },
    );
  }
}

