import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";

/**
 * Validate that admin token refresh fails on an invalid/unauthorized context
 * and does not yield a new authorized session.
 *
 * Business intent (adapted to available APIs):
 *
 * - The backend should not issue new administrative JWT tokens when a refresh
 *   request is made without a valid authenticated or session context.
 * - A refresh attempt using an arbitrary opaque `refresh_token` value, when
 *   performed from a connection that does not carry any previously established
 *   session, must result in an HTTP error rather than a successful
 *   `ITodoAppAdminUser.IAuthorized` response.
 *
 * Concrete test steps:
 *
 * 1. Prepare a baseline connection that represents a normal admin client.
 * 2. Clone the baseline connection into an `unauthConn` that has an empty
 *    `headers` object, representing a client without any active admin session
 *    or Authorization header.
 * 3. Construct a syntactically valid `ITodoAppAdminUser.IRefresh` request body by
 *    generating a random non-empty `refresh_token` string.
 * 4. Call `api.functional.auth.adminUser.refresh` using `unauthConn` and the
 *    constructed body, and assert via `TestValidator.httpError` that the call
 *    fails with an HTTP error (indicating that refresh is not allowed in this
 *    context).
 * 5. Optionally repeat the failure attempt on `unauthConn` to ensure consistent
 *    behavior across multiple invalid refresh calls.
 */
export async function test_api_admin_user_token_refresh_failure_with_expired_or_invalid_session(
  connection: api.IConnection,
) {
  // 1. Prepare an unauthenticated clone connection with empty headers.
  const unauthConn: api.IConnection = {
    ...connection,
    headers: {},
  };

  // 2. Build a syntactically valid refresh body with an opaque token string.
  const refreshBody = {
    refresh_token: RandomGenerator.alphaNumeric(32),
  } satisfies ITodoAppAdminUser.IRefresh;

  // 3. Expect refresh to fail on unauthenticated connection.
  await TestValidator.httpError(
    "admin refresh must fail without valid session context",
    [400, 401, 403, 404, 422],
    async () => {
      // This call is expected to throw HttpError, not return normally.
      await api.functional.auth.adminUser.refresh(unauthConn, {
        body: refreshBody,
      });
    },
  );

  // 4. Repeat the invalid refresh attempt to verify consistent failure.
  await TestValidator.httpError(
    "repeated invalid admin refresh must continue to fail",
    [400, 401, 403, 404, 422],
    async () => {
      await api.functional.auth.adminUser.refresh(unauthConn, {
        body: refreshBody,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";

/**
 * Validate refresh-token behavior for todoApp admin users, focusing on
 * successful rotation for an acceptable admin/session and failure when the
 * token represents an unacceptable admin/session state.
 *
 * ## Business context
 *
 * The /auth/adminUser/refresh endpoint rotates administrative JWT tokens by
 * validating a session record in todo_app_adminuser_sessions and its owning
 * admin record in todo_app_adminusers. Even if a session is time-valid, refresh
 * must be denied when the owning admin’s status is no longer acceptable (for
 * example, suspended or disabled) since the session was first created.
 *
 * Due to the limited SDK surface provided to this test (only the refresh
 * endpoint and DTOs), we cannot explicitly create sessions or change admin
 * status through other APIs. Instead, we treat different opaque refresh_token
 * values as proxies for different underlying session/admin states and observe
 * the refresh behavior through success vs. error outcomes.
 *
 * ## Test flow
 *
 * 1. Perform a successful refresh with a randomly generated opaque refresh_token,
 *    representing a valid, active admin session.
 *
 *    - Assert the response type (ITodoAppAdminUser.IAuthorized) and basic token
 *         invariants.
 * 2. Attempt a refresh with another structurally valid but semantically
 *    unacceptable refresh_token that represents a session whose owning admin
 *    has transitioned to a blocked or otherwise invalid status.
 *
 *    - Assert that this attempt fails with an error, and therefore no new tokens are
 *         issued.
 */
export async function test_api_admin_user_token_refresh_failure_when_admin_status_changed(
  connection: api.IConnection,
) {
  // 1. Successful refresh with a valid opaque refresh_token
  const refreshBodySuccess = {
    refresh_token: RandomGenerator.alphaNumeric(64),
  } satisfies ITodoAppAdminUser.IRefresh;

  const authorized = await api.functional.auth.adminUser.refresh(connection, {
    body: refreshBodySuccess,
  });
  typia.assert<ITodoAppAdminUser.IAuthorized>(authorized);

  // Basic token invariants: access/refresh must be non-empty strings.
  TestValidator.predicate(
    "successful refresh: access token must be non-empty",
    authorized.token.access.length > 0,
  );
  TestValidator.predicate(
    "successful refresh: refresh token must be non-empty",
    authorized.token.refresh.length > 0,
  );

  // 2. Failure scenario: token representing a blocked or otherwise invalid session
  const blockedLikeRefreshBody = {
    refresh_token: RandomGenerator.alphaNumeric(64),
  } satisfies ITodoAppAdminUser.IRefresh;

  await TestValidator.error(
    "refresh must fail when underlying admin/session is not acceptable",
    async () => {
      await api.functional.auth.adminUser.refresh(connection, {
        body: blockedLikeRefreshBody,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";

/**
 * Verify that admin refresh endpoint rejects malformed or tampered refresh
 * tokens.
 *
 * Business intent:
 *
 * - The /auth/adminUser/refresh endpoint must be robust against structurally
 *   invalid or garbage refresh_token values that cannot map to any
 *   todo_app_adminuser_sessions row.
 * - When such an invalid token is provided, the backend should respond with an
 *   error (likely an HttpError surfaced by SDK) and MUST NOT issue a new
 *   ITodoAppAdminUser.IAuthorized payload.
 * - Error responses should be generic and not leak internal validation details
 *   (signature errors, parsing stack traces, etc.). From the E2E perspective,
 *   we validate only that an error occurs, not its exact content or status.
 *
 * Constraints from available SDK:
 *
 * - Only api.functional.auth.adminUser.refresh is provided; no login endpoint or
 *   session listing/inspection APIs are available in this test context.
 * - Therefore, we cannot reliably create or inspect real sessions, nor can we
 *   assert on database state like absence of new rows. Instead, we focus on
 *   runtime behavior: invalid inputs must fail and never produce an
 *   ITodoAppAdminUser.IAuthorized output.
 * - The refresh function signature requires a body of type
 *   ITodoAppAdminUser.IRefresh with a non-empty refresh_token string.
 *
 * Test strategy (single function):
 *
 * 1. Construct a clearly malformed refresh token string that still satisfies the
 *    DTO type (non-empty string), for example a short random alphabetic string
 *    that is unlikely to match any real token.
 * 2. Call api.functional.auth.adminUser.refresh with this malformed token.
 * 3. Use TestValidator.error to assert that the call fails (throws), indicating
 *    that the backend properly rejects invalid tokens.
 * 4. Optionally, repeat the test with another style of token (e.g. a long random
 *    noise string) to ensure that different malformed shapes are also rejected;
 *    however, all are structurally just strings at the DTO level.
 * 5. We do NOT:
 *
 *    - Assert on HTTP status codes,
 *    - Inspect HttpError.message contents,
 *    - Inspect or manipulate connection.headers,
 *    - Attempt to validate database side-effects.
 */
export async function test_api_admin_user_token_refresh_failure_with_malformed_refresh_token(
  connection: api.IConnection,
) {
  // Helper to build a short malformed token that still satisfies MinLength<1>
  const malformedTokenShort: string = RandomGenerator.alphabets(8);

  // 1. Refresh with a short, obviously invalid token string.
  await TestValidator.error(
    "refresh rejects short malformed token",
    async () => {
      await api.functional.auth.adminUser.refresh(connection, {
        body: {
          refresh_token: malformedTokenShort,
        } satisfies ITodoAppAdminUser.IRefresh,
      });
    },
  );

  // 2. Refresh with a longer random noise token, still structurally just a
  //    string but highly unlikely to be a valid session reference.
  const malformedTokenLong: string = RandomGenerator.alphaNumeric(128);

  await TestValidator.error(
    "refresh rejects long random malformed token",
    async () => {
      await api.functional.auth.adminUser.refresh(connection, {
        body: {
          refresh_token: malformedTokenLong,
        } satisfies ITodoAppAdminUser.IRefresh,
      });
    },
  );

  // 3. Refresh with a token that looks like a UUID but should not correspond
  //    to any real session. This mimics a structurally plausible but unknown
  //    token. From the API contract perspective it is still just a string; the
  //    backend must apply its own lookup and reject if no session matches.
  const malformedTokenUuidLike: string = typia.random<
    string & tags.Format<"uuid">
  >();

  await TestValidator.error(
    "refresh rejects uuid-like but unknown token",
    async () => {
      await api.functional.auth.adminUser.refresh(connection, {
        body: {
          refresh_token: malformedTokenUuidLike,
        } satisfies ITodoAppAdminUser.IRefresh,
      });
    },
  );
}

