import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate that the admin-only member user update endpoint enforces email
 * uniqueness and rejects attempts to assign an email already used by another
 * member account.
 *
 * Business context:
 *
 * - The todoApp enforces a unique index on member user emails in the
 *   `todo_app_memberusers` table.
 * - Admins can update member user profiles via PUT
 *   /todoApp/adminUser/memberUsers/{memberUserId}.
 * - A robustness requirement is that trying to change one member's email to
 *   another member's existing email must fail with a business error and must
 *   not corrupt stored data.
 *
 * This test focuses on the conflict behavior, not on success-path updates, and
 * uses only the APIs available in the SDK surface.
 *
 * High-level steps:
 *
 * 1. Register an admin user and authenticate as that admin.
 * 2. Under the admin context, create a system setting to simulate global
 *    configuration activation (even though uniqueness is ultimately enforced at
 *    the DB level).
 * 3. Register memberUserA with a unique email.
 * 4. While authenticated as memberUserA (join auto-logs in), create at least one
 *    todo to ensure the user has activity.
 * 5. Switch back to the admin account via admin login.
 * 6. Register memberUserB with a different, unique email.
 * 7. While authenticated as memberUserB, create at least one todo.
 * 8. Switch again to the admin account via admin login so that admin-only
 *    endpoints are callable.
 * 9. Attempt to update memberUserA's email to memberUserB's email using the admin
 *    update endpoint. Wrap this call with TestValidator.error to assert that
 *    some error is thrown (the exact HTTP status or error body is not asserted,
 *    per constraints).
 *
 * Limitations and scenario adaptation:
 *
 * - The given SDK list does not include a GET endpoint for
 *   /todoApp/adminUser/memberUsers/{memberUserId}, so we cannot re-fetch
 *   memberUserA and memberUserB after the failed update to confirm that their
 *   emails remain unchanged. According to the "rewrite impossible scenarios"
 *   rule, this post-condition check is omitted.
 * - In simulation mode (connection.simulate === true), the update simulator
 *   always returns a random ITodoAppMemberUser and never throws, so the
 *   uniqueness violation cannot be observed there. This E2E test therefore
 *   validates the conflict behavior only when executed against a real backend.
 */
export async function test_api_admin_member_user_update_email_uniqueness_violation(
  connection: api.IConnection,
) {
  // 1. Register admin user (join) and become authenticated as admin.
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "AdminPw123!" as const;

  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword,
    display_name: RandomGenerator.name(2),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todoapp.local/join",
    referrer: "https://admin.todoapp.local/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorizedOnJoin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorizedOnJoin);

  // 2. Create a system setting as admin to simulate configuration enablement.
  const systemSettingBody = {
    key: "email_unique_required",
    value: "true",
    type: "boolean",
    description:
      "Require unique email addresses for todo_app_memberusers records.",
    group: "memberUser",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const systemSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: systemSettingBody,
    });
  typia.assert(systemSetting);

  // 3. Register memberUserA with a unique email.
  const memberUserAEmail = typia.random<string & tags.Format<"email">>();
  const memberUserAPassword = "MemberA123!" as const;

  const memberUserAJoinBody = {
    email: memberUserAEmail,
    password: memberUserAPassword,
    displayName: RandomGenerator.name(2),
    ip: "127.0.0.1",
    href: "https://todoapp.local/signup",
    referrer: "https://todoapp.local/landing",
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberUserAAuthorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberUserAJoinBody,
    });
  typia.assert(memberUserAAuthorized);

  const memberUserAId = memberUserAAuthorized.id;

  // 4. As memberUserA (current auth), create at least one todo.
  const todoABody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
    due_date: null,
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const todoA: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoABody,
    });
  typia.assert(todoA);

  // 5. Switch back to the admin account via login.
  const adminLoginBody = {
    email: adminEmail,
    password: adminPassword,
    ip: "127.0.0.1",
    href: "https://admin.todoapp.local/login",
    referrer: "https://admin.todoapp.local/landing",
  } satisfies ITodoAppAdminUser.ILogin;

  const adminAuthorizedOnLogin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminAuthorizedOnLogin);

  // 6. Register memberUserB with a different unique email.
  const memberUserBEmail = typia.random<string & tags.Format<"email">>();
  const memberUserBPassword = "MemberB123!" as const;

  const memberUserBJoinBody = {
    email: memberUserBEmail,
    password: memberUserBPassword,
    displayName: RandomGenerator.name(2),
    ip: "127.0.0.1",
    href: "https://todoapp.local/signup",
    referrer: "https://todoapp.local/landing",
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberUserBAuthorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberUserBJoinBody,
    });
  typia.assert(memberUserBAuthorized);

  // 7. As memberUserB (current auth), create at least one todo.
  const todoBBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 5 }),
    due_date: null,
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const todoB: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoBBody,
    });
  typia.assert(todoB);

  // 8. Switch again to admin context via login before performing the update.
  const adminAuthorizedBeforeUpdate: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminAuthorizedBeforeUpdate);

  // 9. Attempt to update memberUserA's email to memberUserB's email.
  //    This should violate the unique index on email and trigger an error
  //    in a real backend. We assert only that some error occurs.
  await TestValidator.error(
    "admin update should fail when changing memberUserA email to memberUserB's existing email",
    async () => {
      await api.functional.todoApp.adminUser.memberUsers.update(connection, {
        memberUserId: memberUserAId,
        body: {
          email: memberUserBAuthorized.email,
        } satisfies ITodoAppMemberUser.IUpdate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppSession";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSession";

/**
 * List current member user's sessions with default pagination and no filters.
 *
 * Business goal:
 *
 * - After a fresh memberUser registration, ensure that the current actor can
 *   retrieve their own sessions via PATCH
 *   /todoApp/memberUser/actors/current/sessions using default-style pagination
 *   and without applying any filters.
 *
 * Steps:
 *
 * 1. Register a new member user using /auth/memberUser/join.
 * 2. Rely on the SDK to attach the returned access token to the connection, which
 *    implicitly creates at least one session for the member.
 * 3. Call the sessions index endpoint with page=0, limit=20 and no filters.
 * 4. Validate pagination metadata and that at least one session is returned.
 * 5. For all returned sessions, verify they belong to the joined member and that
 *    basic fields are populated as expected.
 */
export async function test_api_todoapp_memberuser_current_sessions_list_default(
  connection: api.IConnection,
) {
  // 1. Register a new member user (join) to establish authenticated context
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    displayName: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const member: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert(member);

  // 2. Call sessions listing with default-style pagination and no filters
  const page = 0;
  const limit = 20;

  const requestBody = {
    page,
    limit,
  } satisfies ITodoAppSession.IRequest;

  const pageResult: IPageITodoAppSession.ISummary =
    await api.functional.todoApp.memberUser.actors.current.sessions.index(
      connection,
      {
        body: requestBody,
      },
    );

  typia.assert<IPageITodoAppSession.ISummary>(pageResult);

  const pagination = pageResult.pagination;

  // 3. Pagination validations
  TestValidator.equals(
    "pagination.current equals requested page",
    pagination.current,
    page,
  );
  TestValidator.equals(
    "pagination.limit equals requested limit",
    pagination.limit,
    limit,
  );
  TestValidator.predicate(
    "pagination.records is at least 1",
    pagination.records >= 1,
  );
  TestValidator.predicate(
    "pagination.pages is at least 1",
    pagination.pages >= 1,
  );

  // 4. Data array validations
  TestValidator.predicate(
    "data array has at least one session",
    pageResult.data.length >= 1,
  );

  // 5. Validate that all sessions belong to this member and fields are sane
  for (const session of pageResult.data) {
    typia.assert<ITodoAppSession.ISummary>(session);

    TestValidator.equals(
      "session.actor_type must be member",
      session.actor_type,
      "member",
    );

    TestValidator.equals(
      "session.actor_id must equal member id",
      session.actor_id,
      member.id,
    );

    TestValidator.predicate(
      "session.ip is non-empty string",
      typeof session.ip === "string" && session.ip.length > 0,
    );

    TestValidator.predicate(
      "session.href is non-empty string",
      typeof session.href === "string" && session.href.length > 0,
    );

    TestValidator.predicate(
      "session.referrer is non-empty string",
      typeof session.referrer === "string" && session.referrer.length > 0,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppSession";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSession";

/**
 * Filter current member user's sessions by created_at time range.
 *
 * Business flow:
 *
 * 1. Register a new member user via POST /auth/memberUser/join, which also
 *    establishes an authenticated context and initial session.
 * 2. Capture an approximate current timestamp T0 from the test runner after
 *    authentication is established.
 * 3. Query PATCH /todoApp/memberUser/actors/current/sessions with a
 *    createdFrom/createdTo window centered around T0 and assert that the
 *    current session is included and all records' created_at lie within the
 *    window.
 * 4. Query again with a past non-overlapping window and verify the current session
 *    is excluded (no sessions are returned), confirming that the created_at
 *    filters are effective.
 */
export async function test_api_todoapp_memberuser_current_sessions_filter_by_created_at_range(
  connection: api.IConnection,
) {
  // 1. Register member user and establish session
  const joinBody = typia.random<ITodoAppMemberUserJoin.ICreate>();
  const member: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppMemberUser.IAuthorized>(member);

  // 2. Capture current timestamp T0 after authentication context is valid
  const now: Date = new Date();

  // Define +/- 60 seconds buffer around now
  const bufferMs: number = 60 * 1000;
  const fromDate: Date = new Date(now.getTime() - bufferMs);
  const toDate: Date = new Date(now.getTime() + bufferMs);
  const createdFrom: string = fromDate.toISOString();
  const createdTo: string = toDate.toISOString();

  // 3. First query: window containing the current session
  const firstRequestBody = {
    page: 0,
    limit: 10,
    ip: null,
    createdFrom,
    createdTo,
    expiredFrom: null,
    expiredTo: null,
    activeOnly: null,
  } satisfies ITodoAppSession.IRequest;

  const firstPage: IPageITodoAppSession.ISummary =
    await api.functional.todoApp.memberUser.actors.current.sessions.index(
      connection,
      {
        body: firstRequestBody,
      },
    );
  typia.assert<IPageITodoAppSession.ISummary>(firstPage);

  // Validate pagination echoes request
  TestValidator.equals(
    "pagination.current should be 0",
    firstPage.pagination.current,
    0,
  );
  TestValidator.equals(
    "pagination.limit should be 10",
    firstPage.pagination.limit,
    10,
  );

  // Ensure at least one session exists in the target window
  TestValidator.predicate(
    "first query should return at least one session",
    firstPage.data.length > 0,
  );

  // Validate each session summary
  for (const session of firstPage.data) {
    // created_at is within [createdFrom, createdTo]
    const createdAtTime: number = new Date(session.created_at).getTime();
    const fromTime: number = new Date(createdFrom).getTime();
    const toTime: number = new Date(createdTo).getTime();

    TestValidator.predicate(
      "session.created_at must be within requested time window",
      createdAtTime >= fromTime && createdAtTime <= toTime,
    );

    // All sessions must belong to the authenticated member
    TestValidator.equals(
      "session.actor_id must match authenticated member id",
      session.actor_id,
      member.id,
    );
  }

  // 4. Second query: non-overlapping past window
  const pastFromDate: Date = new Date(now.getTime() - 4 * 60 * 60 * 1000); // 4 hours ago
  const pastToDate: Date = new Date(now.getTime() - 3 * 60 * 60 * 1000); // 3 hours ago
  const pastCreatedFrom: string = pastFromDate.toISOString();
  const pastCreatedTo: string = pastToDate.toISOString();

  const secondRequestBody = {
    page: 0,
    limit: 10,
    ip: null,
    createdFrom: pastCreatedFrom,
    createdTo: pastCreatedTo,
    expiredFrom: null,
    expiredTo: null,
    activeOnly: null,
  } satisfies ITodoAppSession.IRequest;

  const secondPage: IPageITodoAppSession.ISummary =
    await api.functional.todoApp.memberUser.actors.current.sessions.index(
      connection,
      {
        body: secondRequestBody,
      },
    );
  typia.assert<IPageITodoAppSession.ISummary>(secondPage);

  // In a non-overlapping past window, there should be no sessions for the
  // newly created account.
  TestValidator.equals(
    "second query for past window should return no sessions",
    secondPage.data.length,
    0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
