import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSession";

/**
 * Validate pagination behavior of current member user sessions across multiple
 * pages.
 *
 * Business context:
 *
 * - A member user can have multiple authentication sessions.
 * - The endpoint PATCH /todoApp/memberUser/actors/current/sessions exposes those
 *   sessions with pageable summaries (IPageITodoAppSession.ISummary).
 *
 * This test:
 *
 * 1. Registers a new member user to establish an authenticated context.
 * 2. Calls the sessions index endpoint with page=0, limit=5 to get the first page.
 * 3. Calls the same endpoint with page=1, limit=5 to get the second page.
 * 4. Validates pagination metadata (current, limit, records, pages) and that each
 *    page does not exceed the specified limit.
 * 5. When there are more than 5 total records, validates that page 0 and page 1
 *    contain disjoint sets of session IDs (no duplicates across pages) and that
 *    pages >= 2.
 * 6. For all returned sessions, validates basic actor metadata consistency and
 *    type safety using typia.assert.
 */
export async function test_api_todoapp_memberuser_current_sessions_pagination_multiple_pages(
  connection: api.IConnection,
) {
  // 1. Register a member user (join) to obtain an authenticated context.
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://todoapp.example.com/join",
    referrer: "https://todoapp.example.com/",
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const authorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppMemberUser.IAuthorized>(authorized);
  typia.assert<IAuthorizationToken>(authorized.token);

  // 2. Request first page of sessions with limit=5.
  const firstRequest = {
    page: 0 as number & tags.Type<"int32">,
    limit: 5 as number & tags.Type<"int32">,
    ip: null,
    createdFrom: null,
    createdTo: null,
    expiredFrom: null,
    expiredTo: null,
    activeOnly: null,
  } satisfies ITodoAppSession.IRequest;

  const firstPage: IPageITodoAppSession.ISummary =
    await api.functional.todoApp.memberUser.actors.current.sessions.index(
      connection,
      { body: firstRequest },
    );
  typia.assert<IPageITodoAppSession.ISummary>(firstPage);

  const firstPagination: IPage.IPagination = firstPage.pagination;
  typia.assert<IPage.IPagination>(firstPagination);

  TestValidator.equals(
    "first page limit should be 5",
    firstPagination.limit,
    5,
  );
  TestValidator.equals(
    "first page current index should be 0",
    firstPagination.current,
    0,
  );
  TestValidator.predicate(
    "first page records should be non-negative",
    firstPagination.records >= 0,
  );
  TestValidator.predicate(
    "first page pages should be non-negative",
    firstPagination.pages >= 0,
  );
  TestValidator.predicate(
    "first page data length should not exceed limit",
    firstPage.data.length <= firstPagination.limit,
  );

  // 3. Request second page with the same limit.
  const secondRequest = {
    page: 1 as number & tags.Type<"int32">,
    limit: 5 as number & tags.Type<"int32">,
    ip: null,
    createdFrom: null,
    createdTo: null,
    expiredFrom: null,
    expiredTo: null,
    activeOnly: null,
  } satisfies ITodoAppSession.IRequest;

  const secondPage: IPageITodoAppSession.ISummary =
    await api.functional.todoApp.memberUser.actors.current.sessions.index(
      connection,
      { body: secondRequest },
    );
  typia.assert<IPageITodoAppSession.ISummary>(secondPage);

  const secondPagination: IPage.IPagination = secondPage.pagination;
  typia.assert<IPage.IPagination>(secondPagination);

  TestValidator.equals(
    "second page limit should be 5",
    secondPagination.limit,
    5,
  );
  TestValidator.equals(
    "second page current index should be 1",
    secondPagination.current,
    1,
  );
  TestValidator.predicate(
    "second page records should be non-negative",
    secondPagination.records >= 0,
  );
  TestValidator.predicate(
    "second page pages should be non-negative",
    secondPagination.pages >= 0,
  );
  TestValidator.predicate(
    "second page data length should not exceed limit",
    secondPage.data.length <= secondPagination.limit,
  );

  // 4. If there are more records than fit in a single page, ensure
  //    disjoint session IDs across first and second pages and pages>=2.
  if (firstPagination.records > firstPagination.limit) {
    TestValidator.predicate(
      "total pages should be at least 2 when records exceed limit",
      firstPagination.pages >= 2,
    );

    const firstIds: string[] = firstPage.data.map((s) => s.id);
    const secondIds: string[] = secondPage.data.map((s) => s.id);

    const unionIds: string[] = [...firstIds, ...secondIds];
    const uniqueIds = new Set(unionIds);

    TestValidator.equals(
      "session IDs across first and second pages should be unique when records exceed limit",
      uniqueIds.size,
      unionIds.length,
    );
  }

  // 5. For all sessions from both pages, validate basic actor fields and UUIDs.
  const allSessions: ITodoAppSession.ISummary[] = [
    ...firstPage.data,
    ...secondPage.data,
  ];

  for (const session of allSessions) {
    typia.assert<ITodoAppSession.ISummary>(session);

    TestValidator.predicate(
      "actor_type should be a non-empty string",
      typeof session.actor_type === "string" && session.actor_type.length > 0,
    );

    const actorId: string & tags.Format<"uuid"> = session.actor_id;
    typia.assert<string & tags.Format<"uuid">>(actorId);

    if (session.actor_id === authorized.id) {
      TestValidator.equals(
        "session actor_id should match authorized member id when referencing same actor",
        session.actor_id,
        authorized.id,
      );
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppSession";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSession";

export async function test_api_todoapp_memberuser_current_session_terminate_single_active_session(
  connection: api.IConnection,
) {
  // 1. Register a new member user (join) and establish authenticated context
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    displayName: RandomGenerator.name(1),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const authorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppMemberUser.IAuthorized>(authorized);

  // 2. List active sessions for the current member user
  const activeRequestBody = {
    page: 0 as number & tags.Type<"int32">,
    limit: 10 as number & tags.Type<"int32">,
    activeOnly: true,
  } satisfies ITodoAppSession.IRequest;

  const activePageBefore: IPageITodoAppSession.ISummary =
    await api.functional.todoApp.memberUser.actors.current.sessions.index(
      connection,
      {
        body: activeRequestBody,
      },
    );
  typia.assert<IPageITodoAppSession.ISummary>(activePageBefore);

  const activeSessionsBefore: ITodoAppSession.ISummary[] =
    activePageBefore.data;

  // Ensure we have at least one active session (the join-created session)
  TestValidator.predicate(
    "active session list must contain at least one session after join",
    () => activeSessionsBefore.length > 0,
  );

  const allActiveIdsBefore: string[] = activeSessionsBefore.map((s) => s.id);
  const targetSession: ITodoAppSession.ISummary = activeSessionsBefore[0];
  const sessionIdTarget: string = targetSession.id;

  // 3. Terminate the selected session
  await api.functional.todoApp.memberUser.actors.current.sessions.erase(
    connection,
    {
      sessionId: sessionIdTarget,
    },
  );

  // 4. List active sessions again and ensure target session is gone
  const activePageAfter: IPageITodoAppSession.ISummary =
    await api.functional.todoApp.memberUser.actors.current.sessions.index(
      connection,
      {
        body: activeRequestBody,
      },
    );
  typia.assert<IPageITodoAppSession.ISummary>(activePageAfter);

  const activeSessionsAfter: ITodoAppSession.ISummary[] = activePageAfter.data;
  const allActiveIdsAfter: string[] = activeSessionsAfter.map((s) => s.id);

  // Target session must not be present in active-only list anymore
  TestValidator.predicate(
    "terminated session id must be removed from active sessions",
    () => allActiveIdsAfter.includes(sessionIdTarget) === false,
  );

  // All other previously active sessions (besides the target) must remain
  for (const id of allActiveIdsBefore) {
    if (id === sessionIdTarget) continue;
    TestValidator.predicate(
      "other sessions must remain active after terminating a single session",
      () => allActiveIdsAfter.includes(id),
    );
  }

  // 5. Optionally verify that the terminated session is marked expired when listing all sessions
  const allSessionsRequestBody = {
    page: 0 as number & tags.Type<"int32">,
    limit: 10 as number & tags.Type<"int32">,
    activeOnly: null,
  } satisfies ITodoAppSession.IRequest;

  const allSessionsPage: IPageITodoAppSession.ISummary =
    await api.functional.todoApp.memberUser.actors.current.sessions.index(
      connection,
      {
        body: allSessionsRequestBody,
      },
    );
  typia.assert<IPageITodoAppSession.ISummary>(allSessionsPage);

  const terminatedSession = allSessionsPage.data.find(
    (s) => s.id === sessionIdTarget,
  );

  if (terminatedSession !== undefined) {
    TestValidator.predicate(
      "terminated session expired_at should be set when listing all sessions",
      () =>
        terminatedSession.expired_at !== null &&
        terminatedSession.expired_at !== undefined,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppSession";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSession";

/**
 * Terminate a current member user's session and verify active vs. historical
 * listings.
 *
 * Business flow (adapted to available APIs):
 *
 * 1. Register a new member user via POST /auth/memberUser/join. This both creates
 *    the member account and establishes at least one authentication session for
 *    that actor.
 * 2. Using the authenticated connection established by join, call PATCH
 *    /todoApp/memberUser/actors/current/sessions with activeOnly=true, page=0,
 *    and a sufficiently large limit to retrieve all active sessions belonging
 *    to the current member user.
 * 3. Select one session summary from the returned list (typically the only one in
 *    a fresh environment) and remember its id.
 * 4. Invoke DELETE /todoApp/memberUser/actors/current/sessions/{sessionId} for
 *    that id to terminate the selected session.
 * 5. Call the PATCH listing endpoint again with activeOnly=true and verify that
 *    the terminated session id is no longer present in the active session
 *    list.
 * 6. Call the listing endpoint once more with activeOnly set to null so that both
 *    active and historical sessions may be returned. If the terminated session
 *    still appears, assert that its expired_at field is non-null, indicating it
 *    is no longer active but retained historically.
 *
 * This scenario validates that the session termination endpoint successfully
 * marks a session as inactive and that the session listing endpoint properly
 * reflects the difference between active-only and full (including historical)
 * views, within the constraints of the available APIs.
 */
export async function test_api_todoapp_memberuser_current_session_terminate_all_other_devices_iteratively(
  connection: api.IConnection,
) {
  // 1. Register a new member user, establishing an authenticated session.
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://todo.example.com/signup",
    referrer: "https://todo.example.com/landing",
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const authorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppMemberUser.IAuthorized>(authorized);

  // 2. Helper to list sessions for the current actor with a given activeOnly flag.
  const listSessions = async (
    activeOnly: boolean | null,
  ): Promise<IPageITodoAppSession.ISummary> => {
    const requestBody = {
      page: 0 as number & tags.Type<"int32">,
      limit: 50 as number & tags.Type<"int32">,
      ip: null,
      createdFrom: null,
      createdTo: null,
      expiredFrom: null,
      expiredTo: null,
      activeOnly,
    } satisfies ITodoAppSession.IRequest;

    const pageResult: IPageITodoAppSession.ISummary =
      await api.functional.todoApp.memberUser.actors.current.sessions.index(
        connection,
        {
          body: requestBody,
        },
      );
    typia.assert<IPageITodoAppSession.ISummary>(pageResult);
    return pageResult;
  };

  // 3. List all active sessions; expect at least one due to the join call.
  const activePageBefore: IPageITodoAppSession.ISummary =
    await listSessions(true);

  TestValidator.equals(
    "initial active sessions page index should be 0",
    activePageBefore.pagination.current,
    0,
  );

  TestValidator.predicate(
    "there should be at least one active session after join",
    activePageBefore.data.length > 0,
  );

  const activeSessionsBefore: ITodoAppSession.ISummary[] =
    activePageBefore.data;

  // Select one session to terminate (for a fresh user, typically the only one).
  const targetSession: ITodoAppSession.ISummary = activeSessionsBefore[0];
  typia.assert<ITodoAppSession.ISummary>(targetSession);

  const targetSessionId: string & tags.Format<"uuid"> = targetSession.id;

  // 4. Terminate the selected session.
  await api.functional.todoApp.memberUser.actors.current.sessions.erase(
    connection,
    {
      sessionId: targetSessionId,
    },
  );

  // 5. Re-list active sessions and verify the terminated session is no longer active.
  const activePageAfter: IPageITodoAppSession.ISummary =
    await listSessions(true);

  TestValidator.equals(
    "active sessions page index after termination should be 0",
    activePageAfter.pagination.current,
    0,
  );

  const activeSessionsAfter: ITodoAppSession.ISummary[] = activePageAfter.data;

  const activeIdsAfter: string[] = activeSessionsAfter.map((s) => s.id);

  TestValidator.predicate(
    "terminated session should not appear in active-only listing",
    !activeIdsAfter.includes(targetSessionId),
  );

  // 6. List all sessions (active + historical) and, if the terminated session
  // is present, ensure it is marked as expired.
  const allPageAfter: IPageITodoAppSession.ISummary = await listSessions(null);
  const allSessionsAfter: ITodoAppSession.ISummary[] = allPageAfter.data;

  const maybeHistorical = allSessionsAfter.find(
    (s) => s.id === targetSessionId,
  );

  if (maybeHistorical !== undefined) {
    typia.assert<ITodoAppSession.ISummary>(maybeHistorical);
    TestValidator.predicate(
      "historical terminated session should have expired_at set",
      maybeHistorical.expired_at !== null &&
        maybeHistorical.expired_at !== undefined,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppSession";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSession";

export async function test_api_todoapp_memberuser_current_session_terminate_idempotent_behavior_for_already_terminated_session(
  connection: api.IConnection,
) {
  // 1. Register a new member user (join) to establish authenticated context
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://todoapp.example.com/signup",
    referrer: "https://todoapp.example.com/landing",
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const authorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppMemberUser.IAuthorized>(authorized);

  // 2. List current sessions with activeOnly=true to obtain an active sessionId
  const listRequestBody = {
    page: 0 satisfies number & tags.Type<"int32">,
    limit: 10 satisfies number & tags.Type<"int32">,
    ip: null,
    createdFrom: null,
    createdTo: null,
    expiredFrom: null,
    expiredTo: null,
    activeOnly: true,
  } satisfies ITodoAppSession.IRequest;

  const pageResult: IPageITodoAppSession.ISummary =
    await api.functional.todoApp.memberUser.actors.current.sessions.index(
      connection,
      {
        body: listRequestBody,
      },
    );
  typia.assert<IPageITodoAppSession.ISummary>(pageResult);

  // Ensure we have at least one active session
  TestValidator.predicate(
    "there should be at least one active session after join",
    pageResult.data.length > 0,
  );

  const targetSession: ITodoAppSession.ISummary = pageResult.data[0];
  typia.assert<ITodoAppSession.ISummary>(targetSession);

  const sessionId: string & tags.Format<"uuid"> = targetSession.id;

  // 3. First DELETE: terminate the selected session
  await api.functional.todoApp.memberUser.actors.current.sessions.erase(
    connection,
    {
      sessionId,
    },
  );

  // 4. Second DELETE: call again with the same sessionId to verify idempotent/safe behavior
  await api.functional.todoApp.memberUser.actors.current.sessions.erase(
    connection,
    {
      sessionId,
    },
  );

  // If we reach here without error, the API treated repeated deletes as safe.

  // 5. List sessions again with activeOnly=true to confirm the session remains inactive
  const listAfterDeleteBody = {
    page: 0 satisfies number & tags.Type<"int32">,
    limit: 10 satisfies number & tags.Type<"int32">,
    ip: null,
    createdFrom: null,
    createdTo: null,
    expiredFrom: null,
    expiredTo: null,
