import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppAdminUser";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";

/**
 * Validate admin user search by email and status with pagination and ordering.
 *
 * Business context: Administrative operators need to search
 * `todo_app_adminusers` using flexible criteria such as partial email and
 * status (e.g. `active`, `disabled`), and receive a paginated, consistently
 * ordered summary list. This test ensures that the search endpoint honors those
 * filters and ordering instructions when called by an authenticated admin, in a
 * realistically initialized environment.
 *
 * Steps:
 *
 * 1. Initialize a global system setting via POST /todoApp/adminUser/systemSettings
 *    so that the administrative environment is non-empty.
 * 2. Register a primary admin via /auth/adminUser/join to bootstrap the admin
 *    session and let the SDK automatically attach the Authorization header to
 *    subsequent requests.
 * 3. Create multiple additional admin users with controlled email patterns and
 *    varying `status` values, so that some but not all match a chosen
 *    combination of email substring and status.
 * 4. As the authenticated admin, call PATCH /todoApp/adminUser/adminUsers with an
 *    ITodoAppAdminUser.IRequest body specifying:
 *
 *    - Page = 1 and a sufficiently large limit,
 *    - Email filter substring shared by a subset of created admins,
 *    - Status = "active" (or similar),
 *    - OrderByCreatedAt = "asc".
 * 5. Validate that the response (IPageITodoAppAdminUser.ISummary):
 *
 *    - Uses pagination.current = 1 and pagination.limit as requested.
 *    - Has pagination.records equal to the number of admins matching the filters (in
 *         this simple one-page scenario).
 *    - Contains only ITodoAppAdminUser.ISummary entries whose email contains the
 *         filter substring and whose status equals the filter.
 *    - Contains none of the created admins that do not satisfy the filters.
 *    - Is sorted by created_at ascending.
 * 6. Issue a second search call with orderByCreatedAt = "desc" and verify that the
 *    same filtered set is returned but in reverse created_at order.
 */
export async function test_api_admin_adminusers_search_by_email_and_status(
  connection: api.IConnection,
) {
  // 1. Initialize at least one system setting to simulate real admin env
  const settingBody = {
    key: "max_active_todos_per_user",
    value: "100",
    type: "int",
    description: "Maximum number of active todos per user for testing",
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const systemSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: settingBody,
    });
  typia.assert(systemSetting);

  // 2. Register primary admin and establish authenticated context
  const joinPassword = "P@ssw0rd!" as string & tags.Format<"password">;
  const joinEmailCommon = "filter-key";

  const primaryAdminJoinBody = {
    email: `primary.${joinEmailCommon}@example.com` as string &
      tags.Format<"email">,
    password: joinPassword,
    display_name: "Primary Admin",
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todoapp.test/join" as string & tags.Format<"uri">,
    referrer: "https://admin.todoapp.test/landing" as string &
      tags.Format<"uri">,
  } satisfies ITodoAppAdminUser.IJoin;

  const primaryAdmin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: primaryAdminJoinBody,
    });
  typia.assert(primaryAdmin);

  // 3. Create additional admins with controlled email patterns and statuses
  type CreatedAdmin = {
    id: string;
    email: string;
    status: string;
    created_at: string;
  };
  const createdAdmins: CreatedAdmin[] = [];

  const makeAdmin = async (
    localPart: string,
    status: string,
  ): Promise<CreatedAdmin> => {
    const body = {
      email: `${localPart}.${joinEmailCommon}@example.com` as string &
        tags.Format<"email">,
      password: joinPassword,
      display_name: RandomGenerator.name(),
      status,
      ip: "127.0.0.1",
      href: "https://admin.todoapp.test/join" as string & tags.Format<"uri">,
      referrer: "https://admin.todoapp.test/landing" as string &
        tags.Format<"uri">,
    } satisfies ITodoAppAdminUser.IJoin;

    const admin: ITodoAppAdminUser.IAuthorized =
      await api.functional.auth.adminUser.join(connection, {
        body,
      });
    typia.assert(admin);

    const record: CreatedAdmin = {
      id: admin.id,
      email: admin.email,
      status: admin.status,
      created_at: admin.created_at,
    };
    createdAdmins.push(record);
    return record;
  };

  // Create admins that should match the filter (email contains "filter-key" & status "active")
  const matching1 = await makeAdmin("match1", "active");
  const matching2 = await makeAdmin("match2", "active");

  // Create admins that should NOT match: different status or email
  const nonMatchingStatus = await makeAdmin("nomatch-status", "disabled");
  const nonMatchingEmailBody = {
    email: "other.user@example.com" as string & tags.Format<"email">,
    password: joinPassword,
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todoapp.test/join" as string & tags.Format<"uri">,
    referrer: "https://admin.todoapp.test/landing" as string &
      tags.Format<"uri">,
  } satisfies ITodoAppAdminUser.IJoin;

  const nonMatchingEmail: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: nonMatchingEmailBody,
    });
  typia.assert(nonMatchingEmail);
  createdAdmins.push({
    id: nonMatchingEmail.id,
    email: nonMatchingEmail.email,
    status: nonMatchingEmail.status,
    created_at: nonMatchingEmail.created_at,
  });

  // Include the primary admin in the local list as well
  createdAdmins.push({
    id: primaryAdmin.id,
    email: primaryAdmin.email,
    status: primaryAdmin.status,
    created_at: primaryAdmin.created_at,
  });

  // Derive expected matches for filter combination
  const emailFilter = joinEmailCommon;
  const statusFilter = "active";

  const expectedMatches = createdAdmins.filter(
    (admin) =>
      admin.email.includes(emailFilter) && admin.status === statusFilter,
  );

  // Ensure we do have both matching and non-matching samples
  await TestValidator.predicate(
    "there are matching admins for filter",
    async () => expectedMatches.length >= 2,
  );
  await TestValidator.predicate(
    "there are non-matching admins present",
    async () => createdAdmins.length > expectedMatches.length,
  );

  const page = 1 as number & tags.Type<"int32"> & tags.Minimum<1>;
  const limit = 20 as number & tags.Type<"int32"> & tags.Minimum<1>;

  const buildRequestBody = (
    order: "asc" | "desc",
  ): ITodoAppAdminUser.IRequest => ({
    page,
    limit,
    email: emailFilter,
    status: statusFilter,
    orderByCreatedAt: order,
  });

  // 4. Search with ascending created_at order
  const ascResponse: IPageITodoAppAdminUser.ISummary =
    await api.functional.todoApp.adminUser.adminUsers.index(connection, {
      body: buildRequestBody("asc"),
    });
  typia.assert(ascResponse);

  const ascPage = ascResponse.pagination;
  const ascData = ascResponse.data;

  // Basic pagination checks
  TestValidator.equals(
    "asc: pagination.current equals requested page",
    ascPage.current,
    page,
  );
  TestValidator.equals(
    "asc: pagination.limit equals requested limit",
    ascPage.limit,
    limit,
  );

  // Records should be at least the number of returned data items and not less than expected filtered count
  await TestValidator.predicate(
    "asc: pagination.records >= data length",
    async () => ascPage.records >= ascData.length,
  );
  await TestValidator.predicate(
    "asc: pagination.records >= expectedMatches length",
    async () => ascPage.records >= expectedMatches.length,
  );

  // All returned summaries must satisfy filters
  for (const summary of ascData) {
    TestValidator.predicate(
      "asc: summary email contains filter substring",
      summary.email.includes(emailFilter),
    );
    TestValidator.equals(
      "asc: summary status equals filter status",
      summary.status,
      statusFilter,
    );
  }

  const expectedMatchingIds = new Set(expectedMatches.map((a) => a.id));

  // No non-matching admin IDs should appear in data
  for (const summary of ascData) {
    await TestValidator.predicate(
      "asc: summary id belongs to expected matching set",
      async () => expectedMatchingIds.has(summary.id),
    );
  }

  // Sorting by created_at ascending
  for (let i = 1; i < ascData.length; i++) {
    const prev = ascData[i - 1];
    const curr = ascData[i];
    const prevTime = new Date(prev.created_at).getTime();
    const currTime = new Date(curr.created_at).getTime();

    await TestValidator.predicate(
      "asc: created_at is non-decreasing",
      async () => prevTime <= currTime,
    );
  }

  // 5. Search with descending created_at order
  const descResponse: IPageITodoAppAdminUser.ISummary =
    await api.functional.todoApp.adminUser.adminUsers.index(connection, {
      body: buildRequestBody("desc"),
    });
  typia.assert(descResponse);

  const descPage = descResponse.pagination;
  const descData = descResponse.data;

  TestValidator.equals(
    "desc: pagination.current equals requested page",
    descPage.current,
    page,
  );
  TestValidator.equals(
    "desc: pagination.limit equals requested limit",
    descPage.limit,
    limit,
  );

  await TestValidator.predicate(
    "desc: pagination.records >= data length",
    async () => descPage.records >= descData.length,
  );
  await TestValidator.predicate(
    "desc: pagination.records >= expectedMatches length",
    async () => descPage.records >= expectedMatches.length,
  );

  for (const summary of descData) {
    TestValidator.predicate(
      "desc: summary email contains filter substring",
      summary.email.includes(emailFilter),
    );
    TestValidator.equals(
      "desc: summary status equals filter status",
      summary.status,
      statusFilter,
    );
    await TestValidator.predicate(
      "desc: summary id belongs to expected matching set",
      async () => expectedMatchingIds.has(summary.id),
    );
  }

  for (let i = 1; i < descData.length; i++) {
    const prev = descData[i - 1];
    const curr = descData[i];
    const prevTime = new Date(prev.created_at).getTime();
    const currTime = new Date(curr.created_at).getTime();

    await TestValidator.predicate(
      "desc: created_at is non-increasing",
      async () => prevTime >= currTime,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppAdminUser";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";

/**
 * Validate pagination boundary behavior when listing admin users.
 *
 * Business context: Administrative consoles typically offer a paginated view of
 * all admin accounts. This test ensures that the pagination API for admin users
 * behaves sensibly at the first page and when a caller requests a page index
 * that is beyond the last available page. The goal is to guarantee stable
 * behavior (no server errors), consistent total record counting, and
 * predictable handling of out-of-range page requests.
 *
 * Scenario steps:
 *
 * 1. Initialize global system settings so the environment mimics a configured
 *    production state. At least one ITodoAppSystemSetting record is created via
 *    POST /todoApp/adminUser/systemSettings.
 * 2. Register an initial adminUser by calling POST /auth/adminUser/join. The SDK
 *    automatically sets connection.headers.Authorization from the returned
 *    IAuthorizationToken, so subsequent adminUser-protected calls are
 *    authenticated.
 * 3. Seed additional admin users by invoking /auth/adminUser/join multiple times
 *    with distinct emails. Each call both creates a new admin record and
 *    updates the Authorization header to that new admin, which is fine because
 *    any authenticated admin can call the adminUsers.index endpoint. Ensure the
 *    total number of admins strictly exceeds the page limit used later (e.g.,
 *    create at least 7 admins for limit = 5).
 * 4. As the currently authenticated admin, request the first page of admin users
 *    by calling PATCH /todoApp/adminUser/adminUsers with an
 *    ITodoAppAdminUser.IRequest body where:
 *
 *    - Page = 1
 *    - Limit = 5
 *    - All filter fields (email, status, orderByCreatedAt, createdFrom, createdTo)
 *         are left undefined so the call returns an unfiltered list. Verify:
 *    - The response matches IPageITodoAppAdminUser.ISummary via typia.assert.
 *    - Pagination.current equals 1.
 *    - Pagination.limit equals the requested limit (5).
 *    - Data.length is >= 0 and <= pagination.limit.
 *    - Pagination.records is >= data.length.
 *    - Pagination.pages is consistent with records and limit: if pagination.records
 *         === 0 then pagination.pages === 0; otherwise pagination.pages >= 1,
 *         and pagination.records <= pagination.pages * pagination.limit.
 * 5. Compute an out-of-range page index based on the first response: const
 *    oversizedPage = pagination.pages + 1 (or 2 if pages is 0). This guarantees
 *    the requested page is strictly greater than the last page when records >
 *    0. Call PATCH /todoApp/adminUser/adminUsers again with the same limit and
 *    page = oversizedPage. Verify for the second response:
 *
 *    - Typia.assert passes for IPageITodoAppAdminUser.ISummary.
 *    - Pagination.records is identical to the value observed in the first response.
 *    - Pagination.limit equals the requested limit (5).
 *    - Pagination.current is either: (a) the requested oversizedPage (API echoes
 *         requested page even when out-of-range), or (b) the last valid page
 *         number from the first response (pagination.pages), meaning the API
 *         clamps to the last page.
 *    - If pagination.current equals oversizedPage, then data.length must be 0,
 *         indicating an empty page beyond the end of the list.
 *    - If pagination.current equals the original pagination.pages, then data.length
 *         must be > 0 and <= limit, representing the last page.
 *
 * The test must never attempt to send invalid types or rely on specific HTTP
 * status codes. It should focus strictly on verifying stable, predictable
 * pagination semantics and consistent record counting across multiple calls.
 */
export async function test_api_admin_adminusers_pagination_boundaries(
  connection: api.IConnection,
) {
  // 1. Create at least one system setting to simulate configured environment.
  const settingCreateBody = {
    key: `max_active_todos_${RandomGenerator.alphaNumeric(8)}`,
    value: "100",
    type: "int",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const systemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: settingCreateBody,
    });
  typia.assert<ITodoAppSystemSetting>(systemSetting);

  // 2. Register a primary admin user (also authenticates the connection).
  const primaryAdminJoinBody = {
    email: `${RandomGenerator.alphaNumeric(12)}@example.com`,
    password: RandomGenerator.alphaNumeric(16) as string &
      tags.Format<"password">,
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todoapp.test/signup" as string & tags.Format<"uri">,
    referrer: "https://admin.todoapp.test/" as string & tags.Format<"uri">,
  } satisfies ITodoAppAdminUser.IJoin;

  const primaryAdmin = await api.functional.auth.adminUser.join(connection, {
    body: primaryAdminJoinBody,
  });
  typia.assert<ITodoAppAdminUser.IAuthorized>(primaryAdmin);
  typia.assert<IAuthorizationToken>(primaryAdmin.token);

  // 3. Seed additional admin users so that total records exceed our page limit.
  const pageLimit: number & tags.Type<"int32"> & tags.Minimum<1> = 5 as number &
    tags.Type<"int32"> &
    tags.Minimum<1>;
  const seedCount = pageLimit + 3; // ensure records > limit

  for (let i = 0; i < seedCount; i++) {
    const seedJoinBody = {
      email: `${RandomGenerator.alphaNumeric(12)}+${i}@example.com`,
      password: RandomGenerator.alphaNumeric(16) as string &
        tags.Format<"password">,
      display_name: RandomGenerator.name(),
      status: "active",
      ip: "127.0.0.1",
      href: "https://admin.todoapp.test/seed" as string & tags.Format<"uri">,
      referrer: "https://admin.todoapp.test/system-settings" as string &
        tags.Format<"uri">,
    } satisfies ITodoAppAdminUser.IJoin;

    const seededAdmin = await api.functional.auth.adminUser.join(connection, {
      body: seedJoinBody,
    });
    typia.assert<ITodoAppAdminUser.IAuthorized>(seededAdmin);
  }

  // 4. Request the first page of admin users.
  const firstPageRequestBody = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: pageLimit,
  } satisfies ITodoAppAdminUser.IRequest;

  const firstPage = await api.functional.todoApp.adminUser.adminUsers.index(
    connection,
    {
      body: firstPageRequestBody,
    },
  );
  typia.assert<IPageITodoAppAdminUser.ISummary>(firstPage);

  const firstPagination = firstPage.pagination;
  const firstData = firstPage.data;

  // Basic pagination validations for the first page.
  TestValidator.equals(
    "first page: current page should be 1",
    firstPagination.current,
    1,
  );
  TestValidator.equals(
    "first page: limit should equal requested limit",
    firstPagination.limit,
    pageLimit,
  );
  TestValidator.predicate(
    "first page: data length must be between 0 and limit",
    firstData.length >= 0 && firstData.length <= firstPagination.limit,
  );
  TestValidator.predicate(
    "first page: records must be >= data length",
    firstPagination.records >= firstData.length,
  );

  if (firstPagination.records === 0) {
    TestValidator.equals(
      "first page: when records is 0, pages must be 0",
      firstPagination.pages,
      0,
    );
  } else {
    TestValidator.predicate(
      "first page: when records > 0, pages must be >= 1",
      firstPagination.pages >= 1,
    );
    TestValidator.predicate(
      "first page: records must be <= pages * limit",
      firstPagination.records <= firstPagination.pages * firstPagination.limit,
    );
  }

  // 5. Request an out-of-range page.
  const oversizedPageRaw =
    firstPagination.pages === 0 ? 2 : firstPagination.pages + 1;
  const oversizedPage = oversizedPageRaw as number &
    tags.Type<"int32"> &
    tags.Minimum<1>;

  const oversizedRequestBody = {
    page: oversizedPage,
    limit: pageLimit,
  } satisfies ITodoAppAdminUser.IRequest;

  const oversizedPageResult =
    await api.functional.todoApp.adminUser.adminUsers.index(connection, {
      body: oversizedRequestBody,
    });
  typia.assert<IPageITodoAppAdminUser.ISummary>(oversizedPageResult);

  const oversizedPagination = oversizedPageResult.pagination;
  const oversizedData = oversizedPageResult.data;

  // Ensure records and limit are consistent with the first call.
  TestValidator.equals(
    "oversized page: records must remain constant",
    oversizedPagination.records,
    firstPagination.records,
  );
  TestValidator.equals(
    "oversized page: limit must equal requested limit",
    oversizedPagination.limit,
    pageLimit,
  );

  // The API may either echo the requested page or clamp to the last page.
  const lastPage = firstPagination.pages;
  TestValidator.predicate(
    "oversized page: current must be either requested page or last page",
    oversizedPagination.current === oversizedPageRaw ||
      oversizedPagination.current === lastPage,
  );

  if (oversizedPagination.current === oversizedPageRaw) {
    // API chooses to honor oversized page and return an empty slice.
    TestValidator.equals(
      "oversized page honored: data must be empty",
      oversizedData.length,
      0,
    );
  } else if (oversizedPagination.current === lastPage) {
    // API clamps to last page; expect non-empty last page when records > 0.
    if (oversizedPagination.records > 0) {
      TestValidator.predicate(
        "clamped to last page: data length must be > 0 and <= limit",
        oversizedData.length > 0 &&
          oversizedData.length <= oversizedPagination.limit,
      );
    } else {
      // When there are no records at all, lastPage === 0 and data should be empty.
      TestValidator.equals(
        "no records: clamped last page should have empty data",
        oversizedData.length,
        0,
      );
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppAdminUser";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";

export async function test_api_admin_adminusers_search_by_created_at_range(
  connection: api.IConnection,
) {
  // 1. Create a system setting to initialize environment
  const systemSettingKeyPrefix: string = RandomGenerator.alphaNumeric(8);
  const systemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: {
        key: `${systemSettingKeyPrefix}_max_active_todos_per_user`,
        value: "100",
        type: "int",
        description: RandomGenerator.paragraph({ sentences: 3 }),
        group: "limits",
        enabled: true,
      } satisfies ITodoAppSystemSetting.ICreate,
    });
  typia.assert(systemSetting);

  // Helper to join an adminUser and capture its authorized payload
  const joinAdmin = async (): Promise<ITodoAppAdminUser.IAuthorized> => {
    const email: string & tags.Format<"email"> = typia.random<
      string & tags.Format<"email">
    >();
    const password: string & tags.Format<"password"> = typia.random<
      string & tags.Format<"password">
    >();

    const authorized = await api.functional.auth.adminUser.join(connection, {
      body: {
        email,
        password,
        display_name: RandomGenerator.name(),
        status: "active",
        ip: "127.0.0.1",
        href: "https://admin.todo-app.test/register",
        referrer: "https://admin.todo-app.test/landing",
      } satisfies ITodoAppAdminUser.IJoin,
    });
    typia.assert(authorized);
    return authorized;
  };

  // 2~5. Create three admin users at different times
  const firstAdmin: ITodoAppAdminUser.IAuthorized = await joinAdmin();
  const secondAdmin: ITodoAppAdminUser.IAuthorized = await joinAdmin();
  const thirdAdmin: ITodoAppAdminUser.IAuthorized = await joinAdmin();

  // Collect their created_at values and IDs
  const admins = [firstAdmin, secondAdmin, thirdAdmin];

  type AdminCreatedInfo = {
    id: string & tags.Format<"uuid">;
    created_at: string & tags.Format<"date-time">;
  };

  const createdInfos: AdminCreatedInfo[] = admins.map((admin) => ({
    id: admin.id,
    created_at: admin.created_at,
  }));

  // Sort admins by created_at lexicographically (ISO date-time is lex-orderable)
  const sortedByCreatedAt: AdminCreatedInfo[] = [...createdInfos].sort(
    (a, b) =>
      a.created_at < b.created_at ? -1 : a.created_at > b.created_at ? 1 : 0,
  );

  const earliest = sortedByCreatedAt[0];
  const middle = sortedByCreatedAt[1];
  const latest = sortedByCreatedAt[2];

  const createdFrom: string & tags.Format<"date-time"> = middle.created_at;
  const createdTo: string & tags.Format<"date-time"> = latest.created_at;

  // 7. Build search request with createdAt range filter
  const page = 1 as number & tags.Type<"int32"> & tags.Minimum<1>;
  const limit = 20 as number & tags.Type<"int32"> & tags.Minimum<1>;

  const requestBody = {
    page,
    limit,
    orderByCreatedAt: "asc" as const,
    createdFrom,
    createdTo,
  } satisfies ITodoAppAdminUser.IRequest;

  const firstPage: IPageITodoAppAdminUser.ISummary =
    await api.functional.todoApp.adminUser.adminUsers.index(connection, {
      body: requestBody,
    });
  typia.assert(firstPage);

  // 8. Validate pagination metadata
  const pagination = firstPage.pagination;
  TestValidator.equals(
    "pagination current page should match request page",
    pagination.current,
    page,
  );
  TestValidator.equals(
    "pagination limit should match request limit",
    pagination.limit,
    limit,
  );
  TestValidator.predicate(
    "records should be >= number of returned admin users",
    pagination.records >= firstPage.data.length,
  );
  TestValidator.predicate("pages should be at least 1", pagination.pages >= 1);

  // Helper to check if created_at is within [from, to] inclusive
  const isWithinRange = (
    value: string & tags.Format<"date-time">,
    from: string & tags.Format<"date-time">,
    to: string & tags.Format<"date-time">,
  ): boolean => value >= from && value <= to;

  // Validate every result row's created_at is within [createdFrom, createdTo]
  for (const summary of firstPage.data) {
    TestValidator.predicate(
      "every returned admin's created_at lies within the specified range",
      isWithinRange(summary.created_at, createdFrom, createdTo),
    );
  }

  const resultIds = firstPage.data.map((s) => s.id);

  // Confirm earliest admin is excluded only when its created_at is strictly before createdFrom
  if (earliest.created_at < createdFrom) {
    TestValidator.predicate(
      "earliest admin should not appear when filtering from middle to latest",
      resultIds.includes(earliest.id) === false,
    );
  }

  TestValidator.predicate(
    "at least one of middle or latest admins should appear in the filtered results",
    resultIds.includes(middle.id) || resultIds.includes(latest.id),
  );

  // 9. Stability check: call the same request again and compare data arrays
  const secondPage: IPageITodoAppAdminUser.ISummary =
    await api.functional.todoApp.adminUser.adminUsers.index(connection, {
      body: requestBody,
    });
  typia.assert(secondPage);

  TestValidator.equals(
    "subsequent search with identical filter should return the same admin list",
    secondPage.data,
    firstPage.data,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";

export async function test_api_admin_user_delete_with_valid_policies(
  connection: api.IConnection,
) {
  // 1. Register Admin B (target admin to be deleted later)
  const adminBJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminB: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminBJoinBody,
    });
  typia.assert(adminB);

  const adminBId = adminB.id;

  // 2. Register Admin A (acting administrator who will configure settings and delete Admin B)
  const adminAJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminA: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminAJoinBody,
    });
  typia.assert(adminA);

  // At this point, connection is authenticated as Admin A.

  // 3. Create required system setting as Admin A to represent policies enabling admin deletion
  const settingKey = "enable_admin_delete";
  const systemSettingCreateBody = {
    key: settingKey,
    value: "true",
    type: "boolean",
    description: "Enable destructive admin user deletion",
    group: "admin_policies",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const createdSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: systemSettingCreateBody,
    });
  typia.assert(createdSetting);

  TestValidator.equals(
    "created system setting key must match input key",
    createdSetting.key,
    settingKey,
  );

  // 4. Perform deletion of Admin B as Admin A
  await api.functional.todoApp.adminUser.adminUsers.erase(connection, {
    adminUserId: adminBId,
  });

  // 5. Verify that attempting to delete Admin B again fails, proving irreversible deletion
  await TestValidator.error(
    "cannot delete an already removed admin user",
    async () => {
      await api.functional.todoApp.adminUser.adminUsers.erase(connection, {
        adminUserId: adminBId,
      });
    },
  );

  // 6. Verify Admin A remains functional by creating another system setting after deletion
  const secondSettingKey =
    "post_delete_admin_setting_" + RandomGenerator.alphaNumeric(8);

  const secondSettingCreateBody = {
    key: secondSettingKey,
    value: "1",
    type: "int",
    description:
      "A setting created after deleting another admin to confirm Admin A still works",
    group: "admin_policies",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const secondSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: secondSettingCreateBody,
    });
  typia.assert(secondSetting);

  TestValidator.equals(
    "second system setting key must match input key",
    secondSetting.key,
    secondSettingKey,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";

/**
 * Validate self-deletion behavior for an admin user and protection of
 * post-deletion admin operations.
 *
 * ## Business intent
 *
 * This E2E test covers the workflow where a single administrative user (Admin
 * A) registers, establishes an authenticated admin session, creates at least
 * one global system setting, and then attempts to delete their own admin
 * account using the dedicated DELETE
 * /todoApp/adminUser/adminUsers/{adminUserId} endpoint.
 *
 * Because we do not have a direct "me" or login endpoint beyond join, and we
 * cannot directly query admin users, we validate self-deletion behavior
 * indirectly:
 *
 * - First, Admin A successfully creates a configuration entry via the admin-only
 *   POST /todoApp/adminUser/systemSettings endpoint.
 * - Then Admin A sends DELETE /todoApp/adminUser/adminUsers/{adminUserId}
 *   targeting their own id, which should remove or disable the account and/or
 *   session according to backend policy.
 * - Finally, we attempt another admin-only systemSettings.create call. The test
 *   expects that an error is thrown, demonstrating that self-deleted admins can
 *   no longer perform admin-only operations.
 *
 * This flow also ensures that a relevant system setting exists prior to
 * self-deletion, satisfying the requirement that business rules may depend on
 * preconfigured system settings.
 *
 * ## Steps
 *
 * 1. Register and authenticate Admin A via POST /auth/adminUser/join.
 * 2. As Admin A, create a system setting representing a policy key (e.g.,
 *    "admin_self_delete_policy").
 * 3. Delete Admin A using DELETE /todoApp/adminUser/adminUsers/{adminUserId} with
 *    adminUserId equal to Admin A's id.
 * 4. Attempt another POST /todoApp/adminUser/systemSettings call with a new key,
 *    expecting the call to fail (any error) via TestValidator.error, which
 *    models protection against continued admin operations after self-deletion.
 */
export async function test_api_admin_user_delete_self_protection(
  connection: api.IConnection,
) {
  // 1. Register and authenticate Admin A
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppAdminUser.IJoin;

  const admin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert(admin);

  TestValidator.predicate(
    "admin id should be a non-empty uuid string",
    () => admin.id.length > 0,
  );

  // 2. Create an initial system setting as Admin A
  const firstSettingKey = "admin_self_delete_policy";
  const firstSettingBody = {
    key: firstSettingKey,
    value: "enabled",
    type: "string",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "admin_policy",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const initialSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: firstSettingBody,
    });
  typia.assert(initialSetting);

  TestValidator.equals(
    "created system setting key should match input",
    initialSetting.key,
    firstSettingKey,
  );

  // 3. Self-delete admin using DELETE /todoApp/adminUser/adminUsers/{adminUserId}
  await api.functional.todoApp.adminUser.adminUsers.erase(connection, {
    adminUserId: admin.id,
  });

  // 4. Attempt another admin-only operation after self-deletion.
  //    We expect this to fail (any error), indicating the self-deleted
  //    admin can no longer perform admin-only operations.
  const secondSettingKey = "admin_self_delete_policy_post_delete_marker";
  const secondSettingBody = {
    key: secondSettingKey,
    value: "after_delete_attempt",
    type: "string",
    description: RandomGenerator.paragraph({ sentences: 2 }),
    group: "admin_policy",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  await TestValidator.error(
    "admin should not be able to create settings after self-deletion",
    async () => {
      await api.functional.todoApp.adminUser.systemSettings.create(connection, {
        body: secondSettingBody,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";

/**
 * Validate that deleting an administrative user requires proper authentication.
 *
 * Business goal:
 *
 * - Ensure that destructive admin operations, such as permanently deleting a
 *   todo_app_adminusers row, cannot be invoked by anonymous or unauthenticated
 *   clients, even when system settings are present.
 * - Confirm that system settings creation itself is also protected by adminUser
 *   authentication.
 *
 * Test steps:
 *
 * 1. Create an "anonymous" connection by cloning the given connection with empty
 *    headers, then attempt to call POST /todoApp/adminUser/systemSettings using
 *    that connection. This should fail with an HTTP authorization error (401 or
 *    403) because only authenticated adminUser actors may manage system
 *    settings.
 * 2. Call POST /auth/adminUser/join to register Admin A. This creates an admin
 *    account and, via the SDK, configures the connection with a valid
 *    Authorization header for the adminUser actor. Assert the returned
 *    ITodoAppAdminUser.IAuthorized payload.
 * 3. Using the authenticated connection (Admin A), call POST
 *    /todoApp/adminUser/systemSettings with a valid
 *    ITodoAppSystemSetting.ICreate body and assert the created
 *    ITodoAppSystemSetting response to verify that authorized admins can manage
 *    system settings successfully.
 * 4. Still on the same connection, call POST /auth/adminUser/join again to
 *    register Admin B and capture the returned id from
 *    ITodoAppAdminUser.IAuthorized. This id will be the deletion target.
 * 5. Construct another unauthenticated connection (headers: {}), then attempt to
 *    delete Admin B by calling DELETE
 *    /todoApp/adminUser/adminUsers/{adminUserId} with Admin B's id. Use
 *    TestValidator.httpError to assert that this operation fails with an HTTP
 *    error status of 401 or 403, proving that anonymous or improperly
 *    authenticated clients cannot perform irreversible admin deletions.
 *
 * Under current API surface, there is no admin-user GET or search endpoint
 * available to verify persistence of Admin B after the failed delete. The test
 * therefore focuses on verifying that the unauthorized erase attempt results in
 * an authentication/authorization error, which is sufficient to validate the
 * enforcement of authentication for this destructive operation.
 */
export async function test_api_admin_user_delete_requires_authentication(
  connection: api.IConnection,
) {
  // 1. Try to create system settings without authentication
  const anonymousConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  await TestValidator.httpError(
    "creating system settings without auth must fail",
    [401, 403],
    async () => {
      await api.functional.todoApp.adminUser.systemSettings.create(
        anonymousConnection,
        {
          body: {
            key: RandomGenerator.alphabets(10),
            value: "100",
            type: "int",
            description: RandomGenerator.paragraph({ sentences: 3 }),
            group: "limits",
            enabled: true,
          } satisfies ITodoAppSystemSetting.ICreate,
        },
      );
    },
  );

  // 2. Join as Admin A (this will authenticate and set Authorization header)
  const adminA: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: RandomGenerator.alphaNumeric(16),
        display_name: RandomGenerator.name(),
        status: "active",
        ip: "127.0.0.1",
        href: "https://admin.todo-app.test/join",
        referrer: "https://admin.todo-app.test/landing",
      } satisfies ITodoAppAdminUser.IJoin,
    });
  typia.assert(adminA);

  // 3. As Admin A, successfully create a system setting
  const setting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: {
        key: RandomGenerator.alphabets(12),
        value: "50",
        type: "int",
        description: RandomGenerator.paragraph({ sentences: 2 }),
        group: "limits",
        enabled: true,
      } satisfies ITodoAppSystemSetting.ICreate,
    });
  typia.assert(setting);

  // 4. As Admin A, register Admin B, capturing id
  const adminB: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: RandomGenerator.alphaNumeric(16),
        display_name: RandomGenerator.name(),
        status: "active",
        ip: "127.0.0.1",
        href: "https://admin.todo-app.test/join",
        referrer: "https://admin.todo-app.test/landing",
      } satisfies ITodoAppAdminUser.IJoin,
    });
  typia.assert(adminB);

  // 5. Attempt to delete Admin B without authentication (no Authorization header)
  const unauthenticatedConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  await TestValidator.httpError(
    "unauthenticated delete of admin user must fail",
    [401, 403],
    async () => {
      await api.functional.todoApp.adminUser.adminUsers.erase(
        unauthenticatedConnection,
        {
          adminUserId: adminB.id,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";

export async function test_api_admin_user_status_update_to_suspended(
  connection: api.IConnection,
) {
  // 1. Register Admin A (policy-controlling admin) and authenticate
  const adminAEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const adminAPassword: string & tags.Format<"password"> =
    "AdminA!234" as string & tags.Format<"password">;

  const adminAJoinBody = {
    email: adminAEmail,
    password: adminAPassword,
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminA: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminAJoinBody,
    });
  typia.assert(adminA);

  // 2. As Admin A, create a system setting that could represent status policy
  const systemSettingBody = {
    key: "admin_status_policy",
    value: "active,suspended,disabled",
    type: "string",
    description: "Allowed admin status values and transitions",
    group: "admin_policies",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const systemSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: systemSettingBody,
    });
  typia.assert(systemSetting);

  TestValidator.equals(
    "created system setting key should match request",
    systemSetting.key,
    systemSettingBody.key,
  );

  // 3. Still as Admin A, register Admin B as an active admin
  const adminBEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const adminBPassword: string & tags.Format<"password"> =
    "AdminB!234" as string & tags.Format<"password">;

  const adminBJoinBody = {
    email: adminBEmail,
    password: adminBPassword,
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminBAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminBJoinBody,
    });
  typia.assert(adminBAuthorized);

  TestValidator.equals(
    "Admin B initial status is active",
    adminBAuthorized.status,
    "active",
  );

  const originalUpdatedAt: string & tags.Format<"date-time"> =
    adminBAuthorized.updated_at;

  // 3-1. Re-login as Admin A so that subsequent status update is performed
  // under Admin A's authenticated context (policy-controlling admin).
  const adminALoginBody = {
    email: adminAEmail,
    password: adminAPassword,
    ip: "127.0.0.1",
    href: "https://admin.example.com/login",
    referrer: "https://admin.example.com/landing",
  } satisfies ITodoAppAdminUser.ILogin;

  const adminALogin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminALoginBody,
    });
  typia.assert(adminALogin);

  TestValidator.equals(
    "Admin A login id should match join id",
    adminALogin.id,
    adminA.id,
  );

  // 4. As Admin A, change Admin B's status to suspended via the status endpoint
  const updateStatusBody = {
    status: "suspended",
    reason: "Policy violation for testing suspension",
  } satisfies ITodoAppAdminUser.IUpdateStatus;

  const updatedAdminB: ITodoAppAdminUser =
    await api.functional.todoApp.adminUser.adminUsers.status.updateStatus(
      connection,
      {
        adminUserId: adminBAuthorized.id,
        body: updateStatusBody,
      },
    );
  typia.assert(updatedAdminB);

  // 5. Assert basic fields on the updated admin record
  TestValidator.equals(
    "updated admin user id should stay the same",
    updatedAdminB.id,
    adminBAuthorized.id,
  );

  TestValidator.equals(
    "updated admin user status should be suspended",
    updatedAdminB.status,
    updateStatusBody.status,
  );

  TestValidator.notEquals(
    "updated_at should change after status update",
    updatedAdminB.updated_at,
    originalUpdatedAt,
  );

  // 6. Attempt to log in as Admin B after suspension; login must be rejected
  await TestValidator.error("suspended admin cannot log in", async () => {
    const loginBody = {
      email: adminBEmail,
      password: adminBPassword,
      ip: "127.0.0.1",
      href: "https://admin.example.com/login",
      referrer: "https://admin.example.com/landing",
    } satisfies ITodoAppAdminUser.ILogin;

    await api.functional.auth.adminUser.login(connection, {
      body: loginBody,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";

/**
 * Validate that updating an admin user's status to a terminal disabled state is
 * applied correctly and that a subsequent attempt to reactivate that user
 * fails, leaving the status unchanged.
 *
 * Business flow:
 *
 * 1. Register Admin A (controller admin) via /auth/adminUser/join; the connection
 *    becomes authenticated as Admin A.
 * 2. As Admin A, create at least one system setting that conceptually supports a
 *    policy where certain statuses, like "disabled", are treated as terminal.
 *    The exact policy logic is hidden in the backend, but the setting simulates
 *    a configuration-based rule.
 * 3. As Admin A, register Admin B via /auth/adminUser/join and capture its id and
 *    initial updated_at timestamp.
 * 4. As Admin A, call PUT /todoApp/adminUser/adminUsers/{adminUserId}/status to
 *    set Admin B's status to "disabled" with a human-readable reason, and
 *    verify that the returned ITodoAppAdminUser reflects the new status and an
 *    updated updated_at timestamp.
 * 5. Attempt to re-activate Admin B by calling the same endpoint with status
 *    "active". Use TestValidator.error to ensure that this transition fails,
 *    without asserting any specific HTTP status code or message.
 * 6. Confirm that the only successful status change for Admin B is the one that
 *    set it to "disabled", by relying on the first successful update response
 *    and the absence of any successful second response.
 */
export async function test_api_admin_user_status_update_to_disabled_and_irreversible(
  connection: api.IConnection,
) {
  // 1. Register Admin A and authenticate
  const adminAJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todo-app.test/join",
    referrer: "https://admin.todo-app.test/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminA: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminAJoinBody,
    });
  typia.assert(adminA);

  // 2. Configure system settings that conceptually define terminal statuses
  const terminalStatusSettingBody = {
    key: "admin_status_disabled_terminal",
    value: "true",
    type: "boolean",
    description:
      "If true, the 'disabled' status for admin users is treated as a terminal, non-reversible state.",
    group: "admin_status_policy",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const terminalStatusSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: terminalStatusSettingBody,
    });
  typia.assert(terminalStatusSetting);
  TestValidator.equals(
    "system setting key should match the configured terminal status key",
    terminalStatusSetting.key,
    terminalStatusSettingBody.key,
  );

  // 3. Register Admin B as the target admin user
  const adminBJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todo-app.test/join",
    referrer: "https://admin.todo-app.test/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminBAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminBJoinBody,
    });
  typia.assert(adminBAuthorized);

  const adminBId = adminBAuthorized.id;
  const adminBInitialUpdatedAt = adminBAuthorized.updated_at;

  // 4. Update Admin B status to "disabled" with a reason
  const disableStatusBody = {
    status: "disabled",
    reason: "Security policy enforcement: account disabled by super-admin.",
  } satisfies ITodoAppAdminUser.IUpdateStatus;

  const disabledAdminB: ITodoAppAdminUser =
    await api.functional.todoApp.adminUser.adminUsers.status.updateStatus(
      connection,
      {
        adminUserId: adminBId,
        body: disableStatusBody,
      },
    );
  typia.assert(disabledAdminB);

  TestValidator.equals(
    "disabled admin id should match Admin B id",
    disabledAdminB.id,
    adminBId,
  );
  TestValidator.equals(
    "admin B status should be updated to disabled",
    disabledAdminB.status,
    disableStatusBody.status,
  );

  // Ensure updated_at changed compared to the initial authorized payload
  TestValidator.notEquals(
    "updated_at should change after disabling admin B",
    disabledAdminB.updated_at,
    adminBInitialUpdatedAt,
  );

  // 5. Attempt to re-activate Admin B; expect an error without asserting status code
  const reactivateStatusBody = {
    status: "active",
    reason: "Attempted reactivation for testing purposes.",
  } satisfies ITodoAppAdminUser.IUpdateStatus;

  await TestValidator.error(
    "reactivating a disabled admin user should be rejected by business rules",
    async () => {
      await api.functional.todoApp.adminUser.adminUsers.status.updateStatus(
        connection,
        {
          adminUserId: adminBId,
          body: reactivateStatusBody,
        },
      );
    },
  );

  // 6. Confirm that the only successful status for Admin B is the disabled state
  // Since there is no GET endpoint, rely on the fact that the second call
  // failed (no ITodoAppAdminUser returned) and that the last known successful
  // state is disabledAdminB with status "disabled".
  TestValidator.equals(
    "final known status for Admin B remains disabled after failed reactivation",
    disabledAdminB.status,
    "disabled",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";

export async function test_api_admin_user_status_update_requires_authentication(
  connection: api.IConnection,
) {
  // 1. Prepare an unauthenticated connection clone with empty headers
  const unauthConnection: api.IConnection = { ...connection, headers: {} };

  // 2. Attempt to update status without authentication and expect an error
  await TestValidator.error(
    "unauthenticated admin status update must fail",
    async () => {
      await api.functional.todoApp.adminUser.adminUsers.status.updateStatus(
        unauthConnection,
        {
          adminUserId: typia.random<string & tags.Format<"uuid">>(),
          body: {
            status: "suspended",
          } satisfies ITodoAppAdminUser.IUpdateStatus,
        },
      );
    },
  );

  // 3. Register Admin A via /auth/adminUser/join (this will also set Authorization header)
  const adminAJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminA: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminAJoinBody,
    });
  typia.assert(adminA);

  // Preserve Admin A's authenticated connection for later use
  const adminAConnection: api.IConnection = { ...connection };

  // 4. As Admin A, create a system setting that could govern status transitions
  const settingCreateBody = {
    key: "admin_status_allowed_transitions",
    value: "active,suspended,disabled",
    type: "string",
    description: "Allowed admin status values for transitions",
    group: "adminUser",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const systemSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(
      adminAConnection,
      {
        body: settingCreateBody,
      },
    );
  typia.assert(systemSetting);
  TestValidator.equals(
    "system setting key must match",
    systemSetting.key,
    settingCreateBody.key,
  );

  // 5. Create Admin B via another join call, using a fresh base connection clone
  const baseConnectionForAdminB: api.IConnection = { ...connection };
  const adminBJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminB: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(baseConnectionForAdminB, {
      body: adminBJoinBody,
    });
  typia.assert(adminB);

  // 6. As Admin A (using preserved connection), update Admin B's status to suspended
  const updateBody = {
    status: "suspended",
    reason: "Security review",
  } satisfies ITodoAppAdminUser.IUpdateStatus;

  const updatedAdminB: ITodoAppAdminUser =
    await api.functional.todoApp.adminUser.adminUsers.status.updateStatus(
      adminAConnection,
      {
        adminUserId: adminB.id,
        body: updateBody,
      },
    );
  typia.assert(updatedAdminB);

  // 7. Validate that the correct admin user was updated and status changed as expected
  TestValidator.equals(
    "updated admin user id must match Admin B id",
    updatedAdminB.id,
    adminB.id,
  );
  TestValidator.equals(
    "admin status must be updated to suspended",
    updatedAdminB.status,
    updateBody.status,
  );

  // 8. Sanity checks that Admin A and Admin B are distinct accounts
  TestValidator.notEquals(
    "Admin A and Admin B must be distinct accounts",
    adminA.id,
    adminB.id,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppMemberUser";
import type { IPageITodoAppMemberUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppMemberUserSession";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserSession";

/**
 * Basic pagination and scoping test for member user session listing.
 *
 * Business goal
 *
 * - Ensure that an authenticated admin user can list sessions for a particular
 *   member user via PATCH
 *   /todoApp/adminUser/memberUsers/{memberUserId}/sessions.
 * - Verify that pagination parameters (page, limit) from the request are
 *   reflected in the response pagination block.
 * - Verify that each returned session summary belongs to the requested member
 *   user.
 *
 * High-level workflow
 *
 * 1. Register a fresh admin user with /auth/adminUser/join. The SDK will
 *    automatically store the access token in connection.headers so that
 *    subsequent todoApp adminUser endpoints are authorized.
 * 2. Search member users with /todoApp/adminUser/memberUsers using a simple filter
 *    (first page, small limit) to obtain at least one member user summary (or
 *    an empty page when there are no members).
 * 3. If there is at least one member user, pick the first one and request its
 *    sessions using /todoApp/adminUser/memberUsers/{memberUserId}/sessions with
 *    ITodoAppMemberUserSession.IRequest specifying page and limit.
 * 4. Assert that the response matches IPageITodoAppMemberUserSession.ISummary and
 *    that:
 *
 *    - Pagination.current equals the requested page
 *    - Pagination.limit equals the requested limit
 *    - Every item in data has memberUser.id equal to the selected member user id
 * 5. If there are no member users, the test still passes by simply asserting the
 *    member user list page shape and skipping the session listing call (since
 *    there is no concrete member user to inspect).
 */
export async function test_api_admin_memberuser_sessions_list_basic_pagination(
  connection: api.IConnection,
) {
  // 1. Register an admin user and get authorized context
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todo-app.local/join",
    referrer: "https://admin.todo-app.local/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminAuthorized);
  typia.assert<IAuthorizationToken>(adminAuthorized.token);

  // 2. Search for member users with a small page size
  const memberPageParam = typia.random<
    number & tags.Type<"int32"> & tags.Minimum<1>
  >();
  const memberLimitParam = typia.random<
    number & tags.Type<"int32"> & tags.Minimum<1>
  >();

  const memberUserRequest = {
    page: memberPageParam,
    limit: memberLimitParam,
  } satisfies ITodoAppMemberUser.IRequest;

  const memberPage: IPageITodoAppMemberUser.ISummary =
    await api.functional.todoApp.adminUser.memberUsers.index(connection, {
      body: memberUserRequest,
    });
  typia.assert<IPageITodoAppMemberUser.ISummary>(memberPage);

  // Basic pagination echo assertions on member user list
  TestValidator.equals(
    "member user list - pagination.current should echo requested page",
    memberPage.pagination.current,
    memberUserRequest.page,
  );
  TestValidator.equals(
    "member user list - pagination.limit should echo requested limit",
    memberPage.pagination.limit,
    memberUserRequest.limit,
  );

  if (memberPage.data.length === 0) {
    // No member users to inspect. Test passes after verifying basic shape.
    TestValidator.equals(
      "member user list can be empty when there are no members",
      memberPage.pagination.records,
      0,
    );
    return;
  }

  // 3. Pick the first member user to inspect sessions
  const targetMember: ITodoAppMemberUser.ISummary = memberPage.data[0];
  typia.assert<ITodoAppMemberUser.ISummary>(targetMember);

  const sessionPageParam = typia.random<
    number & tags.Type<"int32"> & tags.Minimum<1>
  >();
  const sessionLimitParam = typia.random<
    number & tags.Type<"int32"> & tags.Minimum<1>
  >();

  const sessionRequest = {
    page: sessionPageParam,
    limit: sessionLimitParam,
  } satisfies ITodoAppMemberUserSession.IRequest;

  const sessionsPage: IPageITodoAppMemberUserSession.ISummary =
    await api.functional.todoApp.adminUser.memberUsers.sessions.index(
      connection,
      {
        memberUserId: targetMember.id,
        body: sessionRequest,
      },
    );
  typia.assert<IPageITodoAppMemberUserSession.ISummary>(sessionsPage);

  // 4. Assert pagination echo for sessions listing
  TestValidator.equals(
    "sessions list - pagination.current should echo requested page",
    sessionsPage.pagination.current,
    sessionRequest.page,
  );
  TestValidator.equals(
    "sessions list - pagination.limit should echo requested limit",
    sessionsPage.pagination.limit,
    sessionRequest.limit,
  );

  // 5. Validate each session summary belongs to the selected member user
  for (const session of sessionsPage.data) {
    typia.assert<ITodoAppMemberUserSession.ISummary>(session);
    TestValidator.equals(
      "every session summary must belong to the requested member user",
      session.memberUser.id,
      targetMember.id,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppMemberUser";
import type { IPageITodoAppMemberUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppMemberUserSession";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserSession";

/**
 * Validate that an authenticated admin can paginate and sort member user
 * sessions.
 *
 * Business goals:
 *
 * - Ensure admin registration and authentication works (join endpoint).
 * - Ensure admin member user search returns at least one member user when data
 *   exists, but gracefully skip the rest of the test when there are none.
 * - Verify that the sessions listing endpoint correctly applies page/limit and
 *   returns sessions for the given member user only.
 * - Validate that sorting by created_at in descending order is consistent within
 *   each page, and cross-page uniqueness is respected when enough sessions
 *   exist.
 */
export async function test_api_admin_memberuser_sessions_list_with_sorting_and_multiple_pages(
  connection: api.IConnection,
) {
  // 1. Register an admin and authenticate (token handled by SDK).
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12) as string &
      tags.Format<"password">,
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todoapp.local/join" as string & tags.Format<"uri">,
    referrer: "https://admin.todoapp.local/" as string & tags.Format<"uri">,
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. As admin, search member users and pick one.
  const memberSearchBody = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 20 as number & tags.Type<"int32"> & tags.Minimum<1>,
    order_by: "created_at",
    order_direction: "desc",
  } satisfies ITodoAppMemberUser.IRequest;

  const memberPage: IPageITodoAppMemberUser.ISummary =
    await api.functional.todoApp.adminUser.memberUsers.index(connection, {
      body: memberSearchBody,
    });
  typia.assert(memberPage);

  TestValidator.predicate(
    "member search returns pagination",
    () =>
      memberPage.pagination.limit >= 0 && memberPage.pagination.current >= 0,
  );

  TestValidator.predicate(
    "member search data length within limit",
    () => memberPage.data.length <= memberPage.pagination.limit,
  );

  const hasMember = memberPage.data.length > 0;
  if (!hasMember) return;

  const targetMember: ITodoAppMemberUser.ISummary = memberPage.data[0];

  // 3. Request first page of sessions for the selected member user.
  const sessionsRequestPage1 = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 5 as number & tags.Type<"int32"> & tags.Minimum<1>,
    orderBy: "created_at",
    orderDirection: "desc",
  } satisfies ITodoAppMemberUserSession.IRequest;

  const page1: IPageITodoAppMemberUserSession.ISummary =
    await api.functional.todoApp.adminUser.memberUsers.sessions.index(
      connection,
      {
        memberUserId: targetMember.id,
        body: sessionsRequestPage1,
      },
    );
  typia.assert(page1);

  TestValidator.equals(
    "page1 pagination.current should be 1",
    page1.pagination.current,
    1 as number & tags.Type<"int32"> & tags.Minimum<0>,
  );
  TestValidator.equals(
    "page1 pagination.limit should be 5",
    page1.pagination.limit,
    5 as number & tags.Type<"int32"> & tags.Minimum<0>,
  );
  TestValidator.predicate(
    "page1 data length <= limit",
    () => page1.data.length <= page1.pagination.limit,
  );

  for (const session of page1.data) {
    TestValidator.equals(
      "session.memberUser.id matches target member id on page1",
      session.memberUser.id,
      targetMember.id,
    );
  }

  // Verify descending created_at ordering within page1.
  for (let i = 1; i < page1.data.length; ++i) {
    const prev = page1.data[i - 1];
    const curr = page1.data[i];
    TestValidator.predicate(
      `page1 created_at[${i - 1}] >= created_at[${i}] in desc order`,
      () => prev.created_at >= curr.created_at,
    );
  }

  // 4. Request second page with the same criteria.
  const sessionsRequestPage2 = {
    page: 2 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 5 as number & tags.Type<"int32"> & tags.Minimum<1>,
    orderBy: "created_at",
    orderDirection: "desc",
  } satisfies ITodoAppMemberUserSession.IRequest;

  const page2: IPageITodoAppMemberUserSession.ISummary =
    await api.functional.todoApp.adminUser.memberUsers.sessions.index(
      connection,
      {
        memberUserId: targetMember.id,
        body: sessionsRequestPage2,
      },
    );
  typia.assert(page2);

  TestValidator.equals(
    "page2 pagination.current should be 2",
    page2.pagination.current,
    2 as number & tags.Type<"int32"> & tags.Minimum<0>,
  );
  TestValidator.equals(
    "page2 pagination.limit should be 5",
    page2.pagination.limit,
    5 as number & tags.Type<"int32"> & tags.Minimum<0>,
  );
  TestValidator.predicate(
    "page2 data length <= limit",
    () => page2.data.length <= page2.pagination.limit,
  );

  for (const session of page2.data) {
    TestValidator.equals(
      "session.memberUser.id matches target member id on page2",
      session.memberUser.id,
      targetMember.id,
    );
  }

  for (let i = 1; i < page2.data.length; ++i) {
    const prev = page2.data[i - 1];
    const curr = page2.data[i];
    TestValidator.predicate(
      `page2 created_at[${i - 1}] >= created_at[${i}] in desc order`,
      () => prev.created_at >= curr.created_at,
    );
  }

  // 5. Cross-page uniqueness and ordering checks if there are sufficient sessions.
  const allSessions = [...page1.data, ...page2.data];
  const idSet = new Set(allSessions.map((s) => s.id));

  TestValidator.predicate(
    "no duplicate session ids across page1 and page2",
    () => idSet.size === allSessions.length,
  );

  if (page1.data.length >= 5 && page2.data.length >= 5) {
    TestValidator.equals(
      "combined pages have 10 unique session ids when both pages full",
      idSet.size,
      10 as number & tags.Type<"int32"> & tags.Minimum<0>,
    );
  }

  if (page1.data.length > 0 && page2.data.length > 0) {
    const lastPage1 = page1.data[page1.data.length - 1];
    const firstPage2 = page2.data[0];
    TestValidator.predicate(
      "last created_at on page1 should be >= first created_at on page2",
      () => lastPage1.created_at >= firstPage2.created_at,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppMemberUser";
import type { IPageITodoAppMemberUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppMemberUserSession";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserSession";

export async function test_api_admin_memberuser_sessions_list_empty_result_for_member_without_sessions(
  connection: api.IConnection,
) {
  // 1. Register an admin user and establish an authenticated admin context
  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: typia.random<ITodoAppAdminUser.IJoin>(),
    });
  typia.assert(adminAuthorized);

  // 2. Query member users to obtain a real memberUserId to test with
  const memberUsersPage: IPageITodoAppMemberUser.ISummary =
    await api.functional.todoApp.adminUser.memberUsers.index(connection, {
      body: {
        page: 1,
        limit: 1,
      } satisfies ITodoAppMemberUser.IRequest,
    });
  typia.assert(memberUsersPage);

  // Guard: ensure we have at least one member user to run the test against
  TestValidator.predicate(
    "there is at least one member user to test sessions listing",
    memberUsersPage.data.length > 0,
  );

  const targetMember = memberUsersPage.data[0];
  typia.assert<ITodoAppMemberUser.ISummary>(targetMember);

  // 3. Initial call to sessions listing for the chosen member, page=1
  const firstSessionsPage: IPageITodoAppMemberUserSession.ISummary =
    await api.functional.todoApp.adminUser.memberUsers.sessions.index(
      connection,
      {
        memberUserId: targetMember.id,
        body: {
          page: 1,
          limit: 2,
        } satisfies ITodoAppMemberUserSession.IRequest,
      },
    );
  typia.assert(firstSessionsPage);

  const initialPagination = firstSessionsPage.pagination;
  const initialRecords = initialPagination.records;
  const initialLimit = initialPagination.limit;

  // 4. Compute an out-of-range page that must yield an empty result
  const effectiveLimit = initialLimit === 0 ? 1 : initialLimit;
  const lastPage =
    initialRecords === 0 ? 0 : Math.ceil(initialRecords / effectiveLimit);
  const outOfRangePage = lastPage + 2;

  // 5. Request the out-of-range page for the same member user sessions
  const emptySessionsPage: IPageITodoAppMemberUserSession.ISummary =
    await api.functional.todoApp.adminUser.memberUsers.sessions.index(
      connection,
      {
        memberUserId: targetMember.id,
        body: {
          page: outOfRangePage,
          limit: effectiveLimit,
        } satisfies ITodoAppMemberUserSession.IRequest,
      },
    );
  typia.assert(emptySessionsPage);

  const emptyPagination = emptySessionsPage.pagination;

  // 6. Validate pagination metadata matches the requested page and limit
  TestValidator.equals(
    "pagination.current should equal requested out-of-range page",
    emptyPagination.current,
    outOfRangePage,
  );

  TestValidator.equals(
    "pagination.limit should equal requested limit",
    emptyPagination.limit,
    effectiveLimit,
  );

  // 7. Validate that data is empty for out-of-range page
  TestValidator.equals(
    "out-of-range sessions listing should return empty data array",
    emptySessionsPage.data.length,
    0,
  );

  // 8. Validate records count remains consistent with initial query
  TestValidator.equals(
    "total records count should remain consistent across pages",
    emptyPagination.records,
    initialRecords,
  );

  // 9. Validate pages is the ceiling of records/limit and non-negative
  const expectedPages =
    initialRecords === 0 ? 0 : Math.ceil(initialRecords / effectiveLimit);

  TestValidator.equals(
    "pages should be consistent with records and limit",
    emptyPagination.pages,
    expectedPages,
  );

  TestValidator.predicate(
    "pagination.pages must be non-negative",
    emptyPagination.pages >= 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppMemberUser";
import type { IPageITodoAppMemberUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppMemberUserSession";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserSession";

/**
 * Verify that listing sessions for a non-existent member user returns a
 * not-found error.
 *
 * Business context: Administrative users can inspect authentication sessions
 * for individual member users via PATCH
 * /todoApp/adminUser/memberUsers/{memberUserId}/sessions. When the target
 * member user does not exist, the backend should _not_ respond with a
 * successful empty page, but rather with a clear not-found style HTTP error
 * (typically 404) indicating that the target member user cannot be resolved.
 *
 * Scenario steps:
 *
 * 1. Join as an admin user using POST /auth/adminUser/join, which also configures
 *    Authorization on the shared `connection`.
 * 2. Optionally call PATCH /todoApp/adminUser/memberUsers with a broad
 *    ITodoAppMemberUser.IRequest to simulate a realistic environment and to
 *    demonstrate typical pagination usage (the specific ids are not used).
 * 3. Generate a random UUID to act as a fake memberUserId that we never create as
 *    a real member user.
 * 4. Call PATCH /todoApp/adminUser/memberUsers/{memberUserId}/sessions with a
 *    normal ITodoAppMemberUserSession.IRequest body (page/limit/orderBy) using
 *    that fake memberUserId.
 * 5. Assert via TestValidator.httpError that this call throws an HttpError with a
 *    not-found status code (404), proving the service rejects requests
 *    targeting non-existent member users instead of returning a successful
 *    empty list.
 */
export async function test_api_admin_memberuser_sessions_list_nonexistent_memberuser_returns_not_found(
  connection: api.IConnection,
) {
  // 1. Admin join to obtain an authenticated admin context
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphabets(12),
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todo-app.local/join",
    referrer: "https://admin.todo-app.local/",
  } satisfies ITodoAppAdminUser.IJoin;

  const admin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(admin);

  // 2. Optional: index member users with a simple request to demonstrate
  // pagination usage (response not used beyond type assertion).
  const memberUsersRequest = {
    page: 1,
    limit: 10,
    search: undefined,
    status: undefined,
    created_from: undefined,
    created_to: undefined,
    order_by: "created_at",
    order_direction: "desc",
  } satisfies ITodoAppMemberUser.IRequest;

  const memberUsersPage: IPageITodoAppMemberUser.ISummary =
    await api.functional.todoApp.adminUser.memberUsers.index(connection, {
      body: memberUsersRequest,
    });
  typia.assert(memberUsersPage);

  // 3. Generate a random UUID as a fake memberUserId that should not exist.
  const nonexistentMemberUserId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();

  // 4. Prepare a normal sessions listing request body with sane pagination.
  const sessionsRequest = {
    page: 1,
    limit: 10,
    orderBy: "created_at",
    orderDirection: "desc",
  } satisfies ITodoAppMemberUserSession.IRequest;

  // 5. Assert that calling sessions.index with the non-existent memberUserId
  // results in an HTTP not-found style error (404).
  await TestValidator.httpError(
    "listing sessions for non-existent member user returns not-found error",
    404,
    async () => {
      await api.functional.todoApp.adminUser.memberUsers.sessions.index(
        connection,
        {
          memberUserId: nonexistentMemberUserId,
          body: sessionsRequest,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppMemberUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppMemberUserSession";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserSession";

/**
 * Verify that listing member user sessions requires admin authentication and
 * works with a valid admin token.
 *
 * Business goal:
 *
 * - Ensure that the administrative session listing endpoint PATCH
 *   /todoApp/adminUser/memberUsers/{memberUserId}/sessions cannot be called
 *   anonymously.
 * - Confirm that, once an admin user has joined (and thus is authenticated), the
 *   same endpoint can be called successfully and returns data matching
 *   IPageITodoAppMemberUserSession.ISummary.
 *
 * Scenario rewrite and constraints:
 *
 * - We cannot manipulate connection.headers directly; instead we construct a
 *   derived unauthenticated connection with headers: {}.
 * - We do not have a dedicated member user factory, so we use a random UUID for
 *   memberUserId; backend behavior for unknown member users is not asserted
 *   here beyond type-level success.
 * - HTTP status codes are not asserted explicitly; instead we only assert that
 *   unauthenticated calls fail (throw) and authenticated calls succeed.
 */
export async function test_api_admin_memberuser_sessions_list_requires_admin_authentication(
  connection: api.IConnection,
) {
  // Use a fixed (but random) member user id for all calls in this test.
  const memberUserId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();

  // Base request body for listing sessions
  const requestBody: ITodoAppMemberUserSession.IRequest =
    typia.random<ITodoAppMemberUserSession.IRequest>();

  // 1. Build an unauthenticated connection (no headers at all).
  const unauthConn: api.IConnection = {
    ...connection,
    headers: {},
  };

  // 2. First unauthenticated call must fail.
  await TestValidator.error(
    "unauthenticated admin member user sessions listing should fail (first attempt)",
    async () => {
      await api.functional.todoApp.adminUser.memberUsers.sessions.index(
        unauthConn,
        {
          memberUserId,
          body: requestBody,
        },
      );
    },
  );

  // 3. Second unauthenticated call (representing missing/invalid token) must also fail.
  const secondRequestBody: ITodoAppMemberUserSession.IRequest =
    typia.random<ITodoAppMemberUserSession.IRequest>();

  await TestValidator.error(
    "unauthenticated admin member user sessions listing should fail (second attempt)",
    async () => {
      await api.functional.todoApp.adminUser.memberUsers.sessions.index(
