import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberUserRefresh } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserRefresh";

/**
 * Validate refresh token replay protection and rotation semantics.
 *
 * Business goal: Verify that the memberUser refresh endpoint enforces
 * single-use semantics for refresh tokens (replay protection) while continuing
 * to accept the latest issued refresh token. Also check that successful refresh
 * operations rotate access tokens so that each step gets a fresh credential
 * set.
 *
 * High-level steps:
 *
 * 1. Join a new member user account.
 * 2. Login with that account to obtain the initial ITodoAppMemberUser.IAuthorized
 *    containing token.access and token.refresh.
 * 3. Use refreshToken1 (from login) to perform a first refresh and capture
 *    refreshToken2.
 * 4. Attempt to refresh again using the original refreshToken1 and expect an error
 *    (TestValidator.error) to represent replay protection.
 * 5. Refresh again using refreshToken2 and expect success.
 * 6. Confirm all successful responses are structurally valid via typia.assert and
 *    that access tokens are rotated between steps.
 */
export async function test_api_member_user_refresh_replay_with_same_token(
  connection: api.IConnection,
) {
  // 1. Join new member user
  const joinBody = typia.random<ITodoAppMemberUserJoin.ICreate>();
  const joined: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert(joined);

  // 2. Login with same credentials to get initial tokens
  const loginBody = {
    email: joinBody.email,
    password: joinBody.password,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserLogin.ICreate;
  const loggedIn: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: loginBody,
    });
  typia.assert(loggedIn);

  const loginToken: IAuthorizationToken = loggedIn.token;
  const refreshToken1: string = loginToken.refresh;

  // 3. First refresh using refreshToken1
  const firstRefreshBody = {
    refresh_token: refreshToken1,
    ip: undefined,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserRefresh.ICreate;
  const firstRefreshed: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.refresh(connection, {
      body: firstRefreshBody,
    });
  typia.assert(firstRefreshed);

  const firstRefreshToken: IAuthorizationToken = firstRefreshed.token;
  const refreshToken2: string = firstRefreshToken.refresh;

  // Validate rotation of access token between login and first refresh
  TestValidator.notEquals(
    "access token is rotated on first refresh",
    loginToken.access,
    firstRefreshToken.access,
  );

  // 4. Second refresh attempt using original refreshToken1 (expect error)
  const replayBody = {
    refresh_token: refreshToken1,
    ip: undefined,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserRefresh.ICreate;

  await TestValidator.error(
    "replay of already-used refresh token should fail",
    async () => {
      await api.functional.auth.memberUser.refresh(connection, {
        body: replayBody,
      });
    },
  );

  // 5. Refresh again using latest refreshToken2 (expect success)
  const secondRefreshBody = {
    refresh_token: refreshToken2,
    ip: undefined,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserRefresh.ICreate;

  const secondRefreshed: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.refresh(connection, {
      body: secondRefreshBody,
    });
  typia.assert(secondRefreshed);

  const secondRefreshToken: IAuthorizationToken = secondRefreshed.token;

  // 6. Confirm that access token rotates again and refresh token chain progresses
  TestValidator.notEquals(
    "access token is rotated on second refresh",
    firstRefreshToken.access,
    secondRefreshToken.access,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberUserRefresh } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserRefresh";

/**
 * Validate refresh token behavior after multiple logins for the same member
 * user.
 *
 * Business goal
 *
 * - Ensure that a single member user can log in multiple times (e.g., different
 *   devices) and then successfully use refresh tokens obtained from each login,
 *   without breaking the authentication contract.
 * - Confirm that refresh tokens are structurally valid and that refreshed
 *   sessions always represent the same member identity.
 *
 * High-level flow
 *
 * 1. Join a member user with stable email/password and connection metadata.
 * 2. Perform first login with one set of metadata (href/referrer/ip).
 * 3. Perform second login with a different set of metadata.
 * 4. Capture refresh tokens from both login responses.
 * 5. Call refresh using the first refresh token.
 * 6. Call refresh using the second refresh token.
 * 7. Validate identity consistency and token temporal properties across all
 *    responses.
 */
export async function test_api_member_user_refresh_after_multiple_logins(
  connection: api.IConnection,
) {
  // 1. Join a member user
  const email: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const password: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const joinBody = {
    email,
    password,
    displayName: RandomGenerator.name(),
    // Use IPv4-compatible string here; it still satisfies the union on ip.
    ip: "127.0.0.1",
    href: "https://todoapp.example.com/signup",
    referrer: "https://todoapp.example.com/landing",
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const joined: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert(joined);

  const memberId = joined.id;
  const memberEmail = joined.email;
  const memberStatus = joined.status;

  // 2. First login with one set of metadata
  const loginBody1 = {
    email,
    password,
    ip: "192.168.0.10",
    href: "https://todoapp.example.com/login?device=primary",
    referrer: "https://todoapp.example.com/home",
  } satisfies ITodoAppMemberUserLogin.ICreate;

  const login1: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: loginBody1,
    });
  typia.assert(login1);

  const firstRefresh: string = login1.token.refresh;

  // 3. Second login with different metadata
  const loginBody2 = {
    email,
    password,
    ip: "10.0.0.20",
    href: "https://m.todoapp.example.com/login?device=secondary",
    referrer: "https://m.todoapp.example.com/home",
  } satisfies ITodoAppMemberUserLogin.ICreate;

  const login2: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: loginBody2,
    });
  typia.assert(login2);

  const secondRefresh: string = login2.token.refresh;

  // Optional structural check: they may or may not differ; ensure non-empty
  TestValidator.predicate(
    "first refresh token should be non-empty",
    firstRefresh.length > 0,
  );
  TestValidator.predicate(
    "second refresh token should be non-empty",
    secondRefresh.length > 0,
  );

  // 4. Refresh with firstRefresh
  const refreshBody1 = {
    refresh_token: firstRefresh,
    // leave session_id undefined to allow server-side correlation
    ip: "203.0.113.5",
    href: "https://todoapp.example.com/refresh?token=first",
    referrer: "https://todoapp.example.com/app",
  } satisfies ITodoAppMemberUserRefresh.ICreate;

  const refreshed1: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.refresh(connection, {
      body: refreshBody1,
    });
  typia.assert(refreshed1);

  // Identity consistency for refreshed1
  TestValidator.equals(
    "refreshed1 id matches original member id",
    refreshed1.id,
    memberId,
  );
  TestValidator.equals(
    "refreshed1 email matches original member email",
    refreshed1.email,
    memberEmail,
  );
  TestValidator.equals(
    "refreshed1 status matches original member status",
    refreshed1.status,
    memberStatus,
  );

  const token1: IAuthorizationToken = refreshed1.token;
  typia.assert(token1);

  // 5. Refresh with secondRefresh
  const refreshBody2 = {
    refresh_token: secondRefresh,
    ip: "203.0.113.25",
    href: "https://todoapp.example.com/refresh?token=second",
    referrer: "https://todoapp.example.com/app",
  } satisfies ITodoAppMemberUserRefresh.ICreate;

  const refreshed2: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.refresh(connection, {
      body: refreshBody2,
    });
  typia.assert(refreshed2);

  // Identity consistency for refreshed2
  TestValidator.equals(
    "refreshed2 id matches original member id",
    refreshed2.id,
    memberId,
  );
  TestValidator.equals(
    "refreshed2 email matches original member email",
    refreshed2.email,
    memberEmail,
  );
  TestValidator.equals(
    "refreshed2 status matches original member status",
    refreshed2.status,
    memberStatus,
  );

  const token2: IAuthorizationToken = refreshed2.token;
  typia.assert(token2);

  // Validate that expiration-related fields are monotonic or at least not earlier.
  const joinedAccessExpires = new Date(joined.token.expired_at).getTime();
  const login1AccessExpires = new Date(login1.token.expired_at).getTime();
  const login2AccessExpires = new Date(login2.token.expired_at).getTime();
  const refresh1AccessExpires = new Date(token1.expired_at).getTime();
  const refresh2AccessExpires = new Date(token2.expired_at).getTime();

  TestValidator.predicate(
    "login1 access token expiration should be no earlier than joined access token expiration",
    login1AccessExpires >= joinedAccessExpires,
  );
  TestValidator.predicate(
    "login2 access token expiration should be no earlier than login1 access token expiration",
    login2AccessExpires >= login1AccessExpires,
  );
  TestValidator.predicate(
    "refresh1 access token expiration should be no earlier than login1 access token expiration",
    refresh1AccessExpires >= login1AccessExpires,
  );
  TestValidator.predicate(
    "refresh2 access token expiration should be no earlier than login2 access token expiration",
    refresh2AccessExpires >= login2AccessExpires,
  );

  // Also confirm refresh window fields are valid and not in the past relative to access expiry.
  const joinedRefreshable = new Date(joined.token.refreshable_until).getTime();
  const login1Refreshable = new Date(login1.token.refreshable_until).getTime();
  const login2Refreshable = new Date(login2.token.refreshable_until).getTime();
  const refresh1Refreshable = new Date(token1.refreshable_until).getTime();
  const refresh2Refreshable = new Date(token2.refreshable_until).getTime();

  TestValidator.predicate(
    "joined refresh window should be no earlier than joined access expiry",
    joinedRefreshable >= joinedAccessExpires,
  );
  TestValidator.predicate(
    "login1 refresh window should be no earlier than login1 access expiry",
    login1Refreshable >= login1AccessExpires,
  );
  TestValidator.predicate(
    "login2 refresh window should be no earlier than login2 access expiry",
    login2Refreshable >= login2AccessExpires,
  );
  TestValidator.predicate(
    "refresh1 refresh window should be no earlier than refresh1 access expiry",
    refresh1Refreshable >= refresh1AccessExpires,
  );
  TestValidator.predicate(
    "refresh2 refresh window should be no earlier than refresh2 access expiry",
    refresh2Refreshable >= refresh2AccessExpires,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";

/**
 * Validate successful registration and authorization of a new admin user.
 *
 * Business purpose
 *
 * - Ensure a fresh administrative account can be created through the
 *   `/auth/adminUser/join` endpoint.
 * - Confirm that the backend returns a fully-populated
 *   `ITodoAppAdminUser.IAuthorized` object including JWT token information.
 * - Sanity check key business fields such as `email`, `status`, timestamps, and
 *   token expirations.
 *
 * Flow
 *
 * 1. Construct a valid `ITodoAppAdminUser.IJoin` payload with:
 *
 *    - Unique email
 *    - Strong password
 *    - Non-null display name
 *    - Status set to `"active"`
 *    - Realistic IP, href, and referrer values
 * 2. Call `api.functional.auth.adminUser.join`.
 * 3. Validate type structure using `typia.assert`.
 * 4. Verify business expectations via `TestValidator`:
 *
 *    - Email and status echo
 *    - Non-empty access/refresh tokens
 *    - Temporal sanity between created/updated and token expirations.
 */
export async function test_api_admin_user_join_success(
  connection: api.IConnection,
) {
  // 1. Build join payload with realistic values
  const email: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const password: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const displayName: string = RandomGenerator.name();

  const href: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();

  const referrer: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();

  const ip: string = "127.0.0.1";

  const status = "active";

  const joinBody = {
    email,
    password,
    display_name: displayName,
    status,
    ip,
    href,
    referrer,
  } satisfies ITodoAppAdminUser.IJoin;

  // 2. Call join endpoint
  const authorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });

  // 3. Structural/type validation
  typia.assert(authorized);

  // 4. Business and consistency validations

  // 4-1. Email echo
  TestValidator.equals(
    "admin email should echo join request email",
    authorized.email,
    email,
  );

  // 4-2. Status echo
  TestValidator.equals(
    "admin status should echo join request status",
    authorized.status,
    status,
  );

  // 4-3. Token presence (non-empty access and refresh)
  TestValidator.predicate(
    "access token must be non-empty string",
    authorized.token.access.length > 0,
  );

  TestValidator.predicate(
    "refresh token must be non-empty string",
    authorized.token.refresh.length > 0,
  );

  // 4-4. Timestamp parsing and ordering
  const createdAt = new Date(authorized.created_at);
  const updatedAt = new Date(authorized.updated_at);

  TestValidator.predicate(
    "created_at must be a valid date",
    !Number.isNaN(createdAt.getTime()),
  );

  TestValidator.predicate(
    "updated_at must be a valid date",
    !Number.isNaN(updatedAt.getTime()),
  );

  TestValidator.predicate(
    "updated_at must be greater than or equal to created_at",
    updatedAt.getTime() >= createdAt.getTime(),
  );

  // 4-5. Token expiry temporal sanity
  const now = new Date();
  const expiredAt = new Date(authorized.token.expired_at);
  const refreshableUntil = new Date(authorized.token.refreshable_until);

  TestValidator.predicate(
    "token.expired_at must be a valid date",
    !Number.isNaN(expiredAt.getTime()),
  );

  TestValidator.predicate(
    "token.refreshable_until must be a valid date",
    !Number.isNaN(refreshableUntil.getTime()),
  );

  TestValidator.predicate(
    "access token expiration should be in the future",
    expiredAt.getTime() > now.getTime(),
  );

  TestValidator.predicate(
    "refreshable_until should be after or equal to expired_at",
    refreshableUntil.getTime() >= expiredAt.getTime(),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";

/**
 * Validate business enforcement of email uniqueness for administrative users
 * during registration via POST /auth/adminUser/join.
 *
 * Business goal:
 *
 * - Ensure that when an admin account is registered with a given email, any
 *   subsequent attempt to register another admin with the same email is
 *   rejected at the business layer, reflecting the unique index on
 *   todo_app_adminusers.email.
 *
 * Constraints from the testing framework and SDK:
 *
 * - Only api.functional.auth.adminUser.join is available for this scenario.
 * - Must not perform type-error based tests; request payloads must always satisfy
 *   ITodoAppAdminUser.IJoin.
 * - Must not assert specific HTTP status codes; only the fact that an HttpError
 *   is thrown is checked.
 * - Must not touch connection.headers directly; the SDK manages tokens.
 *
 * High-level flow:
 *
 * 1. Prepare an ITodoAppAdminUser.IJoin payload with:
 *
 *    - Email: concrete email string (generated with typia.random and
 *         tags.Format<"email">).
 *    - Password: valid password string (RandomGenerator.alphaNumeric).
 *    - Display_name: a concrete non-null string for clarity.
 *    - Status: a simple string like "active".
 *    - Ip: a simple IP-like string (e.g., "127.0.0.1").
 *    - Href/referrer: URL strings generated via typia.random with
 *         tags.Format<"uri">.
 * 2. Call api.functional.auth.adminUser.join(connection, { body }) to create the
 *    first admin; assert the response with typia.assert to confirm it is a
 *    valid ITodoAppAdminUser.IAuthorized.
 * 3. Build a second ITodoAppAdminUser.IJoin payload, reusing the same email but
 *    possibly different display_name or status, to keep the test focused on
 *    email uniqueness.
 * 4. Use TestValidator.error with an async closure to assert that attempting the
 *    second join call results in an error, indicating rejection of the
 *    duplicate registration. We do not inspect status codes or error messages.
 * 5. Re-assert that the first authorized admin object still conforms to
 *    ITodoAppAdminUser.IAuthorized as a proxy that the original account remains
 *    valid.
 */
export async function test_api_admin_user_join_email_uniqueness_violation_business_flow(
  connection: api.IConnection,
) {
  // 1. Prepare first admin join payload with a unique email
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(16);

  const firstJoinBody = {
    email,
    password,
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppAdminUser.IJoin;

  const firstAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: firstJoinBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(firstAuthorized);

  // 2. Attempt second registration with the same email but different profile
  const secondPassword = RandomGenerator.alphaNumeric(18);
  const secondJoinBody = {
    email,
    password: secondPassword,
    display_name: `${RandomGenerator.name()}-duplicate`,
    status: "active",
    ip: "192.168.0.1",
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppAdminUser.IJoin;

  await TestValidator.error(
    "duplicated admin email join must be rejected",
    async () => {
      await api.functional.auth.adminUser.join(connection, {
        body: secondJoinBody,
      });
    },
  );

  // 3. Re-assert the original authorized admin object still matches its schema
  typia.assert<ITodoAppAdminUser.IAuthorized>(firstAuthorized);
