import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";

/**
 * Validate that admin join endpoint respects non-default initial status.
 *
 * Business goal:
 *
 * - When a new admin registers through /auth/adminUser/join with a custom status
 *   (e.g. "pending" or "disabled" instead of the typical "active"), the backend
 *   must persist that status into todo_app_adminusers.status and return it
 *   unchanged in ITodoAppAdminUser.IAuthorized.
 * - The endpoint must also return a structurally valid authorization token so
 *   that client apps can treat the admin as an authenticated principal,
 *   regardless of whether business logic later restricts their capabilities
 *   based on status.
 *
 * Steps:
 *
 * 1. Build an ITodoAppAdminUser.IJoin payload:
 *
 *    - Email: unique, valid business-like email.
 *    - Password: random strong-looking string.
 *    - Display_name: set to either null or a random human-like name.
 *    - Status: set to a non-default value like "pending" to model non-active.
 *    - Ip: realistic IPv4 string.
 *    - Href: realistic current page URL.
 *    - Referrer: realistic referring URL.
 * 2. Call api.functional.auth.adminUser.join(connection, { body }).
 * 3. Typia.assert that the response is ITodoAppAdminUser.IAuthorized.
 * 4. Validate business expectations:
 *
 *    - Response.status equals the requested non-default status.
 *    - Response.email equals requested email.
 *    - Id, created_at, updated_at are non-empty strings.
 * 5. Validate token structure:
 *
 *    - Token.access and token.refresh are non-empty strings.
 *    - Token.expired_at and token.refreshable_until are non-empty date-time strings.
 */
export async function test_api_admin_user_join_with_non_active_status(
  connection: api.IConnection,
) {
  // 1. Prepare join payload with non-default status
  const email: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const password: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const nonDefaultStatus = "pending";

  const joinBody = {
    email,
    password,
    display_name: null,
    status: nonDefaultStatus,
    ip: "192.168.0.10",
    href: "https://admin.todo-app.local/register",
    referrer: "https://admin.todo-app.local/login",
  } satisfies ITodoAppAdminUser.IJoin;

  // 2. Call join endpoint
  const authorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });

  // 3. Type-level validation
  typia.assert<ITodoAppAdminUser.IAuthorized>(authorized);

  // 4. Business validations for core admin fields
  TestValidator.equals(
    "admin email in response matches join request",
    authorized.email,
    email,
  );

  TestValidator.equals(
    "admin status in response matches non-default requested status",
    authorized.status,
    nonDefaultStatus,
  );

  TestValidator.predicate(
    "admin id should be a non-empty uuid string",
    authorized.id.length > 0,
  );

  TestValidator.predicate(
    "admin created_at should be a non-empty date-time string",
    authorized.created_at.length > 0,
  );

  TestValidator.predicate(
    "admin updated_at should be a non-empty date-time string",
    authorized.updated_at.length > 0,
  );

  // 5. Token structure validations
  const token: IAuthorizationToken = authorized.token;
  typia.assert<IAuthorizationToken>(token);

  TestValidator.predicate(
    "access token must be non-empty",
    token.access.length > 0,
  );

  TestValidator.predicate(
    "refresh token must be non-empty",
    token.refresh.length > 0,
  );

  TestValidator.predicate(
    "expired_at must be a non-empty date-time string",
    token.expired_at.length > 0,
  );

  TestValidator.predicate(
    "refreshable_until must be a non-empty date-time string",
    token.refreshable_until.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppAdminuserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppAdminuserSession";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppAdminUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUserSession";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Basic listing of admin user sessions for the authenticated admin.
 *
 * This scenario verifies that:
 *
 * - An admin who has joined and logged in can retrieve a paginated list of their
 *   own sessions through PATCH
 *   /todoApp/adminUser/adminUsers/{adminUserId}/sessions.
 * - Global system settings exist (at least one ITodoAppSystemSetting created).
 * - Regular member activity (member join + todo creation) has taken place before
 *   auditing sessions, proving the system is in a realistic state.
 * - The listing respects simple pagination arguments (page, limit) and returns
 *   only sessions belonging to the specified admin user.
 *
 * Steps
 *
 * 1. Admin join: create a new admin user and capture id + token.
 * 2. Extra admin login: perform an additional login to ensure multiple sessions
 *    for this admin (join may already create one session).
 * 3. Create a system setting as that admin so that global configuration exists.
 * 4. Member join: register a member user account.
 * 5. Member todo create: create at least one todo for the member to simulate
 *    normal app usage.
 * 6. Admin login again: ensure the current connection represents the admin actor
 *    when calling sessions.index.
 * 7. Call sessions.index with page=1 and limit=10 for the admin’s id.
 * 8. Validate response type and pagination metadata with typia.assert and
 *    TestValidator.
 * 9. Ensure every returned session belongs to the admin and core fields are
 *    well-formed, allowing expired_at to be null for active sessions.
 */
export async function test_api_adminuser_sessions_index_basic_listing(
  connection: api.IConnection,
) {
  // 1. Admin join: register a new admin user and capture authorized response
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const adminPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword,
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todoapp.local/join",
    referrer: "https://admin.todoapp.local/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorizedOnJoin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminAuthorizedOnJoin);

  const adminId: string & tags.Format<"uuid"> = adminAuthorizedOnJoin.id;

  // 2. Extra admin login to ensure additional session exists
  const adminLoginBody = {
    email: adminEmail,
    password: adminPassword,
    ip: "127.0.0.1",
    href: "https://admin.todoapp.local/login",
    referrer: "https://admin.todoapp.local/landing",
  } satisfies ITodoAppAdminUser.ILogin;

  const adminAuthorizedOnLogin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminAuthorizedOnLogin);

  TestValidator.equals(
    "admin id should be consistent between join and login",
    adminAuthorizedOnLogin.id,
    adminId,
  );

  // 3. Create a system setting as the admin to ensure configuration exists
  const systemSettingCreateBody = {
    key: "feature_admin_session_audit",
    value: "true",
    type: "boolean",
    description: "Enable admin session audit listing tests",
    group: "features",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const systemSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: systemSettingCreateBody,
    });
  typia.assert<ITodoAppSystemSetting>(systemSetting);

  // 4. Member join: register a member user
  const memberEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const memberJoinBody = {
    email: memberEmail,
    password: typia.random<string & tags.Format<"password">>(),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://app.todoapp.local/join",
    referrer: "https://app.todoapp.local/landing",
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberAuthorizedOnJoin: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert<ITodoAppMemberUser.IAuthorized>(memberAuthorizedOnJoin);

  // 5. Member todo create: create at least one todo for the member
  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
    due_date: new Date().toISOString(),
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert<ITodoAppTodo>(createdTodo);

  TestValidator.equals(
    "created todo should have state 'active'",
    createdTodo.state,
    "active",
  );

  // 6. Switch back to admin context via login (member join/login modified token)
  const adminAuthorizedAfterMemberOps: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminAuthorizedAfterMemberOps);

  TestValidator.equals(
    "admin id should remain the same after re-login",
    adminAuthorizedAfterMemberOps.id,
    adminId,
  );

  // 7. Call sessions.index for the admin with simple pagination request
  const sessionRequestBody = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 10 as number & tags.Type<"int32"> & tags.Minimum<1>,
    fromCreatedAt: null,
    toCreatedAt: null,
    ip: undefined,
    orderByCreatedAt: "desc" as const,
  } satisfies ITodoAppAdminUserSession.IRequest;

  const pageOfSessions: IPageITodoAppAdminuserSession.ISummary =
    await api.functional.todoApp.adminUser.adminUsers.sessions.index(
      connection,
      {
        adminUserId: adminId,
        body: sessionRequestBody,
      },
    );
  typia.assert<IPageITodoAppAdminuserSession.ISummary>(pageOfSessions);

  const pagination = pageOfSessions.pagination;
  TestValidator.predicate(
    "pagination.current must be non-negative int",
    pagination.current >= 0,
  );
  TestValidator.predicate(
    "pagination.limit must be positive or zero",
    pagination.limit >= 0,
  );
  TestValidator.predicate(
    "pagination.records must be non-negative",
    pagination.records >= 0,
  );
  TestValidator.predicate(
    "pagination.pages must be non-negative",
    pagination.pages >= 0,
  );

  // 8. Ensure data array is non-empty and each session matches admin id
  TestValidator.predicate(
    "session list should not be empty for active admin",
    pageOfSessions.data.length > 0,
  );

  for (const session of pageOfSessions.data) {
    // validate each summary
    typia.assert<ITodoAppAdminUserSession.ISummary>(session);

    TestValidator.equals(
      "each session must belong to requested admin",
      session.adminUser.id,
      adminId,
    );

    TestValidator.predicate(
      "session.ip should be a non-empty string",
      typeof session.ip === "string" && session.ip.length > 0,
    );
    TestValidator.predicate(
      "session.href should be a non-empty string",
      typeof session.href === "string" && session.href.length > 0,
    );
    TestValidator.predicate(
      "session.referrer should be a non-empty string",
      typeof session.referrer === "string" && session.referrer.length > 0,
    );
    TestValidator.predicate(
      "session.created_at should be a non-empty string",
      typeof session.created_at === "string" && session.created_at.length > 0,
    );

    if (session.expired_at !== null && session.expired_at !== undefined) {
      TestValidator.predicate(
        "expired_at when present must be non-empty string",
        typeof session.expired_at === "string" && session.expired_at.length > 0,
      );
    }
  }

  // 9. Optionally ensure at least one active session (expired_at null)
  const hasActiveSession: boolean = pageOfSessions.data.some(
    (s) => s.expired_at === null || s.expired_at === undefined,
  );

  TestValidator.predicate(
    "there should be at least one active (non-expired) session",
    hasActiveSession,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppAdminuserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppAdminuserSession";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppAdminUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUserSession";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate admin session listing with created_at time range filtering.
 *
 * Business workflow:
 *
 * 1. Register an admin via /auth/adminUser/join to obtain an authorized admin and
 *    adminUserId.
 * 2. Create at least one todoApp system setting via
 *    /todoApp/adminUser/systemSettings to simulate initialized configuration.
 * 3. Register a member user via /auth/memberUser/join and create a todo via
 *    /todoApp/memberUser/todos for realistic app usage.
 * 4. Ensure multiple admin sessions exist by logging in the same admin several
 *    times via /auth/adminUser/login.
 * 5. Call PATCH /todoApp/adminUser/adminUsers/{adminUserId}/sessions with a broad
 *    filter to retrieve all sessions for this admin.
 * 6. Derive a time window [fromCreatedAt, toCreatedAt] that includes only a subset
 *    of the sessions and call the index API again with that window.
 * 7. Verify that all returned sessions fall within the requested range, are
 *    ordered by created_at ascending, and that pagination metadata matches the
 *    result size.
 * 8. Optionally perform a second query with a disjoint time window and verify that
 *    its result set is disjoint from the first filtered window or empty.
 */
export async function test_api_adminuser_sessions_index_time_range_filtering(
  connection: api.IConnection,
) {
  // 1. Register admin user (implicitly authenticates and sets Authorization header)
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12) as string &
      tags.Format<"password">,
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  const adminUserId = adminAuthorized.id;

  // 2. Create a system setting as this admin
  const systemSettingBody = {
    key: `max_sessions_${RandomGenerator.alphaNumeric(8)}`,
    value: "10",
    type: "int",
    description: "Maximum concurrent admin sessions for testing.",
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const systemSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: systemSettingBody,
    });
  typia.assert(systemSetting);

  // 3. Register a member user and create a todo for realistic context
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12) as string &
      tags.Format<"password">,
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://app.example.com/signup",
    referrer: "https://app.example.com/landing",
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberAuthorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
    due_date: null,
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const todo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(todo);

  // 4. Generate additional admin sessions by logging in multiple times.
  //    We will perform several login calls with different href/referrer values.
  const loginAttempts = 3;
  for (let i = 0; i < loginAttempts; i++) {
    const adminLoginBody = {
      email: adminAuthorized.email,
      password: adminJoinBody.password,
      ip: "127.0.0.1",
      href: `https://admin.example.com/login?try=${i}` as string &
        tags.Format<"uri">,
      referrer: "https://admin.example.com/dashboard" as string &
        tags.Format<"uri">,
    } satisfies ITodoAppAdminUser.ILogin;

    const adminLoginResult: ITodoAppAdminUser.IAuthorized =
      await api.functional.auth.adminUser.login(connection, {
        body: adminLoginBody,
      });
    typia.assert(adminLoginResult);
  }

  // 5. Broad query to get all sessions for this admin user.
  const broadRequestBody = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 50 as number & tags.Type<"int32"> & tags.Minimum<1>,
    fromCreatedAt: null,
    toCreatedAt: null,
    ip: null,
    orderByCreatedAt: "asc" as const,
  } satisfies ITodoAppAdminUserSession.IRequest;

  const broadPage: IPageITodoAppAdminuserSession.ISummary =
    await api.functional.todoApp.adminUser.adminUsers.sessions.index(
      connection,
      {
        adminUserId,
        body: broadRequestBody,
      },
    );
  typia.assert(broadPage);

  const allSessions: ITodoAppAdminUserSession.ISummary[] = broadPage.data;

  TestValidator.predicate(
    "broad session query should return at least one session",
    allSessions.length > 0,
  );

  // Ensure sessions are sorted ascending by created_at in broad query
  for (let i = 1; i < allSessions.length; i++) {
    const prev = allSessions[i - 1];
    const curr = allSessions[i];
    TestValidator.predicate(
      "broad sessions must be ordered by created_at asc",
      prev.created_at <= curr.created_at,
    );
  }

  // 6. Derive a sub-range [fromCreatedAt, toCreatedAt].
  // If we have at least 3 sessions, use middle slice; otherwise, use first/last.
  const firstCreatedAt = allSessions[0].created_at;
  const lastCreatedAt = allSessions[allSessions.length - 1].created_at;

  let rangeFrom: string & tags.Format<"date-time"> = firstCreatedAt;
  let rangeTo: string & tags.Format<"date-time"> = lastCreatedAt;

  if (allSessions.length >= 3) {
    const middleIndex = Math.floor(allSessions.length / 2);
    rangeFrom = allSessions[0].created_at;
    rangeTo = allSessions[middleIndex].created_at;
  }

  const rangeRequestBody = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 50 as number & tags.Type<"int32"> & tags.Minimum<1>,
    fromCreatedAt: rangeFrom,
    toCreatedAt: rangeTo,
    ip: null,
    orderByCreatedAt: "asc" as const,
  } satisfies ITodoAppAdminUserSession.IRequest;

  const rangePage: IPageITodoAppAdminuserSession.ISummary =
    await api.functional.todoApp.adminUser.adminUsers.sessions.index(
      connection,
      {
        adminUserId,
        body: rangeRequestBody,
      },
    );
  typia.assert(rangePage);

  const rangedSessions = rangePage.data;

  // 7. Validate range inclusion and ordering for filtered results.
  for (const session of rangedSessions) {
    TestValidator.predicate(
      "session.created_at must be within requested range",
      session.created_at >= rangeFrom && session.created_at <= rangeTo,
    );
  }

  for (let i = 1; i < rangedSessions.length; i++) {
    const prev = rangedSessions[i - 1];
    const curr = rangedSessions[i];
    TestValidator.predicate(
      "filtered sessions must be ordered by created_at asc",
      prev.created_at <= curr.created_at,
    );
  }

  TestValidator.equals(
    "pagination limit should match request limit in filtered query",
    rangePage.pagination.limit,
    rangeRequestBody.limit,
  );

  TestValidator.predicate(
    "pagination.records should be at least the number of returned sessions",
    rangePage.pagination.records >= rangedSessions.length,
  );

  // 8. Optional: second non-overlapping window after rangeTo, if possible.
  if (allSessions.length >= 2) {
    const laterFrom = rangeTo;
    const laterTo = lastCreatedAt;

    if (laterFrom < laterTo) {
      const laterRequestBody = {
        page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
        limit: 50 as number & tags.Type<"int32"> & tags.Minimum<1>,
        fromCreatedAt: laterFrom,
        toCreatedAt: laterTo,
        ip: null,
        orderByCreatedAt: "asc" as const,
      } satisfies ITodoAppAdminUserSession.IRequest;

      const laterPage: IPageITodoAppAdminuserSession.ISummary =
        await api.functional.todoApp.adminUser.adminUsers.sessions.index(
          connection,
          {
            adminUserId,
            body: laterRequestBody,
          },
        );
      typia.assert(laterPage);

      const laterSessions = laterPage.data;

      for (const session of laterSessions) {
        TestValidator.predicate(
          "later window session.created_at must be within later range",
          session.created_at >= laterFrom && session.created_at <= laterTo,
        );
      }
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppAdminuserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppAdminuserSession";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppAdminUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUserSession";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate that an authenticated admin can filter their own admin user sessions
 * by IP address through the PATCH
 * /todoApp/adminUser/adminUsers/{adminUserId}/sessions endpoint using
 * ITodoAppAdminUserSession.IRequest.ip, and that pagination metadata is
 * consistent.
 *
 * Business flow:
 *
 * 1. Register a new admin user via /auth/adminUser/join, explicitly specifying a
 *    fixed IP string (e.g., "192.168.0.10") in ITodoAppAdminUser.IJoin.ip so
 *    that the initial session is recorded with that IP, and capture the
 *    returned ITodoAppAdminUser.IAuthorized to obtain adminUserId.
 * 2. Optionally perform an additional admin login via /auth/adminUser/login with
 *    the same IP value to create a second session row for the same admin; this
 *    grows the dataset but is not strictly required for correctness.
 * 3. As the admin, initialize at least one ITodoAppSystemSetting via
 *    /todoApp/adminUser/systemSettings (e.g., a key like
 *    "session_audit_enabled") with enabled=true to simulate that session
 *    auditing features are turned on. The actual key semantics do not influence
 *    the filtering behavior, so any valid ICreate payload is fine.
 * 4. Register a member user via /auth/memberUser/join and then log that member in
 *    via /auth/memberUser/login to create member-side sessions and realistic
 *    traffic context.
 * 5. As the authenticated member, create at least one todo via
 *    /todoApp/memberUser/todos with ITodoAppTodo.ICreate to ensure normal
 *    application activity is present, even though it does not directly affect
 *    admin session queries.
 * 6. Switch authentication context back to the admin using /auth/adminUser/login
 *    with the same credentials and IP to guarantee a fresh, recent session and
 *    consistent Authorization header for subsequent admin calls.
 * 7. Invoke api.functional.todoApp.adminUser.adminUsers.sessions.index with:
 *
 *    - AdminUserId set to the id from ITodoAppAdminUser.IAuthorized
 *    - Body satisfying ITodoAppAdminUserSession.IRequest with page = 1, limit = 20,
 *         ip = the fixed IP string used during join/login, orderByCreatedAt =
 *         "desc" and assert that:
 *    - Typia.assert passes for the returned IPageITodoAppAdminuserSession.ISummary
 *    - Pagination.current equals 1 and pagination.limit equals 20
 *    - Pagination.records is >= 1
 *    - Every ITodoAppAdminUserSession.ISummary in data has ip exactly equal to the
 *         requested filter IP, validated via TestValidator.predicate/equals.
 * 8. Perform a second call to sessions.index for the same adminUserId where the
 *    request body uses a deliberately non-matching ip value (e.g., "10.0.0.1")
 *    while keeping page=1, limit=20, orderByCreatedAt="desc". Assert that:
 *
 *    - Typia.assert passes for the response type
 *    - Data is an empty array
 *    - Pagination.records equals 0 (no matching sessions), confirming that the ip
 *         filter excludes all sessions without causing an error.
 *
 * Implementation notes:
 *
 * - Do not manipulate connection.headers directly; rely on the SDK to manage
 *   Authorization tokens after join/login calls.
 * - Use `satisfies` with the correct DTO variants for all request bodies to
 *   maintain strict type safety without resorting to `as any`.
 * - Avoid any tests that intentionally send type-invalid payloads; focus solely
 *   on logical filtering behavior and pagination consistency.
 */
export async function test_api_adminuser_sessions_index_ip_filtering(
  connection: api.IConnection,
) {
  // 1. Admin registration with fixed IP for deterministic filtering
  const adminIp = "192.168.0.10";
  const adminJoinBody = {
    email: `${RandomGenerator.alphabets(8)}@admin.example.com`,
    password: "AdminPassw0rd!",
    display_name: RandomGenerator.name(),
    status: "active",
    ip: adminIp,
    href: "https://admin.todo-app.test/join",
    referrer: "https://admin.todo-app.test/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorizedFromJoin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorizedFromJoin);

  // 2. Optional additional admin login with same IP to create another session
  const adminLoginBody = {
    email: adminAuthorizedFromJoin.email,
    password: adminJoinBody.password,
    ip: adminIp,
    href: "https://admin.todo-app.test/login",
    referrer: "https://admin.todo-app.test/landing",
  } satisfies ITodoAppAdminUser.ILogin;

  const adminAuthorizedFromLogin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminAuthorizedFromLogin);

  // 3. Create a system setting to simulate enabling session audit features
  const systemSettingBody = {
    key: `session_audit_${RandomGenerator.alphabets(6)}`,
    value: "true",
    type: "boolean",
    description: "Enable admin session auditing in tests",
    group: "audit",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const systemSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: systemSettingBody,
    });
  typia.assert(systemSetting);

  // 4. Register a member user
  const memberJoinBody = {
    email: `${RandomGenerator.alphabets(8)}@member.example.com`,
    password: "MemberPassw0rd!" as string & tags.Format<"password">,
    displayName: RandomGenerator.name(),
    ip: "203.0.113.5" as string & tags.Format<"ipv4">,
    href: "https://app.todo-app.test/join",
    referrer: "https://app.todo-app.test/landing",
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberAuthorizedFromJoin: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorizedFromJoin);

  // 5. Member login to create additional member sessions
  const memberLoginBody = {
    email: memberAuthorizedFromJoin.email,
    password: memberJoinBody.password,
    ip: memberJoinBody.ip ?? null,
    href: "https://app.todo-app.test/login",
    referrer: "https://app.todo-app.test/landing",
  } satisfies ITodoAppMemberUserLogin.ICreate;

  const memberAuthorizedFromLogin: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberAuthorizedFromLogin);

  // 6. As authenticated member, create at least one todo
  const todoCreateBody = {
    title: `Todo - ${RandomGenerator.paragraph({ sentences: 3 })}`,
    description: RandomGenerator.content({
      paragraphs: 1,
      sentenceMin: 3,
      sentenceMax: 6,
    }),
    due_date: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(),
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const todo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(todo);

  // 7. Switch back to admin context with a fresh login (ensures Authorization header is admin)
  const adminAuthorizedForListing: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminAuthorizedForListing);

  const adminId: string & tags.Format<"uuid"> = adminAuthorizedForListing.id;

  // 8. Positive-path IP-filtered session listing
  const page = 1 as number & tags.Type<"int32"> & tags.Minimum<1>;
  const limit = 20 as number & tags.Type<"int32"> & tags.Minimum<1>;

  const filterRequestBody = {
    page,
    limit,
    fromCreatedAt: null,
    toCreatedAt: null,
    ip: adminIp,
    orderByCreatedAt: "desc",
  } satisfies ITodoAppAdminUserSession.IRequest;

  const filteredPage: IPageITodoAppAdminuserSession.ISummary =
    await api.functional.todoApp.adminUser.adminUsers.sessions.index(
      connection,
      {
        adminUserId: adminId,
        body: filterRequestBody,
      },
    );
  typia.assert(filteredPage);

  // Validate pagination metadata
  TestValidator.equals(
    "pagination current page should be 1",
    filteredPage.pagination.current,
    page,
  );
  TestValidator.equals(
    "pagination limit should be 20",
    filteredPage.pagination.limit,
    limit,
  );

  // There should be at least one session for this admin from join/login
  TestValidator.predicate(
    "filtered session records should be at least 1 for matching IP",
    filteredPage.pagination.records >= 1,
  );
  TestValidator.predicate(
    "filtered session data length should be at least 1",
    filteredPage.data.length >= 1,
  );

  // Every summary should have IP exactly matching the filter
  for (const summary of filteredPage.data) {
    TestValidator.equals(
      "session summary ip should equal filter ip",
      summary.ip,
      adminIp,
    );
  }

  // 9. Negative-path IP filtering: query sessions with an IP that should not exist
  const nonMatchingIp = "10.0.0.1";
  const negativeRequestBody = {
    page,
    limit,
    fromCreatedAt: null,
    toCreatedAt: null,
    ip: nonMatchingIp,
    orderByCreatedAt: "desc",
  } satisfies ITodoAppAdminUserSession.IRequest;

  const negativePage: IPageITodoAppAdminuserSession.ISummary =
    await api.functional.todoApp.adminUser.adminUsers.sessions.index(
      connection,
      {
        adminUserId: adminId,
        body: negativeRequestBody,
      },
    );
  typia.assert(negativePage);

  TestValidator.equals(
    "negative IP filter should return zero records",
    negativePage.pagination.records,
    0,
  );
  TestValidator.equals(
    "negative IP filter should return empty data array",
    negativePage.data.length,
    0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppAdminuserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppAdminuserSession";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppAdminUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUserSession";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

export async function test_api_adminuser_sessions_index_pagination_and_sorting(
  connection: api.IConnection,
) {
  // 1. Register an admin user (join) to get a real adminUserId and first session.
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const adminPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword,
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todo-app.test/join",
    referrer: "https://admin.todo-app.test/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const joinedAdmin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(joinedAdmin);

  const adminUserId = joinedAdmin.id;

  // 2. Create at least one system setting as admin to simulate realistic system config.
  const systemSettingBody = {
    key: `max_active_todos_${RandomGenerator.alphaNumeric(8)}`,
    value: "100",
    type: "int",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const createdSystemSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: systemSettingBody,
    });
  typia.assert(createdSystemSetting);

  // 3. Register and login a member user, then create at least one todo to simulate activity.
  const memberEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const memberJoinBody = {
    email: memberEmail,
    password: typia.random<string & tags.Format<"password">>(),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.test/join",
    referrer: "https://todo-app.test/landing",
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const joinedMember: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(joinedMember);

  const memberLoginBody = {
    email: memberEmail,
    password: memberJoinBody.password,
    ip: null,
    href: "https://todo-app.test/login",
    referrer: "https://todo-app.test/landing",
  } satisfies ITodoAppMemberUserLogin.ICreate;

  const loggedInMember: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(loggedInMember);

  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
    due_date: null,
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(createdTodo);

  // 4. Generate multiple additional sessions for the same admin by logging in repeatedly.
  // Switch back to admin context (login).
  const adminLoginBody = {
    email: adminEmail,
    password: adminPassword,
    ip: "127.0.0.1",
    href: "https://admin.todo-app.test/login",
    referrer: "https://admin.todo-app.test/landing",
  } satisfies ITodoAppAdminUser.ILogin;

  // Ensure several sessions exist: join already created 1, add 3 more via login.
  const additionalSessionsCount = 3;
  for (let i = 0; i < additionalSessionsCount; i++) {
    const loggedInAdmin: ITodoAppAdminUser.IAuthorized =
      await api.functional.auth.adminUser.login(connection, {
        body: adminLoginBody,
      });
    typia.assert(loggedInAdmin);
  }

  // 5. Call sessions.index with page=1, limit=2, orderByCreatedAt="asc".
  const page1Limit2AscBody = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 2 as number & tags.Type<"int32"> & tags.Minimum<1>,
    fromCreatedAt: null,
    toCreatedAt: null,
    ip: null,
    orderByCreatedAt: "asc",
  } satisfies ITodoAppAdminUserSession.IRequest;

  const page1Asc: IPageITodoAppAdminuserSession.ISummary =
    await api.functional.todoApp.adminUser.adminUsers.sessions.index(
      connection,
      {
        adminUserId,
        body: page1Limit2AscBody,
      },
    );
  typia.assert(page1Asc);

  // Basic structural validations for page 1
  TestValidator.equals(
    "page1 asc: pagination current should be 1",
    page1Asc.pagination.current,
    1,
  );
  TestValidator.equals(
    "page1 asc: pagination limit should be 2",
    page1Asc.pagination.limit,
    2,
  );
  TestValidator.predicate(
    "page1 asc: data length must be <= limit",
    page1Asc.data.length <= page1Asc.pagination.limit,
  );

  // Ensure every session belongs to the adminUserId
  for (const session of page1Asc.data) {
    TestValidator.equals(
      "page1 asc: each session adminUser id matches target",
      session.adminUser.id,
      adminUserId,
    );
  }

  // Validate ascending created_at order within the page.
  for (let i = 1; i < page1Asc.data.length; i++) {
    const prev = page1Asc.data[i - 1];
    const curr = page1Asc.data[i];
    TestValidator.predicate(
      "page1 asc: created_at should be non-decreasing",
      prev.created_at <= curr.created_at,
    );
  }

  // 6. Call sessions.index with page=2, limit=2, orderByCreatedAt="asc".
  const page2Limit2AscBody = {
    page: 2 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 2 as number & tags.Type<"int32"> & tags.Minimum<1>,
    fromCreatedAt: null,
    toCreatedAt: null,
    ip: null,
    orderByCreatedAt: "asc",
  } satisfies ITodoAppAdminUserSession.IRequest;

  const page2Asc: IPageITodoAppAdminuserSession.ISummary =
    await api.functional.todoApp.adminUser.adminUsers.sessions.index(
      connection,
      {
        adminUserId,
        body: page2Limit2AscBody,
      },
    );
  typia.assert(page2Asc);

  TestValidator.equals(
    "page2 asc: pagination current should be 2",
    page2Asc.pagination.current,
    2,
  );
  TestValidator.equals(
    "page2 asc: pagination limit should be 2",
    page2Asc.pagination.limit,
    2,
  );
  TestValidator.predicate(
    "page2 asc: data length must be <= limit",
    page2Asc.data.length <= page2Asc.pagination.limit,
  );

  for (const session of page2Asc.data) {
    TestValidator.equals(
      "page2 asc: each session adminUser id matches target",
      session.adminUser.id,
      adminUserId,
    );
  }

  for (let i = 1; i < page2Asc.data.length; i++) {
    const prev = page2Asc.data[i - 1];
    const curr = page2Asc.data[i];
    TestValidator.predicate(
      "page2 asc: created_at should be non-decreasing",
      prev.created_at <= curr.created_at,
    );
  }

  // Validate that there is no overlap of IDs between page 1 and page 2
  const page1Ids = new Set(page1Asc.data.map((s) => s.id));
  for (const session of page2Asc.data) {
    TestValidator.predicate(
      "page2 asc: session IDs should not overlap with page1",
      page1Ids.has(session.id) === false,
    );
  }

  // 7. Optionally, call sessions.index with orderByCreatedAt="desc" page=1, limit=2.
  const page1Limit2DescBody = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 2 as number & tags.Type<"int32"> & tags.Minimum<1>,
    fromCreatedAt: null,
    toCreatedAt: null,
    ip: null,
    orderByCreatedAt: "desc",
  } satisfies ITodoAppAdminUserSession.IRequest;

  const page1Desc: IPageITodoAppAdminuserSession.ISummary =
    await api.functional.todoApp.adminUser.adminUsers.sessions.index(
      connection,
      {
        adminUserId,
        body: page1Limit2DescBody,
      },
    );
  typia.assert(page1Desc);

  TestValidator.equals(
    "page1 desc: pagination current should be 1",
    page1Desc.pagination.current,
    1,
  );
  TestValidator.equals(
    "page1 desc: pagination limit should be 2",
    page1Desc.pagination.limit,
    2,
  );
  TestValidator.predicate(
    "page1 desc: data length must be <= limit",
    page1Desc.data.length <= page1Desc.pagination.limit,
  );

  for (const session of page1Desc.data) {
    TestValidator.equals(
      "page1 desc: each session adminUser id matches target",
      session.adminUser.id,
      adminUserId,
    );
  }

  for (let i = 1; i < page1Desc.data.length; i++) {
    const prev = page1Desc.data[i - 1];
    const curr = page1Desc.data[i];
    TestValidator.predicate(
      "page1 desc: created_at should be non-increasing",
      prev.created_at >= curr.created_at,
    );
  }

  // 8. Cross-check pagination metadata coherence.
  // At least we know total records should be >= number of sessions retrieved so far.
  const totalRecordsAsc = page1Asc.pagination.records;
  TestValidator.predicate(
    "pagination.records should be >= total sessions seen in page1+page2",
    totalRecordsAsc >= page1Asc.data.length + page2Asc.data.length,
  );

  TestValidator.predicate(
    "pagination.pages should be >= 1",
    page1Asc.pagination.pages >= 1,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppAdminuserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppAdminuserSession";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppAdminUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUserSession";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate that an authenticated admin user can retrieve detailed information
 * for one of their own sessions and that the detail endpoint is read-only.
 *
 * Business flow:
 *
 * 1. Register an admin account (join) which implicitly creates an initial admin
 *    session; capture the admin id and ensure tokens are issued.
 * 2. Log in again as the same admin to create at least one more adminUserSession
 *    row.
 * 3. While authenticated as that admin, create a system setting so the admin side
 *    of the system has some configuration data.
 * 4. Create a member user and at least one member todo so there is general
 *    application activity (not strictly required by the API contract but
 *    reflects realistic context).
 * 5. Log in again as the admin to ensure a fresh, recent session exists and that
 *    the Authorization header is set for admin-only APIs.
 * 6. List the admin’s sessions using the PATCH
 *    /todoApp/adminUser/adminUsers/{adminUserId}/sessions endpoint with a
 *    simple IRequest filter; select one concrete session summary from the
 *    returned page.
 * 7. Call GET /todoApp/adminUser/adminUsers/{adminUserId}/sessions/{sessionId} for
 *    the selected session and verify that the returned ITodoAppAdminUserSession
 *    matches the summary: id matches, adminUser.id matches the admin id,
 *    created_at matches, and expired_at is consistent.
 * 8. Assert basic field-level sanity (ip is non-empty, href/referrer are non-empty
 *    valid URIs via typia, etc.).
 * 9. Call the same detail endpoint again for the same session id and assert that
 *    the response is unchanged, confirming the detail view is read-only and
 *    does not mutate session attributes on read.
 */
export async function test_api_adminuser_session_detail_basic_retrieval(
  connection: api.IConnection,
) {
  // 1. Register an admin account (join)
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword,
    display_name: RandomGenerator.name(),
    status: "active",
    ip: RandomGenerator.mobile(),
    href: "https://admin.todoapp.example.com/join",
    referrer: "https://admin.todoapp.example.com/",
  } satisfies ITodoAppAdminUser.IJoin;

  const joinedAdmin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(joinedAdmin);

  const adminId = joinedAdmin.id;

  // 2. Log in again as the same admin to create additional session
  const adminLoginBody = {
