import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppAdminuserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppAdminuserSession";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppAdminUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUserSession";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate that admin session detail endpoint does not leak data for invalid or
 * cross-admin session IDs.
 *
 * Business goal
 *
 * - Ensure that GET
 *   /todoApp/adminUser/adminUsers/{adminUserId}/sessions/{sessionId} only
 *   returns details for sessions that belong to the specified admin user and
 *   that exist, and that any invalid or cross-admin combination results in an
 *   error without returning ITodoAppAdminUserSession payloads.
 *
 * High-level flow
 *
 * 1. Register admin A and establish an authenticated admin session.
 * 2. As admin A, create system settings to satisfy admin domain prerequisites.
 * 3. Register and authenticate a member user and create at least one todo to
 *    simulate normal app activity (not directly tied to sessions, but ensures
 *    the environment is in realistic use).
 * 4. Re-login as admin A, then enumerate sessions for admin A using PATCH
 *    /todoApp/adminUser/adminUsers/{adminUserId}/sessions, capturing at least
 *    one valid session summary.
 * 5. Register a second admin (admin B) and ensure there is at least one valid
 *    session for admin B as well.
 * 6. Use a cross-admin mismatch: call the session detail endpoint with adminUserId
 *    of admin B but sessionId of an existing session owned by admin A. This
 *    simulates an attempt by admin B (or a caller scoped to admin B) to access
 *    admin A's session detail.
 * 7. Assert that the GET call throws an error (via TestValidator.error) and does
 *    not return ITodoAppAdminUserSession data, avoiding any assumption about
 *    the concrete HTTP status code.
 *
 * Implementation notes
 *
 * - Use explicit DTOs:
 *
 *   - ITodoAppAdminUser.IJoin and ITodoAppAdminUser.ILogin for admin auth.
 *   - ITodoAppMemberUserJoin.ICreate and ITodoAppMemberUserLogin.ICreate for member
 *       user flows.
 *   - ITodoAppSystemSetting.ICreate for creating system settings.
 *   - ITodoAppTodo.ICreate for member todos.
 *   - ITodoAppAdminUserSession.IRequest for session index filters.
 * - Always call typia.assert on successful responses.
 * - Use RandomGenerator and typia.random to build realistic payloads while
 *   respecting tags (email, uri, date-time, etc.).
 * - For the negative test, wrap the GET call in `await TestValidator.error(
 *   "cross admin session detail must fail", async () => { ... })`.
 */
export async function test_api_adminuser_session_detail_not_found_for_invalid_session(
  connection: api.IConnection,
) {
  // 1. Register admin A (join) and obtain authorized context.
  const adminAJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminA: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminAJoinBody,
    });
  typia.assert(adminA);

  // 2. As admin A, create at least one system setting to satisfy domain usage.
  const settingCreateBody = {
    key: `max_active_todos_per_user_${RandomGenerator.alphaNumeric(6)}`,
    value: "100",
    type: "int",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const systemSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: settingCreateBody,
    });
  typia.assert(systemSetting);

  // 3. Register and login a member user, then create a todo to simulate traffic.
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://app.example.com/join",
    referrer: "https://app.example.com/marketing",
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberAuthorizedFromJoin: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorizedFromJoin);

  // Explicit member login to exercise login flow as well.
  const memberLoginBody = {
    email: memberJoinBody.email,
    password: memberJoinBody.password,
    ip: null,
    href: "https://app.example.com/login",
    referrer: "https://app.example.com/landing",
  } satisfies ITodoAppMemberUserLogin.ICreate;

  const memberAuthorizedFromLogin: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberAuthorizedFromLogin);

  // Create a member todo.
  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    due_date: null,
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const todo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(todo);

  // 4. Re-login as admin A to ensure the connection is using admin credentials
  //    when enumerating sessions.
  const adminALoginBody = {
    email: adminA.email,
    password: adminAJoinBody.password,
    ip: null,
    href: "https://admin.example.com/login",
    referrer: "https://admin.example.com/landing",
  } satisfies ITodoAppAdminUser.ILogin;

  const adminALogin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminALoginBody,
    });
  typia.assert(adminALogin);

  // Enumerate sessions for admin A.
  const adminASessionRequest = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 10 as number & tags.Type<"int32"> & tags.Minimum<1>,
    fromCreatedAt: null,
    toCreatedAt: null,
    ip: null,
    orderByCreatedAt: "desc" as const,
  } satisfies ITodoAppAdminUserSession.IRequest;

  const adminASessionsPage: IPageITodoAppAdminuserSession.ISummary =
    await api.functional.todoApp.adminUser.adminUsers.sessions.index(
      connection,
      {
        adminUserId: adminALogin.id,
        body: adminASessionRequest,
      },
    );
  typia.assert(adminASessionsPage);

  TestValidator.predicate(
    "admin A sessions list should have at least one item",
    adminASessionsPage.pagination.records >= 1,
  );

  const adminASessionSummary: ITodoAppAdminUserSession.ISummary =
    adminASessionsPage.data[0];

  // 5. Register a second admin (admin B) and ensure they have a session.
  const adminBJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.2",
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/campaign",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminB: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminBJoinBody,
    });
  typia.assert(adminB);

  // Optionally, login as admin B explicitly to create another session.
  const adminBLoginBody = {
    email: adminB.email,
    password: adminBJoinBody.password,
    ip: null,
    href: "https://admin.example.com/login",
    referrer: "https://admin.example.com/landing",
  } satisfies ITodoAppAdminUser.ILogin;

  const adminBLogin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminBLoginBody,
    });
  typia.assert(adminBLogin);

  const adminBSessionRequest = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 10 as number & tags.Type<"int32"> & tags.Minimum<1>,
    fromCreatedAt: null,
    toCreatedAt: null,
    ip: null,
    orderByCreatedAt: "desc" as const,
  } satisfies ITodoAppAdminUserSession.IRequest;

  const adminBSessionsPage: IPageITodoAppAdminuserSession.ISummary =
    await api.functional.todoApp.adminUser.adminUsers.sessions.index(
      connection,
      {
        adminUserId: adminBLogin.id,
        body: adminBSessionRequest,
      },
    );
  typia.assert(adminBSessionsPage);

  TestValidator.predicate(
    "admin B sessions list should have at least one item",
    adminBSessionsPage.pagination.records >= 1,
  );

  // 6. Cross-admin mismatch: use admin A's sessionId with admin B's adminUserId.
  const mismatchedAdminUserId = adminBLogin.id;
  const foreignSessionId = adminASessionSummary.id;

  // 7. Assert that fetching session detail with mismatched adminUserId and
  //    sessionId fails and does not return ITodoAppAdminUserSession.
  await TestValidator.error(
    "cross-admin session detail access must fail",
    async () => {
      await api.functional.todoApp.adminUser.adminUsers.sessions.at(
        connection,
        {
          adminUserId: mismatchedAdminUserId,
          sessionId: foreignSessionId,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppAdminuserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppAdminuserSession";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppAdminUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUserSession";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

export async function test_api_adminuser_session_detail_with_expired_session(
  connection: api.IConnection,
) {
  // 1. Admin joins and gets initial authorized context
  const adminJoinBody = {
    email: `${RandomGenerator.alphabets(8)}@admin.test.com`,
    password: "AdminPassw0rd!",
    display_name: RandomGenerator.name(2),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todo-app.test/join",
    referrer: "https://admin.todo-app.test/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorizedOnJoin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorizedOnJoin);

  const adminId: string & tags.Format<"uuid"> = adminAuthorizedOnJoin.id;

  // 2. As admin, create a system setting to simulate typical admin activity
  const systemSettingBody = {
    key: `max_active_todos_${RandomGenerator.alphabets(6)}`,
    value: "100",
    type: "int",
    description: "Maximum active todos per member user for load management",
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const createdSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: systemSettingBody,
    });
  typia.assert(createdSetting);

  // 3. Create a member user and log them in to generate member-side activity
  const memberJoinBody = {
    email: `${RandomGenerator.alphabets(8)}@member.test.com`,
    password: "MemberPassw0rd!",
    displayName: RandomGenerator.name(2),
    ip: "127.0.0.1",
    href: "https://todo-app.test/signup",
    referrer: "https://todo-app.test/landing",
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberAuthorizedOnJoin: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorizedOnJoin);

  const memberLoginBody = {
    email: memberJoinBody.email,
    password: memberJoinBody.password,
    ip: "127.0.0.1",
    href: "https://todo-app.test/login",
    referrer: "https://todo-app.test/landing",
  } satisfies ITodoAppMemberUserLogin.ICreate;

  const memberAuthorizedOnLogin: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberAuthorizedOnLogin);

  // 4. As member, create a todo to simulate workload
  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
    due_date: null,
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(createdTodo);

  // 5. Log in again as the admin user to create at least one additional session
  const adminLoginBody = {
    email: adminJoinBody.email,
    password: adminJoinBody.password,
    ip: "127.0.0.1",
    href: "https://admin.todo-app.test/login",
    referrer: "https://admin.todo-app.test/landing",
  } satisfies ITodoAppAdminUser.ILogin;

  const adminAuthorizedOnLogin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminAuthorizedOnLogin);

  // 6. List sessions for the admin user
  const sessionsRequestBody = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 20 as number & tags.Type<"int32"> & tags.Minimum<1>,
    fromCreatedAt: null,
    toCreatedAt: null,
    ip: null,
    orderByCreatedAt: "desc" as const,
  } satisfies ITodoAppAdminUserSession.IRequest;

  const sessionsPageBefore: IPageITodoAppAdminuserSession.ISummary =
    await api.functional.todoApp.adminUser.adminUsers.sessions.index(
      connection,
      {
        adminUserId: adminId,
        body: sessionsRequestBody,
      },
    );
  typia.assert(sessionsPageBefore);

  TestValidator.predicate(
    "admin sessions list should contain at least one session",
    sessionsPageBefore.pagination.records > 0,
  );

  const sessionsBefore: ITodoAppAdminUserSession.ISummary[] =
    sessionsPageBefore.data;

  // Prefer a session that appears expired (expired_at != null), otherwise
  // just use the last session in the list as the target for detail inspection
  const candidateExpired = sessionsBefore.find(
    (s) => s.expired_at !== null && s.expired_at !== undefined,
  );

  const targetSessionSummary =
    candidateExpired !== undefined
      ? candidateExpired
      : sessionsBefore[sessionsBefore.length - 1];

  const targetSessionId = targetSessionSummary.id;

  // 7. Fetch detailed information for the chosen session
  const detail1: ITodoAppAdminUserSession =
    await api.functional.todoApp.adminUser.adminUsers.sessions.at(connection, {
      adminUserId: adminId,
      sessionId: targetSessionId,
    });
  typia.assert(detail1);

  // 8. Basic consistency checks between summary and detail
  TestValidator.equals(
    "detailed session id should match summary id",
    detail1.id,
    targetSessionSummary.id,
  );

  TestValidator.equals(
    "detailed admin id should match admin user id",
    detail1.adminUser.id,
    adminId,
  );

  TestValidator.equals(
    "summary and detail ip should match",
    detail1.ip,
    targetSessionSummary.ip,
  );

  TestValidator.equals(
    "summary and detail href should match",
    detail1.href,
    targetSessionSummary.href,
  );

  TestValidator.equals(
    "summary and detail referrer should match",
    detail1.referrer,
    targetSessionSummary.referrer,
  );

  TestValidator.equals(
    "summary and detail created_at should match",
    detail1.created_at,
    targetSessionSummary.created_at,
  );

  if (
    targetSessionSummary.expired_at !== null &&
    targetSessionSummary.expired_at !== undefined
  ) {
    TestValidator.equals(
      "summary and detail expired_at should both be non-null and equal",
      detail1.expired_at,
      targetSessionSummary.expired_at,
    );
  } else {
    TestValidator.equals(
      "summary and detail expired_at should both be null when summary is null",
      detail1.expired_at,
      null,
    );
  }

  // 9. Confirm that repeated GET calls are read-only
  const detail2: ITodoAppAdminUserSession =
    await api.functional.todoApp.adminUser.adminUsers.sessions.at(connection, {
      adminUserId: adminId,
      sessionId: targetSessionId,
    });
  typia.assert(detail2);

  TestValidator.equals(
    "repeated session detail fetch should return identical data (read-only)",
    detail2,
    detail1,
  );

  // Optional: re-fetch the sessions index and ensure the targeted session
  // still has the same expired_at value, confirming the detail call did not
  // mutate state.
  const sessionsPageAfter: IPageITodoAppAdminuserSession.ISummary =
    await api.functional.todoApp.adminUser.adminUsers.sessions.index(
      connection,
      {
        adminUserId: adminId,
        body: sessionsRequestBody,
      },
    );
  typia.assert(sessionsPageAfter);

  const sessionsAfter: ITodoAppAdminUserSession.ISummary[] =
    sessionsPageAfter.data;

  const targetAfter = sessionsAfter.find((s) => s.id === targetSessionId);

  TestValidator.predicate(
    "target session should still be present after detail inspection",
    targetAfter !== undefined,
  );

  if (targetAfter !== undefined) {
    TestValidator.equals(
      "expired_at should remain unchanged after detail inspection",
      targetAfter.expired_at ?? null,
      targetSessionSummary.expired_at ?? null,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";

/**
 * Validate that an authenticated admin can retrieve a specific guest user
 * concept record by UUID using the admin-only guestUsers detail endpoint.
 *
 * Business context:
 *
 * - Admin users are registered via /auth/adminUser/join, which also issues JWT
 *   tokens encapsulated in ITodoAppAdminUser.IAuthorized and automatically
 *   propagated into the SDK connection headers.
 * - System-level configuration is managed via /todoApp/adminUser/systemSettings
 *   and must be initialized before certain diagnostic or analytics endpoints
 *   are used.
 * - Guest users are modeled as anonymous or transient actors stored in
 *   todo_app_guestusers and surfaced via ITodoAppGuestUser for admin-only
 *   inspection and troubleshooting.
 *
 * This test exercises the happy-path flow:
 *
 * 1. Join an admin user and establish admin authentication.
 * 2. Create at least one system setting as a prerequisite for system
 *    configuration.
 * 3. Call GET /todoApp/adminUser/guestUsers/{guestUserId} as an admin with a UUID
 *    path parameter.
 * 4. Validate that the response conforms to ITodoAppGuestUser and that the id
 *    matches the UUID used in the path.
 *
 * Error and negative authorization paths (e.g., 404 for unknown UUID, non-admin
 * access) are intentionally not covered here due to API surface and test
 * environment constraints, and to keep the test focused on the core contract of
 * the admin guest user detail endpoint.
 */
export async function test_api_admin_guest_user_detail_basic_flow(
  connection: api.IConnection,
) {
  // 1. Admin registration / authentication
  const adminJoinInput = typia.random<ITodoAppAdminUser.IJoin>();

  const admin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinInput,
    });
  typia.assert(admin);

  // 2. Initialize a system setting as prerequisite configuration
  const systemSettingKeyPrefix = "e2e_max_active_todos_per_user_";
  const systemSettingKey =
    systemSettingKeyPrefix + RandomGenerator.alphaNumeric(8);

  const systemSettingCreateBody = {
    key: systemSettingKey,
    value: "100",
    type: "int",
    description: "E2E test system setting for max active todos per user",
    group: "e2e-tests",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const systemSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: systemSettingCreateBody,
    });
  typia.assert(systemSetting);

  // Basic sanity checks on created system setting
  TestValidator.equals(
    "system setting key should match request",
    systemSetting.key,
    systemSettingCreateBody.key,
  );
  TestValidator.predicate(
    "system setting should be enabled",
    systemSetting.enabled === true,
  );

  // 3. Prepare a guest user id and call the admin guestUsers detail endpoint
  const guestUserId = typia.random<string & tags.Format<"uuid">>();

  const guestUser: ITodoAppGuestUser =
    await api.functional.todoApp.adminUser.guestUsers.at(connection, {
      guestUserId,
    });
  typia.assert(guestUser);

  // 4. Validate response business expectations
  TestValidator.equals(
    "guest user id should match requested guestUserId",
    guestUser.id,
    guestUserId,
  );
  TestValidator.predicate(
    "guest user id should be non-empty",
    guestUser.id.length > 0,
  );
  TestValidator.predicate(
    "guest user created_at should be non-empty",
    guestUser.created_at.length > 0,
  );
  TestValidator.predicate(
    "guest user updated_at should be non-empty",
    guestUser.updated_at.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
