import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";

export async function test_api_admin_guest_user_detail_not_found(
  connection: api.IConnection,
) {
  // 1. Register and authenticate an admin user so that admin-only
  //    endpoints such as systemSettings and guestUsers are accessible.
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://todo-app.example.com/admin/join",
    referrer: "https://todo-app.example.com/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminAuthorized);
  typia.assert<IAuthorizationToken>(adminAuthorized.token);

  // 2. Create at least one system setting to simulate a configured
  //    production-like environment.
  const systemSettingBody = {
    key: `e2e_not_found_guest_detail_${RandomGenerator.alphaNumeric(8)}`,
    value: "true",
    type: "boolean",
    description:
      "E2E: flag used to ensure system settings path is exercised before guest user lookup.",
    group: "e2e-tests",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const createdSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: systemSettingBody,
    });
  typia.assert<ITodoAppSystemSetting>(createdSetting);

  // 3. Generate a random UUID that should not correspond to an existing
  //    guest user record.
  const nonExistentGuestUserId = typia.random<string & tags.Format<"uuid">>();

  // 4. Call the guest user detail endpoint with the random UUID and
  //    assert that an error is thrown (e.g., not-found or equivalent).
  await TestValidator.error(
    "admin guest user detail with non-existent id must fail",
    async () => {
      await api.functional.todoApp.adminUser.guestUsers.at(connection, {
        guestUserId: nonExistentGuestUserId,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";

export async function test_api_admin_guest_user_detail_unauthorized_access_blocked_by_missing_token(
  connection: api.IConnection,
) {
  // 1) Register an admin user to satisfy dependency and ensure admin capability exists
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todo-app.test/register",
    referrer: "https://admin.todo-app.test/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const admin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(admin);

  // 2) Build an unauthenticated connection (no Authorization header)
  const unauthenticated: api.IConnection = {
    ...connection,
    headers: {},
  };

  // 3) Prepare a valid-looking UUID for guestUserId (existence should not be leaked)
  const guestUserId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();

  // 4) Attempt to access the admin-only guest user detail endpoint without token
  //    Expectation: call fails due to missing authentication (some HttpError)
  await TestValidator.error(
    "missing token blocks guest user detail access",
    async () => {
      await api.functional.todoApp.adminUser.guestUsers.at(unauthenticated, {
        guestUserId,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppMemberUser";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate basic member user search pagination for admin users.
 *
 * Business goal:
 *
 * - Ensure that an authenticated admin can list member users without applying
 *   additional filters, using explicit pagination parameters page=1 and
 *   limit=10.
 * - Confirm that the endpoint respects the requested pagination settings and
 *   returns at least one member user when data exists.
 *
 * High-level workflow:
 *
 * 1. Register an admin user (join) so we have an administrative actor.
 * 2. (Optional but explicit) Login as the same admin to confirm token-based
 *    authentication works and that the SDK switches the Authorization header
 *    appropriately.
 * 3. As the admin actor, create at least one system setting entry required by the
 *    todoApp backend (e.g., a limit-related or feature-flag configuration).
 * 4. Register a member user (join) so that there is at least one member account to
 *    be listed, and ensure the member has at least one todo.
 * 5. Perform a member login for that member and create a todo item to satisfy the
 *    dependency "member user with at least one todo exists".
 * 6. Switch back to the admin actor (login) so that subsequent admin APIs are
 *    authorized as an admin user.
 * 7. Call PATCH /todoApp/adminUser/memberUsers with an ITodoAppMemberUser.IRequest
 *    body specifying:
 *
 *    - Page: 1
 *    - Limit: 10
 *    - No search/status/date filters (all omitted)
 * 8. Validate the response:
 *
 *    - Typia.assert on the IPageITodoAppMemberUser.ISummary response.
 *    - Pagination.current === 1.
 *    - Pagination.limit === 10.
 *    - Pagination.records >= 1.
 *    - Pagination.pages >= 1.
 *    - Data array is non-empty and has length <= 10.
 *    - At least one entry in data has required fields:
 *
 *         - Id: UUID string.
 *         - Email: valid email format.
 *         - Status: non-empty string.
 *         - Created_at: valid date-time string. and display_name may be null or string
 *                   (no extra validation beyond type).
 *    - Optionally, verify that the specific member we created is present in the
 *         result set (by matching its id or email) when it falls into the first
 *         page.
 */
export async function test_api_admin_member_users_search_basic_pagination(
  connection: api.IConnection,
) {
  // 1. Register an admin user via /auth/adminUser/join
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12) as string &
      tags.Format<"password">,
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todo-app.test/join",
    referrer: "https://admin.todo-app.test/",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorizedFromJoin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorizedFromJoin);

  // 2. Explicitly login as the same admin to validate token swap and ensure
  //    we have a clean admin authentication context.
  const adminAuthorizedFromLogin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: {
        email: adminJoinBody.email,
        password: adminJoinBody.password,
        ip: "127.0.0.1",
        href: "https://admin.todo-app.test/login",
        referrer: "https://admin.todo-app.test/",
      } satisfies ITodoAppAdminUser.ILogin,
    });
  typia.assert(adminAuthorizedFromLogin);

  // 3. As the admin actor, create a system setting entry that might influence
  //    todo limits or feature flags.
  const systemSettingCreateBody = {
    key: `max_active_todos_per_user_${RandomGenerator.alphaNumeric(8)}`,
    value: "100",
    type: "int",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const createdSystemSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: systemSettingCreateBody,
    });
  typia.assert(createdSystemSetting);

  // 4. Register a member user via /auth/memberUser/join so that there is at
  //    least one member to be found.
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12) as string &
      tags.Format<"password">,
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.test/join",
    referrer: "https://todo-app.test/landing",
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberAuthorizedFromJoin: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorizedFromJoin);

  // 5. Login as the member and create at least one todo so that the member has
  //    concrete activity in the system.
  const memberAuthorizedFromLogin: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: {
        email: memberJoinBody.email,
        password: memberJoinBody.password,
        ip: null,
        href: "https://todo-app.test/login",
        referrer: "https://todo-app.test/landing",
      } satisfies ITodoAppMemberUserLogin.ICreate,
    });
  typia.assert(memberAuthorizedFromLogin);

  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
    due_date: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(),
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(createdTodo);

  // 6. Switch back to the admin actor by logging in again as the admin user.
  const adminAuthorizedForSearch: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: {
        email: adminJoinBody.email,
        password: adminJoinBody.password,
        ip: "127.0.0.1",
        href: "https://admin.todo-app.test/login",
        referrer: "https://admin.todo-app.test/",
      } satisfies ITodoAppAdminUser.ILogin,
    });
  typia.assert(adminAuthorizedForSearch);

  // 7. Perform the admin-side member user search with explicit page and limit
  //    and no other filters.
  const requestBody = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 10 as number & tags.Type<"int32"> & tags.Minimum<1>,
  } satisfies ITodoAppMemberUser.IRequest;

  const pageResult: IPageITodoAppMemberUser.ISummary =
    await api.functional.todoApp.adminUser.memberUsers.index(connection, {
      body: requestBody,
    });
  typia.assert(pageResult);

  const pagination = pageResult.pagination;
  typia.assert<IPage.IPagination>(pagination);

  // 8. Validate pagination metadata and data collection.
  TestValidator.equals(
    "pagination current page should be 1",
    pagination.current,
    1,
  );

  TestValidator.equals("pagination limit should be 10", pagination.limit, 10);

  TestValidator.predicate(
    "pagination records should be at least 1 when member exists",
    pagination.records >= 1,
  );

  TestValidator.predicate(
    "pagination pages should be at least 1",
    pagination.pages >= 1,
  );

  TestValidator.predicate(
    "data array should not be empty when records >= 1",
    pageResult.data.length >= 1,
  );

  TestValidator.predicate(
    "data array length should not exceed requested limit",
    pageResult.data.length <= requestBody.limit!,
  );

  // Pick the first summary entry to validate its fields.
  const firstSummary: ITodoAppMemberUser.ISummary = pageResult.data[0];
  typia.assert(firstSummary);

  TestValidator.predicate(
    "member summary id should be a non-empty string",
    typeof firstSummary.id === "string" && firstSummary.id.length > 0,
  );

  TestValidator.predicate(
    "member summary email should be a non-empty string",
    typeof firstSummary.email === "string" && firstSummary.email.length > 0,
  );

  TestValidator.predicate(
    "member summary status should be a non-empty string",
    typeof firstSummary.status === "string" && firstSummary.status.length > 0,
  );

  TestValidator.predicate(
    "member summary created_at should be a non-empty string",
    typeof firstSummary.created_at === "string" &&
      firstSummary.created_at.length > 0,
  );

  // Confirm that the specific member we created is included in the dataset of
  // the first page when possible (best-effort, soft assertion).
  const createdMemberId = memberAuthorizedFromJoin.id;
  const createdMemberInPage = pageResult.data.find(
    (item) => item.id === createdMemberId,
  );

  TestValidator.predicate(
    "created member should appear in at least one page of results (best-effort)",
    createdMemberInPage !== undefined,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppMemberUser";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

export async function test_api_admin_member_users_search_with_filters_and_sorting(
  connection: api.IConnection,
) {
  // 1. Register and implicitly authenticate an admin user via join
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const adminPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();
  const adminHref: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();
  const adminReferrer: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword,
    display_name: RandomGenerator.name(2),
    status: "active",
    ip: "127.0.0.1",
    href: adminHref,
    referrer: adminReferrer,
  } satisfies ITodoAppAdminUser.IJoin;

  const admin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(admin);

  // 2. Configure a system setting as admin: max_active_todos_per_user enabled=true
  const settingKey = "max_active_todos_per_user";
  const systemSettingBody = {
    key: settingKey,
    value: "100", // numeric limit encoded as string
    type: "int",
    description: "Maximum number of active todos per member user for testing",
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const systemSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: systemSettingBody,
    });
  typia.assert(systemSetting);
  TestValidator.equals(
    "system setting key should match",
    systemSetting.key,
    settingKey,
  );

  // 3. Create multiple member users with different identities
  // We will create three member users: two intended as active (one will have a todo), one extra.
  const memberHref: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();
  const memberReferrer: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();

  const makeMemberJoinBody = (
    email: string & tags.Format<"email">,
    password: string & tags.Format<"password">,
    displayName: string,
  ): ITodoAppMemberUserJoin.ICreate => ({
    email,
    password,
    displayName,
    ip: null,
    href: memberHref,
    referrer: memberReferrer,
  });

  const activeEmail1: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const activeEmail2: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const otherEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const activePassword1: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();
  const activePassword2: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();
  const otherPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const activeDisplayName1 = RandomGenerator.name(2);
  const activeDisplayName2 = RandomGenerator.name(2);
  const otherDisplayName = RandomGenerator.name(2);

  const member1: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: makeMemberJoinBody(
        activeEmail1,
        activePassword1,
        activeDisplayName1,
      ),
    });
  typia.assert(member1);

  const member2: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: makeMemberJoinBody(
        activeEmail2,
        activePassword2,
        activeDisplayName2,
      ),
    });
  typia.assert(member2);

  const member3: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: makeMemberJoinBody(otherEmail, otherPassword, otherDisplayName),
    });
  typia.assert(member3);

  const activeMembers: ITodoAppMemberUser.IAuthorized[] = [member1, member2];
  const otherMembers: ITodoAppMemberUser.IAuthorized[] = [member3];

  // At least member1 should be active according to the backend's default rules
  TestValidator.equals(
    "member1 status should be active",
    activeMembers[0].status,
    "active",
  );

  // 4. Ensure at least one member has a todo
  // Login as member1 using the same credentials used at join time
  const memberLoginHref: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();
  const memberLoginReferrer: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();

  const member1LoginBody = {
    email: member1.email,
    password: activePassword1,
    ip: null,
    href: memberLoginHref,
    referrer: memberLoginReferrer,
  } satisfies ITodoAppMemberUserLogin.ICreate;

  const member1Login: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: member1LoginBody,
    });
  typia.assert(member1Login);

  // Create a todo for member1
  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 8 }),
    due_date: new Date().toISOString(),
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const todo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(todo);
  TestValidator.equals(
    "todo member id should match member1",
    todo.memberUser.id,
    member1.id,
  );

  // Capture member created_at timestamps for date range filter
  const createdAtValues: string[] = activeMembers
    .map((m) => m.created_at)
    .concat(otherMembers.map((m) => m.created_at));

  const sortedCreatedAt = [...createdAtValues].sort((a, b) =>
    a.localeCompare(b),
  );
  const createdFrom = sortedCreatedAt[0];
  const createdTo = sortedCreatedAt[sortedCreatedAt.length - 1];

  // 5. Switch back to admin context via explicit login
  const adminLoginHref: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();
  const adminLoginReferrer: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();

  const adminLoginBody = {
    email: admin.email,
    password: adminPassword,
    ip: null,
    href: adminLoginHref,
    referrer: adminLoginReferrer,
  } satisfies ITodoAppAdminUser.ILogin;

  const adminLogin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLogin);

  // 6. Call PATCH /todoApp/adminUser/memberUsers with ITodoAppMemberUser.IRequest
  // Use a search term that matches member1 display_name or email
  const searchTerm = member1.display_name ?? member1.email;

  const requestBody = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 5 as number & tags.Type<"int32"> & tags.Minimum<1>,
    status: "active",
    search: searchTerm,
    created_from: createdFrom,
    created_to: createdTo,
    order_by: "created_at",
    order_direction: "desc",
  } satisfies ITodoAppMemberUser.IRequest;

  const pageResult: IPageITodoAppMemberUser.ISummary =
    await api.functional.todoApp.adminUser.memberUsers.index(connection, {
      body: requestBody,
    });
  typia.assert(pageResult);

  const pagination: IPage.IPagination = pageResult.pagination;
  typia.assert(pagination);

  const summaries: ITodoAppMemberUser.ISummary[] = pageResult.data;

  // 7. Validate that all returned summaries satisfy business conditions
  for (const summary of summaries) {
    TestValidator.equals(
      "member summary status should be active",
      summary.status,
      "active",
    );

    TestValidator.predicate(
      "member created_at within requested range",
      summary.created_at >= createdFrom && summary.created_at <= createdTo,
    );

    if (requestBody.search && requestBody.search.length > 0) {
      const lowerSearch = requestBody.search.toLowerCase();
      const emailMatch = summary.email.toLowerCase().includes(lowerSearch);
      const displayMatch = (summary.display_name ?? "")
        .toLowerCase()
        .includes(lowerSearch);
      TestValidator.predicate(
        "email or display_name should match search term when provided",
        emailMatch || displayMatch,
      );
    }
  }

  // Verify ordering: created_at descending
  for (let i = 1; i < summaries.length; i++) {
    const prev = summaries[i - 1];
    const curr = summaries[i];
    TestValidator.predicate(
      "results should be ordered by created_at descending",
      prev.created_at >= curr.created_at,
    );
  }

  // 8. Confirm pagination metadata consistency
  TestValidator.predicate(
    "pagination current page matches request",
    pagination.current === 1,
  );

  TestValidator.predicate(
    "pagination limit is at least requested limit",
    pagination.limit >= 5,
  );

  TestValidator.predicate(
    "pagination records should be >= data length",
    pagination.records >= summaries.length,
  );

  if (pagination.limit > 0) {
    TestValidator.predicate(
      "pagination pages * limit covers records",
      pagination.pages * pagination.limit >= pagination.records,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
