export async function test_api_admin_member_users_search_empty_result_set(
  connection: api.IConnection,
) {
  // 1. Create and auto-login an admin user via join
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminJoinBody = {
    email: adminEmail,
    password: "Admin1234!", // any strong-ish password string
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todo-app.test/join",
    referrer: "https://admin.todo-app.test/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Initialize at least one system setting so configuration exists
  const settingCreateBody = {
    key: `test_empty_member_search_${RandomGenerator.alphaNumeric(8)}`,
    value: "true",
    type: "boolean",
    description: "Enable member search for E2E empty-result test",
    group: "e2e-test",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const systemSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: settingCreateBody,
    });
  typia.assert(systemSetting);

  // 3. Create a baseline member user and a todo, so database is not globally empty
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const memberJoinBody = {
    email: memberEmail,
    password: typia.random<string & tags.Format<"password">>(),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.test/signup",
    referrer: "https://todo-app.test/landing",
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberAuthorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // Member login (not strictly required if join already authenticates, but
  // exercise the login flow as dependency describes multi-actor switching).
  const memberLoginBody = {
    email: memberEmail,
    password: memberJoinBody.password,
    ip: null,
    href: "https://todo-app.test/login",
    referrer: "https://todo-app.test/landing",
  } satisfies ITodoAppMemberUserLogin.ICreate;

  const memberAuthorizedAfterLogin: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberAuthorizedAfterLogin);

  // Create at least one todo for the member user
  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
    due_date: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(),
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(createdTodo);

  // 4. Switch back to admin context by logging in as the admin user
  const adminLoginBody = {
    email: adminEmail,
    password: adminJoinBody.password,
    ip: null,
    href: "https://admin.todo-app.test/login",
    referrer: "https://admin.todo-app.test/landing",
  } satisfies ITodoAppAdminUser.ILogin;

  const adminAuthorizedAfterLogin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminAuthorizedAfterLogin);

  // 5a. Control call: relaxed filter expected to return at least one member
  const relaxedRequestBody = {
    page: 1,
    limit: 10,
  } satisfies ITodoAppMemberUser.IRequest;

  const relaxedPage: IPageITodoAppMemberUser.ISummary =
    await api.functional.todoApp.adminUser.memberUsers.index(connection, {
      body: relaxedRequestBody,
    });
  typia.assert(relaxedPage);

  TestValidator.predicate(
    "relaxed member search should return at least one record",
    relaxedPage.data.length > 0,
  );
  TestValidator.predicate(
    "relaxed pagination.records must be >= data.length",
    relaxedPage.pagination.records >= relaxedPage.data.length,
  );

  // 5b. Main scenario: choose filters that intentionally yield an empty set.
  // Use a created_from in the far future to guarantee no matches.
  const futureFrom: string = new Date(
    Date.now() + 365 * 24 * 60 * 60 * 1000,
  ).toISOString();
  const futureTo: string = new Date(
    Date.now() + 366 * 24 * 60 * 60 * 1000,
  ).toISOString();

  const emptyRequestBody = {
    page: 1,
    limit: 10,
    created_from: futureFrom,
    created_to: futureTo,
  } satisfies ITodoAppMemberUser.IRequest;

  const emptyPage: IPageITodoAppMemberUser.ISummary =
    await api.functional.todoApp.adminUser.memberUsers.index(connection, {
      body: emptyRequestBody,
    });
  typia.assert(emptyPage);

  // 6. Validate empty result set and consistent pagination metadata
  TestValidator.equals(
    "empty filter should return empty data array",
    emptyPage.data.length,
    0,
  );

  TestValidator.equals(
    "empty filter should report zero records",
    emptyPage.pagination.records,
    0,
  );

  TestValidator.predicate(
    "pages should be zero or one when there are no records",
    emptyPage.pagination.pages === 0 || emptyPage.pagination.pages === 1,
  );

  TestValidator.predicate(
    "pagination.current should be non-negative even for empty results",
    emptyPage.pagination.current >= 0,
  );

  TestValidator.predicate(
    "pagination.limit should be non-negative",
    emptyPage.pagination.limit >= 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppMemberUser";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";

/**
 * Verify that the admin-only member user search endpoint cannot be accessed
 * when no Authorization token is present on the connection.
 *
 * Business context:
 *
 * - /todoApp/adminUser/memberUsers exposes paginated views of sensitive member
 *   user accounts (ITodoAppMemberUser.ISummary records wrapped in
 *   IPageITodoAppMemberUser.ISummary).
 * - According to the requirements, this endpoint is intended for the `adminUser`
 *   actor only, and must not be callable with a missing or invalid token.
 *
 * Test objective:
 *
 * - Ensure that when the PATCH /todoApp/adminUser/memberUsers endpoint is called
 *   without any Authorization header, the SDK throws an error and no member
 *   user data is returned.
 * - We do NOT validate HTTP status code or error body structure; we only assert
 *   that an error occurs, in line with global E2E rules.
 *
 * Steps:
 *
 * 1. Prepare a minimal, valid ITodoAppMemberUser.IRequest body using page=1 and
 *    limit=10 so that the backend validation would pass if authorization were
 *    present.
 * 2. Construct an unauthenticated connection by shallow-copying the provided
 *    `connection` and replacing its headers with an empty object, thereby
 *    removing any Authorization token that may have been set by previous
 *    tests.
 * 3. Call api.functional.todoApp.adminUser.memberUsers.index with this
 *    unauthenticated connection and the valid request body inside an async
 *    closure passed to TestValidator.error.
 * 4. Await TestValidator.error with a descriptive title, asserting that the call
 *    results in an error (authentication failure) rather than a successful page
 *    of member users.
 */
export async function test_api_admin_member_users_search_unauthorized_access_blocked_by_missing_token(
  connection: api.IConnection,
) {
  // 1. Prepare minimal, valid search request body
  const requestBody = {
    page: 1,
    limit: 10,
  } satisfies ITodoAppMemberUser.IRequest;

  // 2. Create an unauthenticated connection (no Authorization header)
  //    We must not mutate the original connection.headers directly.
  const unauthenticatedConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  // 3 & 4. Attempt to call the admin-only search endpoint without token
  //        and assert that it fails.
  await TestValidator.error(
    "member user search must fail without admin Authorization token",
    async () => {
      await api.functional.todoApp.adminUser.memberUsers.index(
        unauthenticatedConnection,
        {
          body: requestBody,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppMemberUser";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";

/**
 * Verify that the admin-only member user search endpoint rejects access when
 * called from a non-admin (unauthenticated) context.
 *
 * Business context:
 *
 * - The PATCH /todoApp/adminUser/memberUsers endpoint is reserved for
 *   administrative users (adminUser actor).
 * - Only authenticated adminUser sessions (established via POST
 *   /auth/adminUser/join or equivalent) may invoke this endpoint to search and
 *   paginate member users.
 * - Any non-admin or unauthenticated context must be blocked from accessing this
 *   endpoint to preserve role-based access control.
 *
 * Test workflow:
 *
 * 1. (Sanity) Use the provided `connection` to join as an adminUser and verify
 *    that the member user search endpoint works in an authenticated admin
 *    context.
 * 2. Construct a new connection object that mimics a non-admin context by clearing
 *    headers (no Authorization token).
 * 3. Attempt to call PATCH /todoApp/adminUser/memberUsers with this
 *    unauthenticated connection and a simple ITodoAppMemberUser.IRequest body
 *    (page: 1, limit: 5).
 * 4. Assert that the call fails by using TestValidator.error, without checking
 *    specific HTTP status codes, only that an error occurs.
 *
 * This validates that the endpoint enforces admin-only access and does not
 * allow anonymous or non-admin callers to retrieve member user data.
 */
export async function test_api_admin_member_users_search_forbidden_for_non_admin_context(
  connection: api.IConnection,
) {
  // 1. Sanity: establish an adminUser session and verify that the
  //    member user search endpoint works in an authenticated context.
  const adminJoinInput = typia.random<ITodoAppAdminUser.IJoin>();

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinInput,
    });
  typia.assert(adminAuthorized);

  const adminSearchResponse: IPageITodoAppMemberUser.ISummary =
    await api.functional.todoApp.adminUser.memberUsers.index(connection, {
      body: {
        page: 1,
        limit: 5,
      } satisfies ITodoAppMemberUser.IRequest,
    });
  typia.assert(adminSearchResponse);

  // Basic sanity check on pagination fields to ensure endpoint behaves
  // normally in admin context.
  TestValidator.predicate(
    "admin context: pagination current page is non-negative",
    adminSearchResponse.pagination.current >= 0,
  );
  TestValidator.predicate(
    "admin context: pagination limit is positive",
    adminSearchResponse.pagination.limit > 0,
  );

  // 2. Build a non-admin/unauthenticated connection by cloning the
  //    existing connection but providing an empty headers object.
  //    Do not touch `connection.headers` directly, as the SDK manages it.
  const unauthConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  // 3. Attempt to call the admin-only endpoint with the unauthenticated
  //    connection. This should fail due to missing adminUser
  //    authorization.
  await TestValidator.error(
    "non-admin (unauthenticated) context cannot access admin-only member user search",
    async () => {
      await api.functional.todoApp.adminUser.memberUsers.index(
        unauthConnection,
        {
          body: {
            page: 1,
            limit: 5,
          } satisfies ITodoAppMemberUser.IRequest,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";

/**
 * Validate that an authenticated admin user can invoke the self session erase
 * endpoint and that unauthenticated callers are rejected.
 *
 * Business focus:
 *
 * - Ensure an admin can call DELETE
 *   /todoApp/adminUser/adminUsers/{adminUserId}/sessions/{sessionId} while
 *   authenticated.
 * - Confirm that after attempting to erase a session, the admin can still perform
 *   other privileged operations (system settings creation) using the remaining
 *   valid session.
 * - Verify that unauthenticated connections cannot call the erase endpoint.
 *
 * Scenario steps:
 *
 * 1. Register a new admin account via /auth/adminUser/join (creates session A).
 * 2. Log in as the same admin via /auth/adminUser/login (creates session B).
 * 3. Create a system setting using the authenticated admin context.
 * 4. Call the erase endpoint with the admin's id and a UUID session id.
 * 5. Verify that the call succeeds and that admin operations still work afterward
 *    by creating another system setting.
 * 6. Using an unauthenticated connection, attempt to call erase again and expect
 *    an error.
 */
export async function test_api_admin_session_erase_self_session(
  connection: api.IConnection,
) {
  // 1. Register a new admin user (session A is created implicitly)
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const adminPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const joinBody = {
    email: adminEmail,
    password: adminPassword,
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todoapp.test/join",
    referrer: "https://landing.todoapp.test/",
  } satisfies ITodoAppAdminUser.IJoin;

  const joinedAdmin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert(joinedAdmin);

  const adminUserId: string & tags.Format<"uuid"> = joinedAdmin.id;

  // 2. Log in as the same admin (session B)
  const loginBody = {
    email: adminEmail,
    password: adminPassword,
    ip: "127.0.0.1",
    href: "https://admin.todoapp.test/login",
    referrer: "https://admin.todoapp.test/join",
  } satisfies ITodoAppAdminUser.ILogin;

  const loggedInAdmin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: loginBody,
    });
  typia.assert(loggedInAdmin);

  TestValidator.equals(
    "login should return same admin id as join",
    loggedInAdmin.id,
    adminUserId,
  );

  // 3. Create an initial system setting to ensure admin environment works
  const firstSettingBody = {
    key: `max_todos_${RandomGenerator.alphaNumeric(8)}`,
    value: "100",
    type: "int",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const firstSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: firstSettingBody,
    });
  typia.assert(firstSetting);

  TestValidator.equals(
    "first system setting key matches request",
    firstSetting.key,
    firstSettingBody.key,
  );

  // 4. Call erase on a session id for this admin
  const targetSessionId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();

  let eraseReached = false;
  await api.functional.todoApp.adminUser.adminUsers.sessions.erase(connection, {
    adminUserId,
    sessionId: targetSessionId,
  });
  eraseReached = true;

  TestValidator.predicate(
    "erase should complete without throwing in authenticated context",
    eraseReached,
  );

  // 5. Verify that admin operations still work after erase by creating
  //    another system setting with the current authenticated context.
  const secondSettingBody = {
    key: `feature_flag_${RandomGenerator.alphaNumeric(8)}`,
    value: "true",
    type: "boolean",
    description: RandomGenerator.paragraph({ sentences: 2 }),
    group: "features",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const secondSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: secondSettingBody,
    });
  typia.assert(secondSetting);

  TestValidator.equals(
    "second system setting key matches request",
    secondSetting.key,
    secondSettingBody.key,
  );

  // 6. Negative scenario: unauthenticated client cannot erase sessions
  const unauthenticatedConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  await TestValidator.error("unauthenticated erase should fail", async () => {
    await api.functional.todoApp.adminUser.adminUsers.sessions.erase(
      unauthenticatedConnection,
      {
        adminUserId,
        sessionId: typia.random<string & tags.Format<"uuid">>(),
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
