  // 3. Call the session erase endpoint for a random target session of this admin
  const targetSessionId = typia.random<string & tags.Format<"uuid">>();

  await api.functional.todoApp.adminUser.adminUsers.sessions.erase(connection, {
    adminUserId: joinedAdmin.id,
    sessionId: targetSessionId,
  });

  // 4. After erase, ensure the current admin token can still perform admin actions
  const secondSettingBody = {
    key: `feature_flag_${RandomGenerator.alphabets(6)}`,
    value: "true",
    type: "boolean",
    description: RandomGenerator.paragraph({ sentences: 2 }),
    group: "features",
    enabled: firstSetting.enabled,
  } satisfies ITodoAppSystemSetting.ICreate;

  const secondSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: secondSettingBody,
    });
  typia.assert<ITodoAppSystemSetting>(secondSetting);

  // 5. Basic logical validations on the created settings
  TestValidator.predicate(
    "system setting keys should differ between first and second creation",
    firstSetting.key !== secondSetting.key,
  );
  TestValidator.equals(
    "enabled flags of both settings should match",
    firstSetting.enabled,
    secondSetting.enabled,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";

export async function test_api_admin_session_erase_not_found_or_mismatched(
  connection: api.IConnection,
) {
  // 1. Register Admin A and obtain authorized context
  const adminAJoinBody = {
    email: `${RandomGenerator.alphabets(8)}@example.com`,
    password: RandomGenerator.alphabets(12),
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminA: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminAJoinBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminA);

  // 2. Optionally log in Admin A again to simulate multiple sessions (not strictly required)
  const adminALoginBody = {
    email: adminA.email,
    password: adminAJoinBody.password,
    ip: "127.0.0.1",
    href: "https://admin.example.com/login",
    referrer: "https://admin.example.com/login-ref",
  } satisfies ITodoAppAdminUser.ILogin;

  const adminALogin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminALoginBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminALogin);

  // Ensure we’re using the latest Admin A identity consistently
  TestValidator.equals(
    "Admin A id from join and login should match",
    adminA.id,
    adminALogin.id,
  );

  const adminUserIdA = adminA.id;

  // 3. Register Admin B and obtain authorized context
  const adminBJoinBody = {
    email: `${RandomGenerator.alphabets(8)}@example.com`,
    password: RandomGenerator.alphabets(12),
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminB: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminBJoinBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminB);

  const adminUserIdB = adminB.id;

  TestValidator.notEquals(
    "Admin A and Admin B must be distinct admins",
    adminUserIdA,
    adminUserIdB,
  );

  // At this point, connection headers contain Admin B token
  // Switch back to Admin A by logging in again as Admin A
  const adminALoginAgain: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminALoginBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminALoginAgain);

  // 4. While authenticated as Admin A, initialize a system setting to prove valid admin context
  const systemSettingCreateBody = {
    key: `max_active_todos_${RandomGenerator.alphabets(6)}`,
    value: "100",
    type: "int",
    description: "Max active todos per user for test scenario",
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const createdSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: systemSettingCreateBody,
    });
  typia.assert<ITodoAppSystemSetting>(createdSetting);

  TestValidator.equals(
    "Created system setting key should match request",
    createdSetting.key,
    systemSettingCreateBody.key,
  );

  // 5. Case 1: Attempt to delete a non-existent session for Admin A
  const randomSessionIdNonexistent = typia.random<
    string & tags.Format<"uuid">
  >();

  await TestValidator.error(
    "Deleting a non-existent session for Admin A should fail",
    async () => {
      await api.functional.todoApp.adminUser.adminUsers.sessions.erase(
        connection,
        {
          adminUserId: adminUserIdA,
          sessionId: randomSessionIdNonexistent,
        },
      );
    },
  );

  // 6. Case 2: Attempt to delete a session that (conceptually) belongs to another admin
  // We cannot access real session IDs, but we can still verify that arbitrary UUIDs
  // not associated with Admin A are rejected.
  const randomSessionIdMismatched = typia.random<
    string & tags.Format<"uuid">
  >();

  await TestValidator.error(
    "Deleting a mismatched admin/session pair for Admin A should fail",
    async () => {
      await api.functional.todoApp.adminUser.adminUsers.sessions.erase(
        connection,
        {
          adminUserId: adminUserIdA,
          sessionId: randomSessionIdMismatched,
        },
      );
    },
  );

  // 7. After failed deletions, verify Admin A can still perform admin-only operations
  const postFailureSettingBody = {
    key: `post_failure_setting_${RandomGenerator.alphabets(6)}`,
    value: "1",
    type: "int",
    description: "Setting created after failed session deletions",
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const postFailureSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: postFailureSettingBody,
    });
  typia.assert<ITodoAppSystemSetting>(postFailureSetting);

  TestValidator.equals(
    "Post-failure system setting key should match request",
    postFailureSetting.key,
    postFailureSettingBody.key,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IETodoAppActorKind } from "@ORGANIZATION/PROJECT-api/lib/structures/IETodoAppActorKind";
import type { ITodoAppActorCurrent } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppActorCurrent";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate memberUser actor context immediately after self-registration.
 *
 * This test ensures that when a new member user joins the todoApp service
 * through the memberUser join endpoint, the unified actor endpoint
 * `/todoApp/memberUser/actors/current` correctly resolves that session as a
 * `memberUser` actor. It also verifies that the member context can be used for
 * normal business operations, and that unauthenticated access to
 * `/actors/current` is rejected.
 *
 * Workflow:
 *
 * 1. Self-register a new member user using POST /auth/memberUser/join.
 * 2. Using the authenticated member context (token set by SDK), create a simple
 *    todo via POST /todoApp/memberUser/todos.
 * 3. Call GET /todoApp/memberUser/actors/current and assert that:
 *
 *    - ActorKind is `"memberUser"`.
 *    - MemberUser is non-null and its id, email, status, created_at match the joined
 *         member summary.
 *    - AdminUser and guestUser are null.
 * 4. Create an unauthenticated connection and confirm that calling /actors/current
 *    without credentials results in an authentication error.
 */
export async function test_api_actor_current_member_context_after_join(
  connection: api.IConnection,
) {
  // 1. Register a new member user (join)
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    displayName: RandomGenerator.name(),
    ip: typia.random<string & tags.Format<"ipv4">>(),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const joinedMember: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(joinedMember);

  // 2. Create a simple todo as the joined member to confirm business context
  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
    due_date: null,
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(createdTodo);

  // Ensure the todo belongs to the joined member
  TestValidator.equals(
    "created todo must belong to joined member",
    createdTodo.memberUser.id,
    joinedMember.id,
  );

  // 3. Fetch current actor as memberUser
  const actorCurrent: ITodoAppActorCurrent =
    await api.functional.todoApp.memberUser.actors.current.at(connection);
  typia.assert(actorCurrent);

  // Validate that actorKind is memberUser
  TestValidator.equals(
    "actorKind equals memberUser",
    actorCurrent.actorKind,
    "memberUser" as IETodoAppActorKind,
  );

  // Validate memberUser summary matches joined member basic info
  TestValidator.predicate(
    "memberUser summary must not be null",
    actorCurrent.memberUser !== null,
  );

  if (actorCurrent.memberUser !== null) {
    TestValidator.equals(
      "member summary id must match joined member id",
      actorCurrent.memberUser.id,
      joinedMember.id,
    );
    TestValidator.equals(
      "member summary email must match joined member email",
      actorCurrent.memberUser.email,
      joinedMember.email,
    );
    TestValidator.equals(
      "member summary status must match joined member status",
      actorCurrent.memberUser.status,
      joinedMember.status,
    );
    TestValidator.equals(
      "member summary created_at must match joined member created_at",
      actorCurrent.memberUser.created_at,
      joinedMember.created_at,
    );
  }

  // Ensure adminUser and guestUser are null
  TestValidator.equals(
    "adminUser summary must be null for memberUser actor",
    actorCurrent.adminUser,
    null,
  );
  TestValidator.equals(
    "guestUser summary must be null for memberUser actor",
    actorCurrent.guestUser,
    null,
  );

  // 4. Unauthenticated access should fail
  const unauthConn: api.IConnection = { ...connection, headers: {} };

  await TestValidator.error(
    "unauthenticated /actors/current must fail",
    async () => {
      await api.functional.todoApp.memberUser.actors.current.at(unauthConn);
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IETodoAppActorKind } from "@ORGANIZATION/PROJECT-api/lib/structures/IETodoAppActorKind";
import type { ITodoAppActorCurrent } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppActorCurrent";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

export async function test_api_actor_current_member_context_after_login(
  connection: api.IConnection,
) {
  // 1. Register a new member user via join to establish a stable identity.
  const email: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const password: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const joinBody = {
    email,
    password,
    displayName: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const joined: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert(joined);

  // Create a fresh unauthenticated connection for explicit login tests.
  const baseConnection: api.IConnection = { ...connection, headers: {} };

  // 2. Explicit login with the same credentials using the fresh connection.
  const loginBody = {
    email,
    password,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserLogin.ICreate;

  const loggedIn: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.login(baseConnection, {
      body: loginBody,
    });
  typia.assert(loggedIn);

  TestValidator.equals(
    "joined and logged-in member id should match",
    loggedIn.id,
    joined.id,
  );
  TestValidator.equals(
    "joined and logged-in member email should match",
    loggedIn.email,
    joined.email,
  );

  // 3. Create a todo as this member to ensure the session works.
  const todoBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 5 }),
    due_date: new Date().toISOString(),
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(baseConnection, {
      body: todoBody,
    });
  typia.assert(createdTodo);

  TestValidator.equals(
    "todo should belong to logged-in member by id",
    createdTodo.memberUser.id,
    loggedIn.id,
  );

  // 4. Call /todoApp/memberUser/actors/current twice to validate actor context.
  const actor1: ITodoAppActorCurrent =
    await api.functional.todoApp.memberUser.actors.current.at(baseConnection);
  typia.assert(actor1);

  const actor2: ITodoAppActorCurrent =
    await api.functional.todoApp.memberUser.actors.current.at(baseConnection);
  typia.assert(actor2);

  // 5. Validate business invariants for actor context.
  TestValidator.equals(
    "actorKind must be memberUser",
    actor1.actorKind,
    "memberUser",
  );

  TestValidator.equals(
    "adminUser must be null for member session",
    actor1.adminUser,
    null,
  );
  TestValidator.equals(
    "guestUser must be null for member session",
    actor1.guestUser,
    null,
  );

  // memberUser summary should be non-null and match logged-in member.
  TestValidator.predicate(
    "memberUser summary should be non-null",
    () => actor1.memberUser !== null,
  );

  if (actor1.memberUser !== null) {
    TestValidator.equals(
      "actor memberUser id should match logged-in id",
      actor1.memberUser.id,
      loggedIn.id,
    );
    TestValidator.equals(
      "actor memberUser email should match logged-in email",
      actor1.memberUser.email,
      loggedIn.email,
    );
    TestValidator.equals(
      "actor memberUser status should match logged-in status",
      actor1.memberUser.status,
      loggedIn.status,
    );
  }

  // 6. Ensure stability: repeated /actors/current calls should be consistent.
  TestValidator.equals(
    "actorKind should remain stable across calls",
    actor2.actorKind,
    actor1.actorKind,
  );

  TestValidator.equals(
    "adminUser should remain null across calls",
    actor2.adminUser,
    actor1.adminUser,
  );

  TestValidator.equals(
    "guestUser should remain null across calls",
    actor2.guestUser,
    actor1.guestUser,
  );

  // For memberUser, validate identity equality when both non-null.
  TestValidator.predicate(
    "memberUser identity stable across calls",
    () =>
      actor1.memberUser !== null &&
      actor2.memberUser !== null &&
      actor1.memberUser.id === actor2.memberUser.id &&
      actor1.memberUser.email === actor2.memberUser.email,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IETodoAppActorKind } from "@ORGANIZATION/PROJECT-api/lib/structures/IETodoAppActorKind";
import type { ITodoAppActorCurrent } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppActorCurrent";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate that GET /todoApp/memberUser/actors/current enforces authentication.
 *
 * Business goals:
 *
 * - Prove that an authenticated memberUser can successfully retrieve their
 *   unified actor representation via /todoApp/memberUser/actors/current.
 * - Prove that an unauthenticated request to the same endpoint fails with an
 *   authentication error and never returns an ITodoAppActorCurrent payload.
 * - Show that existence of valid actors (member/admin/guest) and configured
 *   system settings does not relax the authentication requirement.
 *
 * End-to-end steps:
 *
 * 1. Register a member user through /auth/memberUser/join, which also
 *    authenticates the connection as that member (Authorization header is
 *    automatically attached by the SDK).
 * 2. Register an admin user through /auth/adminUser/join and create a system
 *    setting via /todoApp/adminUser/systemSettings to emulate a production-like
 *    environment where global configuration exists.
 * 3. While authenticated as the member user, call GET
 *    /todoApp/memberUser/actors/current and verify:
 *
 *    - Response conforms to ITodoAppActorCurrent.
 *    - ActorKind is "memberUser".
 *    - MemberUser summary is present and matches the joined member.
 *    - AdminUser and guestUser summaries are null.
 * 4. Still as the authenticated member, create a todo via POST
 *    /todoApp/memberUser/todos to prove that normal member-only operations work
 *    and the auth context is valid.
 * 5. Create a new connection object that has the same host/options as the original
 *    but an empty headers object, representing an unauthenticated client. Do
 *    not mutate headers after creation.
 * 6. Using this unauthenticated connection, attempt GET
 *    /todoApp/memberUser/actors/current inside TestValidator.error with an
 *    async callback, asserting that an error is thrown (without checking exact
 *    HTTP status codes) and therefore no ITodoAppActorCurrent is returned to
 *    unauthenticated callers.
 */
export async function test_api_actor_current_requires_authentication(
  connection: api.IConnection,
) {
  // 1. Register and authenticate a member user.
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    displayName: RandomGenerator.name(1),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberAuthorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert<ITodoAppMemberUser.IAuthorized>(memberAuthorized);

  // Snapshot member summary expectations for later comparison.
  const expectedMemberId = memberAuthorized.id;
  const expectedMemberEmail = memberAuthorized.email;
  const expectedMemberDisplayName = memberAuthorized.display_name ?? null;

  // 2. Register an admin user and create a system setting as that admin.
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(1),
    status: "active",
    ip: "127.0.0.1",
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminAuthorized);

  const systemSettingBody = {
    key: "max_active_todos_per_user",
    value: "100",
    type: "int",
    description: "Maximum number of active todos allowed per member user.",
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const setting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: systemSettingBody,
    });
  typia.assert<ITodoAppSystemSetting>(setting);

  // 3. Switch back to the member user by logging in, ensuring member context.
  const memberLoginBody = {
    email: expectedMemberEmail,
    password: memberJoinBody.password,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserLogin.ICreate;

  const memberLoggedIn: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert<ITodoAppMemberUser.IAuthorized>(memberLoggedIn);

  // 4. As authenticated member, load the current actor.
  const currentActor: ITodoAppActorCurrent =
    await api.functional.todoApp.memberUser.actors.current.at(connection);
  typia.assert<ITodoAppActorCurrent>(currentActor);

  // Validate unified actor representation.
  TestValidator.equals<IETodoAppActorKind, IETodoAppActorKind>(
    "actorKind value",
    currentActor.actorKind,
    "memberUser",
  );

  TestValidator.predicate(
    "memberUser summary must be present",
    currentActor.memberUser !== null,
  );
  TestValidator.predicate(
    "adminUser summary must be null for member actor",
    currentActor.adminUser === null,
  );
  TestValidator.predicate(
    "guestUser summary must be null for member actor",
    currentActor.guestUser === null,
  );

  if (currentActor.memberUser !== null) {
    TestValidator.equals(
      "memberUser id should match authorized member id",
      currentActor.memberUser.id,
      expectedMemberId,
    );
    TestValidator.equals(
      "memberUser email should match authorized member email",
      currentActor.memberUser.email,
      expectedMemberEmail,
    );
    if (expectedMemberDisplayName !== null) {
      TestValidator.equals(
        "memberUser display_name should match when present",
        currentActor.memberUser.display_name,
        expectedMemberDisplayName,
      );
    }
  }

  // 5. As the same member, create a todo to confirm member-only flows.
  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
    due_date: null,
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const todo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert<ITodoAppTodo>(todo);

  TestValidator.equals(
    "created todo owner id must match member id",
    todo.memberUser.id,
    expectedMemberId,
  );

  // 6. Build an unauthenticated connection (no Authorization header).
  const unauthenticated: api.IConnection = {
    ...connection,
    headers: {},
  };

  // 7. Ensure unauthenticated GET /actors/current fails with an error.
  await TestValidator.error(
    "unauthenticated actor current call must fail",
    async () => {
      await api.functional.todoApp.memberUser.actors.current.at(
        unauthenticated,
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppSystemSetting";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";

export async function test_api_system_settings_search_with_basic_filters(
  connection: api.IConnection,
) {
  /**
   * 1. Register and authenticate an admin user via /auth/adminUser/join.
   * 2. Seed multiple system settings with varied keys, groups, and enabled flags
   *    via POST /todoApp/adminUser/systemSettings.
   * 3. Search settings with PATCH /todoApp/adminUser/systemSettings using
   *    ITodoAppSystemSetting.IRequest filters: page, pageSize, key substring,
   *    group, enabled=true.
   * 4. Validate pagination metadata and that returned summaries respect all
   *    filters and match seeded data.
   */

  // 1. Register and authenticate an admin user.
  const joinBody = {
    email: `${RandomGenerator.alphabets(8)}@example.com`,
    password: "Admin!234" as string & tags.Format<"password">,
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todo-app.test/register" as string & tags.Format<"uri">,
    referrer: "https://admin.todo-app.test" as string & tags.Format<"uri">,
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert(adminAuthorized);
  typia.assert<IAuthorizationToken>(adminAuthorized.token);

  // 2. Seed multiple system settings.
  const groupLimits = "limits";
  const groupFeatures = "features";
  const keyPrefix = "max_active_todos";

  const seeds: ITodoAppSystemSetting.ICreate[] = [
    {
      key: `${keyPrefix}_per_user_enabled_true_1`,
      value: "100",
      type: "int",
      description: "Max active todos per user for limits group, enabled",
      group: groupLimits,
      enabled: true,
    },
    {
      key: `${keyPrefix}_per_user_enabled_true_2`,
      value: "200",
      type: "int",
      description: "Another max limit in limits group, enabled",
      group: groupLimits,
      enabled: true,
    },
    {
      key: `${keyPrefix}_per_user_enabled_false_1`,
      value: "300",
      type: "int",
      description: "Disabled setting in limits group",
      group: groupLimits,
      enabled: false,
    },
    {
      key: `otherprefix_enabled_true_1`,
      value: "true",
      type: "boolean",
      description: "Feature flag in features group, enabled",
      group: groupFeatures,
      enabled: true,
    },
    {
      key: `${keyPrefix}_features_group_enabled_true`,
      value: "true",
      type: "boolean",
      description: "Setting in features group but matching key substring",
      group: groupFeatures,
      enabled: true,
    },
  ];

  const createdSettings: ITodoAppSystemSetting[] = [];
  for (const seed of seeds) {
    const created =
      await api.functional.todoApp.adminUser.systemSettings.create(connection, {
        body: seed,
      });
    typia.assert(created);
    createdSettings.push(created);
  }

  // Build a map from key to created setting for later comparison.
  const createdByKey = new Map<string, ITodoAppSystemSetting>();
  for (const setting of createdSettings) {
    createdByKey.set(setting.key, setting);
  }

  // 3. Execute search with basic filters.
  const page = 1 as number & tags.Type<"int32"> & tags.Minimum<1>;
  const pageSize = 10 as number & tags.Type<"int32"> & tags.Minimum<1>;
  const requestBody = {
    page,
    pageSize,
    key: keyPrefix,
    group: groupLimits,
    enabled: true,
    createdFrom: undefined,
    createdTo: undefined,
    updatedFrom: undefined,
    updatedTo: undefined,
    sortBy: "key",
    sortDirection: "asc",
  } satisfies ITodoAppSystemSetting.IRequest;

  const pageResult: IPageITodoAppSystemSetting.ISummary =
    await api.functional.todoApp.adminUser.systemSettings.index(connection, {
      body: requestBody,
    });
  typia.assert(pageResult);

  const pagination = pageResult.pagination;
  const data = pageResult.data;

  // 4. Validate pagination metadata.
  TestValidator.equals(
    "pagination current page matches request",
    pagination.current,
    page,
  );
  TestValidator.equals(
    "pagination limit matches requested pageSize",
    pagination.limit,
    pageSize,
  );

  // Compute expected matches based on seed data.
  const expectedMatches = createdSettings.filter(
    (s) =>
      s.group === groupLimits &&
      s.enabled === true &&
      s.key.includes(keyPrefix),
  );

  TestValidator.predicate(
    "pagination.records is at least number of matching seeded settings",
    () => pagination.records >= expectedMatches.length,
  );

  TestValidator.predicate(
    "pagination.pages is consistent with records and limit",
    () => {
      const expectedPages =
        pagination.limit === 0
          ? 0
          : Math.ceil(pagination.records / pagination.limit);
      return pagination.pages === expectedPages;
    },
  );

  // 5. Validate each returned summary respects filters and matches seeded data.
  for (const summary of data) {
    // typia.assert on each summary is already covered by pageResult assert,
    // but we can rely on type safety here.

    TestValidator.predicate(
      `summary key contains filter substring for key ${summary.key}`,
      () => summary.key.includes(keyPrefix),
    );
    TestValidator.equals(
      `summary group equals requested group for key ${summary.key}`,
      summary.group ?? null,
      groupLimits,
    );
    TestValidator.equals(
      `summary enabled is true for key ${summary.key}`,
      summary.enabled,
      true,
    );

    // Cross-check against seeded data if this key was seeded.
    const original = createdByKey.get(summary.key);
    if (original !== undefined) {
      TestValidator.equals(
        `summary type matches original for key ${summary.key}`,
        summary.type,
        original.type,
      );
      TestValidator.equals(
        `summary value matches original for key ${summary.key}`,
        summary.value,
        original.value,
      );
      TestValidator.equals(
        `summary description matches original (nullable safe) for key ${summary.key}`,
        summary.description ?? null,
        original.description ?? null,
      );
      TestValidator.equals(
        `summary group matches original (nullable safe) for key ${summary.key}`,
        summary.group ?? null,
        original.group ?? null,
      );
      TestValidator.equals(
        `summary enabled matches original for key ${summary.key}`,
        summary.enabled,
        original.enabled,
      );
    }

    // Ensure no summary violates the enabled or group filter from seed space.
    TestValidator.predicate(
      `no summary outside group ${groupLimits} with enabled=false for key ${summary.key}`,
      () => summary.enabled === true && summary.group === groupLimits,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppSystemSetting";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";

export async function test_api_system_settings_search_with_date_and_sorting(
  connection: api.IConnection,
) {
  // 1. Join an admin user to obtain authorized context
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todoapp.local/join",
    referrer: "https://admin.todoapp.local/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const admin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(admin);

  // 2. Create multiple system settings with distinct keys
  const baseKeyPrefix = `e2e_system_setting_${RandomGenerator.alphaNumeric(8)}`;

  const settingsToCreate: ITodoAppSystemSetting.ICreate[] = [
    {
      key: `${baseKeyPrefix}_old_1`,
      value: "10",
      type: "int",
      description: RandomGenerator.paragraph({ sentences: 3 }),
      group: "limits",
      enabled: true,
    },
    {
      key: `${baseKeyPrefix}_old_2`,
      value: "false",
      type: "boolean",
      description: RandomGenerator.paragraph({ sentences: 2 }),
      group: "features",
      enabled: false,
    },
    {
      key: `${baseKeyPrefix}_new_1`,
      value: "true",
      type: "boolean",
      description: RandomGenerator.paragraph({ sentences: 2 }),
      group: "features",
      enabled: true,
    },
    {
      key: `${baseKeyPrefix}_new_2`,
      value: "100",
      type: "int",
      description: RandomGenerator.paragraph({ sentences: 3 }),
      group: "limits",
      enabled: true,
    },
  ];

  const createdSettings: ITodoAppSystemSetting[] = [];
  for (const body of settingsToCreate) {
    const created =
      await api.functional.todoApp.adminUser.systemSettings.create(connection, {
        body,
      });
    typia.assert<ITodoAppSystemSetting>(created);
    createdSettings.push(created);
  }

  // Assume later-created settings have later created_at/updated_at values.
  // Take timestamps around creation of "new" settings as range boundaries.
  const oldSettings = createdSettings.filter((s) => s.key.includes("_old_"));
  const newSettings = createdSettings.filter((s) => s.key.includes("_new_"));

  // Sanity checks for created settings
  TestValidator.equals(
    "there should be both old and new settings",
    createdSettings.length,
    settingsToCreate.length,
  );
  TestValidator.predicate("old settings exist", oldSettings.length > 0);
  TestValidator.predicate("new settings exist", newSettings.length > 0);

  // Derive time window boundaries based on created_at of one old and one new.
  // Use the earliest new and latest created to build a window that focuses on newer records.
  const sortedByCreatedAt = [...createdSettings].sort((a, b) =>
    a.created_at.localeCompare(b.created_at),
  );

  const earliestNew = sortedByCreatedAt.find((s) => s.key.includes("_new_"));

  TestValidator.predicate("earliest new exists", earliestNew !== undefined);

  const createdFrom = earliestNew!.created_at;
  const latestCreated =
    sortedByCreatedAt[sortedByCreatedAt.length - 1]?.created_at ?? createdFrom;
  const createdTo = latestCreated;

  // 3. Search with date range and sorting by updated_at desc
  const requestBody = {
    page: 1,
    pageSize: 20,
    createdFrom,
    createdTo,
    sortBy: "updated_at",
    sortDirection: "desc" as const,
  } satisfies ITodoAppSystemSetting.IRequest;

  const page: IPageITodoAppSystemSetting.ISummary =
    await api.functional.todoApp.adminUser.systemSettings.index(connection, {
      body: requestBody,
    });
  typia.assert<IPageITodoAppSystemSetting.ISummary>(page);

  const { pagination, data } = page;

  // 4. Basic pagination validations
  TestValidator.predicate(
    "pagination current page is 1",
    pagination.current === 1,
  );
  TestValidator.predicate(
    "pagination limit equals requested pageSize",
    pagination.limit === 20,
  );
  TestValidator.predicate("records non-negative", pagination.records >= 0);
  TestValidator.predicate("pages non-negative", pagination.pages >= 0);

  // Records should at least be the number of items in data
  TestValidator.predicate(
    "records greater or equal to data length",
    pagination.records >= data.length,
  );

  // 5. Validate that all returned summaries correspond to created settings when applicable
  const createdById = new Map<string, ITodoAppSystemSetting>();
  for (const s of createdSettings) createdById.set(s.id, s);

  for (const summary of data) {
    const full = createdById.get(summary.id);
    if (full) {
      TestValidator.equals(
        "summary key matches full record",
        full.key,
        summary.key,
      );
      TestValidator.equals(
        "summary value matches full record",
        full.value,
        summary.value,
      );
      TestValidator.equals(
        "summary type matches full record",
        full.type,
        summary.type,
      );
      TestValidator.equals(
        "summary enabled matches full record",
        full.enabled,
        summary.enabled,
      );
    }
  }

  // 6. Verify that at least one old setting is not included in the results
  const resultIds = new Set(data.map((d) => d.id));
  const anyOldExcluded = oldSettings.some((s) => !resultIds.has(s.id));
  TestValidator.predicate(
    "at least one old setting is excluded by date range",
    anyOldExcluded,
  );

  // 7. Verify ordering by updated_at desc using detail GET
  const details: ITodoAppSystemSetting[] = [];
  for (const summary of data) {
    const detail = await api.functional.todoApp.adminUser.systemSettings.at(
      connection,
      {
        settingKey: summary.key,
      },
    );
    typia.assert<ITodoAppSystemSetting>(detail);
    details.push(detail);
  }

  for (let i = 1; i < details.length; ++i) {
    const prev = details[i - 1];
    const curr = details[i];
    TestValidator.predicate(
      "updated_at is non-increasing in desc order",
      prev.updated_at >= curr.updated_at,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppSystemSetting";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";

/**
 * Validate pagination boundary behavior for admin system settings search.
 *
 * Business goal: Ensure that PATCH /todoApp/adminUser/systemSettings returns
 * consistent pagination metadata and correctly segmented result sets when an
 * admin searches system settings across multiple pages. The test focuses on
 * boundary pages (first, middle, last) and a page beyond the last one.
 *
 * Scenario steps:
 *
 * 1. Register an admin user via POST /auth/adminUser/join to obtain an
 *    authenticated admin session (token automatically attached to connection by
 *    SDK).
 * 2. Create more ITodoAppSystemSetting records than a selected pageSize using POST
 *    /todoApp/adminUser/systemSettings so that PATCH
 *    /todoApp/adminUser/systemSettings will produce at least three pages of
 *    results.
 * 3. Request page 1 (page=1, pageSize=10) with no additional filters and verify:
 *
 *    - Pagination.current === 1
 *    - Pagination.limit === 10
 *    - Pagination.records >= createdCount
 *    - Pagination.pages >= 3
 *    - Data.length === 10
 * 4. Request page 2 with the same pageSize and verify equivalent metadata
 *    constraints plus that its items are distinct from page 1 (no overlapping
 *    ids).
 * 5. Request the last page using pagination.pages from a prior response and
 *    verify:
 *
 *    - Data.length <= pageSize
 *    - No item on the last page overlaps with items from earlier pages (simple
 *         global distinctness check across all collected pages).
 * 6. Request a page beyond the last (pages + 1) and verify that:
 *
 *    - Pagination.current equals the requested page index
 *    - Pagination.records and pagination.pages remain the same as the last in-range
 *         call
 *    - Data.length === 0.
 */
export async function test_api_system_settings_search_pagination_boundaries(
  connection: api.IConnection,
) {
  // 1. Register an admin user to obtain an authorized admin session.
  const joinBody = typia.random<ITodoAppAdminUser.IJoin>();
  const admin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert(admin);

  // 2. Create more system settings than pageSize so that we have at least 3 pages.
  const pageSize = 10;
  const totalToCreate = 25; // ensures at least 3 pages when limit=10

  const createdSettings: ITodoAppSystemSetting[] = await ArrayUtil.asyncRepeat(
    totalToCreate,
    async (index) => {
      const suffix = index.toString().padStart(2, "0");
      const keyBase = `test_pagination_setting_${suffix}`;
      const createBody = {
        key: keyBase,
        value: RandomGenerator.paragraph({ sentences: 3 }),
        type: RandomGenerator.pick([
          "int",
          "boolean",
          "string",
          "double",
        ] as const),
        description: RandomGenerator.paragraph({ sentences: 2 }),
        group: "pagination-boundary-test",
        enabled: true,
      } satisfies ITodoAppSystemSetting.ICreate;

      const created =
        await api.functional.todoApp.adminUser.systemSettings.create(
          connection,
          { body: createBody },
        );
      typia.assert(created);
      return created;
    },
  );

  // Sanity check: we created the expected number.
  TestValidator.equals(
    "created settings count should match totalToCreate",
    createdSettings.length,
    totalToCreate,
  );

  // Helper to build a basic search request body with specific page and pageSize.
  const buildRequest = (
    page: number,
    pageSizeValue: number,
  ): ITodoAppSystemSetting.IRequest => ({
    page,
    pageSize: pageSizeValue,
  });

  // 3. Request page 1.
  const page1Request = buildRequest(1, pageSize);
  const page1: IPageITodoAppSystemSetting.ISummary =
    await api.functional.todoApp.adminUser.systemSettings.index(connection, {
      body: page1Request,
    });
  typia.assert(page1);

  const page1Pagination = page1.pagination;
  typia.assert<IPage.IPagination>(page1Pagination);

  TestValidator.equals(
    "page1 current page should be 1",
    page1Pagination.current,
    1,
  );
  TestValidator.equals(
    "page1 limit should equal requested pageSize",
    page1Pagination.limit,
    pageSize,
  );
  TestValidator.predicate(
    "page1 total records should be at least number created",
    page1Pagination.records >= createdSettings.length,
  );
  TestValidator.predicate(
    "page1 pages should be at least 3",
    page1Pagination.pages >= 3,
  );
  TestValidator.equals(
    "page1 data length should equal pageSize",
    page1.data.length,
    pageSize,
  );

  // Collect seen ids as we go to check distinctness later.
  const seenIds = new Set<string>();
  for (const summary of page1.data) {
    typia.assert<ITodoAppSystemSetting.ISummary>(summary);
    seenIds.add(summary.id);
  }

  // 4. Request page 2.
  const page2Request = buildRequest(2, pageSize);
  const page2: IPageITodoAppSystemSetting.ISummary =
    await api.functional.todoApp.adminUser.systemSettings.index(connection, {
      body: page2Request,
    });
  typia.assert(page2);

  const page2Pagination = page2.pagination;
  typia.assert<IPage.IPagination>(page2Pagination);

  TestValidator.equals(
    "page2 current page should be 2",
    page2Pagination.current,
    2,
  );
  TestValidator.equals(
    "page2 limit should equal requested pageSize",
    page2Pagination.limit,
    pageSize,
  );
  TestValidator.equals(
    "page2 records should match page1 records",
    page2Pagination.records,
    page1Pagination.records,
  );
  TestValidator.equals(
    "page2 pages should match page1 pages",
    page2Pagination.pages,
    page1Pagination.pages,
  );
  TestValidator.equals(
    "page2 data length should equal pageSize",
    page2.data.length,
    pageSize,
  );

  for (const summary of page2.data) {
    typia.assert<ITodoAppSystemSetting.ISummary>(summary);
    TestValidator.predicate(
      "page2 items must not duplicate page1 items",
      seenIds.has(summary.id) === false,
    );
    seenIds.add(summary.id);
  }

  // 5. Request the last page.
  const lastPageIndex = page1Pagination.pages;
  const lastPageRequest = buildRequest(lastPageIndex, pageSize);
  const lastPage: IPageITodoAppSystemSetting.ISummary =
    await api.functional.todoApp.adminUser.systemSettings.index(connection, {
      body: lastPageRequest,
    });
  typia.assert(lastPage);

  const lastPagination = lastPage.pagination;
  typia.assert<IPage.IPagination>(lastPagination);

  TestValidator.equals(
    "last page current should equal pages",
    lastPagination.current,
    lastPageIndex,
  );
  TestValidator.equals(
    "last page limit should equal requested pageSize",
    lastPagination.limit,
    pageSize,
  );
  TestValidator.equals(
    "last page records should match previous records",
    lastPagination.records,
    page1Pagination.records,
  );
  TestValidator.equals(
    "last page pages should match previous pages",
    lastPagination.pages,
    page1Pagination.pages,
  );
  TestValidator.predicate(
    "last page data length should be at most pageSize",
    lastPage.data.length <= pageSize,
  );

  for (const summary of lastPage.data) {
    typia.assert<ITodoAppSystemSetting.ISummary>(summary);
    TestValidator.predicate(
      "last page items must not duplicate earlier items",
      seenIds.has(summary.id) === false,
    );
    seenIds.add(summary.id);
  }

  // 6. Request a page beyond the last.
  const beyondPageIndex = lastPagination.pages + 1;
  const beyondRequest = buildRequest(beyondPageIndex, pageSize);
  const beyond: IPageITodoAppSystemSetting.ISummary =
    await api.functional.todoApp.adminUser.systemSettings.index(connection, {
      body: beyondRequest,
    });
  typia.assert(beyond);

  const beyondPagination = beyond.pagination;
  typia.assert<IPage.IPagination>(beyondPagination);

  TestValidator.equals(
    "beyond-last current should equal requested page index",
    beyondPagination.current,
    beyondPageIndex,
  );
  TestValidator.equals(
    "beyond-last records should remain unchanged",
    beyondPagination.records,
    lastPagination.records,
  );
  TestValidator.equals(
    "beyond-last pages should remain unchanged",
    beyondPagination.pages,
    lastPagination.pages,
  );
  TestValidator.equals("beyond-last data must be empty", beyond.data.length, 0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
