import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";

export async function test_api_system_settings_search_enabled_flag_tristate(
  connection: api.IConnection,
) {
  // 1. Join an admin user and let SDK attach Authorization header
  const joinBody = {
    email: `admin+${RandomGenerator.alphaNumeric(8)}@example.com`,
    password: "P@ssw0rd!",
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todo-app.local/join",
    referrer: "https://admin.todo-app.local/",
  } satisfies ITodoAppAdminUser.IJoin;

  const admin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert(admin);

  // 2. Create two system settings: one enabled, one disabled
  const baseKeyPrefix = `e2e_tristate_${RandomGenerator.alphaNumeric(6)}`;

  const enabledCreateBody = {
    key: `${baseKeyPrefix}_enabled`,
    value: "true",
    type: "boolean",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "tristate-test",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const disabledCreateBody = {
    key: `${baseKeyPrefix}_disabled`,
    value: "false",
    type: "boolean",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "tristate-test",
    enabled: false,
  } satisfies ITodoAppSystemSetting.ICreate;

  const enabledSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: enabledCreateBody,
    });
  typia.assert(enabledSetting);

  const disabledSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: disabledCreateBody,
    });
  typia.assert(disabledSetting);

  // Sanity check: ensure created settings reflect requested enabled flags
  TestValidator.predicate(
    "created enabled/disabled settings must reflect requested flags",
    enabledSetting.enabled === true && disabledSetting.enabled === false,
  );

  // Helper to build a common base search request
  const page = 1;
  const pageSize = 50;

  const buildRequest = (
    enabled: boolean | null | undefined,
  ): ITodoAppSystemSetting.IRequest => {
    const body = {
      page,
      pageSize,
      key: baseKeyPrefix,
      group: "tristate-test",
      enabled,
      createdFrom: undefined,
      createdTo: undefined,
      updatedFrom: undefined,
      updatedTo: undefined,
      sortBy: "key",
      sortDirection: "asc" as const,
    } satisfies ITodoAppSystemSetting.IRequest;
    return body;
  };

  // 3. Search with enabled=true
  const enabledIndexResponse: IPageITodoAppSystemSetting.ISummary =
    await api.functional.todoApp.adminUser.systemSettings.index(connection, {
      body: buildRequest(true),
    });
  typia.assert(enabledIndexResponse);

  TestValidator.predicate(
    "enabled=true search should return only enabled settings",
    enabledIndexResponse.data.every((s) => s.enabled === true),
  );

  const enabledIds = enabledIndexResponse.data.map((s) => s.id);

  TestValidator.predicate(
    "enabled=true result should include the created enabled setting",
    enabledIds.includes(enabledSetting.id),
  );

  TestValidator.predicate(
    "enabled=true result should NOT include the created disabled setting",
    !enabledIds.includes(disabledSetting.id),
  );

  const enabledPagination = enabledIndexResponse.pagination;

  // 4. Search with enabled=false
  const disabledIndexResponse: IPageITodoAppSystemSetting.ISummary =
    await api.functional.todoApp.adminUser.systemSettings.index(connection, {
      body: buildRequest(false),
    });
  typia.assert(disabledIndexResponse);

  TestValidator.predicate(
    "enabled=false search should return only disabled settings",
    disabledIndexResponse.data.every((s) => s.enabled === false),
  );

  const disabledIds = disabledIndexResponse.data.map((s) => s.id);

  TestValidator.predicate(
    "enabled=false result should include the created disabled setting",
    disabledIds.includes(disabledSetting.id),
  );

  TestValidator.predicate(
    "enabled=false result should NOT include the created enabled setting",
    !disabledIds.includes(enabledSetting.id),
  );

  const disabledPagination = disabledIndexResponse.pagination;

  // 5. Search with enabled=null (no filter)
  const tristateIndexResponse: IPageITodoAppSystemSetting.ISummary =
    await api.functional.todoApp.adminUser.systemSettings.index(connection, {
      body: buildRequest(null),
    });
  typia.assert(tristateIndexResponse);

  const tristateIds = tristateIndexResponse.data.map((s) => s.id);

  TestValidator.predicate(
    "unfiltered search should include the enabled setting",
    tristateIds.includes(enabledSetting.id),
  );

  TestValidator.predicate(
    "unfiltered search should include the disabled setting",
    tristateIds.includes(disabledSetting.id),
  );

  // 6. Basic pagination consistency checks
  const tristatePagination = tristateIndexResponse.pagination;

  TestValidator.equals(
    "page index should be consistent across filter modes",
    tristatePagination.current,
    enabledPagination.current,
  );

  TestValidator.equals(
    "page size should be consistent across filter modes",
    tristatePagination.limit,
    enabledPagination.limit,
  );

  TestValidator.predicate(
    "unfiltered total records should be >= enabled-only records",
    tristatePagination.records >= enabledPagination.records,
  );

  TestValidator.predicate(
    "unfiltered total records should be >= disabled-only records",
    tristatePagination.records >= disabledPagination.records,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppSystemSetting";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";

export async function test_api_system_settings_search_security_requires_admin(
  connection: api.IConnection,
) {
  // 1. Unauthenticated call: use a cloned connection with empty headers to ensure
  // no Authorization is sent, then expect the admin-only systemSettings.index
  // endpoint to reject the call. We only verify that an error occurs, not the
  // exact HTTP status code.
  const unauthenticatedConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  await TestValidator.error(
    "unauthenticated users cannot search system settings",
    async () => {
      await api.functional.todoApp.adminUser.systemSettings.index(
        unauthenticatedConnection,
        {
          body: {
            page: 1,
            pageSize: 10,
          } satisfies ITodoAppSystemSetting.IRequest,
        },
      );
    },
  );

  // 2. Join an admin user and perform an authorized search call that should
  // succeed, validating the resulting page structure.
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: null,
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todoapp.local/join",
    referrer: "https://admin.todoapp.local/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  const adminPage: IPageITodoAppSystemSetting.ISummary =
    await api.functional.todoApp.adminUser.systemSettings.index(connection, {
      body: {
        page: 1,
        pageSize: 20,
      } satisfies ITodoAppSystemSetting.IRequest,
    });
  typia.assert(adminPage);

  // Basic pagination sanity checks
  TestValidator.predicate(
    "admin search pagination current page is >= 0",
    adminPage.pagination.current >= 0,
  );
  TestValidator.predicate(
    "admin search pagination limit is >= 0",
    adminPage.pagination.limit >= 0,
  );
  TestValidator.predicate(
    "admin search pagination records is >= 0",
    adminPage.pagination.records >= 0,
  );
  TestValidator.predicate(
    "admin search pagination pages is >= 0",
    adminPage.pagination.pages >= 0,
  );

  // 3. Join a member user and verify that memberUser tokens cannot access the
  // admin-only systemSettings.index endpoint.
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://app.todoapp.local/join/member",
    referrer: "https://app.todoapp.local/landing",
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberAuthorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  await TestValidator.error(
    "memberUser tokens cannot search admin system settings",
    async () => {
      await api.functional.todoApp.adminUser.systemSettings.index(connection, {
        body: {
          page: 1,
          pageSize: 5,
        } satisfies ITodoAppSystemSetting.IRequest,
      });
    },
  );

  // 4. Join a guest user and verify guest tokens also cannot access the admin
  // system settings search.
  const guestJoinBody = {
    external_ref: "guest-correlation-id",
  } satisfies ITodoAppGuestUser.IJoinRequest;

  const guestAuthorized: ITodoAppGuestUser.IAuthorized =
    await api.functional.auth.guestUser.join(connection, {
      body: guestJoinBody,
    });
  typia.assert(guestAuthorized);

  await TestValidator.error(
    "guestUser tokens cannot search admin system settings",
    async () => {
      await api.functional.todoApp.adminUser.systemSettings.index(connection, {
        body: {
          page: 1,
          pageSize: 5,
        } satisfies ITodoAppSystemSetting.IRequest,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppSystemSetting";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";

/**
 * Validate detailed retrieval of a system setting by its unique business key.
 *
 * ## Business context
 *
 * System settings in the todoApp backend represent cross-cutting configuration
 * entries (limits, feature flags, etc.) stored in `todo_app_system_settings`.
 * Administrative APIs allow an `adminUser` actor to create and inspect these
 * settings. The detail endpoint `GET
 * /todoApp/adminUser/systemSettings/{settingKey}` must reliably return the full
 * ITodoAppSystemSetting record for a given business key, including metadata
 * fields (id, created_at, updated_at, deleted_at) and core business fields
 * (key, value, type, description, group, enabled).
 *
 * ## Test purpose
 *
 * This test ensures that:
 *
 * - After an admin joins and creates a new system setting with a known key, the
 *   detail endpoint can load that exact setting by its key.
 * - The returned ITodoAppSystemSetting matches the creation payload for all
 *   overlapping fields.
 * - Server-managed metadata fields are present and have the expected semantics
 *   for a freshly created, non-deleted record.
 * - The listing endpoint (PATCH /todoApp/adminUser/systemSettings) returns a
 *   summary that is consistent with the detail view for the same key.
 *
 * ## Scenario steps
 *
 * 1. Register an admin user through `api.functional.auth.adminUser.join` using a
 *    random-but-valid payload for ITodoAppAdminUser.IJoin.
 *
 *    - The join call will also set the Authorization header on the connection for
 *         subsequent admin-only operations.
 * 2. Create a new system setting via
 *    `api.functional.todoApp.adminUser.systemSettings.create`.
 *
 *    - Construct a unique key such as "test.setting.detail." plus a random suffix to
 *         avoid collisions.
 *    - Provide explicit values for value, type, description, group, and enabled.
 *    - Use `satisfies ITodoAppSystemSetting.ICreate` when constructing the request
 *         body.
 *    - Assert the response with `typia.assert`.
 * 3. Retrieve the setting detail by key via
 *    `api.functional.todoApp.adminUser.systemSettings.at`.
 *
 *    - Pass the same key used at creation as `settingKey`.
 *    - Assert the response type using `typia.assert<ITodoAppSystemSetting>`.
 * 4. Validate business expectations:
 *
 *    - Using `TestValidator.equals` (with descriptive titles), verify that the
 *         detail response has:
 *
 *         - Key equal to the original key
 *         - Value, type, description, group, and enabled equal to the creation payload
 *    - Use `TestValidator.predicate` to assert that:
 *
 *         - Id is a non-empty string (typia.assert already checks uuid, so we only need
 *                   to assert business logic such as non-emptiness if desired)
 *         - Created_at and updated_at are non-empty strings (typia.assert ensures
 *                   date-time format)
 *         - Deleted_at is null or undefined for a freshly created setting.
 * 5. Optionally cross-check with the index endpoint:
 *
 *    - Call `api.functional.todoApp.adminUser.systemSettings.index` with a body that
 *         filters by the same key, and reasonable pagination (e.g. page=1,
 *         pageSize=10).
 *    - Assert the response type as `IPageITodoAppSystemSetting.ISummary`.
 *    - Ensure at least one record is returned whose key matches the test key.
 *    - Find that summary record and verify via `TestValidator.equals` that
 *         summary.key, summary.value, summary.type, summary.description,
 *         summary.group, and summary.enabled match the detail object.
 *
 * ## Error conditions and edge cases
 *
 * - This test does not attempt to validate 404 behavior or missing keys; it
 *   focuses on the happy path where the setting exists.
 * - It also does not attempt to test type-level or schema-level validation
 *   errors; those are covered elsewhere. All request bodies must respect their
 *   DTO types.
 *
 * ## Implementation notes
 *
 * - Use only the imports available in the test template: api, typia, tags,
 *   RandomGenerator, TestValidator, ArrayUtil, and the DTO types.
 * - Avoid manipulating `connection.headers` directly; rely on the join endpoint
 *   to manage Authorization.
 * - Use explicit `await` for all API calls.
 * - Use `satisfies` when building request bodies for IJoin, ICreate, and IRequest
 *   DTOs.
 */
export async function test_api_system_settings_detail_retrieval_by_key(
  connection: api.IConnection,
) {
  // 1. Register an admin user so that subsequent systemSettings calls
  //    are authenticated as adminUser.
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todo-app.local/join",
    referrer: "https://admin.todo-app.local/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const admin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert(admin);

  // 2. Create a new system setting with a unique key and known payload.
  const uniqueSuffix: string = RandomGenerator.alphaNumeric(12);
  const settingKey: string = `test.setting.detail.${uniqueSuffix}`;

  const createBody = {
    key: settingKey,
    value: "42",
    type: "int",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "e2e-detail-test",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const created: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: createBody,
    });
  typia.assert(created);

  // Basic equality checks between creation payload and created record.
  TestValidator.equals(
    "detail create: key should match input key",
    created.key,
    createBody.key,
  );
  TestValidator.equals(
    "detail create: value should match input value",
    created.value,
    createBody.value,
  );
  TestValidator.equals(
    "detail create: type should match input type",
    created.type,
    createBody.type,
  );
  TestValidator.equals(
    "detail create: description should match input description",
    created.description ?? null,
    createBody.description ?? null,
  );
  TestValidator.equals(
    "detail create: group should match input group",
    created.group ?? null,
    createBody.group ?? null,
  );
  TestValidator.equals(
    "detail create: enabled should match input enabled",
    created.enabled,
    createBody.enabled,
  );

  // 3. Retrieve the system setting by its key using the detail endpoint.
  const detailed: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.at(connection, {
      settingKey,
    });
  typia.assert(detailed);

  // 4. Validate that the detailed record matches creation payload and
  //    basic metadata expectations.
  TestValidator.equals(
    "detail at: key should equal path key",
    detailed.key,
    settingKey,
  );
  TestValidator.equals(
    "detail at: value should equal created value",
    detailed.value,
    createBody.value,
  );
  TestValidator.equals(
    "detail at: type should equal created type",
    detailed.type,
    createBody.type,
  );
  TestValidator.equals(
    "detail at: description should equal created description",
    detailed.description ?? null,
    createBody.description ?? null,
  );
  TestValidator.equals(
    "detail at: group should equal created group",
    detailed.group ?? null,
    createBody.group ?? null,
  );
  TestValidator.equals(
    "detail at: enabled should equal created enabled",
    detailed.enabled,
    createBody.enabled,
  );

  TestValidator.predicate(
    "detail at: id must be non-empty string",
    typeof detailed.id === "string" && detailed.id.length > 0,
  );
  TestValidator.predicate(
    "detail at: created_at must be non-empty string",
    typeof detailed.created_at === "string" && detailed.created_at.length > 0,
  );
  TestValidator.predicate(
    "detail at: updated_at must be non-empty string",
    typeof detailed.updated_at === "string" && detailed.updated_at.length > 0,
  );
  TestValidator.predicate(
    "detail at: deleted_at must be null or undefined for new setting",
    detailed.deleted_at === null || detailed.deleted_at === undefined,
  );

  // 5. Cross-check with index listing filtered by key to ensure that the
  //    summary view is consistent with the detail view.
  const indexBody = {
    page: 1,
    pageSize: 10,
    key: settingKey,
  } satisfies ITodoAppSystemSetting.IRequest;

  const page: IPageITodoAppSystemSetting.ISummary =
    await api.functional.todoApp.adminUser.systemSettings.index(connection, {
      body: indexBody,
    });
  typia.assert(page);

  TestValidator.predicate(
    "index: at least one summary should be returned for the created key",
    page.pagination.records >= 1 && page.data.length >= 1,
  );

  const summary = page.data.find((row) => row.key === settingKey);
  TestValidator.predicate(
    "index: summary entry for created key must exist",
    summary !== undefined,
  );

  if (summary !== undefined) {
    TestValidator.equals(
      "index vs detail: key should match",
      summary.key,
      detailed.key,
    );
    TestValidator.equals(
      "index vs detail: value should match",
      summary.value,
      detailed.value,
    );
    TestValidator.equals(
      "index vs detail: type should match",
      summary.type,
      detailed.type,
    );
    TestValidator.equals(
      "index vs detail: description should match",
      summary.description ?? null,
      detailed.description ?? null,
    );
    TestValidator.equals(
      "index vs detail: group should match",
      summary.group ?? null,
      detailed.group ?? null,
    );
    TestValidator.equals(
      "index vs detail: enabled should match",
      summary.enabled,
      detailed.enabled,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";

/**
 * Ensure admin cannot load details for non-existent or logically deleted system
 * settings.
 *
 * Business context: Admin users manage global configuration entries via
 * todo_app_system_settings. The detail endpoint GET
 * /todoApp/adminUser/systemSettings/{settingKey} must only expose active
 * (non-deleted) settings. When a key does not exist at all, or has been
 * soft-deleted via DELETE, the API should behave as not-found instead of
 * returning the underlying record.
 *
 * Scenario steps:
 *
 * 1. Register an adminUser via POST /auth/adminUser/join; this returns
 *    ITodoAppAdminUser.IAuthorized and sets Authorization on the connection.
 * 2. Probe detail with a random, surely-unknown key using GET
 *    /todoApp/adminUser/systemSettings/{settingKey}. Expect a not-found style
 *    error, asserted via TestValidator.error (no status-code checking).
 * 3. Create a real setting with POST /todoApp/adminUser/systemSettings using
 *    ITodoAppSystemSetting.ICreate, with a distinct random key and realistic
 *    value/type/description/group/enabled fields. Assert the created
 *    ITodoAppSystemSetting with typia.assert.
 * 4. Logically delete that setting using DELETE
 *    /todoApp/adminUser/systemSettings/{settingKey} for the created key. This
 *    should succeed without returning a body.
 * 5. Call the detail endpoint again for the deleted key and assert that it now
 *    behaves as not-found via TestValidator.error, confirming that soft-deleted
 *    configuration entries are hidden from the detail endpoint.
 */
export async function test_api_system_settings_detail_not_found_for_unknown_key(
  connection: api.IConnection,
) {
  // 1. Register an admin user and establish authenticated context
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todo-app.test/register",
    referrer: "https://admin.todo-app.test/",
  } satisfies ITodoAppAdminUser.IJoin;

  const admin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert(admin);

  // 2. Request detail for a clearly non-existent setting key
  const unknownKey: string = `unknown_setting_${RandomGenerator.alphaNumeric(16)}`;

  await TestValidator.error(
    "detail request for unknown system setting key should fail",
    async () => {
      await api.functional.todoApp.adminUser.systemSettings.at(connection, {
        settingKey: unknownKey,
      });
    },
  );

  // 3. Create a real system setting with a known key
  const existingKey: string = `existing_setting_${RandomGenerator.alphaNumeric(16)}`;

  const createBody = {
    key: existingKey,
    value: "1000",
    type: "int",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const created: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: createBody,
    });
  typia.assert(created);

  TestValidator.equals(
    "created system setting key should match request body",
    created.key,
    existingKey,
  );

  // 4. Logically delete the created setting by its key
  await api.functional.todoApp.adminUser.systemSettings.erase(connection, {
    settingKey: existingKey,
  });

  // 5. Verify that detail endpoint now treats the deleted key as not found
  await TestValidator.error(
    "detail request for logically deleted system setting should fail",
    async () => {
      await api.functional.todoApp.adminUser.systemSettings.at(connection, {
        settingKey: existingKey,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppSystemSetting";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";

/**
 * Verify that the system setting detail endpoint reflects updates performed by
 * the update endpoint for an authenticated admin user.
 *
 * Business context:
 *
 * - System settings in todoApp are global configuration entries stored in
 *   `todo_app_system_settings`, with a stable identity (id, key, created_at)
 *   and mutable configuration fields (value, type, description, group, enabled,
 *   updated_at, deleted_at).
 * - Admin users manage these settings via the adminUser actor APIs. Joining as an
 *   admin issues JWT tokens that the SDK automatically wires into
 *   `connection.headers.Authorization`, so subsequent calls on the same
 *   connection are authenticated.
 * - The detail endpoint `GET /todoApp/adminUser/systemSettings/{settingKey}`
 *   returns the full `ITodoAppSystemSetting` for a given business key, while
 *   the update endpoint `PUT /todoApp/adminUser/systemSettings/{settingKey}`
 *   applies partial updates using `ITodoAppSystemSetting.IUpdate` and returns
 *   the updated entity. The index endpoint `PATCH
 *   /todoApp/adminUser/systemSettings` returns `ISummary` projections for
 *   listing.
 *
 * Test flow:
 *
 * 1. Join an admin via `POST /auth/adminUser/join` to establish an authenticated
 *    admin session. The returned token is wired into `connection` by the SDK.
 * 2. Create a new system setting via `POST /todoApp/adminUser/systemSettings` with
 *    a unique key and initial values for `value`, `type`, `description`,
 *    `group`, and `enabled`.
 * 3. Immediately fetch the created setting via `GET
 *    /todoApp/adminUser/systemSettings/{settingKey}` and record its `id`,
 *    `key`, `created_at`, `updated_at`, and mutable fields.
 * 4. Build an `ITodoAppSystemSetting.IUpdate` payload that changes `value`,
 *    `description`, `group`, `enabled`, and optionally `type`, and send it via
 *    `PUT /todoApp/adminUser/systemSettings/{settingKey}`.
 * 5. Fetch the setting again via the detail GET and verify that:
 *
 *    - `id` and `key` are unchanged.
 *    - `created_at` is unchanged.
 *    - `updated_at` has increased compared to the previous value.
 *    - The mutable fields (`value`, `type`, `description`, `group`, `enabled`) match
 *         the update payload.
 * 6. Optionally call `PATCH /todoApp/adminUser/systemSettings` with a filter on
 *    `key` to retrieve a paginated summary list, locate the summary entry for
 *    this key, and assert that its `value`, `type`, `description`, `group`, and
 *    `enabled` fields match the updated entity.
 */
export async function test_api_system_settings_detail_reflects_updates(
  connection: api.IConnection,
) {
  // 1. Join an admin user to obtain an authorized connection
  const adminJoinBody = typia.random<ITodoAppAdminUser.IJoin>();
  const admin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(admin);

  // 2. Create a new system setting with a unique key and initial values
  const settingKey = `e2e_test_setting_${RandomGenerator.alphaNumeric(8)}`;
  const createBody = {
    key: settingKey,
    value: "10",
    type: "int",
    description: "Initial description for E2E test setting",
    group: "e2e-tests",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const created: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: createBody,
    });
  typia.assert(created);

  TestValidator.equals(
    "created setting key should match requested key",
    created.key,
    settingKey,
  );

  // 3. Fetch the created setting via detail GET to get baseline timestamps
  const initialDetail: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.at(connection, {
      settingKey,
    });
  typia.assert(initialDetail);

  TestValidator.equals(
    "detail id matches created id",
    initialDetail.id,
    created.id,
  );
  TestValidator.equals(
    "detail key matches created key",
    initialDetail.key,
    created.key,
  );
  TestValidator.equals(
    "detail created_at matches created created_at",
    initialDetail.created_at,
    created.created_at,
  );

  const previousUpdatedAt = initialDetail.updated_at;

  // 4. Update the setting with changed value/description/group/enabled/type
  const updateBody = {
    value: "20",
    type: "string",
    description: "Updated description for E2E test setting",
    group: "e2e-tests-updated",
    enabled: false,
  } satisfies ITodoAppSystemSetting.IUpdate;

  const updated: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.update(connection, {
      settingKey,
      body: updateBody,
    });
  typia.assert(updated);

  // Identity invariants
  TestValidator.equals(
    "updated id remains same as created",
    updated.id,
    created.id,
  );
  TestValidator.equals(
    "updated key remains same as path settingKey",
    updated.key,
    settingKey,
  );
  TestValidator.equals(
    "updated created_at remains unchanged",
    updated.created_at,
    created.created_at,
  );

  // Mutable fields should reflect update payload
  TestValidator.equals(
    "updated value matches update payload",
    updated.value,
    updateBody.value,
  );
  TestValidator.equals(
    "updated type matches update payload",
    updated.type,
    updateBody.type,
  );
  TestValidator.equals(
    "updated description matches update payload",
    updated.description,
    updateBody.description,
  );
  TestValidator.equals(
    "updated group matches update payload",
    updated.group,
    updateBody.group,
  );
  TestValidator.equals(
    "updated enabled matches update payload",
    updated.enabled,
    updateBody.enabled,
  );

  await TestValidator.predicate(
    "updated_at should increase after update",
    () => {
      const before = new Date(previousUpdatedAt).getTime();
      const after = new Date(updated.updated_at).getTime();
      return after > before;
    },
  );

  // 5. Fetch detail again and validate it matches the updated entity
  const detailAfterUpdate: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.at(connection, {
      settingKey,
    });
  typia.assert(detailAfterUpdate);

  TestValidator.equals(
    "detail-after-update id matches updated id",
    detailAfterUpdate.id,
    updated.id,
  );
  TestValidator.equals(
    "detail-after-update key matches settingKey",
    detailAfterUpdate.key,
    settingKey,
  );
  TestValidator.equals(
    "detail-after-update created_at matches updated created_at",
    detailAfterUpdate.created_at,
    updated.created_at,
  );
  TestValidator.equals(
    "detail-after-update value matches updated value",
    detailAfterUpdate.value,
    updated.value,
  );
  TestValidator.equals(
    "detail-after-update type matches updated type",
    detailAfterUpdate.type,
    updated.type,
  );
  TestValidator.equals(
    "detail-after-update description matches updated description",
    detailAfterUpdate.description,
    updated.description,
  );
  TestValidator.equals(
    "detail-after-update group matches updated group",
    detailAfterUpdate.group,
    updated.group,
  );
  TestValidator.equals(
    "detail-after-update enabled matches updated enabled",
    detailAfterUpdate.enabled,
    updated.enabled,
  );

  await TestValidator.predicate(
    "detail-after-update updated_at matches update response updated_at",
    detailAfterUpdate.updated_at === updated.updated_at,
  );

  // 6. Optionally verify summary view via index with key filter
  const indexBody = {
    page: 1,
    pageSize: 10,
    key: settingKey,
  } satisfies ITodoAppSystemSetting.IRequest;

  const page: IPageITodoAppSystemSetting.ISummary =
    await api.functional.todoApp.adminUser.systemSettings.index(connection, {
      body: indexBody,
    });
  typia.assert(page);

  const summaries = page.data;
  await TestValidator.predicate(
    "index result should contain at least one summary for the setting key",
    summaries.some((s) => s.key === settingKey),
  );

  const summary = summaries.find((s) => s.key === settingKey);
  if (summary !== undefined) {
    typia.assert(summary);

    TestValidator.equals(
      "summary value matches updated value",
      summary.value,
      updated.value,
    );
    TestValidator.equals(
      "summary type matches updated type",
      summary.type,
      updated.type,
    );
    TestValidator.equals(
      "summary description matches updated description",
      summary.description,
      updated.description,
    );
    TestValidator.equals(
      "summary group matches updated group",
      summary.group,
      updated.group,
    );
    TestValidator.equals(
      "summary enabled matches updated enabled",
      summary.enabled,
      updated.enabled,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";

/**
 * Verify that system settings detail retrieval is restricted to admin users.
 *
 * Business intent:
 *
 * - System settings in todoApp contain sensitive global configuration such as
 *   feature flags or limits.
 * - Only actors authenticated as adminUser should be able to read detailed
 *   configuration for a specific key.
 * - Unauthenticated callers must not be able to read any system setting detail.
 * - Member/guest users should not gain access to admin-only configuration
 *   surfaces.
 *
 * Test flow:
 *
 * 1. Admin registration and authentication
 *
 *    - Call POST /auth/adminUser/join with a valid ITodoAppAdminUser.IJoin body.
 *    - Rely on the SDK to set connection.headers.Authorization to the admin access
 *         token.
 *    - Assert that an ITodoAppAdminUser.IAuthorized object is returned
 *         (typia.assert).
 * 2. Create a concrete system setting under the admin context
 *
 *    - Call POST /todoApp/adminUser/systemSettings with a valid
 *         ITodoAppSystemSetting.ICreate body.
 *    - Use a deterministic key (e.g., "e2e_admin_only_setting_<random_suffix>") so
 *         it can be fetched later.
 *    - Assert that an ITodoAppSystemSetting is returned and that its key matches the
 *         requested key, using typia.assert + TestValidator.equals.
 * 3. Attempt unauthenticated access to the same setting
 *
 *    - Construct a secondary IConnection based on the original but with headers: {}
 *         to simulate a client with no Authorization header.
 *    - Call GET /todoApp/adminUser/systemSettings/{settingKey} via
 *         api.functional.todoApp.adminUser.systemSettings.at using the
 *         unauthenticated connection.
 *    - Wrap this call in TestValidator.error with a descriptive title.
 *    - Do not assert specific HTTP status codes or error bodies; only assert that an
 *         error occurs.
 * 4. Retrieve system setting detail as the authenticated admin
 *
 *    - Using the original, admin-authenticated connection, call systemSettings.at
 *         with the same key.
 *    - Assert that an ITodoAppSystemSetting is returned and matches the created
 *         record (id and key equality at minimum).
 * 5. (Optional) Join memberUser and verify they cannot access admin system
 *    settings
 *
 *    - Call POST /auth/memberUser/join with a valid ITodoAppMemberUserJoin.ICreate
 *         body; SDK will set Authorization to a member token.
 *    - Create a fresh unauthenticated connection (headers: {}) or reuse the
 *         member-authenticated connection depending on how the backend enforces
 *         actor-based guards.
 *    - For safety and to avoid touching or reasoning about headers beyond what SDK
 *         manages, simulate non-admin calls using a clone with empty headers.
 *    - Call systemSettings.at for the same settingKey using that non-admin
 *         connection and wrap in TestValidator.error.
 * 6. (Optional) Join guestUser and verify they cannot access admin system settings
 *
 *    - Call POST /auth/guestUser/join with a valid ITodoAppGuestUser.IJoinRequest
 *         body; SDK sets guest Authorization.
 *    - As with memberUser, create a cloned connection with empty headers to avoid
 *         directly manipulating Authorization.
 *    - Call systemSettings.at for the same settingKey and assert error via
 *         TestValidator.error.
 * 7. Business assertions
 *
 *    - All successful responses must pass typia.assert for structural/type
 *         correctness.
 *    - Use TestValidator.equals to ensure that the `key` in the created and fetched
 *         ITodoAppSystemSetting match.
 *    - Use TestValidator.predicate with clear titles if additional boolean business
 *         checks are helpful (e.g., `enabled` flag preserved).
 *
 * Constraints and caveats:
 *
 * - Never inspect or mutate connection.headers directly except for creating a
 *   brand-new connection object with headers: {} to simulate unauthenticated
 *   requests.
 * - Never check HTTP status codes or error messages; only validate that an error
 *   is thrown when unauthorized/non-admin access is attempted.
 * - Do not create any invalid DTO bodies or perform negative type tests; all
 *   payloads must satisfy their DTO types.
 */
export async function test_api_system_settings_detail_security_requires_admin(
  connection: api.IConnection,
) {
  // 1. Admin registration and authentication
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todoapp.local/join",
    referrer: "https://admin.todoapp.local/",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Create a concrete system setting under the admin context
  const settingKey = `e2e_admin_only_setting_${RandomGenerator.alphaNumeric(8)}`;
  const createSettingBody = {
    key: settingKey,
    value: "42",
    type: "int",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "e2e-security",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const createdSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: createSettingBody,
    });
  typia.assert(createdSetting);
  TestValidator.equals(
    "created system setting key should match request",
    createdSetting.key,
    settingKey,
  );

  // 3. Attempt unauthenticated access to the same setting
  const unauthenticatedConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  await TestValidator.error(
    "unauthenticated caller cannot access system setting detail",
    async () => {
      await api.functional.todoApp.adminUser.systemSettings.at(
        unauthenticatedConnection,
        {
          settingKey,
        },
      );
    },
  );

  // 4. Retrieve system setting detail as the authenticated admin
  const fetchedAsAdmin: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.at(connection, {
      settingKey,
    });
  typia.assert(fetchedAsAdmin);

  TestValidator.equals(
    "admin should see same system setting id",
    fetchedAsAdmin.id,
    createdSetting.id,
  );
  TestValidator.equals(
    "admin should see same system setting key",
    fetchedAsAdmin.key,
    createdSetting.key,
  );

  // 5. Optional: join memberUser and verify they cannot access admin system settings
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://todoapp.local/signup",
    referrer: "https://todoapp.local/landing",
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberAuthorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  const memberUnauthConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  await TestValidator.error(
    "member-equivalent unauthenticated caller cannot access system setting detail",
    async () => {
      await api.functional.todoApp.adminUser.systemSettings.at(
        memberUnauthConnection,
        { settingKey },
      );
    },
  );

  // 6. Optional: join guestUser and verify they cannot access admin system settings
  const guestJoinBody = {
    external_ref: RandomGenerator.alphaNumeric(12),
  } satisfies ITodoAppGuestUser.IJoinRequest;

  const guestAuthorized: ITodoAppGuestUser.IAuthorized =
    await api.functional.auth.guestUser.join(connection, {
      body: guestJoinBody,
    });
  typia.assert(guestAuthorized);

  const guestUnauthConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  await TestValidator.error(
    "guest-equivalent unauthenticated caller cannot access system setting detail",
    async () => {
      await api.functional.todoApp.adminUser.systemSettings.at(
        guestUnauthConnection,
        { settingKey },
      );
    },
  );

  // 7. Additional business sanity checks
  TestValidator.predicate(
    "created system setting should be enabled",
    createdSetting.enabled === true,
  );
  TestValidator.equals(
    "fetched system setting enabled flag matches created setting",
    fetchedAsAdmin.enabled,
    createdSetting.enabled,
  );
