import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppSystemSetting";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";

/**
 * Validate that an authenticated admin user can soft delete a global system
 * setting by its business key, and that the setting behaves as logically
 * deleted afterwards.
 *
 * Business flow under test:
 *
 * 1. Admin registration and authentication using /auth/adminUser/join.
 * 2. System setting creation with a unique business key via POST
 *    /todoApp/adminUser/systemSettings.
 * 3. Verification that the setting is retrievable via GET
 *    /todoApp/adminUser/systemSettings/{settingKey}.
 * 4. Logical deletion using DELETE /todoApp/adminUser/systemSettings/{settingKey}
 *    with the same key.
 * 5. Post-deletion verification that:
 *
 *    - GET by key now results in an HTTP error (not-found semantics).
 *    - Listing active settings via PATCH /todoApp/adminUser/systemSettings no longer
 *         includes the deleted key.
 * 6. Error path checks:
 *
 *    - Deleting a non-existent key yields a not-found style HTTP error.
 *    - Using an unauthenticated connection to delete a setting fails with an HTTP
 *         error.
 */
export async function test_api_system_setting_soft_delete_by_admin(
  connection: api.IConnection,
) {
  // 1. Register a new admin user to obtain an authenticated admin context.
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todo-app.test/settings",
    referrer: "https://admin.todo-app.test/",
  } satisfies ITodoAppAdminUser.IJoin;

  const admin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(admin);
  typia.assert<IAuthorizationToken>(admin.token);

  // 2. Create a concrete system setting with a unique business key.
  const settingKey = `max_active_todos_${RandomGenerator.alphaNumeric(8)}`;

  const createBody = {
    key: settingKey,
    value: "100",
    type: "int",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const created: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: createBody,
    });
  typia.assert<ITodoAppSystemSetting>(created);

  TestValidator.equals(
    "created setting key must match request key",
    created.key,
    settingKey,
  );
  TestValidator.equals(
    "created setting should be enabled",
    created.enabled,
    true,
  );

  // 3. Verify the setting is retrievable by its business key via GET /systemSettings/{settingKey}.
  const fetched: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.at(connection, {
      settingKey,
    });
  typia.assert<ITodoAppSystemSetting>(fetched);

  TestValidator.equals(
    "fetched setting id must match created id",
    fetched.id,
    created.id,
  );
  TestValidator.equals(
    "fetched setting key must match created key",
    fetched.key,
    created.key,
  );

  // 4. Optionally, confirm the setting appears in a listing of enabled settings.
  const listBefore: IPageITodoAppSystemSetting.ISummary =
    await api.functional.todoApp.adminUser.systemSettings.index(connection, {
      body: {
        page: 1,
        pageSize: 50,
        key: settingKey,
        group: undefined,
        enabled: true,
        createdFrom: undefined,
        createdTo: undefined,
        updatedFrom: undefined,
        updatedTo: undefined,
        sortBy: "key",
        sortDirection: "asc",
      } satisfies ITodoAppSystemSetting.IRequest,
    });
  typia.assert<IPageITodoAppSystemSetting.ISummary>(listBefore);

  TestValidator.predicate(
    "listing before delete should contain the created setting key",
    () =>
      listBefore.data.some((row) => {
        return row.key === settingKey;
      }),
  );

  // 5. Perform the soft delete using DELETE /systemSettings/{settingKey}.
  await api.functional.todoApp.adminUser.systemSettings.erase(connection, {
    settingKey,
  });

  // 6. After deletion, GET by the same key should result in a not-found style HttpError.
  await TestValidator.httpError(
    "GET after delete should respond with client error (not found)",
    [400, 404, 410],
    async () => {
      await api.functional.todoApp.adminUser.systemSettings.at(connection, {
        settingKey,
      });
    },
  );

  // 7. Listing enabled settings should no longer include the deleted key.
  const listAfter: IPageITodoAppSystemSetting.ISummary =
    await api.functional.todoApp.adminUser.systemSettings.index(connection, {
      body: {
        page: 1,
        pageSize: 50,
        key: settingKey,
        group: undefined,
        enabled: true,
        createdFrom: undefined,
        createdTo: undefined,
        updatedFrom: undefined,
        updatedTo: undefined,
        sortBy: "key",
        sortDirection: "asc",
      } satisfies ITodoAppSystemSetting.IRequest,
    });
  typia.assert<IPageITodoAppSystemSetting.ISummary>(listAfter);

  TestValidator.predicate(
    "listing after delete should not contain the deleted setting key",
    () => listAfter.data.every((row) => row.key !== settingKey),
  );

  // 8. Deleting a non-existent key should yield a not-found style HTTP error.
  const nonExistentKey = `nonexistent_${RandomGenerator.alphaNumeric(8)}`;
  await TestValidator.httpError(
    "deleting non-existent system setting should fail with client error",
    [400, 404, 410],
    async () => {
      await api.functional.todoApp.adminUser.systemSettings.erase(connection, {
        settingKey: nonExistentKey,
      });
    },
  );

  // 9. Attempt soft delete without authentication should fail.
  const unauthenticatedConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  await TestValidator.httpError(
    "unauthenticated adminUser erase should be rejected",
    [401, 403],
    async () => {
      await api.functional.todoApp.adminUser.systemSettings.erase(
        unauthenticatedConnection,
        {
          settingKey,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppSystemSetting";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";

/**
 * Validate deletion behavior for non-existent and already-deleted system
 * settings.
 *
 * Business objectives:
 *
 * - Deleting a system setting by a key that has no active (non-deleted) record
 *   must behave as a not-found style error.
 * - Deleting an existing system setting succeeds once; a second delete on the
 *   same key must behave as not-found and must not resurrect or corrupt data.
 * - Other unrelated settings must remain intact after deletion attempts.
 *
 * Scenario steps:
 *
 * 1. Register and authenticate an admin user via POST /auth/adminUser/join.
 * 2. Create two baseline system settings via POST
 *    /todoApp/adminUser/systemSettings:
 *
 *    - One that will be deleted ("existing_setting").
 *    - One that must remain intact ("other_setting").
 * 3. Optionally list settings via PATCH /todoApp/adminUser/systemSettings to
 *    confirm both keys exist and are enabled.
 * 4. Attempt to DELETE a clearly non-existent key and assert not-found behavior.
 * 5. DELETE the existing_setting key once and expect success.
 * 6. DELETE the same existing_setting key again and assert not-found behavior.
 * 7. Use GET /todoApp/adminUser/systemSettings/{settingKey} to verify that
 *    non-existent and deleted keys behave as not-found, while other_setting is
 *    still retrievable and intact.
 */
export async function test_api_system_setting_delete_nonexistent_key(
  connection: api.IConnection,
) {
  // 1. Register and authenticate an admin user (join only).
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Admin1234!" as string & tags.Format<"password">,
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todo-app.test/join" as string & tags.Format<"uri">,
    referrer: "https://admin.todo-app.test/landing" as string &
      tags.Format<"uri">,
  } satisfies ITodoAppAdminUser.IJoin;

  const admin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert(admin);

  // 2. Create baseline system settings: one to delete, one to remain.
  const existingKey = `existing_setting_${RandomGenerator.alphaNumeric(8)}`;
  const otherKey = `other_setting_${RandomGenerator.alphaNumeric(8)}`;

  const existingCreateBody = {
    key: existingKey,
    value: "100",
    type: "int",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const otherCreateBody = {
    key: otherKey,
    value: "true",
    type: "boolean",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "features",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const existingSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: existingCreateBody,
    });
  typia.assert(existingSetting);

  const otherSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: otherCreateBody,
    });
  typia.assert(otherSetting);

  TestValidator.equals(
    "created existing setting key matches",
    existingSetting.key,
    existingKey,
  );
  TestValidator.equals(
    "created other setting key matches",
    otherSetting.key,
    otherKey,
  );

  // 3. Confirm baseline via listing.
  const listRequestBody = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    pageSize: 50 as number & tags.Type<"int32"> & tags.Minimum<1>,
    key: undefined,
    group: undefined,
    enabled: null,
    createdFrom: undefined,
    createdTo: undefined,
    updatedFrom: undefined,
    updatedTo: undefined,
    sortBy: undefined,
    sortDirection: undefined,
  } satisfies ITodoAppSystemSetting.IRequest;

  const pageResult: IPageITodoAppSystemSetting.ISummary =
    await api.functional.todoApp.adminUser.systemSettings.index(connection, {
      body: listRequestBody,
    });
  typia.assert(pageResult);

  const existingSummary = pageResult.data.find(
    (row) => row.key === existingKey,
  );
  const otherSummary = pageResult.data.find((row) => row.key === otherKey);

  TestValidator.predicate(
    "existing setting should appear in listing",
    existingSummary !== undefined,
  );
  TestValidator.predicate(
    "other setting should appear in listing",
    otherSummary !== undefined,
  );

  if (existingSummary !== undefined) {
    TestValidator.equals(
      "existing setting summary enabled",
      existingSummary.enabled,
      true,
    );
  }
  if (otherSummary !== undefined) {
    TestValidator.equals(
      "other setting summary enabled",
      otherSummary.enabled,
      true,
    );
  }

  // 4. Delete a clearly non-existent key and expect not-found behavior.
  const nonexistentKey = `nonexistent_setting_${RandomGenerator.alphaNumeric(8)}`;

  TestValidator.predicate(
    "nonexistent key must differ from existing and other keys",
    nonexistentKey !== existingKey && nonexistentKey !== otherKey,
  );

  await TestValidator.error(
    "erase should fail for non-existent key",
    async () => {
      await api.functional.todoApp.adminUser.systemSettings.erase(connection, {
        settingKey: nonexistentKey,
      });
    },
  );

  // 5. Delete existing setting once and expect success.
  await api.functional.todoApp.adminUser.systemSettings.erase(connection, {
    settingKey: existingKey,
  });

  // 6. Delete the same setting again and expect not-found behavior.
  await TestValidator.error(
    "second erase of same key should behave as not-found",
    async () => {
      await api.functional.todoApp.adminUser.systemSettings.erase(connection, {
        settingKey: existingKey,
      });
    },
  );

  // 7. Validate detail retrieval behavior for non-existent and deleted keys.
  await TestValidator.error(
    "GET on never-existing key should be not-found",
    async () => {
      await api.functional.todoApp.adminUser.systemSettings.at(connection, {
        settingKey: nonexistentKey,
      });
    },
  );

  await TestValidator.error(
    "GET on deleted existing key should be not-found",
    async () => {
      await api.functional.todoApp.adminUser.systemSettings.at(connection, {
        settingKey: existingKey,
      });
    },
  );

  // 8. Validate that unrelated setting remains intact.
  const otherDetail: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.at(connection, {
      settingKey: otherKey,
    });
  typia.assert(otherDetail);

  TestValidator.equals(
    "other setting detail key should match",
    otherDetail.key,
    otherKey,
  );
  TestValidator.equals(
    "other setting detail value should match",
    otherDetail.value,
    otherCreateBody.value,
  );
  TestValidator.equals(
    "other setting detail type should match",
    otherDetail.type,
    otherCreateBody.type,
  );
  TestValidator.equals(
    "other setting detail enabled should remain true",
    otherDetail.enabled,
    true,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppSystemSetting";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

export async function test_api_system_setting_delete_requires_admin_auth(
  connection: api.IConnection,
) {
  // 1. Prepare admin and an initial system setting
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = "Admin1234!";

  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword as string & tags.Format<"password">,
    display_name: RandomGenerator.name(2),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todo-app.test/join",
    referrer: "https://admin.todo-app.test/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  const settingKeyBase = "e2e_delete_auth_setting";
  const settingKey = `${settingKeyBase}_${RandomGenerator.alphaNumeric(8)}`;

  const createSettingBody = {
    key: settingKey,
    value: "42",
    type: "int",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const createdSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: createSettingBody,
    });
  typia.assert(createdSetting);

  TestValidator.equals(
    "created setting key should match input key",
    createdSetting.key,
    settingKey,
  );
  TestValidator.predicate(
    "created setting should be enabled",
    createdSetting.enabled === true,
  );

  const loadedSetting1: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.at(connection, {
      settingKey,
    });
  typia.assert(loadedSetting1);
  TestValidator.equals(
    "loaded setting (initial) key should match",
    loadedSetting1.key,
    settingKey,
  );

  const initialIndexRequest = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    pageSize: 10 as number & tags.Type<"int32"> & tags.Minimum<1>,
    key: settingKey,
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.IRequest;

  const initialIndexPage: IPageITodoAppSystemSetting.ISummary =
    await api.functional.todoApp.adminUser.systemSettings.index(connection, {
      body: initialIndexRequest,
    });
  typia.assert(initialIndexPage);

  TestValidator.predicate(
    "initial index should contain at least one matching setting",
    initialIndexPage.data.some(
      (s) => s.key === settingKey && s.enabled === true,
    ),
  );

  // 2. Attempt DELETE as unauthenticated guest (no Authorization header)
  const guestConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  await TestValidator.error(
    "unauthenticated guest should be forbidden to delete system setting",
    async () => {
      await api.functional.todoApp.adminUser.systemSettings.erase(
        guestConnection,
        {
          settingKey,
        },
      );
    },
  );

  const loadedAfterGuest: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.at(connection, {
      settingKey,
    });
  typia.assert(loadedAfterGuest);

  TestValidator.equals(
    "setting key should remain unchanged after guest delete attempt",
    loadedAfterGuest.key,
    settingKey,
  );
  TestValidator.predicate(
    "setting should remain enabled after guest delete attempt",
    loadedAfterGuest.enabled === true,
  );

  const indexAfterGuestRequest = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    pageSize: 10 as number & tags.Type<"int32"> & tags.Minimum<1>,
    key: settingKey,
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.IRequest;

  const indexAfterGuest: IPageITodoAppSystemSetting.ISummary =
    await api.functional.todoApp.adminUser.systemSettings.index(connection, {
      body: indexAfterGuestRequest,
    });
  typia.assert(indexAfterGuest);

  TestValidator.predicate(
    "index listing should still contain setting after guest attempt",
    indexAfterGuest.data.some(
      (s) => s.key === settingKey && s.enabled === true,
    ),
  );

  // 3. Create a member user and verify member flows
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const memberPassword: string = "Member1234!";

  const memberJoinBody = {
    email: memberEmail,
    password: memberPassword as string & tags.Format<"password">,
    displayName: RandomGenerator.name(2),
    ip: "127.0.0.1" as string & tags.Format<"ipv4">,
    href: "https://member.todo-app.test/join" as string & tags.Format<"uri">,
    referrer: "https://member.todo-app.test/landing" as string &
      tags.Format<"uri">,
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberAuthorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    due_date: new Date().toISOString() as string & tags.Format<"date-time">,
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(createdTodo);

  TestValidator.equals(
    "created todo title should match input",
    createdTodo.title,
    todoCreateBody.title,
  );

  // 4. Attempt DELETE with member token
  await TestValidator.error(
    "member user should not be allowed to delete admin system settings",
    async () => {
      await api.functional.todoApp.adminUser.systemSettings.erase(connection, {
        settingKey,
      });
    },
  );

  // 5. Switch back to admin and verify setting is still present and enabled
  const adminLoginBody = {
    email: adminEmail,
    password: adminPassword,
    ip: "127.0.0.1",
    href: "https://admin.todo-app.test/login",
    referrer: "https://admin.todo-app.test/dashboard",
  } satisfies ITodoAppAdminUser.ILogin;

  const adminRelogin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminRelogin);

  const loadedAfterMember: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.at(connection, {
      settingKey,
    });
  typia.assert(loadedAfterMember);

  TestValidator.equals(
    "setting key should remain unchanged after member delete attempt",
    loadedAfterMember.key,
    settingKey,
  );
  TestValidator.predicate(
    "setting should remain enabled after member delete attempt",
    loadedAfterMember.enabled === true,
  );

  const indexAfterMemberRequest = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    pageSize: 10 as number & tags.Type<"int32"> & tags.Minimum<1>,
    key: settingKey,
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.IRequest;

  const indexAfterMember: IPageITodoAppSystemSetting.ISummary =
    await api.functional.todoApp.adminUser.systemSettings.index(connection, {
      body: indexAfterMemberRequest,
    });
  typia.assert(indexAfterMember);

  TestValidator.predicate(
    "index listing should still contain setting after member attempt",
    indexAfterMember.data.some(
      (s) => s.key === settingKey && s.enabled === true,
    ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppGuestUser";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate basic pagination of admin guest user search.
 *
 * Business purpose:
 *
 * - Ensure that an authenticated admin user can retrieve guest user concept
 *   listings with simple pagination parameters.
 * - Confirm that the pagination metadata (current, limit, records, pages) in
 *   IPageITodoAppGuestUser.ISummary is coherent and that the data array
 *   respects the requested limit.
 * - Sanity-check that moving from page 1 to page 2 changes the record set when
 *   there are enough records, proving that server-side pagination is wired
 *   correctly.
 *
 * High-level flow:
 *
 * 1. Register an admin user (join) to obtain an authenticated admin session.
 * 2. As admin, create at least one ITodoAppSystemSetting to simulate a realistic
 *    admin environment (no strict assertions on content).
 * 3. Register a member user and log in that member.
 * 4. As member, create multiple todos to populate the system with realistic data.
 * 5. Log back in as admin.
 * 6. Call PATCH /todoApp/adminUser/guestUsers with page=1 and limit=10, leaving
 *    all other filters undefined.
 * 7. Assert structural correctness with typia.assert and verify pagination
 *    metadata and data length.
 * 8. If total records exceed the chosen limit, call the endpoint again with page=2
 *    and the same limit and assert basic non-duplication of id sequences
 *    between page 1 and page 2 when both have data.
 */
export async function test_api_guest_users_search_basic_pagination(
  connection: api.IConnection,
) {
  // 1. Register an admin user to obtain an authenticated admin session.
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: "AdminPassword123!", // matches password format tag
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todo-app.test/join",
    referrer: "https://admin.todo-app.test/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminAuthorized);

  // 2. As admin, create at least one system setting to simulate configuration.
  const systemSettingBody = {
    key: "guest_users_page_default_limit",
    value: "10",
    type: "int",
    description: "Default page size for guest user listing in admin UI",
    group: "analytics",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const systemSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: systemSettingBody,
    });
  typia.assert<ITodoAppSystemSetting>(systemSetting);

  // 3. Register a member user and log in that member.
  const memberEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const memberJoinBody = {
    email: memberEmail,
    password: typia.random<string & tags.Format<"password">>(),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.test/signup",
    referrer: "https://todo-app.test/landing",
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberAuthorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert<ITodoAppMemberUser.IAuthorized>(memberAuthorized);

  const memberLoginBody = {
    email: memberEmail,
    password: memberJoinBody.password,
    ip: null,
    href: "https://todo-app.test/login",
    referrer: "https://todo-app.test/landing",
  } satisfies ITodoAppMemberUserLogin.ICreate;

  const memberLoggedIn: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert<ITodoAppMemberUser.IAuthorized>(memberLoggedIn);

  // 4. As member, create multiple todos to populate the system.
  const todoCount: number & tags.Type<"int32"> & tags.Minimum<1> =
    5 satisfies number as number;

  const createTodoBodies: ITodoAppTodo.ICreate[] = ArrayUtil.repeat(
    todoCount,
    (index) => {
      const baseTitle = `Guest pagination seed todo #${index + 1}`;
      return {
        title: baseTitle,
        description: RandomGenerator.paragraph({
          sentences: 3,
          wordMin: 3,
          wordMax: 8,
        }),
        due_date: null,
        state: "active",
      } satisfies ITodoAppTodo.ICreate;
    },
  );

  const createdTodos: ITodoAppTodo[] = [];
  for (const body of createTodoBodies) {
    const todo: ITodoAppTodo =
      await api.functional.todoApp.memberUser.todos.create(connection, {
        body,
      });
    typia.assert<ITodoAppTodo>(todo);
    createdTodos.push(todo);
  }

  // 5. Log back in as admin to ensure admin session is active.
  const adminLoginBody = {
    email: adminEmail,
    password: adminJoinBody.password,
    ip: null,
    href: "https://admin.todo-app.test/login",
    referrer: "https://admin.todo-app.test/landing",
  } satisfies ITodoAppAdminUser.ILogin;

  const adminLoggedIn: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminLoggedIn);

  // 6. Call PATCH /todoApp/adminUser/guestUsers with page=1 and limit=10.
  const page1 = 1 as number & tags.Type<"int32"> & tags.Minimum<1>;
  const limit = 10 as number & tags.Type<"int32"> & tags.Minimum<1>;

  const requestPage1 = {
    page: page1,
    limit,
    fromCreatedAt: undefined,
    toCreatedAt: undefined,
    externalRef: undefined,
    sortBy: undefined,
    sortDirection: undefined,
  } satisfies ITodoAppGuestUser.IRequest;

  const page1Result: IPageITodoAppGuestUser.ISummary =
    await api.functional.todoApp.adminUser.guestUsers.index(connection, {
      body: requestPage1,
    });
  typia.assert<IPageITodoAppGuestUser.ISummary>(page1Result);

  const pagination1 = page1Result.pagination;
  const data1 = page1Result.data;

  // 7. Validate pagination metadata and page-1 data constraints.
  TestValidator.equals(
    "page 1: current page should equal requested page",
    pagination1.current,
    page1,
  );
  TestValidator.equals(
    "page 1: limit should equal requested limit",
    pagination1.limit,
    limit,
  );

  TestValidator.predicate(
    "page 1: records must be non-negative",
    pagination1.records >= 0,
  );
  TestValidator.predicate(
    "page 1: pages must be non-negative",
    pagination1.pages >= 0,
  );
  TestValidator.predicate(
    "page 1: data.length must not exceed limit",
    data1.length <= pagination1.limit,
  );

  if (data1.length > 0) {
    const firstGuest: ITodoAppGuestUser.ISummary = data1[0];
    typia.assert<ITodoAppGuestUser.ISummary>(firstGuest);
  }

  // 8. If there are more records than one page, request page 2 and compare.
  if (pagination1.records > pagination1.limit) {
    const page2 = 2 as number & tags.Type<"int32"> & tags.Minimum<1>;
    const requestPage2 = {
      page: page2,
      limit,
      fromCreatedAt: undefined,
      toCreatedAt: undefined,
      externalRef: undefined,
      sortBy: undefined,
      sortDirection: undefined,
    } satisfies ITodoAppGuestUser.IRequest;

    const page2Result: IPageITodoAppGuestUser.ISummary =
      await api.functional.todoApp.adminUser.guestUsers.index(connection, {
        body: requestPage2,
      });
    typia.assert<IPageITodoAppGuestUser.ISummary>(page2Result);

    const pagination2 = page2Result.pagination;
    const data2 = page2Result.data;

    TestValidator.equals(
      "page 2: current page should equal requested page",
      pagination2.current,
      page2,
    );
    TestValidator.equals(
      "page 2: limit should equal requested limit",
      pagination2.limit,
      limit,
    );
    TestValidator.predicate(
      "page 2: data.length must not exceed limit",
      data2.length <= pagination2.limit,
    );

    if (data1.length > 0 && data2.length > 0) {
      const ids1 = data1.map((g) => g.id);
      const ids2 = data2.map((g) => g.id);

      const serialized1 = JSON.stringify(ids1);
      const serialized2 = JSON.stringify(ids2);

      TestValidator.predicate(
        "page 1 and page 2 should not have identical id sequences when both have data",
        serialized1 !== serialized2,
      );
    }
  }

  // 9. Optionally, sanity-check a very small limit (1) still respects limit.
  const tinyLimit = 1 as number & tags.Type<"int32"> & tags.Minimum<1>;
  const tinyRequest = {
    page: page1,
    limit: tinyLimit,
    fromCreatedAt: undefined,
    toCreatedAt: undefined,
    externalRef: undefined,
    sortBy: undefined,
    sortDirection: undefined,
  } satisfies ITodoAppGuestUser.IRequest;

  const tinyPage: IPageITodoAppGuestUser.ISummary =
    await api.functional.todoApp.adminUser.guestUsers.index(connection, {
      body: tinyRequest,
    });
  typia.assert<IPageITodoAppGuestUser.ISummary>(tinyPage);

  TestValidator.equals(
    "tiny limit: current page should be 1",
    tinyPage.pagination.current,
    page1,
  );
  TestValidator.equals(
    "tiny limit: limit should equal requested limit",
    tinyPage.pagination.limit,
    tinyLimit,
  );
  TestValidator.predicate(
    "tiny limit: data.length must not exceed tiny limit",
    tinyPage.data.length <= tinyPage.pagination.limit,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppGuestUser";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";

/**
 * Validate guest user search filtering by time range and external_ref,
 * including sorting.
 *
 * Business goals:
 *
 * - Ensure an authenticated admin can query guest users via PATCH
 *   /todoApp/adminUser/guestUsers.
 * - Verify that fromCreatedAt/toCreatedAt are treated as inclusive bounds.
 * - Confirm that externalRef filter narrows results to the expected external_ref
 *   value.
 * - Validate that sortBy="created_at" with sortDirection="asc" and "desc" is
 *   honored.
 * - Optionally check that an intentionally exclusive time window yields an empty
 *   data page.
 *
 * High-level flow:
 *
 * 1. Join an admin user using POST /auth/adminUser/join.
 * 2. Create at least one ITodoAppSystemSetting via POST
 *    /todoApp/adminUser/systemSettings to simulate realistic config.
 * 3. Fetch an initial guest user page with a broad, mostly unfiltered search.
 * 4. If no guests exist, assert type correctness and stop (nothing more to
 *    validate).
 * 5. If guests exist: 5-1. Pick a representative guest summary and derive a narrow
 *    [fromCreatedAt, toCreatedAt] window. 5-2. Query again with that window,
 *    externalRef filter, and sortBy/asc; assert filter constraints and
 *    ascending order. 5-3. Query again with the same window and externalRef,
 *    but sortDirection="desc"; assert filter constraints and descending order.
 *    5-4. Query with an intentionally exclusive time window and assert an empty
 *    data array with valid pagination.
 */
export async function test_api_guest_users_search_with_time_and_external_ref_filters(
  connection: api.IConnection,
) {
  // 1. Join an admin user to obtain an authorized connection.
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "AdminPassword123!", // satisfies password format
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todo-app.test/join",
    referrer: "https://admin.todo-app.test/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const admin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(admin);

  // 2. Create a sample system setting to simulate realistic environment.
  const systemSettingBody = {
    key: `guest_search_max_window_${RandomGenerator.alphaNumeric(8)}`,
    value: "P7D", // e.g., ISO-8601-like duration string, business-agnostic
    type: "string",
    description: "Test-only system setting for guest search E2E.",
    group: "e2e-test",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const systemSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: systemSettingBody,
    });
  typia.assert(systemSetting);

  // 3. Fetch an initial guest user page with a broad search.
  const initialRequestBody = {
    page: 1,
    limit: 20,
    fromCreatedAt: null,
    toCreatedAt: null,
    externalRef: null,
    sortBy: null,
    sortDirection: null,
  } satisfies ITodoAppGuestUser.IRequest;

  const initialPage: IPageITodoAppGuestUser.ISummary =
    await api.functional.todoApp.adminUser.guestUsers.index(connection, {
      body: initialRequestBody,
    });
  typia.assert(initialPage);

  const initialData: ITodoAppGuestUser.ISummary[] = initialPage.data;

  // If there is no data, we can only validate the basic shape and exit.
  if (initialData.length === 0) {
    await TestValidator.predicate(
      "initial guest user list may be empty in this environment",
      true,
    );
    return;
  }

  // 4. Pick a representative guest summary.
  const withExternalRef = initialData.find(
    (g) => g.external_ref !== null && g.external_ref !== undefined,
  );
  const target: ITodoAppGuestUser.ISummary = withExternalRef ?? initialData[0];

  const targetCreatedAt: string & tags.Format<"date-time"> = target.created_at;
  const targetExternalRef: string | null | undefined = target.external_ref;

  // Derive inclusive time window equal to the target created_at.
  const fromCreatedAt: string & tags.Format<"date-time"> = targetCreatedAt;
  const toCreatedAt: string & tags.Format<"date-time"> = targetCreatedAt;

  const baseFilterBody = {
    page: 1,
    limit: initialPage.pagination.limit,
    fromCreatedAt,
    toCreatedAt,
    externalRef: targetExternalRef ?? null,
    sortBy: "created_at",
  } satisfies {
    page: number & tags.Type<"int32"> & tags.Minimum<1>;
    limit: number & tags.Type<"int32"> & tags.Minimum<1>;
    fromCreatedAt: string & tags.Format<"date-time">;
    toCreatedAt: string & tags.Format<"date-time">;
    externalRef: string | null;
    sortBy: string | null;
  };

  // Helper to validate filter constraints and sort ordering.
  const assertFilterAndSort = (
    page: IPageITodoAppGuestUser.ISummary,
    direction: "asc" | "desc",
  ): void => {
    typia.assert(page);

    const summaries: ITodoAppGuestUser.ISummary[] = page.data;

    // If no data, nothing to validate beyond type.
    if (summaries.length === 0) return;

    const fromTime = new Date(fromCreatedAt).getTime();
    const toTime = new Date(toCreatedAt).getTime();

    // Validate each row respects filters.
    summaries.forEach((summary, index) => {
      const createdTime = new Date(summary.created_at).getTime();
      TestValidator.predicate(
        `created_at within range for row ${index}`,
        fromTime <= createdTime && createdTime <= toTime,
      );

      if (targetExternalRef !== null && targetExternalRef !== undefined) {
        TestValidator.equals(
          `external_ref matches filter for row ${index}`,
          summary.external_ref,
          targetExternalRef,
        );
      } else {
        TestValidator.equals(
          `external_ref is null when filtering by null for row ${index}`,
          summary.external_ref,
          null,
        );
      }
    });

    // Validate sort ordering by created_at.
    for (let i = 1; i < summaries.length; i++) {
      const prev = new Date(summaries[i - 1].created_at).getTime();
      const curr = new Date(summaries[i].created_at).getTime();

      if (direction === "asc") {
        TestValidator.predicate(
          `created_at ascending between index ${i - 1} and ${i}`,
          prev <= curr,
        );
      } else {
        TestValidator.predicate(
          `created_at descending between index ${i - 1} and ${i}`,
          prev >= curr,
        );
      }
    }
  };

  // 5-2. Query with sortDirection = "asc".
  const ascRequestBody = {
    ...baseFilterBody,
    sortDirection: "asc",
  } satisfies ITodoAppGuestUser.IRequest;

  const ascPage: IPageITodoAppGuestUser.ISummary =
    await api.functional.todoApp.adminUser.guestUsers.index(connection, {
      body: ascRequestBody,
    });
  assertFilterAndSort(ascPage, "asc");

  // 5-3. Query with sortDirection = "desc".
  const descRequestBody = {
    ...baseFilterBody,
    sortDirection: "desc",
  } satisfies ITodoAppGuestUser.IRequest;

  const descPage: IPageITodoAppGuestUser.ISummary =
    await api.functional.todoApp.adminUser.guestUsers.index(connection, {
      body: descRequestBody,
    });
  assertFilterAndSort(descPage, "desc");

  // 5-4. Intentionally exclusive time window to yield empty data.
  const targetTime = new Date(targetCreatedAt).getTime();
  const exclusiveFrom = new Date(targetTime + 1).toISOString();

  const exclusiveRequestBody = {
    page: 1,
    limit: initialPage.pagination.limit,
    fromCreatedAt: exclusiveFrom,
    toCreatedAt: exclusiveFrom,
    externalRef: targetExternalRef ?? null,
    sortBy: "created_at",
    sortDirection: "asc",
  } satisfies ITodoAppGuestUser.IRequest;

  const exclusivePage: IPageITodoAppGuestUser.ISummary =
    await api.functional.todoApp.adminUser.guestUsers.index(connection, {
      body: exclusiveRequestBody,
    });
  typia.assert(exclusivePage);

  TestValidator.equals(
    "exclusive time window should yield empty guest data",
    exclusivePage.data.length,
    0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppGuestUser";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

export async function test_api_guest_users_search_requires_admin_auth(
  connection: api.IConnection,
) {
  // 1. Prepare distinct URLs used in join/login metadata
  const adminHref: string = "https://admin.todo-app.test/join";
  const adminReferrer: string = "https://admin.todo-app.test/landing";
  const memberHref: string = "https://member.todo-app.test/join";
  const memberReferrer: string = "https://member.todo-app.test/home";

  // 2. Create an admin user via /auth/adminUser/join (this also authenticates as admin)
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16) as string &
      tags.Format<"password">,
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: adminHref as string & tags.Format<"uri">,
    referrer: adminReferrer as string & tags.Format<"uri">,
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 3. Configure at least one system setting via POST /todoApp/adminUser/systemSettings
  const systemSettingCreateBody = {
    key: "max_active_todos_per_user",
    value: "100",
    type: "int",
    description:
      "Maximum number of active todos per member user for load control.",
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const systemSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: systemSettingCreateBody,
    });
  typia.assert(systemSetting);

  // 4. Join a member user via /auth/memberUser/join (this also authenticates as member)
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    displayName: RandomGenerator.name(),
    ip: null,
    href: memberHref as string & tags.Format<"uri">,
    referrer: memberReferrer as string & tags.Format<"uri">,
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberAuthorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 5. Create at least one todo for the member user using POST /todoApp/memberUser/todos
  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
    due_date: null,
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(createdTodo);

  // 6. Build a simple guest user search request body
  const guestSearchRequest = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 5 as number & tags.Type<"int32"> & tags.Minimum<1>,
  } satisfies ITodoAppGuestUser.IRequest;

  // 7. Call PATCH /todoApp/adminUser/guestUsers WITHOUT any Authorization header
  const unauthConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  await TestValidator.error(
    "guestUsers index should fail without authentication",
    async () => {
      await api.functional.todoApp.adminUser.guestUsers.index(
        unauthConnection,
        {
          body: guestSearchRequest,
        },
      );
    },
  );

  // 8. Ensure we have a fresh member token via /auth/memberUser/login
  const memberLoginBody = {
    email: memberAuthorized.email,
    password: memberJoinBody.password,
    ip: null,
    href: memberHref as string & tags.Format<"uri">,
    referrer: memberReferrer as string & tags.Format<"uri">,
  } satisfies ITodoAppMemberUserLogin.ICreate;

  const memberLoginAuthorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberLoginAuthorized);

  // 9. With member-authenticated connection (connection now holds member token),
  // attempt to search guest users and expect an authorization error.
  await TestValidator.error(
    "guestUsers index should fail for member-authenticated token",
    async () => {
      await api.functional.todoApp.adminUser.guestUsers.index(connection, {
        body: guestSearchRequest,
      });
    },
  );

  // 10. Re-authenticate as admin via /auth/adminUser/login
  const adminLoginBody = {
    email: adminAuthorized.email,
    password: adminJoinBody.password,
    ip: null,
    href: adminHref as string & tags.Format<"uri">,
    referrer: adminReferrer as string & tags.Format<"uri">,
  } satisfies ITodoAppAdminUser.ILogin;

  const adminLoginAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLoginAuthorized);

  // 11. With admin-authenticated connection, call guestUsers.index and expect success.
  const guestPage: IPageITodoAppGuestUser.ISummary =
    await api.functional.todoApp.adminUser.guestUsers.index(connection, {
      body: guestSearchRequest,
    });
  typia.assert(guestPage);

  // 12. Basic logical assertions on the returned page structure
  TestValidator.predicate(
    "guestUsers index returns non-negative pagination values",
    guestPage.pagination.current >= 0 &&
      guestPage.pagination.limit >= 0 &&
      guestPage.pagination.records >= 0 &&
      guestPage.pagination.pages >= 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";

export async function test_api_system_setting_create_success_by_admin_user(
  connection: api.IConnection,
) {
  /**
   * Validate that an authenticated admin user can create a new global system
   * setting entry via the protected /todoApp/adminUser/systemSettings
   * endpoint.
   *
   * Business flow:
   *
   * 1. Register a fresh admin user using /auth/adminUser/join. This both creates
   *    the admin account and configures the connection with a valid
   *    Authorization header (access token) for the adminUser actor.
   * 2. Using the authenticated admin connection, call
   *    /todoApp/adminUser/systemSettings with a meaningful
   *    ITodoAppSystemSetting.ICreate payload for something like
   *    "max_active_todos_per_user".
   * 3. Assert that the response conforms to ITodoAppSystemSetting and that
   *    business fields (key, value, type, description, group, enabled) match
   *    the request while server-managed fields (id, timestamps, deleted_at) are
   *    populated correctly for a new, non-deleted setting.
   */

  // 1. Join as a new admin user to obtain authorized context (token is
  // automatically attached to connection.headers by the SDK join() call).
  const joinBody = {
    email: `admin+${RandomGenerator.alphaNumeric(8)}@example.com`,
    password: "P@ssw0rd-1234",
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todoapp.local/register",
    referrer: "https://admin.todoapp.local/login",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminAuthorized);

  // 2. Prepare a concrete system setting creation payload.
  const settingKey = "max_active_todos_per_user";
  const settingValue = "100"; // Representing an integer limit, encoded as string
  const settingType = "int"; // Semantic type descriptor for the value
  const settingDescription =
    "Maximum number of active (non-completed) todo items allowed per member user.";
  const settingGroup = "limits";

  const createBody = {
    key: settingKey,
    value: settingValue,
    type: settingType,
    description: settingDescription,
    group: settingGroup,
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const created: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: createBody,
    });
  typia.assert<ITodoAppSystemSetting>(created);

  // 3. Business-level assertions comparing request vs response.
  TestValidator.equals(
    "system setting key should match the requested key",
    created.key,
    settingKey,
  );

  TestValidator.equals(
    "system setting value should match the requested value",
    created.value,
    settingValue,
  );

  TestValidator.equals(
    "system setting type should match the requested type",
    created.type,
    settingType,
  );

  TestValidator.equals(
    "system setting description should match the requested description",
    created.description,
    settingDescription,
  );

  TestValidator.equals(
    "system setting group should match the requested group",
    created.group,
    settingGroup,
  );

  TestValidator.equals(
    "system setting enabled flag should match the requested enabled state",
    created.enabled,
    true,
  );

  // Ensure id and timestamps are non-empty strings in the expected formats.
  TestValidator.predicate(
    "system setting id should be a non-empty UUID-like string",
    () => typeof created.id === "string" && created.id.length > 0,
  );

  TestValidator.predicate(
    "system setting created_at should be a non-empty date-time string",
    () =>
      typeof created.created_at === "string" && created.created_at.length > 0,
  );

  TestValidator.predicate(
    "system setting updated_at should be a non-empty date-time string",
    () =>
      typeof created.updated_at === "string" && created.updated_at.length > 0,
  );

  // For a newly created setting, deleted_at should be null or undefined.
  TestValidator.predicate(
    "system setting deleted_at should be null or undefined on creation",
    () => created.deleted_at === null || created.deleted_at === undefined,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";

/**
 * Validate creation of a disabled todoApp system setting and its lifecycle
 * fields.
 *
 * Business goal: Ensure that an administrative user can create a new global
 * configuration / feature flag entry in `todo_app_system_settings` with
 * `enabled=false`, and that the record is persisted as a normal row
 * (non-deleted) with correct metadata. The disabled state must be controlled
 * purely by the `enabled` flag, not by soft deletion via `deleted_at`.
 *
 * End-to-end workflow:
 *
 * 1. Register a new admin via POST /auth/adminUser/join using a realistic
 *    `ITodoAppAdminUser.IJoin` payload.
 *
 *    - Email is random and unique (Format<"email">).
 *    - Password respects Format<"password"> (any non-empty string is acceptable per
 *         typia tag).
 *    - Optionally include a `display_name`.
 *    - Provide plausible `status` (e.g., "active") and simple `ip`, `href`,
 *         `referrer` strings.
 *    - Assert the response using `typia.assert<ITodoAppAdminUser.IAuthorized>`.
 *    - Rely on the SDK to install the Authorization token onto the shared
 *         `connection`.
 * 2. Call POST /todoApp/adminUser/systemSettings via
 *    `api.functional.todoApp.adminUser.systemSettings.create` with an
 *    `ITodoAppSystemSetting.ICreate` body representing a disabled experimental
 *    feature flag:
 *
 *    - Key: a deterministic test key string like
 *         "experimental_feature_x_disabled_flag_test" to avoid collisions
 *         within this test process.
 *    - Value: "true" (string) to model a boolean flag value stored as string.
 *    - Type: "boolean" to indicate semantic meaning.
 *    - Description: non-null, descriptive text stating this is for E2E disabled-flag
 *         behavior testing.
 *    - Group: "experimental" to categorize the setting.
 *    - Enabled: false.
 * 3. Validate that the create call returns an `ITodoAppSystemSetting` whose
 *    business fields match the request and whose lifecycle fields reflect
 *    proper persistence semantics:
 *
 *    - Use `typia.assert<ITodoAppSystemSetting>(setting)` to guarantee structural
 *         correctness, including id and timestamp formats.
 *    - Use `TestValidator.equals` to assert that `setting.key`, `setting.value`,
 *         `setting.type`, `setting.description`, `setting.group` equal the
 *         request payload values.
 *    - Use `TestValidator.equals` to assert that `setting.enabled` is `false`.
 *    - Use `TestValidator.predicate` to assert that `setting.created_at` and
 *         `setting.updated_at` are non-empty strings; `typia.assert` already
 *         validates `date-time` format.
 *    - Use `TestValidator.predicate` or `TestValidator.equals` to assert that
 *         `setting.deleted_at === null` or `setting.deleted_at === undefined`,
 *         confirming that disabled entries are not soft-deleted.
 * 4. Do not modify `connection.headers` directly; depend entirely on the SDK to
 *    manage Authorization. No additional endpoints (such as list or get-by-key)
 *    are required; validation is done solely against the create response.
 */
export async function test_api_system_setting_create_disabled_flag_behavior(
  connection: api.IConnection,
) {
  // 1. Admin registration (join) to obtain an authorized admin context.
  const joinBody = {
    email: `${RandomGenerator.alphabets(8)}@example.com`,
    password: RandomGenerator.alphabets(12),
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todoapp.local/register",
    referrer: "https://admin.todoapp.local/login",
  } satisfies ITodoAppAdminUser.IJoin;

  const admin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(admin);

  // 2. Create a disabled experimental system setting.
  const requestBody = {
    key: "experimental_feature_x_disabled_flag_test",
    value: "true",
    type: "boolean",
    description: "Experimental feature X flag for E2E disabled-state test",
    group: "experimental",
    enabled: false,
  } satisfies ITodoAppSystemSetting.ICreate;

  const setting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: requestBody,
    });
  typia.assert<ITodoAppSystemSetting>(setting);

