import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";

/**
 * Validate that updating a non-existent system setting key fails without
 * creating a new setting.
 *
 * Business goal: Ensure that the administrative endpoint PUT
 * /todoApp/adminUser/systemSettings/{settingKey} does not implicitly create new
 * configuration rows when called with an unknown key. Instead, it must fail in
 * a not-found style manner for such keys, while still requiring proper admin
 * authentication and a structurally valid update payload.
 *
 * Scenario steps:
 *
 * 1. Register and authenticate an admin user via POST /auth/adminUser/join,
 *    obtaining an ITodoAppAdminUser.IAuthorized response. The SDK will
 *    automatically attach the access token to the shared connection for
 *    subsequent adminUser calls.
 * 2. Construct two distinct, highly unlikely-to-exist setting keys (e.g., prefixed
 *    with "e2e_unknown_setting_") and a valid ITodoAppSystemSetting.IUpdate
 *    payload.
 * 3. Attempt to call PUT /todoApp/adminUser/systemSettings/{settingKey} with the
 *    first unknown key and the valid update body, and assert that the operation
 *    fails by throwing an error (business-level not-found behavior).
 * 4. Repeat the update attempt with the second unknown key (optionally varying the
 *    update body slightly) and again assert that an error is thrown.
 *
 * By using valid authentication and structurally correct DTOs, any failure
 * observed is attributed to the non-existence of the targeted system setting
 * key rather than type validation problems. This test does not inspect specific
 * HTTP status codes, but the error thrown by the SDK suffices to confirm that
 * unknown keys are not silently upserted.
 */
export async function test_api_system_setting_update_not_found_for_unknown_key(
  connection: api.IConnection,
) {
  // 1. Admin registration and authentication
  const joinBody = typia.random<ITodoAppAdminUser.IJoin>();

  const admin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(admin);

  // 2. Prepare non-existent setting keys
  const unknownKey1 = `e2e_unknown_setting_${RandomGenerator.alphaNumeric(16)}`;
  const unknownKey2 = `e2e_unknown_setting_${RandomGenerator.alphaNumeric(16)}`;

  // 3. Prepare a valid update payload for ITodoAppSystemSetting.IUpdate
  const updateBody1 = {
    value: "42",
    type: "int",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.IUpdate;

  const updateBody2 = {
    value: "true",
    type: "boolean",
    description: RandomGenerator.paragraph({ sentences: 2 }),
    group: "features",
    enabled: false,
  } satisfies ITodoAppSystemSetting.IUpdate;

  // 4. Attempt update with the first unknown key and expect an error
  await TestValidator.error(
    "updating an unknown system setting key (unknownKey1) should fail",
    async () => {
      await api.functional.todoApp.adminUser.systemSettings.update(connection, {
        settingKey: unknownKey1,
        body: updateBody1,
      });
    },
  );

  // 5. Attempt update with the second unknown key and expect an error
  await TestValidator.error(
    "updating another unknown system setting key (unknownKey2) should also fail",
    async () => {
      await api.functional.todoApp.adminUser.systemSettings.update(connection, {
        settingKey: unknownKey2,
        body: updateBody2,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";

/**
 * Verify that updating a system setting strictly requires admin authentication.
 *
 * Business context:
 *
 * - System settings in todoApp (todo_app_system_settings) control global behavior
 *   of the service (limits, feature flags, etc.).
 * - Only administrative actors (adminUser) are allowed to create and update these
 *   settings.
 * - Any unauthenticated or improperly authenticated request attempting to update
 *   a system setting must be rejected.
 *
 * Test steps:
 *
 * 1. Register an admin user via POST /auth/adminUser/join.
 *
 *    - This seeds an administrative principal and, via the SDK, attaches an
 *         Authorization header to the provided connection for subsequent
 *         calls.
 * 2. Create an initial system setting via POST /todoApp/adminUser/systemSettings
 *    using the authenticated connection.
 * 3. Construct an unauthenticated connection by shallow-cloning the original
 *    connection but providing an empty headers object, without touching the
 *    original connection.headers after that.
 * 4. Attempt to update the system setting using PUT
 *    /todoApp/adminUser/systemSettings/{settingKey} with the unauthenticated
 *    connection and expect an error via TestValidator.error.
 * 5. Perform a valid authenticated update using the original authenticated
 *    connection and assert that the update succeeds and that returned fields
 *    reflect the requested changes.
 *
 * This demonstrates that admin authentication is both required and sufficient
 * for updating system settings.
 */
export async function test_api_system_setting_update_requires_admin_authentication(
  connection: api.IConnection,
) {
  // 1. Register an admin user and obtain an authenticated connection
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todo-app.example.com/register",
    referrer: "https://admin.todo-app.example.com/",
  } satisfies ITodoAppAdminUser.IJoin;

  const admin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert(admin);

  // 2. Create an initial system setting using authenticated connection
  const settingKey: string = `max_active_todos_${RandomGenerator.alphaNumeric(8)}`;
  const createBody = {
    key: settingKey,
    value: "100",
    type: "int",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const created: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: createBody,
    });
  typia.assert(created);

  TestValidator.equals(
    "created system setting key must match input key",
    created.key,
    settingKey,
  );

  // 3. Prepare an unauthenticated connection (no Authorization header)
  const unauthenticated: api.IConnection = {
    ...connection,
    headers: {},
  };

  // 4. Attempt to update the setting without authentication and expect failure
  const unauthUpdateBody = {
    value: "200",
    enabled: false,
  } satisfies ITodoAppSystemSetting.IUpdate;

  await TestValidator.error(
    "unauthenticated system setting update must fail",
    async () => {
      await api.functional.todoApp.adminUser.systemSettings.update(
        unauthenticated,
        {
          settingKey: created.key,
          body: unauthUpdateBody,
        },
      );
    },
  );

  // 5. Perform a valid authenticated update and verify success
  const authUpdateBody = {
    value: "150",
    type: "int",
    description: RandomGenerator.paragraph({ sentences: 2 }),
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.IUpdate;

  const updated: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.update(connection, {
      settingKey: created.key,
      body: authUpdateBody,
    });
  typia.assert(updated);

  // Key must remain the same
  TestValidator.equals(
    "updated system setting key must remain unchanged",
    updated.key,
    created.key,
  );

  // Updated business fields must match the authenticated update body
  TestValidator.equals(
    "updated system setting value must match authenticated update",
    updated.value,
    authUpdateBody.value,
  );

  TestValidator.equals(
    "updated system setting type must match authenticated update",
    updated.type,
    authUpdateBody.type,
  );

  TestValidator.equals(
    "updated system setting description must match authenticated update",
    updated.description,
    authUpdateBody.description,
  );

  TestValidator.equals(
    "updated system setting group must match authenticated update",
    updated.group,
    authUpdateBody.group,
  );

  TestValidator.equals(
    "updated system setting enabled flag must match authenticated update",
    updated.enabled,
    authUpdateBody.enabled,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";

/**
 * Validate updating an existing todoApp system setting using a re-authenticated
 * admin login session.
 *
 * This test ensures that an administrative user who first joined and created a
 * system setting, and then logs in again in a new logical session, can still
 * fully manage configuration entries via the login-issued token.
 *
 * High-level steps:
 *
 * 1. Admin joins (POST /auth/adminUser/join) with random but valid credentials.
 * 2. While authenticated from join, admin creates a system setting via POST
 *    /todoApp/adminUser/systemSettings using a deterministic key.
 * 3. Admin logs in again using POST /auth/adminUser/login with the same
 *    credentials, receiving a fresh ITodoAppAdminUser.IAuthorized and new
 *    Authorization header set by the SDK.
 * 4. Using the login-based session, admin updates the previously created setting
 *    via PUT /todoApp/adminUser/systemSettings/{settingKey}, changing at least
 *    value and enabled (and optionally description/group).
 * 5. Validate that id and key are unchanged, while mutable fields and updated_at
 *    have changed as expected.
 */
export async function test_api_system_setting_update_via_admin_login_existing_account(
  connection: api.IConnection,
) {
  // 1. Admin joins with valid credentials
  const email: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const password: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();
  const href: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();
  const referrer: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();

  const joinBody = {
    email,
    password,
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href,
    referrer,
  } satisfies ITodoAppAdminUser.IJoin;

  const joinedAdmin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert(joinedAdmin);

  // 2. Create a system setting under the join-based session
  const settingKey: string = `e2e_setting_${RandomGenerator.alphaNumeric(8)}`;

  const createBody = {
    key: settingKey,
    value: "100",
    type: "int",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const createdSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: createBody,
    });
  typia.assert(createdSetting);

  // Sanity checks on created entity
  TestValidator.equals(
    "created setting key must match requested key",
    createdSetting.key,
    settingKey,
  );
  TestValidator.equals(
    "created setting enabled flag should match",
    createdSetting.enabled,
    createBody.enabled,
  );

  // Capture original snapshot for later comparison
  const originalId: string & tags.Format<"uuid"> = createdSetting.id;
  const originalKey: string = createdSetting.key;
  const originalValue: string = createdSetting.value;
  const originalDescription: string | null | undefined =
    createdSetting.description;
  const originalGroup: string | null | undefined = createdSetting.group;
  const originalEnabled: boolean = createdSetting.enabled;
  const originalUpdatedAt: string & tags.Format<"date-time"> =
    createdSetting.updated_at;

  // 3. Log in again with the same credentials (new logical session)
  const loginBody = {
    email,
    password,
    ip: "127.0.0.1",
    href,
    referrer,
  } satisfies ITodoAppAdminUser.ILogin;

  const loggedInAdmin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: loginBody,
    });
  typia.assert(loggedInAdmin);

  TestValidator.equals(
    "logged-in admin id matches joined admin id",
    loggedInAdmin.id,
    joinedAdmin.id,
  );

  // 4. Update the system setting using login-issued token
  const updatedValue: string = "200";
  const updatedDescription: string = RandomGenerator.paragraph({
    sentences: 4,
  });
  const updatedGroup: string = "limits_updated";
  const updatedEnabled: boolean = false;

  const updateBody = {
    value: updatedValue,
    type: "int",
    description: updatedDescription,
    group: updatedGroup,
    enabled: updatedEnabled,
  } satisfies ITodoAppSystemSetting.IUpdate;

  const updatedSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.update(connection, {
      settingKey,
      body: updateBody,
    });
  typia.assert(updatedSetting);

  // 5. Validate invariants and changes
  TestValidator.equals(
    "updated setting id must remain the same",
    updatedSetting.id,
    originalId,
  );
  TestValidator.equals(
    "updated setting key must remain the same",
    updatedSetting.key,
    originalKey,
  );

  TestValidator.equals(
    "updated setting value should match new value",
    updatedSetting.value,
    updatedValue,
  );
  TestValidator.equals(
    "updated setting enabled flag should match new value",
    updatedSetting.enabled,
    updatedEnabled,
  );
  TestValidator.equals(
    "updated setting description should match new description",
    updatedSetting.description,
    updatedDescription,
  );
  TestValidator.equals(
    "updated setting group should match new group",
    updatedSetting.group,
    updatedGroup,
  );

  TestValidator.notEquals(
    "updated_at should be refreshed after update",
    updatedSetting.updated_at,
    originalUpdatedAt,
  );

  TestValidator.notEquals(
    "value should actually change from original",
    updatedSetting.value,
    originalValue,
  );
  TestValidator.notEquals(
    "enabled flag should actually change from original",
    updatedSetting.enabled,
    originalEnabled,
  );

  // Optional: ensure description/group changed when they originally existed
  if (originalDescription !== null && originalDescription !== undefined) {
    TestValidator.notEquals(
      "description should differ from original when original existed",
      updatedSetting.description,
      originalDescription,
    );
  }
  if (originalGroup !== null && originalGroup !== undefined) {
    TestValidator.notEquals(
      "group should differ from original when original existed",
      updatedSetting.group,
      originalGroup,
    );
  }
}

