  TestValidator.equals(
    "admin B status updated to active",
    updatedAdminB.status,
    "active",
  );

  // Ensure updated_at has a valid date-time format (typia.assert already checks
  // this, but we keep a semantic check that it's present and non-empty).
  TestValidator.predicate(
    "updatedAdminB.updated_at is a non-empty string",
    updatedAdminB.updated_at.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate that an admin can suspend another admin and that the updated profile
 * reflects the new status.
 *
 * Business context:
 *
 * - Admin A manages system configuration and other admin accounts.
 * - Admin B is another admin who should be suspended by Admin A.
 * - Member users and todos exist to reflect a realistic application state, though
 *   they are not directly affected by the suspension.
 *
 * Steps:
 *
 * 1. Register Admin A (via /auth/adminUser/join) and obtain an authenticated admin
 *    session.
 * 2. As Admin A, create at least one system setting (via
 *    /todoApp/adminUser/systemSettings) to simulate admin activity.
 * 3. Still as Admin A, register Admin B (via /auth/adminUser/join) and capture
 *    their id, email, status, and timestamps.
 * 4. Register a member user and create a todo for them to ensure business data
 *    exists.
 * 5. Switch authentication back to Admin A using /auth/adminUser/login so Admin A
 *    performs the suspension.
 * 6. Call PUT /todoApp/adminUser/adminUsers/{adminUserId} for Admin B with
 *    ITodoAppAdminUser.IUpdate, setting status to "suspended" and updating
 *    display_name.
 * 7. Assert that the response has status "suspended", preserves id/email, applies
 *    the new display_name, and advances updated_at while leaving created_at
 *    unchanged.
 */
export async function test_api_admin_user_suspend_and_verify_effect_on_profile(
  connection: api.IConnection,
) {
  // 1. Register Admin A (join)
  const adminAEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const adminAPassword: string & tags.Format<"password"> =
    "AdminA-Password-1" as string & tags.Format<"password">;

  const adminAJoinBody = {
    email: adminAEmail,
    password: adminAPassword,
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todo-app.local/join",
    referrer: "https://admin.todo-app.local/",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminAJoinBody,
    });
  typia.assert(adminAAuthorized);

  // 2. As Admin A, create a system setting
  const systemSettingCreateBody = {
    key: `max_active_todos_${RandomGenerator.alphaNumeric(8)}`,
    value: "100",
    type: "int",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const systemSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: systemSettingCreateBody,
    });
  typia.assert(systemSetting);

  // 3. Register Admin B as another admin
  const adminBEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const adminBPassword: string & tags.Format<"password"> =
    "AdminB-Password-1" as string & tags.Format<"password">;

  const adminBJoinBody = {
    email: adminBEmail,
    password: adminBPassword,
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todo-app.local/join",
    referrer: "https://admin.todo-app.local/",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminBAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminBJoinBody,
    });
  typia.assert(adminBAuthorized);

  const adminBInitialId = adminBAuthorized.id;
  const adminBInitialEmail = adminBAuthorized.email;
  const adminBInitialCreatedAt = adminBAuthorized.created_at;
  const adminBInitialUpdatedAt = adminBAuthorized.updated_at;

  // 4. Create a member user and one todo to simulate app data
  const memberEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const memberPassword: string & tags.Format<"password"> =
    "Member-Password-1" as string & tags.Format<"password">;

  const memberJoinBody = {
    email: memberEmail,
    password: memberPassword,
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.local/join",
    referrer: "https://todo-app.local/",
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberAuthorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  const memberLoginBody = {
    email: memberEmail,
    password: memberPassword,
    ip: null,
    href: "https://todo-app.local/login",
    referrer: "https://todo-app.local/",
  } satisfies ITodoAppMemberUserLogin.ICreate;

  const memberAuthorizedAfterLogin: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberAuthorizedAfterLogin);

  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
    due_date: null,
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const todo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(todo);

  // 5. Switch authentication back to Admin A so Admin A performs the suspension
  const adminALoginBody = {
    email: adminAEmail,
    password: adminAPassword,
    ip: null,
    href: "https://admin.todo-app.local/login",
    referrer: "https://admin.todo-app.local/",
  } satisfies ITodoAppAdminUser.ILogin;

  const adminAAuthorizedAfterLogin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminALoginBody,
    });
  typia.assert(adminAAuthorizedAfterLogin);

  // 6. Admin A suspends Admin B via PUT /todoApp/adminUser/adminUsers/{adminUserId}
  const newDisplayName = `${RandomGenerator.name()} (suspended)`;
  const adminBUpdateBody = {
    display_name: newDisplayName,
    status: "suspended",
  } satisfies ITodoAppAdminUser.IUpdate;

  const updatedAdminB: ITodoAppAdminUser =
    await api.functional.todoApp.adminUser.adminUsers.update(connection, {
      adminUserId: adminBInitialId,
      body: adminBUpdateBody,
    });
  typia.assert(updatedAdminB);

  // 7. Validate updated profile
  TestValidator.equals(
    "admin B id should remain unchanged",
    updatedAdminB.id,
    adminBInitialId,
  );

  TestValidator.equals(
    "admin B email should remain unchanged",
    updatedAdminB.email,
    adminBInitialEmail,
  );

  TestValidator.equals(
    "admin B status should be suspended after update",
    updatedAdminB.status,
    "suspended",
  );

  TestValidator.equals(
    "admin B display_name should be updated",
    updatedAdminB.display_name ?? null,
    newDisplayName,
  );

  TestValidator.equals(
    "admin B created_at should remain unchanged",
    updatedAdminB.created_at,
    adminBInitialCreatedAt,
  );

  const initialUpdatedAtMillis = new Date(adminBInitialUpdatedAt).getTime();
  const updatedUpdatedAtMillis = new Date(updatedAdminB.updated_at).getTime();

  await TestValidator.predicate(
    "admin B updated_at should advance after suspension",
    async () => updatedUpdatedAtMillis > initialUpdatedAtMillis,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate that an authenticated admin can update their own display_name using
 * the generic adminUsers.update endpoint.
 *
 * Business context:
 *
 * - Admin operators are represented by todo_app_adminusers and exposed via
 *   ITodoAppAdminUser/ITodoAppAdminUser.IAuthorized DTOs.
 * - The generic update endpoint PUT /todoApp/adminUser/adminUsers/{adminUserId}
 *   should allow an admin to modify their own non-sensitive profile fields
 *   (display_name, possibly status/email depending on policies).
 * - The scenario focuses on self-service profile editing: Admin A updates their
 *   own display_name while keeping email and status unchanged.
 *
 * Test steps:
 *
 * 1. Register Admin A via /auth/adminUser/join and capture their
 *    ITodoAppAdminUser.IAuthorized data (id, email, status, timestamps).
 * 2. While authenticated as Admin A (token auto-applied by SDK), create a sample
 *    system setting via /todoApp/adminUser/systemSettings to simulate a
 *    realistic admin environment.
 * 3. Register a member user and create at least one todo via /auth/memberUser/join
 *    and /todoApp/memberUser/todos to ensure general application data exists
 *    alongside admin operations.
 * 4. Ensure we are authenticated as Admin A (optionally re-login via
 *    /auth/adminUser/login).
 * 5. Call PUT /todoApp/adminUser/adminUsers/{adminUserId} with Admin A's own id
 *    and a body that sets a new display_name using ITodoAppAdminUser.IUpdate.
 * 6. Validate the response ITodoAppAdminUser:
 *
 *    - Id remains the same as Admin A's original id.
 *    - Email remains unchanged.
 *    - Status remains unchanged (e.g., still "active").
 *    - Display_name has been updated to the new value.
 *    - Created_at is unchanged.
 *    - Updated_at is greater than or equal to the original updated_at.
 */
export async function test_api_admin_user_update_self_profile(
  connection: api.IConnection,
) {
  // 1. Register Admin A
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "AdminPassword1!",
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminAuthorized);

  const originalAdminId = adminAuthorized.id;
  const originalAdminEmail = adminAuthorized.email;
  const originalAdminStatus = adminAuthorized.status;
  const originalCreatedAt = adminAuthorized.created_at;
  const originalUpdatedAt = adminAuthorized.updated_at;

  // 2. Create a system setting as Admin A
  const systemSettingBody = {
    key: `max_active_todos_per_user_${RandomGenerator.alphaNumeric(8)}`,
    value: "100",
    type: "int",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const systemSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: systemSettingBody,
    });
  typia.assert<ITodoAppSystemSetting>(systemSetting);

  // 3. Register a member user and create a todo
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "MemberPassword1!",
    displayName: RandomGenerator.name(),
    ip: "127.0.0.1",
    href: "https://app.example.com/join",
    referrer: "https://app.example.com/landing",
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberAuthorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert<ITodoAppMemberUser.IAuthorized>(memberAuthorized);

  // Ensure member is logged in (join already authenticates, but this also
  // exercises login flow and confirms credentials work)
  const memberLoginBody = {
    email: memberJoinBody.email,
    password: memberJoinBody.password,
    ip: "127.0.0.1",
    href: "https://app.example.com/login",
    referrer: "https://app.example.com/join",
  } satisfies ITodoAppMemberUserLogin.ICreate;

  const memberAuthorizedAfterLogin: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert<ITodoAppMemberUser.IAuthorized>(memberAuthorizedAfterLogin);

  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
    due_date: new Date().toISOString(),
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert<ITodoAppTodo>(createdTodo);

  // 4. Re-authenticate as Admin A to ensure admin token is active
  const adminLoginBody = {
    email: originalAdminEmail,
    password: adminJoinBody.password,
    ip: "127.0.0.1",
    href: "https://admin.example.com/login",
    referrer: "https://admin.example.com/join",
  } satisfies ITodoAppAdminUser.ILogin;

  const adminAuthorizedAfterLogin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminAuthorizedAfterLogin);

  TestValidator.equals(
    "admin id should remain same after login",
    adminAuthorizedAfterLogin.id,
    originalAdminId,
  );

  // 5. Self-update: change display_name using adminUsers.update
  const newDisplayName = RandomGenerator.name();
  const adminUpdateBody = {
    display_name: newDisplayName,
  } satisfies ITodoAppAdminUser.IUpdate;

  const updatedAdmin: ITodoAppAdminUser =
    await api.functional.todoApp.adminUser.adminUsers.update(connection, {
      adminUserId: originalAdminId,
      body: adminUpdateBody,
    });
  typia.assert<ITodoAppAdminUser>(updatedAdmin);

  // 6. Validate updated admin fields
  TestValidator.equals(
    "admin id remains unchanged after self-update",
    updatedAdmin.id,
    originalAdminId,
  );
  TestValidator.equals(
    "admin email remains unchanged after self-update",
    updatedAdmin.email,
    originalAdminEmail,
  );
  TestValidator.equals(
    "admin status remains unchanged after self-update",
    updatedAdmin.status,
    originalAdminStatus,
  );
  TestValidator.equals(
    "admin display_name updated to new value",
    updatedAdmin.display_name ?? null,
    newDisplayName,
  );
  TestValidator.equals(
    "created_at remains unchanged after self-update",
    updatedAdmin.created_at,
    originalCreatedAt,
  );

  const originalUpdatedEpoch = Date.parse(originalUpdatedAt);
  const newUpdatedEpoch = Date.parse(updatedAdmin.updated_at);
  TestValidator.predicate(
    "updated_at is greater than or equal to original updated_at",
    newUpdatedEpoch >= originalUpdatedEpoch,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

export async function test_api_todo_reopen_after_completion_by_owner_member(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin joins (register admin account and obtain admin auth context)
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const adminPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword,
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminJoinOutput: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminJoinOutput);

  // 2. Admin login to re-establish admin context (optional but explicit)
  const adminLoginBody = {
    email: adminEmail,
    password: adminPassword,
    ip: "127.0.0.1",
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppAdminUser.ILogin;

  const adminLoginOutput: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminLoginOutput);

  // 3. Admin creates a system setting to allow many active todos per user
  const settingKey = "max_active_todos_per_user";
  const systemSettingBody = {
    key: settingKey,
    value: "100",
    type: "int",
    description: RandomGenerator.paragraph({ sentences: 4 }),
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const systemSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: systemSettingBody,
    });
  typia.assert<ITodoAppSystemSetting>(systemSetting);

  TestValidator.equals(
    "system setting key should match",
    systemSetting.key,
    settingKey,
  );
  TestValidator.predicate(
    "system setting should be enabled",
    systemSetting.enabled === true,
  );

  // 4. Member joins (registers a new member user)
  const memberEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const memberPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const memberJoinBody = {
    email: memberEmail,
    password: memberPassword,
    displayName: RandomGenerator.name(),
    ip: typia.random<string & tags.Format<"ipv4">>(),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberJoinOutput: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert<ITodoAppMemberUser.IAuthorized>(memberJoinOutput);

  TestValidator.equals(
    "joined member email should match",
    memberJoinOutput.email,
    memberEmail,
  );

  // 5. Member logs in explicitly to ensure member context
  const memberLoginBody = {
    email: memberEmail,
    password: memberPassword,
    ip: "127.0.0.1",
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserLogin.ICreate;

  const memberLoginOutput: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert<ITodoAppMemberUser.IAuthorized>(memberLoginOutput);

  TestValidator.equals(
    "logged-in member email should match",
    memberLoginOutput.email,
    memberEmail,
  );

  // 6. Member creates an active todo with a future due date
  const initialState = "active";
  const futureDueDate: string & tags.Format<"date-time"> = RandomGenerator.date(
    new Date(),
    7 * 24 * 60 * 60 * 1000,
  ).toISOString() as string & tags.Format<"date-time">;

  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 8 }),
    due_date: futureDueDate,
    state: initialState,
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert<ITodoAppTodo>(createdTodo);

  TestValidator.equals(
    "created todo should be owned by joined member",
    createdTodo.memberUser.email,
    memberEmail,
  );
  TestValidator.equals(
    "created todo state should be initial active state",
    createdTodo.state,
    initialState,
  );
  TestValidator.predicate(
    "created todo should not be completed",
    createdTodo.completed_at === null || createdTodo.completed_at === undefined,
  );
  TestValidator.predicate(
    "created todo should not be deleted",
    createdTodo.deleted_at === null || createdTodo.deleted_at === undefined,
  );

  const createdUpdatedAt = new Date(createdTodo.updated_at).getTime();

  // 7. Member completes the todo
  const completedTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.complete(connection, {
      todoId: createdTodo.id,
    });
  typia.assert<ITodoAppTodo>(completedTodo);

  TestValidator.equals(
    "completed todo id should match original",
    completedTodo.id,
    createdTodo.id,
  );
  TestValidator.notEquals(
    "completed todo state should differ from initial active state",
    completedTodo.state,
    initialState,
  );
  TestValidator.predicate(
    "completed todo should have completed_at set",
    completedTodo.completed_at !== null &&
      completedTodo.completed_at !== undefined,
  );

  const completedUpdatedAt = new Date(completedTodo.updated_at).getTime();
  TestValidator.predicate(
    "completed todo updated_at should be >= created updated_at",
    completedUpdatedAt >= createdUpdatedAt,
  );

  // 8. Member reopens the completed todo
  const reopenedTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.reopen(connection, {
      todoId: createdTodo.id,
    });
  typia.assert<ITodoAppTodo>(reopenedTodo);

  TestValidator.equals(
    "reopened todo id should match original",
    reopenedTodo.id,
    createdTodo.id,
  );
  TestValidator.equals(
    "reopened todo state should return to initial active state",
    reopenedTodo.state,
    initialState,
  );
  TestValidator.notEquals(
    "reopened todo state should differ from completed state",
    reopenedTodo.state,
    completedTodo.state,
  );
  TestValidator.predicate(
    "reopened todo should have completed_at cleared",
    reopenedTodo.completed_at === null ||
      reopenedTodo.completed_at === undefined,
  );
  TestValidator.predicate(
    "reopened todo should not be deleted",
    reopenedTodo.deleted_at === null || reopenedTodo.deleted_at === undefined,
  );

  const reopenedUpdatedAt = new Date(reopenedTodo.updated_at).getTime();
  TestValidator.predicate(
    "reopened todo updated_at should be greater than completed updated_at",
    reopenedUpdatedAt > completedUpdatedAt,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate reopening a logically deleted todo for its owning member user.
 *
 * Business workflow covered by this E2E test:
 *
 * 1. Bootstrap an admin user and create a generic system setting that conceptually
 *    enables todo reopening behavior.
 * 2. Register a member user and authenticate as that member.
 * 3. As the member, create a new active todo.
 * 4. Delete the todo using the memberUser DELETE endpoint to simulate a logically
 *    deleted state.
 * 5. Call the reopen action on the same todoId.
 * 6. Assert that the reopened todo:
 *
 *    - Reuses the same id and owner.
 *    - Preserves created_at but advances updated_at.
 *    - Has deleted_at cleared to null.
 *    - Has state set to an active value ("active").
 * 7. Register a second member user and verify that this non-owner cannot reopen
 *    the first member's todo, ensuring ownership enforcement.
 */
export async function test_api_todo_reopen_from_soft_deleted_state(
  connection: api.IConnection,
) {
  // 1. Admin bootstrap & system setting creation
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todoapp.test/join",
    referrer: "https://admin.todoapp.test/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  const systemSettingBody = {
    key: "todo_reopen_enabled",
    value: "true",
    type: "boolean",
    description: "Flag to conceptually enable todo reopen behavior in tests",
    group: "features",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const systemSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: systemSettingBody,
    });
  typia.assert(systemSetting);

  // 2. Member registration and authentication (owner)
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://todoapp.test/signup",
    referrer: "https://todoapp.test/landing",
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberAuthorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 3. Create an active todo for the member
  const createTodoBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 8 }),
    due_date: null,
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: createTodoBody,
    });
  typia.assert(createdTodo);

  // 4. Delete the todo to simulate a logically deleted state prerequisite
  await api.functional.todoApp.memberUser.todos.erase(connection, {
    todoId: createdTodo.id,
  });

  // 5. Reopen the same todo
  const reopenedTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.reopen(connection, {
      todoId: createdTodo.id,
    });
  typia.assert(reopenedTodo);

  // 6. Business assertions on reopened todo
  TestValidator.equals(
    "reopened todo should keep the same id",
    reopenedTodo.id,
    createdTodo.id,
  );

  TestValidator.equals(
    "reopened todo should keep same owner memberUser.id",
    reopenedTodo.memberUser.id,
    createdTodo.memberUser.id,
  );

  TestValidator.equals(
    "reopened todo should preserve created_at",
    reopenedTodo.created_at,
    createdTodo.created_at,
  );

  const createdUpdatedAt = new Date(createdTodo.updated_at).getTime();
  const reopenedUpdatedAt = new Date(reopenedTodo.updated_at).getTime();
  TestValidator.predicate(
    "reopened todo updated_at should be equal or later than original",
    reopenedUpdatedAt >= createdUpdatedAt,
  );

  TestValidator.equals(
    "reopened todo deleted_at should be null after reopen",
    reopenedTodo.deleted_at ?? null,
    null,
  );

  TestValidator.equals(
    "reopened todo state should be active",
    reopenedTodo.state,
    "active",
  );

  // 7. Ownership enforcement: another member cannot reopen this todo
  const intruderJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://todoapp.test/signup",
    referrer: "https://todoapp.test/landing",
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const intruderAuthorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: intruderJoinBody,
    });
  typia.assert(intruderAuthorized);

  await TestValidator.error(
    "non-owner member should not be able to reopen another member's todo",
    async () => {
      await api.functional.todoApp.memberUser.todos.reopen(connection, {
        todoId: createdTodo.id,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

export async function test_api_todo_reopen_idempotent_when_already_active(
  connection: api.IConnection,
) {
  // 1. Admin joins and configures a basic system setting so that todo feature is in a normal state.
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todo-app.test/join",
    referrer: "https://admin.todo-app.test/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const admin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(admin);

  // Create a simple system setting; actual key/value do not affect reopen semantics.
  const systemSettingBody = {
    key: "max_active_todos_per_user",
    value: "100",
    type: "int",
    description: "Maximum number of active todos per member user in tests",
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const systemSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: systemSettingBody,
    });
  typia.assert<ITodoAppSystemSetting>(systemSetting);

  // 2. Member user joins (self-registration) and becomes authenticated.
  const memberJoinBody = typia.random<ITodoAppMemberUserJoin.ICreate>();
  const member: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert<ITodoAppMemberUser.IAuthorized>(member);

  // 3. As this member, create an ACTIVE todo.
  const createTodoBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
    due_date: null,
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: createTodoBody,
    });
  typia.assert<ITodoAppTodo>(createdTodo);

  // Initial lifecycle expectations for a freshly created active todo.
  TestValidator.equals(
    "created todo state should be active as requested",
    createdTodo.state,
    "active",
  );

  TestValidator.equals(
    "created todo completed_at should be null or undefined",
    createdTodo.completed_at ?? null,
    null,
  );

  TestValidator.equals(
    "created todo deleted_at should be null or undefined",
    createdTodo.deleted_at ?? null,
    null,
  );

  // 4. Immediately call reopen on an already active todo.
  const reopenedTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.reopen(connection, {
      todoId: createdTodo.id,
    });
  typia.assert<ITodoAppTodo>(reopenedTodo);

  // 5. Validate idempotent behavior and lifecycle consistency.
  TestValidator.equals(
    "reopen should not create a new record; id must be identical",
    reopenedTodo.id,
    createdTodo.id,
  );

  TestValidator.equals(
    "reopened todo state remains active after idempotent reopen",
    reopenedTodo.state,
    "active",
  );

  TestValidator.equals(
    "reopened todo deleted_at remains null/undefined",
    reopenedTodo.deleted_at ?? null,
    null,
  );

  TestValidator.equals(
    "reopened todo completed_at remains null/undefined",
    reopenedTodo.completed_at ?? null,
    null,
  );

  TestValidator.equals(
    "reopened todo created_at must be unchanged",
    reopenedTodo.created_at,
    createdTodo.created_at,
  );

  const createdUpdatedAt = Date.parse(createdTodo.updated_at);
  const reopenedUpdatedAt = Date.parse(reopenedTodo.updated_at);

  TestValidator.predicate(
    "reopened todo updated_at should be greater than or equal to original updated_at",
    reopenedUpdatedAt >= createdUpdatedAt,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Verify that a member user cannot reopen another member's todo.
 *
 * Business context:
 *
 * - The todoApp service exposes lifecycle operations for todos owned by
 *   authenticated member users.
 * - Reopening a todo (PUT /todoApp/memberUser/todos/{todoId}/reopen) must only be
 *   permitted for the owning member.
 * - Cross-account attempts must fail and must not change the todo's underlying
 *   lifecycle state.
 *
 * Test steps:
 *
 * 1. Bootstrap system-level configuration as an admin user:
 *
 *    - Register an admin via POST /auth/adminUser/join.
 *    - Create at least one system setting via POST /todoApp/adminUser/systemSettings
 *         to simulate a configured environment for todo lifecycle.
 * 2. Register Member A and create + complete a todo:
 *
 *    - Join as Member A via POST /auth/memberUser/join.
 *    - As Member A, create a todo using POST /todoApp/memberUser/todos with a valid
 *         ITodoAppTodo.ICreate payload (non-empty title, optional
 *         description/due_date, and an initial state like "active").
 *    - Complete the todo as Member A via PUT
 *         /todoApp/memberUser/todos/{todoId}/complete. Capture the completed
 *         entity as `completedTodo` and assert that it matches the created
 *         todo's id and reflects completion semantics (for example,
 *         `completed_at` is not null).
 * 3. Register Member B as a separate member user:
 *
 *    - Call POST /auth/memberUser/join again with a different email to create Member
 *         B. The SDK automatically switches the connection's Authorization
 *         header to Member B's access token.
 * 4. Attempt forbidden reopen as Member B:
 *
 *    - While authenticated as Member B, attempt to call PUT
 *         /todoApp/memberUser/todos/{todoId}/reopen on Member A's todo id.
 *    - Use TestValidator.error with an async callback to assert that the reopen call
 *         fails (indicating authorization is enforced). Do not validate
 *         specific HTTP status codes or error payloads.
 * 5. Invariant reasoning about state:
 *
 *    - Because we cannot re-fetch the todo by id (no GET
 *         /todoApp/memberUser/todos/{todoId} endpoint in the provided SDK), we
 *         treat the failure of the reopen attempt as evidence that Member B
 *         cannot change the lifecycle state of Member A's todo.
 *    - The fact that we previously obtained `completedTodo` in a completed state and
 *         do not see any successful reopen response suffices to validate the
 *         main business rule: only the owner can perform the reopen operation.
 */
export async function test_api_todo_reopen_forbidden_for_non_owner_member(
  connection: api.IConnection,
) {
  // 1. Bootstrap system as admin: join and create a system setting
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todo-app.local/join",
    referrer: "https://admin.todo-app.local/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  const systemSettingCreateBody = {
    key: "max_active_todos_per_user",
    value: "100",
    type: "int",
    description: "Maximum number of active todos a user can have concurrently.",
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const createdSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: systemSettingCreateBody,
    });
  typia.assert(createdSetting);

  // 2. Register Member A and create + complete a todo
  const memberAJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.local/memberA/join",
    referrer: "https://todo-app.local/landing",
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberAAuthorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberAJoinBody,
    });
  typia.assert(memberAAuthorized);

  const memberATodoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
    due_date: new Date().toISOString(),
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const todoOfMemberA: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: memberATodoCreateBody,
    });
  typia.assert(todoOfMemberA);

  // Complete the todo as Member A
  const completedTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.complete(connection, {
      todoId: todoOfMemberA.id,
    });
  typia.assert(completedTodo);

  TestValidator.equals(
    "completed todo must preserve original id",
    completedTodo.id,
    todoOfMemberA.id,
  );

  // If completed_at is present, it should be non-null to indicate completion
  await TestValidator.predicate(
    "todo should be in completed state",
    async () => {
      if (
        completedTodo.completed_at !== null &&
        completedTodo.completed_at !== undefined
      ) {
        return true;
      }
      // Even if completed_at is null, we still consider the test inconclusive
      // about internal lifecycle naming, but this predicate enforces the
      // expectation that completion sets a timestamp when supported.
      return false;
    },
  );

  // 3. Register Member B as another member user
  const memberBJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.local/memberB/join",
    referrer: "https://todo-app.local/landing",
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberBAuthorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberBJoinBody,
    });
  typia.assert(memberBAuthorized);

  // 4. Attempt forbidden reopen as Member B
  await TestValidator.error(
    "non-owner member cannot reopen another user's todo",
    async () => {
      await api.functional.todoApp.memberUser.todos.reopen(connection, {
        todoId: todoOfMemberA.id,
      });
    },
  );
}

