    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: buildTodoCreateBody("#2"),
    });
  typia.assert(todo2);

  // 7. Attempt to create one more todo beyond the limit and expect failure
  await TestValidator.error(
    "creating a 3rd active todo should violate max_active_todos_per_user limit",
    async () => {
      await api.functional.todoApp.memberUser.todos.create(connection, {
        body: buildTodoCreateBody("#3-over-limit"),
      });
    },
  );

  // 8. Delete one of the existing todos (todo1)
  await api.functional.todoApp.memberUser.todos.erase(connection, {
    todoId: todo1.id,
  });

  // 9. After deletion, creating a new active todo should now succeed again
  const todo3AfterDelete: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: buildTodoCreateBody("#3-after-delete"),
    });
  typia.assert(todo3AfterDelete);

  // 10. Optionally, confirm that attempting to exceed the limit again fails once
  //     the active count is back at the cap.
  await TestValidator.error(
    "creating a 3rd active todo after refilling to the limit should fail again",
    async () => {
      await api.functional.todoApp.memberUser.todos.create(connection, {
        body: buildTodoCreateBody("#4-over-limit-again"),
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate the basic completion flow of a member user's own todo.
 *
 * Business context:
 *
 * - System settings can gate todo behavior; admin must configure them first.
 * - Member users own personal todos and can complete their own active items.
 * - Completing a todo should update its state and completion timestamp while
 *   preserving identity and ownership.
 *
 * Steps:
 *
 * 1. As an admin, join and log in to obtain admin authorization.
 * 2. Create at least one system setting to simulate enabling todo completion.
 * 3. As a member user, join and log in to obtain member authorization.
 * 4. Create a new active todo for the member user.
 * 5. Call the completion endpoint for that todo as the owning member.
 * 6. Verify that the todo is returned with the same id and owner, a changed state
 *    representing completion, and a populated completed_at timestamp.
 * 7. Call the completion endpoint a second time to ensure the operation is
 *    stable/idempotent and invariants still hold.
 */
export async function test_api_todo_completion_basic_flow(
  connection: api.IConnection,
) {
  // 1. Admin joins (registration + implicit authentication)
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = "Admin#" + RandomGenerator.alphaNumeric(12);

  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword as string & tags.Format<"password">,
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todo-app.test/join",
    referrer: "https://admin.todo-app.test/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Admin logs in explicitly (exercise login; keeps Authorization as admin)
  const adminLoginBody = {
    email: adminEmail,
    password: adminPassword,
    ip: null,
    href: "https://admin.todo-app.test/login",
    referrer: "https://admin.todo-app.test/landing",
  } satisfies ITodoAppAdminUser.ILogin;

  const adminLoggedIn: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLoggedIn);

  TestValidator.equals(
    "admin id should be stable between join and login",
    adminLoggedIn.id,
    adminAuthorized.id,
  );

  // 3. Create a system setting that conceptually enables todo completion
  const systemSettingKey = "enable_todo_completion";
  const systemSettingBody = {
    key: systemSettingKey,
    value: "true",
    type: "boolean",
    description: "Flag to enable member todo completion actions in e2e tests.",
    group: "features",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const systemSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: systemSettingBody,
    });
  typia.assert(systemSetting);

  TestValidator.equals(
    "created system setting key matches request",
    systemSetting.key,
    systemSettingKey,
  );

  TestValidator.predicate(
    "system setting should be enabled",
    systemSetting.enabled === true,
  );

  // 4. Member user joins
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const memberPassword: string = "Member#" + RandomGenerator.alphaNumeric(12);

  const memberJoinBody = {
    email: memberEmail,
    password: memberPassword as string & tags.Format<"password">,
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.test/member/join",
    referrer: "https://todo-app.test/landing",
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberAuthorizedOnJoin: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorizedOnJoin);

  // 5. Member logs in explicitly to ensure member auth context
  const memberLoginBody = {
    email: memberEmail,
    password: memberPassword,
    ip: null,
    href: "https://todo-app.test/member/login",
    referrer: "https://todo-app.test/landing",
  } satisfies ITodoAppMemberUserLogin.ICreate;

  const memberAuthorizedOnLogin: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberAuthorizedOnLogin);

  TestValidator.equals(
    "member id should be stable between join and login",
    memberAuthorizedOnLogin.id,
    memberAuthorizedOnJoin.id,
  );

  const memberId: string & tags.Format<"uuid"> = memberAuthorizedOnLogin.id;

  // 6. Member creates an active todo
  const todoTitle = RandomGenerator.paragraph({ sentences: 3 });
  const todoDescription = RandomGenerator.paragraph({ sentences: 6 });
  const dueDate = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString();

  const todoCreateBody = {
    title: todoTitle,
    description: todoDescription,
    due_date: dueDate,
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(createdTodo);

  const createdTodoId = createdTodo.id;

  TestValidator.equals(
    "created todo id should match itself",
    createdTodo.id,
    createdTodoId,
  );

  TestValidator.equals(
    "created todo owner should be the logged-in member",
    createdTodo.memberUser.id,
    memberId,
  );

  TestValidator.equals(
    "created todo state should match requested initial state",
    createdTodo.state,
    todoCreateBody.state,
  );

  TestValidator.predicate(
    "newly created todo should not have completed_at set",
    createdTodo.completed_at === null || createdTodo.completed_at === undefined,
  );

  const initialState = createdTodo.state;
  const initialCompletedAt = createdTodo.completed_at ?? null;
  const initialUpdatedAt = createdTodo.updated_at;

  // 7. Complete the todo as the owning member
  const completedTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.complete(connection, {
      todoId: createdTodoId,
    });
  typia.assert(completedTodo);

  TestValidator.equals(
    "completed todo id should be identical to created todo id",
    completedTodo.id,
    createdTodoId,
  );

  TestValidator.equals(
    "completed todo owner should remain the same member",
    completedTodo.memberUser.id,
    memberId,
  );

  TestValidator.notEquals(
    "todo state should change after completion",
    completedTodo.state,
    initialState,
  );

  TestValidator.predicate(
    "completed todo state should be non-empty string",
    typeof completedTodo.state === "string" && completedTodo.state.length > 0,
  );

  TestValidator.predicate(
    "completed_at should be populated after completion",
    completedTodo.completed_at !== null &&
      completedTodo.completed_at !== undefined,
  );

  TestValidator.predicate(
    "updated_at should be the same or later than before completion",
    new Date(completedTodo.updated_at).getTime() >=
      new Date(initialUpdatedAt).getTime(),
  );

  const firstCompletionUpdatedAt = completedTodo.updated_at;

  // 8. Invoke completion again to check stability/idempotence
  const completedAgainTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.complete(connection, {
      todoId: createdTodoId,
    });
  typia.assert(completedAgainTodo);

  TestValidator.equals(
    "second completion should target the same todo id",
    completedAgainTodo.id,
    createdTodoId,
  );

  TestValidator.equals(
    "second completion should keep the same owner",
    completedAgainTodo.memberUser.id,
    memberId,
  );

  TestValidator.notEquals(
    "state after second completion should still differ from initial state",
    completedAgainTodo.state,
    initialState,
  );

  TestValidator.predicate(
    "completed_at should remain populated after second completion",
    completedAgainTodo.completed_at !== null &&
      completedAgainTodo.completed_at !== undefined,
  );

  TestValidator.predicate(
    "updated_at after second completion should be >= first completion",
    new Date(completedAgainTodo.updated_at).getTime() >=
      new Date(firstCompletionUpdatedAt).getTime(),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Verify idempotent behavior of todo completion.
 *
 * Business goal
 *
 * - Ensure that calling PUT /todoApp/memberUser/todos/{todoId}/complete multiple
 *   times for the same member-owned todo results in a stable completed state
 *   without corrupting lifecycle fields.
 *
 * Steps
 *
 * 1. As admin, register and login to obtain administrative context.
 * 2. As admin, create at least one global system setting to ensure the todo domain
 *    is configured.
 * 3. As member, register and login to obtain member context.
 * 4. Create a new todo for this member in an active state.
 * 5. Call the completion endpoint once and verify:
 *
 *    - State changes compared to the initial todo state
 *    - Completed_at is non-null
 *    - Deleted_at remains null.
 * 6. Call the completion endpoint a second time for the same todo and verify
 *    idempotent behavior:
 *
 *    - The todo remains completed
 *    - Completed_at is still non-null and not earlier than the first completion
 *         timestamp
 *    - No soft deletion occurs and identifiers remain stable.
 */
export async function test_api_todo_completion_idempotent_behavior(
  connection: api.IConnection,
) {
  // 1. Admin registration (join)
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphabets(12) as string & tags.Format<"password">,
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todo-app.test/signup",
    referrer: "https://admin.todo-app.test/",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorizedFromJoin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorizedFromJoin);

  // 2. Admin explicit login (switch/refresh context, even if join already authenticated)
  const adminLoginBody = {
    email: adminAuthorizedFromJoin.email,
    password: adminJoinBody.password,
    ip: "127.0.0.1",
    href: "https://admin.todo-app.test/login",
    referrer: "https://admin.todo-app.test/",
  } satisfies ITodoAppAdminUser.ILogin;

  const adminAuthorizedFromLogin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminAuthorizedFromLogin);

  // 3. Create a system setting that could affect todo behavior.
  //    We use a generic key/value pair with boolean semantic type.
  const systemSettingBody = {
    key: `max_active_todos_per_user_${RandomGenerator.alphaNumeric(8)}`,
    value: "100",
    type: "int",
    description: "Maximum number of active todos per member user for testing.",
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const systemSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: systemSettingBody,
    });
  typia.assert(systemSetting);

  // 4. Member registration (join)
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphabets(12) as string & tags.Format<"password">,
    displayName: RandomGenerator.name(),
    ip: "127.0.0.1",
    href: "https://app.todo-app.test/signup",
    referrer: "https://app.todo-app.test/landing",
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberAuthorizedFromJoin: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorizedFromJoin);

  // 5. Member login (ensure current auth context is the member)
  const memberLoginBody = {
    email: memberJoinBody.email,
    password: memberJoinBody.password,
    ip: "127.0.0.1",
    href: "https://app.todo-app.test/login",
    referrer: "https://app.todo-app.test/",
  } satisfies ITodoAppMemberUserLogin.ICreate;

  const memberAuthorizedFromLogin: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberAuthorizedFromLogin);

  // 6. Create a new active todo for the member
  const initialTodoBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
    due_date: null,
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: initialTodoBody,
    });
  typia.assert(createdTodo);

  TestValidator.predicate(
    "created todo should be in active state before completion",
    createdTodo.state === initialTodoBody.state,
  );
  TestValidator.predicate(
    "created todo should not be completed yet (completed_at is null)",
    createdTodo.completed_at === null || createdTodo.completed_at === undefined,
  );
  TestValidator.predicate(
    "created todo should not be soft-deleted (deleted_at is null)",
    createdTodo.deleted_at === null || createdTodo.deleted_at === undefined,
  );

  // 7. First completion call
  const firstCompleted: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.complete(connection, {
      todoId: createdTodo.id,
    });
  typia.assert(firstCompleted);

  // Basic identity invariants
  TestValidator.equals(
    "todo id remains stable after first completion",
    firstCompleted.id,
    createdTodo.id,
  );
  TestValidator.equals(
    "memberUser id remains stable after first completion",
    firstCompleted.memberUser.id,
    createdTodo.memberUser.id,
  );

  // State and lifecycle checks after first completion
  TestValidator.predicate(
    "todo state should change from initial state after completion (if implementation differentiates)",
    firstCompleted.state !== initialTodoBody.state ||
      createdTodo.state !== initialTodoBody.state,
  );
  TestValidator.predicate(
    "completed_at should be set after first completion",
    firstCompleted.completed_at !== null &&
      firstCompleted.completed_at !== undefined,
  );
  TestValidator.predicate(
    "todo should not be soft-deleted after first completion",
    firstCompleted.deleted_at === null ||
      firstCompleted.deleted_at === undefined,
  );

  const firstCompletedAt: string & tags.Format<"date-time"> = typia.assert<
    string & tags.Format<"date-time">
  >(firstCompleted.completed_at!);

  // 8. Second completion call (idempotency check)
  const secondCompleted: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.complete(connection, {
      todoId: createdTodo.id,
    });
  typia.assert(secondCompleted);

  // Identity invariants across all three snapshots
  TestValidator.equals(
    "todo id remains stable after second completion",
    secondCompleted.id,
    createdTodo.id,
  );
  TestValidator.equals(
    "memberUser id remains stable after second completion",
    secondCompleted.memberUser.id,
    createdTodo.memberUser.id,
  );

  // State remains completed (at least, not regressed to the original state)
  TestValidator.predicate(
    "todo state remains at least as completed as after first completion",
    secondCompleted.state === firstCompleted.state ||
      secondCompleted.state !== initialTodoBody.state,
  );

  // Lifecycle flags should remain valid
  TestValidator.predicate(
    "completed_at remains non-null after second completion",
    secondCompleted.completed_at !== null &&
      secondCompleted.completed_at !== undefined,
  );
  TestValidator.predicate(
    "todo should not be soft-deleted after second completion",
    secondCompleted.deleted_at === null ||
      secondCompleted.deleted_at === undefined,
  );

  const secondCompletedAt: string & tags.Format<"date-time"> = typia.assert<
    string & tags.Format<"date-time">
  >(secondCompleted.completed_at!);

  // completed_at should not move backwards in time; in many implementations
  // it will remain exactly equal across idempotent calls.
  TestValidator.predicate(
    "completed_at from second completion should be equal or later than first completion",
    secondCompletedAt >= firstCompletedAt,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Enforce ownership rules on todo completion.
 *
 * Business goal
 *
 * - Ensure that a member user cannot mark another member user’s todo as completed
 *   through PUT /todoApp/memberUser/todos/{todoId}/complete.
 * - Verify that the system enforces strict ownership on completion state
 *   transitions, rejecting cross-account attempts while allowing the legitimate
 *   owner to complete the todo.
 *
 * High-level steps
 *
 * 1. Bootstrap an admin user and configure system settings so todos can be created
 *    and completed normally.
 * 2. Register Member A, authenticate as Member A, and create a todo (owned by
 *    Member A).
 * 3. Register Member B and authenticate as Member B.
 * 4. While authenticated as Member B, attempt to complete Member A’s todo and
 *    assert that the operation fails.
 * 5. Switch authentication back to Member A and successfully complete the todo,
 *    verifying that ownership is respected and that the todo remains in a valid
 *    state for its rightful owner.
 */
export async function test_api_todo_completion_ownership_enforcement(
  connection: api.IConnection,
) {
  // 1. Admin bootstrap: join as admin and create a system setting
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const adminPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword,
    display_name: RandomGenerator.name(1),
    status: "active",
    ip: "127.0.0.1",
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  const settingBody = {
    key: "todo_completion_enabled",
    value: "true",
    type: "boolean",
    description: "Flag to enable todo completion operations in tests",
    group: "feature_flags",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const systemSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: settingBody,
    });
  typia.assert(systemSetting);

  // 2. Member A registration and login
  const memberAEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const memberAPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const memberAJoinBody = {
    email: memberAEmail,
    password: memberAPassword,
    displayName: RandomGenerator.name(1),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberAAuthorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberAJoinBody,
    });
  typia.assert(memberAAuthorized);

  // 3. Member A creates a todo
  const memberATodoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const memberATodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: memberATodoCreateBody,
    });
  typia.assert(memberATodo);

  // 4. Member B registration (this switches auth context to Member B)
  const memberBEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const memberBPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const memberBJoinBody = {
    email: memberBEmail,
    password: memberBPassword,
    displayName: RandomGenerator.name(1),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberBAuthorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberBJoinBody,
    });
  typia.assert(memberBAuthorized);

  TestValidator.notEquals(
    "member A and member B must be distinct users",
    memberAAuthorized.id,
    memberBAuthorized.id,
  );

  // 5. Unauthorized completion attempt by Member B
  await TestValidator.error(
    "member B cannot complete member A's todo",
    async () => {
      await api.functional.todoApp.memberUser.todos.complete(connection, {
        todoId: memberATodo.id,
      });
    },
  );

  // 6. Switch back to Member A and successfully complete the todo
  const memberALoginBody = {
    email: memberAEmail,
    password: memberAPassword,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserLogin.ICreate;

  const memberALoginAuthorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberALoginBody,
    });
  typia.assert(memberALoginAuthorized);

  TestValidator.equals(
    "member A login id should equal member A join id",
    memberALoginAuthorized.id,
    memberAAuthorized.id,
  );

  const completedTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.complete(connection, {
      todoId: memberATodo.id,
    });
  typia.assert(completedTodo);

  TestValidator.equals(
    "completed todo must keep same id",
    completedTodo.id,
    memberATodo.id,
  );
  TestValidator.equals(
    "completed todo must remain owned by member A",
    completedTodo.memberUser.id,
    memberAAuthorized.id,
  );
  TestValidator.predicate(
    "completed todo should have a completion timestamp",
    completedTodo.completed_at !== null &&
      completedTodo.completed_at !== undefined,
  );
}

