  TestValidator.equals(
    "newly created active todo should have requested state",
    activeTodo.state,
    activeTodoCreateBody.state,
  );

  const incompatibleTodoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    due_date: null,
    state: "archived",
  } satisfies ITodoAppTodo.ICreate;

  const incompatibleTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: incompatibleTodoCreateBody,
    });
  typia.assert(incompatibleTodo);

  TestValidator.equals(
    "newly created incompatible todo should have requested state",
    incompatibleTodo.state,
    incompatibleTodoCreateBody.state,
  );

  // 4. Valid completion: active todo should transition to completed
  const completedTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.complete(connection, {
      todoId: activeTodo.id,
    });
  typia.assert(completedTodo);

  TestValidator.equals(
    "completed todo should keep same id",
    completedTodo.id,
    activeTodo.id,
  );

  TestValidator.predicate(
    "completed todo should have non-null completed_at",
    completedTodo.completed_at !== null &&
      completedTodo.completed_at !== undefined,
  );

  TestValidator.equals<ITodoAppMemberUser.ISummary | null | undefined>(
    "completed todo should still belong to same member user",
    completedTodo.memberUser,
    activeTodo.memberUser,
  );

  // 5. Invalid completion: incompatible state should be rejected
  await TestValidator.error(
    "completing todo in incompatible state should fail",
    async () => {
      await api.functional.todoApp.memberUser.todos.complete(connection, {
        todoId: incompatibleTodo.id,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate that a member user can create a todo when default system settings
 * exist.
 *
 * Business narrative:
 *
 * - An admin onboards first and configures a global system setting such as
 *   `max_active_todos_per_user`, representing the generic requirement that
 *   certain configuration exists before members can interact with todos.
 * - A new member user then signs up and, under their authenticated context,
 *   creates a todo with a title, optional description, a due date, and an
 *   initial state string.
 * - The API should accept the request, respect the authenticated member as the
 *   owner, and return a fully populated ITodoAppTodo entity with correct
 *   mapping from the creation payload.
 *
 * Steps:
 *
 * 1. Register an admin via /auth/adminUser/join and rely on the SDK to set the
 *    Authorization header from the returned token.
 * 2. As that admin, create a system setting via /todoApp/adminUser/systemSettings
 *    with a key such as "max_active_todos_per_user" and a sane value.
 * 3. Register a member user via /auth/memberUser/join and enter the member context
 *    via the SDK-managed token.
 * 4. In the member context, call /todoApp/memberUser/todos with a
 *    ITodoAppTodo.ICreate payload including title, optional description,
 *    due_date and state.
 * 5. Assert that the returned ITodoAppTodo is structurally valid, that memberUser
 *    fields match the newly created member, and that title, description,
 *    due_date, and state are echoed or normalized as expected.
 */
export async function test_api_todo_creation_with_default_system_settings(
  connection: api.IConnection,
) {
  // 1. Admin registration
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Admin#1234" as string & tags.Format<"password">,
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todoapp.local/join" as string & tags.Format<"uri">,
    referrer: "https://admin.todoapp.local/" as string & tags.Format<"uri">,
  } satisfies ITodoAppAdminUser.IJoin;

  const admin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(admin);

  // 2. Create a baseline system setting as admin
  const settingBody = {
    key: "max_active_todos_per_user",
    value: "100",
    type: "int",
    description:
      "Maximum number of active todos allowed per member user in tests.",
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const systemSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: settingBody,
    });
  typia.assert(systemSetting);

  // 3. Register a member user (this call also sets member Authorization in connection)
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://todoapp.local/join" as string & tags.Format<"uri">,
    referrer: "https://todoapp.local/landing" as string & tags.Format<"uri">,
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const member: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(member);

  // 4. With member context, create a todo
  const dueDate = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString();

  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.content({
      paragraphs: 1,
      sentenceMin: 3,
      sentenceMax: 6,
    }),
    due_date: dueDate as string & tags.Format<"date-time">,
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const todo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(todo);

  // 5. Business assertions
  TestValidator.equals(
    "todo owner must match newly joined member user",
    todo.memberUser.id,
    member.id,
  );

  TestValidator.equals(
    "todo title should echo request payload",
    todo.title,
    todoCreateBody.title,
  );

  TestValidator.equals(
    "todo description should echo request payload",
    todo.description ?? null,
    todoCreateBody.description ?? null,
  );

  TestValidator.equals(
    "todo due_date should echo request payload",
    todo.due_date ?? null,
    todoCreateBody.due_date ?? null,
  );

  TestValidator.equals(
    "todo state should match requested initial state",
    todo.state,
    todoCreateBody.state,
  );

  // Ensure created_at and updated_at exist and look like ISO strings via typia.assert already;
  // add a sanity predicate that updated_at is not before created_at.
  TestValidator.predicate("updated_at should be at or after created_at", () => {
    const created = new Date(todo.created_at).getTime();
    const updated = new Date(todo.updated_at).getTime();
    return (
      !Number.isNaN(created) && !Number.isNaN(updated) && updated >= created
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Ensure todo creation enforces the configured max_active_todos_per_user limit.
 *
 * Business workflow:
 *
 * 1. Register an admin user and become authenticated as that admin.
 * 2. As admin, create a system setting with key "max_active_todos_per_user", value
 *    "2", type "int", and enabled=true.
 * 3. Register a member user and become authenticated as that member.
 * 4. As the member, successfully create 2 active todos.
 * 5. Attempt to create a 3rd active todo and verify that the request fails with a
 *    business-rule error.
 *
 * This test validates that the POST /todoApp/memberUser/todos endpoint consults
 * global configuration and refuses to create more active todos than allowed for
 * a single member user.
 */
export async function test_api_todo_creation_respects_max_active_limit(
  connection: api.IConnection,
) {
  // 1. Register an admin user (also authenticates as admin)
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12) as string &
      tags.Format<"password">,
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todo-app.test/join",
    referrer: "https://admin.todo-app.test/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Configure system setting: max_active_todos_per_user = 2
  const settingBody = {
    key: "max_active_todos_per_user",
    value: "2",
    type: "int",
    description:
      "Maximum number of active todos allowed per member user for testing.",
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const systemSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: settingBody,
    });
  typia.assert(systemSetting);
  TestValidator.equals(
    "system setting key should match configured key",
    systemSetting.key,
    settingBody.key,
  );
  TestValidator.equals(
    "system setting value should match configured value",
    systemSetting.value,
    settingBody.value,
  );
  TestValidator.equals(
    "system setting enabled flag should be true",
    systemSetting.enabled,
    true,
  );

  // 3. Register a member user (also authenticates as member)
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.test/signup",
    referrer: "https://todo-app.test/landing",
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberAuthorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 4. Create active todos up to the configured limit (2)
  const limit = 2;
  const createdTodos: ITodoAppTodo[] = [];

  for (let i = 0; i < limit; i++) {
    const todoCreateBody = {
      title: RandomGenerator.paragraph({ sentences: 3 }),
      description: RandomGenerator.paragraph({ sentences: 6 }),
      due_date: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(),
      state: "active",
    } satisfies ITodoAppTodo.ICreate;

    const todo: ITodoAppTodo =
      await api.functional.todoApp.memberUser.todos.create(connection, {
        body: todoCreateBody,
      });
    typia.assert(todo);

    TestValidator.equals(
      `created todo ${i + 1} title should match request`,
      todo.title,
      todoCreateBody.title,
    );
    TestValidator.equals(
      `created todo ${i + 1} state should be active`,
      todo.state,
      todoCreateBody.state,
    );

    createdTodos.push(todo);
  }

  TestValidator.equals(
    "number of successfully created todos should equal limit",
    createdTodos.length,
    limit,
  );

  // 5. Attempt to create one more active todo and expect failure
  const overLimitTodoBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    due_date: new Date(Date.now() + 48 * 60 * 60 * 1000).toISOString(),
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  await TestValidator.error(
    "creating an active todo beyond max_active_todos_per_user should fail",
    async () => {
      await api.functional.todoApp.memberUser.todos.create(connection, {
        body: overLimitTodoBody,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate creation of todos with different combinations of optional fields.
 *
 * Business goal:
 *
 * - Ensure that the todo creation API correctly handles optional `description`
 *   and `due_date` fields when they are provided, omitted, or explicitly set to
 *   null.
 * - Confirm that system bootstrap via admin user and system settings does not
 *   block member-level todo creation.
 *
 * Scenario steps:
 *
 * 1. Bootstrap an admin user and ensure at least one ITodoAppSystemSetting exists
 *    using api.functional.todoApp.adminUser.systemSettings.create.
 * 2. Register a member user via api.functional.auth.memberUser.join.
 * 3. Using the authenticated member session, create: 3-1. A todo with title,
 *    state, non-null description, and non-null due_date. 3-2. A todo with title
 *    and state, but `description: null` and `due_date: null` explicitly. 3-3. A
 *    todo with title and state where only `description` is non-null and
 *    `due_date` is null (or vice versa) to validate field-level optionality.
 * 4. For each created todo, assert that:
 *
 *    - The response type matches ITodoAppTodo (using typia.assert).
 *    - The echo of title and state matches the request.
 *    - The nullable fields reflect the values sent: non-null strings when provided
 *         and null when explicitly set to null.
 *    - For non-null `due_date`, the value is a syntactically valid ISO-8601
 *         date-time string (already guaranteed by typia.assert, so we rely on
 *         that).
 */
export async function test_api_todo_creation_with_optional_fields_variations(
  connection: api.IConnection,
) {
  // 1. Bootstrap admin user and system setting
  const adminEmail: string = typia.random<string & tags.Format<"email">>();

  const adminJoinBody = {
    email: adminEmail,
    password: RandomGenerator.alphaNumeric(12),
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todo-app.test/signup",
    referrer: "https://admin.todo-app.test/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminAuthorized);

  // Create a baseline system setting to ensure configuration exists
  const systemSettingBody = {
    key: "max_active_todos_per_user",
    value: "100",
    type: "int",
    description: "Maximum number of active todos per member user for tests",
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const systemSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: systemSettingBody,
    });
  typia.assert<ITodoAppSystemSetting>(systemSetting);
  TestValidator.equals(
    "system setting key is correctly stored",
    systemSetting.key,
    systemSettingBody.key,
  );

  // 2. Register a member user via /auth/memberUser/join
  const memberEmail: string = typia.random<string & tags.Format<"email">>();

  const memberJoinBody = {
    email: memberEmail,
    password: RandomGenerator.alphaNumeric(12) as string &
      tags.Format<"password">,
    displayName: RandomGenerator.name(),
    ip: "127.0.0.1" as string & tags.Format<"ipv4">,
    href: "https://todo-app.test/signup" as string & tags.Format<"uri">,
    referrer: "https://todo-app.test/landing" as string & tags.Format<"uri">,
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberAuthorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert<ITodoAppMemberUser.IAuthorized>(memberAuthorized);

  // 3-1. Create todo with non-null description and non-null due_date
  const dueDate1: string & tags.Format<"date-time"> = new Date(
    Date.now() + 24 * 60 * 60 * 1000,
  ).toISOString() as string & tags.Format<"date-time">;

  const todoCreateBody1 = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
    due_date: dueDate1,
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const todo1: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody1,
    });
  typia.assert<ITodoAppTodo>(todo1);

  TestValidator.equals("todo1 title echo", todo1.title, todoCreateBody1.title);
  TestValidator.equals("todo1 state echo", todo1.state, todoCreateBody1.state);
  TestValidator.equals(
    "todo1 description non-null echo",
    todo1.description,
    todoCreateBody1.description,
  );
  TestValidator.equals(
    "todo1 due_date non-null echo",
    todo1.due_date,
    todoCreateBody1.due_date,
  );

  // 3-2. Create todo with description and due_date explicitly null
  const todoCreateBody2 = {
    title: RandomGenerator.paragraph({ sentences: 2 }),
    description: null,
    due_date: null,
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const todo2: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody2,
    });
  typia.assert<ITodoAppTodo>(todo2);

  TestValidator.equals("todo2 title echo", todo2.title, todoCreateBody2.title);
  TestValidator.equals("todo2 state echo", todo2.state, todoCreateBody2.state);
  TestValidator.equals(
    "todo2 description is null",
    todo2.description,
    todoCreateBody2.description,
  );
  TestValidator.equals(
    "todo2 due_date is null",
    todo2.due_date,
    todoCreateBody2.due_date,
  );

  // 3-3. Mixed optionality: description non-null, due_date null
  const todoCreateBody3 = {
    title: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    due_date: null,
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const todo3: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody3,
    });
  typia.assert<ITodoAppTodo>(todo3);

  TestValidator.equals("todo3 title echo", todo3.title, todoCreateBody3.title);
  TestValidator.equals("todo3 state echo", todo3.state, todoCreateBody3.state);
  TestValidator.equals(
    "todo3 description non-null echo",
    todo3.description,
    todoCreateBody3.description,
  );
  TestValidator.equals(
    "todo3 due_date is null",
    todo3.due_date,
    todoCreateBody3.due_date,
  );

  // Additionally validate that created todos belong to the authenticated member
  TestValidator.equals(
    "todo1 owner matches member",
    todo1.memberUser.id,
    memberAuthorized.id,
  );
  TestValidator.equals(
    "todo2 owner matches member",
    todo2.memberUser.id,
    memberAuthorized.id,
  );
  TestValidator.equals(
    "todo3 owner matches member",
    todo3.memberUser.id,
    memberAuthorized.id,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Verify that todos created for distinct member users are isolated by
 * ownership.
 *
 * Business goal:
 *
 * - Ensure that POST /todoApp/memberUser/todos always binds the new todo to the
 *   currently authenticated member user, not to any client-controlled field.
 * - Demonstrate that two separate member accounts (Member A and Member B) each
 *   receive todos whose `memberUser` summary reflects their own identity, and
 *   that those owners differ between the two todos.
 *
 * High-level flow:
 *
 * 1. Admin joins and establishes global system settings (precondition for todo
 *    creation under the todoApp domain).
 * 2. Member A joins (and is implicitly authenticated by the join endpoint).
 * 3. While authenticated as Member A, create a todo and capture the returned
 *    ITodoAppTodo, including its embedded `memberUser` summary.
 * 4. Member B joins as a completely separate member account.
 * 5. While authenticated as Member B, create another todo with a distinct title
 *    and capture its `memberUser` summary.
 * 6. Assert that Member A and Member B have different ids and emails.
 * 7. Assert that Member A’s todo.memberUser.* matches Member A’s identity, and
 *    Member B’s todo.memberUser.* matches Member B’s identity.
 * 8. Assert that the owner summaries of the two todos differ (no ownership leakage
 *    between accounts).
 */
export async function test_api_todo_creation_for_distinct_members_is_isolated(
  connection: api.IConnection,
) {
  // 1. Admin joins to initialize an administrative actor.
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16) as string &
      tags.Format<"password">,
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todo-app.test/join",
    referrer: "https://admin.todo-app.test/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Create at least one system setting so the todoApp domain is configured.
  const systemSettingBody = {
    key: "max_active_todos_per_user",
    value: "100",
    type: "int",
    description:
      "Maximum number of active todos a member user can have at once.",
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const systemSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: systemSettingBody,
    });
  typia.assert(systemSetting);

  // 3. Register Member A (join implicitly authenticates as this member).
  const memberAEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const memberAJoinBody = {
    email: memberAEmail,
    password: RandomGenerator.alphaNumeric(16) as string &
      tags.Format<"password">,
    displayName: RandomGenerator.name(),
    ip: "127.0.0.1" as string & tags.Format<"ipv4">,
    href: "https://todo-app.test/signup" as string & tags.Format<"uri">,
    referrer: "https://todo-app.test/landing" as string & tags.Format<"uri">,
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberAAuthorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberAJoinBody,
    });
  typia.assert(memberAAuthorized);

  // Sanity checks for Member A
  TestValidator.equals(
    "member A email must match join payload",
    memberAAuthorized.email,
    memberAEmail,
  );

  // 4. While authenticated as Member A, create their todo.
  const todoATitle = `Todo for Member A - ${RandomGenerator.paragraph({
    sentences: 2,
  })}`;

  const todoABody = {
    title: todoATitle,
    description: RandomGenerator.paragraph({ sentences: 4 }),
    due_date: typia.random<string & tags.Format<"date-time">>(),
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const todoA: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoABody,
    });
  typia.assert(todoA);

  // Validate that todoA is owned by Member A
  TestValidator.equals(
    "todo A owner id matches Member A id",
    todoA.memberUser.id,
    memberAAuthorized.id,
  );
  TestValidator.equals(
    "todo A owner email matches Member A email",
    todoA.memberUser.email,
    memberAAuthorized.email,
  );

  // 5. Register Member B as a separate member account.
  const memberBEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const memberBJoinBody = {
    email: memberBEmail,
    password: RandomGenerator.alphaNumeric(16) as string &
      tags.Format<"password">,
    displayName: RandomGenerator.name(),
    ip: "127.0.0.1" as string & tags.Format<"ipv4">,
    href: "https://todo-app.test/signup" as string & tags.Format<"uri">,
    referrer: "https://todo-app.test/landing" as string & tags.Format<"uri">,
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberBAuthorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberBJoinBody,
    });
  typia.assert(memberBAuthorized);

  // Basic isolation check: Member A and Member B must be different principals.
  TestValidator.notEquals(
    "Member A id and Member B id must differ",
    memberAAuthorized.id,
    memberBAuthorized.id,
  );
  TestValidator.notEquals(
    "Member A email and Member B email must differ",
    memberAAuthorized.email,
    memberBAuthorized.email,
  );

  // 6. While authenticated as Member B, create their todo with a distinct title.
  const todoBTitle = `Todo for Member B - ${RandomGenerator.paragraph({
    sentences: 2,
  })}`;

  const todoBBody = {
    title: todoBTitle,
    description: RandomGenerator.paragraph({ sentences: 4 }),
    due_date: typia.random<string & tags.Format<"date-time">>(),
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const todoB: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoBBody,
    });
  typia.assert(todoB);

  // Validate that todoB is owned by Member B
  TestValidator.equals(
    "todo B owner id matches Member B id",
    todoB.memberUser.id,
    memberBAuthorized.id,
  );
  TestValidator.equals(
    "todo B owner email matches Member B email",
    todoB.memberUser.email,
    memberBAuthorized.email,
  );

  // 7. Cross-check that the two todos are owned by different members.
  TestValidator.notEquals(
    "todo A and todo B must have different owner ids",
    todoA.memberUser.id,
    todoB.memberUser.id,
  );
  TestValidator.notEquals(
    "todo A and todo B must have different owner emails",
    todoA.memberUser.email,
    todoB.memberUser.email,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Verify that a member user can partially update the basic content fields of
 * their own todo.
 *
 * Business flow:
 *
 * 1. Create an admin user and initialize at least one system setting, simulating
 *    required global configuration.
 * 2. Register a member user (owner) via /auth/memberUser/join and rely on SDK to
 *    attach their token to the connection.
 * 3. As that member user, create an initial todo via /todoApp/memberUser/todos
 *    with title, optional description, state, and due_date.
 * 4. Capture the created todo and remember id, owner identity, state, created_at
 *    and updated_at, description and due_date.
 * 5. Send PUT /todoApp/memberUser/todos/{todoId} with ITodoAppTodo.IUpdate that
 *    changes title, description and due_date only (omit state).
 * 6. Validate that:
 *
 *    - Id remains the same.
 *    - MemberUser summary still points to the same owner (id and email unchanged).
 *    - Title, description and due_date have been updated to the new values.
 *    - State remains unchanged because it was omitted from the update body.
 *    - Created_at is unchanged, while updated_at is strictly greater than the
 *         original value.
 */
export async function test_api_todo_update_basic_fields_by_owner(
  connection: api.IConnection,
) {
  // 1. Admin bootstrap: join as admin and create at least one system setting.
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: "AdminPassword123!",
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todo-app.local/join",
    referrer: "https://admin.todo-app.local/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  const systemSettingBody = {
    key: "max_active_todos_per_user",
    value: "100",
    type: "int",
    description:
      "Maximum number of active todos a single member user can have.",
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const systemSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: systemSettingBody,
    });
  typia.assert(systemSetting);

  // 2. Member user registration (owner of the todo).
  const memberEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const memberJoinBody = {
    email: memberEmail,
    password: "MemberPassword123!" as string & tags.Format<"password">,
    displayName: RandomGenerator.name(),
    ip: "127.0.0.1" as string & tags.Format<"ipv4">,
    href: "https://app.todo-app.local/signup" as string & tags.Format<"uri">,
    referrer: "https://app.todo-app.local/landing" as string &
      tags.Format<"uri">,
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberAuthorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 3. Create an initial todo as this member user.
  const initialDueDate: string & tags.Format<"date-time"> = typia.random<
    string & tags.Format<"date-time">
  >();

  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
    due_date: initialDueDate,
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(createdTodo);

  // Persist original values for later comparison.
  const originalId = createdTodo.id;
  const originalState = createdTodo.state;
  const originalCreatedAt = createdTodo.created_at;
  const originalUpdatedAt = createdTodo.updated_at;
  const originalMemberId = createdTodo.memberUser.id;
  const originalMemberEmail = createdTodo.memberUser.email;

  // Sanity checks on ownership and identity.
  TestValidator.equals(
    "created todo is owned by the authenticated member (id)",
    createdTodo.memberUser.id,
    memberAuthorized.id,
  );
  TestValidator.equals(
    "created todo is owned by the authenticated member (email)",
    createdTodo.memberUser.email,
    memberAuthorized.email,
  );

  // 4. Prepare update payload for title, description, and due_date only.
  const updatedDueDate: string & tags.Format<"date-time"> = typia.random<
    string & tags.Format<"date-time">
  >();

  const updateBody = {
    title: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    due_date: updatedDueDate,
  } satisfies ITodoAppTodo.IUpdate;

  const updatedTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.update(connection, {
      todoId: createdTodo.id,
      body: updateBody,
    });
  typia.assert(updatedTodo);

  // 5. Validate identity, ownership, and unchanged fields.
  TestValidator.equals(
    "todo id should remain the same after update",
    updatedTodo.id,
    originalId,
  );

  TestValidator.equals(
    "memberUser id should remain the same after update",
    updatedTodo.memberUser.id,
    originalMemberId,
  );
  TestValidator.equals(
    "memberUser email should remain the same after update",
    updatedTodo.memberUser.email,
    originalMemberEmail,
  );

  TestValidator.equals(
    "state should remain unchanged when omitted from IUpdate",
    updatedTodo.state,
    originalState,
  );

  // 6. Validate updated content fields.
  TestValidator.equals(
    "title should be updated to the new value",
    updatedTodo.title,
    updateBody.title,
  );
  TestValidator.equals(
    "description should be updated to the new value",
    updatedTodo.description,
    updateBody.description,
  );
  TestValidator.equals(
    "due_date should be updated to the new value",
    updatedTodo.due_date,
    updateBody.due_date,
  );

  // 7. Validate timestamps: created_at unchanged, updated_at increased.
  TestValidator.equals(
    "created_at must remain unchanged after content update",
    updatedTodo.created_at,
    originalCreatedAt,
  );

  const originalUpdatedDate = new Date(originalUpdatedAt);
  const updatedUpdatedDate = new Date(updatedTodo.updated_at);

  TestValidator.predicate(
    "updated_at should be strictly greater than original updated_at",
    updatedUpdatedDate.getTime() > originalUpdatedDate.getTime(),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate inline lifecycle state transition of a member user's todo from an
 * active state to a completed state.
 *
 * Business context:
 *
 * - Admins can configure system-level settings that may influence todo lifecycle
 *   behavior via /todoApp/adminUser/systemSettings.
 * - Member users own personal todos and can update them via
 *   /todoApp/memberUser/todos/{todoId}.
 * - This test focuses on an allowed inline state transition from an active-like
 *   state to a completed-like state and verifies lifecycle timestamps and
 *   ownership are handled correctly.
 *
 * Steps:
 *
 * 1. Register an admin user and configure a lifecycle-related system setting.
 * 2. Register a member user and authenticate as that member.
 * 3. Create an initial todo in an active state for the member.
 * 4. Update the todo's state to "completed" using the update endpoint.
 * 5. Validate state change, timestamps, and ownership.
 * 6. Optionally, verify that a different member cannot update another user's todo
 *    (authorization enforcement).
 */
export async function test_api_todo_update_state_transition_active_to_completed(
  connection: api.IConnection,
) {
  // 1. Admin setup and system setting configuration
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const adminPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword,
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todo-app.test/join",
    referrer: "https://admin.todo-app.test/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  const settingBody = {
    key: "todo_lifecycle_direct_complete_enabled",
    value: "true",
    type: "boolean",
    description:
      "Flag to enable direct lifecycle completion transitions via update endpoint in tests.",
    group: "lifecycle",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const systemSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: settingBody,
    });
  typia.assert(systemSetting);

  // 2. Member user setup and authentication
  const memberEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const memberPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const memberJoinBody = {
    email: memberEmail,
    password: memberPassword,
    displayName: RandomGenerator.name(),
    ip: "127.0.0.1",
    href: "https://todo-app.test/join",
    referrer: "https://todo-app.test/landing",
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberAuthorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  const memberLoginBody = {
    email: memberEmail,
    password: memberPassword,
    ip: "127.0.0.1",
    href: "https://todo-app.test/login",
    referrer: "https://todo-app.test/landing",
  } satisfies ITodoAppMemberUserLogin.ICreate;

  const memberAuthorizedFromLogin: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberAuthorizedFromLogin);

  // 3. Create an initial active todo for the member
  const createTodoBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
    due_date: null,
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: createTodoBody,
    });
  typia.assert(createdTodo);

  const originalTodoId = createdTodo.id;
  const originalMemberId = createdTodo.memberUser.id;
  const originalState = createdTodo.state;
  const originalUpdatedAt = createdTodo.updated_at;
  const originalCompletedAt = createdTodo.completed_at ?? null;

  TestValidator.equals(
    "initial todo state must be active",
    originalState,
    "active",
  );

  // 4. Update the todo's state to "completed" via update endpoint
  const updateBody = {
    state: "completed",
  } satisfies ITodoAppTodo.IUpdate;

  const updatedTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.update(connection, {
      todoId: originalTodoId,
      body: updateBody,
    });
  typia.assert(updatedTodo);

  // 5. Validate state change, timestamps, and ownership
  TestValidator.equals(
    "todo id is unchanged after update",
    updatedTodo.id,
    originalTodoId,
  );

  TestValidator.equals(
    "todo owner member id is unchanged after update",
    updatedTodo.memberUser.id,
    originalMemberId,
  );

  TestValidator.equals(
    "todo state transitioned to completed",
    updatedTodo.state,
    "completed",
  );

  TestValidator.notEquals(
    "updated_at must change after state update",
    updatedTodo.updated_at,
    originalUpdatedAt,
  );

  TestValidator.predicate(
    "completed_at is populated after completing todo",
    updatedTodo.completed_at !== null && updatedTodo.completed_at !== undefined,
  );

  if (originalCompletedAt !== null) {
    TestValidator.notEquals(
      "completed_at should reflect latest completion time when re-completing",
      updatedTodo.completed_at,
      originalCompletedAt,
    );
  }

  TestValidator.predicate(
    "deleted_at remains null/undefined after completion update",
    updatedTodo.deleted_at === null || updatedTodo.deleted_at === undefined,
  );

  // 6. Optional: verify non-owner cannot update the todo
  const otherMemberEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const otherMemberPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const otherMemberJoinBody = {
    email: otherMemberEmail,
    password: otherMemberPassword,
    displayName: RandomGenerator.name(),
    ip: "127.0.0.2",
    href: "https://todo-app.test/join",
    referrer: "https://todo-app.test/landing",
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const otherMemberAuthorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: otherMemberJoinBody,
    });
  typia.assert(otherMemberAuthorized);

  const otherMemberLoginBody = {
    email: otherMemberEmail,
    password: otherMemberPassword,
    ip: "127.0.0.2",
    href: "https://todo-app.test/login",
    referrer: "https://todo-app.test/landing",
  } satisfies ITodoAppMemberUserLogin.ICreate;

  const otherMemberAuthorizedFromLogin: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: otherMemberLoginBody,
    });
  typia.assert(otherMemberAuthorizedFromLogin);

  const otherUpdateBody = {
    state: "active",
  } satisfies ITodoAppTodo.IUpdate;

  await TestValidator.error(
    "non-owner cannot update another user's todo",
    async () => {
      await api.functional.todoApp.memberUser.todos.update(connection, {
        todoId: originalTodoId,
        body: otherUpdateBody,
      });
    },
  );
}

