import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodo";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate combined text search and due date range filters for member todos
 * listing.
 *
 * Business goal: Ensure that PATCH /todoApp/memberUser/todos correctly applies
 * both a text search (on title) and a due-date range (dueFrom/dueTo)
 * simultaneously, returning only todos that satisfy both filters and belong to
 * the authenticated member.
 *
 * Scenario steps:
 *
 * 1. Admin bootstrap
 *
 *    - Register an adminUser via POST /auth/adminUser/join.
 *    - Create a system setting via POST /todoApp/adminUser/systemSettings to
 *         exercise that dependency (even if not strictly required for
 *         filters).
 * 2. Member bootstrap
 *
 *    - Register a memberUser via POST /auth/memberUser/join; the SDK will set the
 *         Authorization header for subsequent member-scoped calls.
 * 3. Seed todos for the member via POST /todoApp/memberUser/todos:
 *
 *    - Create multiple todos such that: a) Two todos contain the keyword in their
 *         title and have due_date inside a chosen [dueFrom, dueTo] window
 *         ("in-window + keyword"). b) One todo contains the keyword but has
 *         due_date outside the window ("keyword only"). c) One todo has
 *         due_date inside the window but title without the keyword ("window
 *         only"). d) One todo without keyword and outside the window.
 * 4. Invoke PATCH /todoApp/memberUser/todos with ITodoAppTodo.IRequest:
 *
 *    - Page = 0, limit large enough to contain all seeded todos.
 *    - Search = keyword.
 *    - DueFrom/dueTo set to the window that includes only the "in-window + keyword"
 *         todos.
 * 5. Assertions:
 *
 *    - Response passes typia.assert as IPageITodoAppTodo.ISummary.
 *    - Pagination.current and pagination.limit equal the request values.
 *    - Every returned todo summary has title including the keyword and due_date
 *         within [dueFrom, dueTo].
 *    - Todos with keyword-only or window-only or outside-all characteristics are not
 *         included.
 *    - Returned todo IDs are a subset of the IDs we created for this member.
 */
export async function test_api_todo_list_with_text_search_and_date_range_filters(
  connection: api.IConnection,
) {
  // 1. Admin bootstrap: register admin and create a system setting
  const adminEmail: string = typia.random<string & tags.Format<"email">>();

  const adminJoinBody = {
    email: adminEmail,
    password: RandomGenerator.alphabets(12),
    display_name: RandomGenerator.name(2),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todo-app.test/join",
    referrer: "https://admin.todo-app.test/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  const systemSettingBody = {
    key: "todo_search_enabled",
    value: "true",
    type: "boolean",
    description: "Enable text search and due date filters for todo listings",
    group: "features",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const systemSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: systemSettingBody,
    });
  typia.assert(systemSetting);

  // 2. Member bootstrap: register member user (Authorization is set by SDK)
  const memberEmail: string = typia.random<string & tags.Format<"email">>();

  const memberJoinBody = {
    email: memberEmail,
    password: RandomGenerator.alphabets(12),
    displayName: RandomGenerator.name(2),
    ip: "127.0.0.1",
    href: "https://todo-app.test/join",
    referrer: "https://todo-app.test/landing",
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberAuthorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 3. Seed todos for that member
  const now = new Date();
  const dayMs = 24 * 60 * 60 * 1000;

  const windowStart = new Date(now.getTime() + dayMs * 3);
  const windowEnd = new Date(now.getTime() + dayMs * 7);

  const dueInWindow1 = new Date(windowStart.getTime() + dayMs);
  const dueInWindow2 = new Date(windowEnd.getTime() - dayMs);

  const keyword = "project";

  const todoInWindowKeyword1Body = {
    title: `${keyword} alpha task`,
    description: RandomGenerator.paragraph({ sentences: 4 }),
    due_date: dueInWindow1.toISOString(),
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const todoInWindowKeyword2Body = {
    title: `beta ${keyword} follow-up`,
    description: RandomGenerator.paragraph({ sentences: 5 }),
    due_date: dueInWindow2.toISOString(),
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const todoKeywordOutsideWindowBody = {
    title: `${keyword} far future`,
    description: RandomGenerator.paragraph({ sentences: 3 }),
    due_date: new Date(now.getTime() + dayMs * 30).toISOString(),
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const todoWindowOnlyBody = {
    title: "miscellaneous chores", // no keyword
    description: RandomGenerator.paragraph({ sentences: 2 }),
    due_date: new Date(windowStart.getTime() + dayMs / 2).toISOString(),
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const todoOutsideAllBody = {
    title: "unrelated note", // no keyword
    description: RandomGenerator.paragraph({ sentences: 2 }),
    due_date: new Date(now.getTime() + dayMs * 20).toISOString(),
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const createdTodos: ITodoAppTodo[] = [];

  const createdInWindowKeyword1: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoInWindowKeyword1Body,
    });
  typia.assert(createdInWindowKeyword1);
  createdTodos.push(createdInWindowKeyword1);

  const createdInWindowKeyword2: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoInWindowKeyword2Body,
    });
  typia.assert(createdInWindowKeyword2);
  createdTodos.push(createdInWindowKeyword2);

  const createdKeywordOutside: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoKeywordOutsideWindowBody,
    });
  typia.assert(createdKeywordOutside);
  createdTodos.push(createdKeywordOutside);

  const createdWindowOnly: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoWindowOnlyBody,
    });
  typia.assert(createdWindowOnly);
  createdTodos.push(createdWindowOnly);

  const createdOutsideAll: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoOutsideAllBody,
    });
  typia.assert(createdOutsideAll);
  createdTodos.push(createdOutsideAll);

  const createdTodoIds = createdTodos.map((t) => t.id);

  // Build search window and request
  const dueFrom = windowStart.toISOString();
  const dueTo = windowEnd.toISOString();

  const requestBody = {
    page: 0,
    limit: 20,
    search: keyword,
    state: null,
    createdFrom: null,
    createdTo: null,
    dueFrom,
    dueTo,
    completed: null,
  } satisfies ITodoAppTodo.IRequest;

  const page: IPageITodoAppTodo.ISummary =
    await api.functional.todoApp.memberUser.todos.index(connection, {
      body: requestBody,
    });
  typia.assert(page);

  const pagination = page.pagination;
  const summaries = page.data;

  // Basic pagination coherence checks
  TestValidator.equals(
    "pagination current page should match request",
    pagination.current,
    requestBody.page,
  );
  TestValidator.equals(
    "pagination limit should match request",
    pagination.limit,
    requestBody.limit,
  );

  // All returned todos must match keyword AND due-date window and belong to this member
  await TestValidator.predicate(
    "all returned todos must contain keyword in title and have due_date within window",
    async () => {
      for (const summary of summaries) {
        const titleHasKeyword = summary.title.toLowerCase().includes(keyword);
        if (!titleHasKeyword) return false;

        if (summary.due_date === null || summary.due_date === undefined) {
          return false;
        }
        const dueTs = new Date(summary.due_date).getTime();
        const fromTs = new Date(dueFrom).getTime();
        const toTs = new Date(dueTo).getTime();
        if (dueTs < fromTs || dueTs > toTs) return false;

        if (!createdTodoIds.includes(summary.id)) return false;
      }
      return true;
    },
  );

  // Expect the two in-window+keyword todos to be present
  const expectedIds = [createdInWindowKeyword1.id, createdInWindowKeyword2.id];

  const returnedIds = summaries.map((s) => s.id);

  for (const expectedId of expectedIds) {
    TestValidator.predicate(
      `expected todo ${expectedId} should be included in results`,
      returnedIds.includes(expectedId),
    );
  }

  // Todos that do not satisfy both filters must be excluded
  const excludedCandidates = [
    createdKeywordOutside.id,
    createdWindowOnly.id,
    createdOutsideAll.id,
  ];

  for (const excludedId of excludedCandidates) {
    TestValidator.predicate(
      `todo ${excludedId} should be excluded by filters`,
      !returnedIds.includes(excludedId),
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodo";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

export async function test_api_todo_list_pagination_across_multiple_pages(
  connection: api.IConnection,
) {
  // 1. Admin registration and implicit authentication
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: "Admin1234!" as string & tags.Format<"password">,
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todoapp.test/join",
    referrer: "https://admin.todoapp.test/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Create a harmless system setting that could conceptually influence limits
  const systemSettingBody = {
    key: `pagination_test_max_page_size_${RandomGenerator.alphaNumeric(8)}`,
    value: "50",
    type: "int",
    description: "Max page size for pagination E2E test (non-enforced demo)",
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const systemSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: systemSettingBody,
    });
  typia.assert(systemSetting);

  // 3. Member user registration (auto-auth via join)
  const memberEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const memberJoinBody = {
    email: memberEmail,
    password: "Member1234!" as string & tags.Format<"password">,
    displayName: RandomGenerator.name(),
    ip: "127.0.0.1" as string & (tags.Format<"ipv4"> | tags.Format<"ipv6">),
    href: "https://todoapp.test/join",
    referrer: "https://todoapp.test/landing",
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberAuthorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 4. Create more todos than a single page can contain
  const pageLimit = 10;
  const createCount = 25;

  const createdTodoIds: string[] = [];

  for (let i = 0; i < createCount; i++) {
    const createBody = {
      title: `pagination-test-${i}-${RandomGenerator.paragraph({
        sentences: 1,
      })}`,
      description: RandomGenerator.paragraph({ sentences: 2 }),
      due_date: null,
      state: "active",
    } satisfies ITodoAppTodo.ICreate;

    const todo: ITodoAppTodo =
      await api.functional.todoApp.memberUser.todos.create(connection, {
        body: createBody,
      });
    typia.assert(todo);
    createdTodoIds.push(todo.id);
  }

  // Helper to fetch a page
  const fetchPage = async (
    page: number & tags.Type<"int32">,
  ): Promise<IPageITodoAppTodo.ISummary> => {
    const body = {
      page,
      limit: pageLimit as number & tags.Type<"int32">,
      search: null,
      state: null,
      createdFrom: null,
      createdTo: null,
      dueFrom: null,
      dueTo: null,
      completed: null,
    } satisfies ITodoAppTodo.IRequest;

    const pageResult: IPageITodoAppTodo.ISummary =
      await api.functional.todoApp.memberUser.todos.index(connection, {
        body,
      });
    typia.assert(pageResult);
    return pageResult;
  };

  // 5. Page 0
  const page0 = await fetchPage(0 as number & tags.Type<"int32">);
  const pagination0 = page0.pagination;

  TestValidator.equals("page 0: current page index", pagination0.current, 0);
  TestValidator.equals("page 0: limit", pagination0.limit, pageLimit);
  TestValidator.predicate(
    "page 0: records should be at least created count",
    pagination0.records >= createCount,
  );
  TestValidator.predicate(
    "page 0: pages should be positive",
    pagination0.pages > 0,
  );
  TestValidator.equals(
    "page 0: data length should not exceed limit",
    page0.data.length,
    Math.min(pageLimit, pagination0.records),
  );

  const page0Ids = page0.data.map((todo) => todo.id);

  // 6. Page 1
  const page1 = await fetchPage(1 as number & tags.Type<"int32">);
  const pagination1 = page1.pagination;

  TestValidator.equals("page 1: current page index", pagination1.current, 1);
  TestValidator.equals("page 1: limit", pagination1.limit, pageLimit);
  TestValidator.predicate(
    "page 1: records should be consistent with page 0",
    pagination1.records === pagination0.records,
  );
  TestValidator.predicate(
    "page 1: pages should be consistent with page 0",
    pagination1.pages === pagination0.pages,
  );
  TestValidator.equals(
    "page 1: data length should not exceed limit",
    page1.data.length,
    Math.min(pageLimit, pagination1.records - pageLimit),
  );

  const page1Ids = page1.data.map((todo) => todo.id);

  // Non-overlap between page 0 and 1
  const overlap01 = page0Ids.filter((id) => page1Ids.includes(id));
  TestValidator.equals(
    "page 0 and 1: no overlapping todo IDs",
    overlap01.length,
    0,
  );

  // 7. Page 2
  const page2 = await fetchPage(2 as number & tags.Type<"int32">);
  const pagination2 = page2.pagination;

  TestValidator.equals("page 2: current page index", pagination2.current, 2);
  TestValidator.equals("page 2: limit", pagination2.limit, pageLimit);
  TestValidator.predicate(
    "page 2: records consistent across pages",
    pagination2.records === pagination0.records,
  );
  TestValidator.predicate(
    "page 2: pages consistent across pages",
    pagination2.pages === pagination0.pages,
  );

  const page2Ids = page2.data.map((todo) => todo.id);

  // Ensure no overlap across pages 0, 1, 2
  const overlap02 = page0Ids.filter((id) => page2Ids.includes(id));
  const overlap12 = page1Ids.filter((id) => page2Ids.includes(id));

  TestValidator.equals(
    "page 0 and 2: no overlapping todo IDs",
    overlap02.length,
    0,
  );
  TestValidator.equals(
    "page 1 and 2: no overlapping todo IDs",
    overlap12.length,
    0,
  );

  // 8. Request a page index beyond the last page and verify behavior
  const lastPageIndex = pagination0.pages;

  const beyondPage = await fetchPage(
    lastPageIndex as number & tags.Type<"int32">,
  );
  const beyondPagination = beyondPage.pagination;

  TestValidator.equals(
    "beyond last: current page index should match requested index",
    beyondPagination.current,
    lastPageIndex,
  );
  TestValidator.equals(
    "beyond last: limit should match page limit",
    beyondPagination.limit,
    pageLimit,
  );
  TestValidator.equals(
    "beyond last: pages should remain consistent",
    beyondPagination.pages,
    pagination0.pages,
  );
  TestValidator.equals(
    "beyond last: records should remain consistent",
    beyondPagination.records,
    pagination0.records,
  );
  TestValidator.equals(
    "beyond last: data array should be empty or very small if pages just increased",
    beyondPage.data.length,
    0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate that a member user can retrieve full details of their own todo.
 *
 * Business flow:
 *
 * 1. Bootstrap admin context and create at least one system setting so that todo
 *    operations run under an initialized configuration.
 * 2. Register a member user (memberUser join) and obtain an authorized
 *    ITodoAppMemberUser.IAuthorized context.
 * 3. As this member, create a new todo via POST /todoApp/memberUser/todos using
 *    ITodoAppTodo.ICreate.
 * 4. Immediately fetch the same todo via GET /todoApp/memberUser/todos/{todoId}.
 * 5. Assert that all key fields (id, owner/memberUser, title, description, state,
 *    timestamps, due_date, completion and deletion markers) in the fetched todo
 *    match the originally created record.
 * 6. Confirm that the memberUser sub-object on the todo corresponds to the
 *    authenticated member (id and email) and that no cross-user data leak
 *    occurs.
 */
export async function test_api_todo_detail_retrieval_for_own_todo(
  connection: api.IConnection,
) {
  // 1. Admin bootstrap: join admin and create a system setting.
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12) as string &
      tags.Format<"password">,
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todo-app.local/join",
    referrer: "https://admin.todo-app.local/",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  const systemSettingBody = {
    key: "max_active_todos_per_user",
    value: "100",
    type: "int",
    description:
      "Maximum number of active todos allowed per member user in tests",
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const systemSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: systemSettingBody,
    });
  typia.assert(systemSetting);

  TestValidator.equals(
    "system setting key must match creation payload",
    systemSetting.key,
    systemSettingBody.key,
  );

  // 2. Member registration (join) to get authorized member context.
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12) as string &
      tags.Format<"password">,
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.local/signup",
    referrer: "https://todo-app.local/landing",
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberAuthorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  TestValidator.equals(
    "member authorized email must match join email",
    memberAuthorized.email,
    memberJoinBody.email,
  );

  // 3. Create a todo as the authenticated member.
  const now = new Date();
  const dueDate = new Date(now.getTime() + 24 * 60 * 60 * 1000).toISOString();

  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
    due_date: dueDate,
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(createdTodo);

  TestValidator.equals(
    "created todo title must match request payload",
    createdTodo.title,
    todoCreateBody.title,
  );
  TestValidator.equals(
    "created todo description must match request payload",
    createdTodo.description,
    todoCreateBody.description,
  );
  TestValidator.equals(
    "created todo state must match request payload",
    createdTodo.state,
    todoCreateBody.state,
  );
  TestValidator.equals(
    "created todo due_date must match request payload",
    createdTodo.due_date,
    todoCreateBody.due_date,
  );

  TestValidator.equals(
    "created todo owner id must equal authorized member id",
    createdTodo.memberUser.id,
    memberAuthorized.id,
  );
  TestValidator.equals(
    "created todo owner email must equal authorized member email",
    createdTodo.memberUser.email,
    memberAuthorized.email,
  );

  TestValidator.predicate(
    "created todo should not be soft-deleted initially",
    createdTodo.deleted_at === null || createdTodo.deleted_at === undefined,
  );

  // 4. Retrieve todo details by id as the same member.
  const fetchedTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.at(connection, {
      todoId: createdTodo.id,
    });
  typia.assert(fetchedTodo);

  // 5. Assertions: identity, ownership, field consistency.
  TestValidator.equals(
    "todo id must match between creation and retrieval",
    fetchedTodo.id,
    createdTodo.id,
  );

  TestValidator.equals(
    "fetched todo owner id must equal authorized member id",
    fetchedTodo.memberUser.id,
    memberAuthorized.id,
  );
  TestValidator.equals(
    "fetched todo owner email must equal authorized member email",
    fetchedTodo.memberUser.email,
    memberAuthorized.email,
  );

  TestValidator.equals(
    "todo title must remain unchanged between creation and retrieval",
    fetchedTodo.title,
    createdTodo.title,
  );
  TestValidator.equals(
    "todo description must remain unchanged between creation and retrieval",
    fetchedTodo.description,
    createdTodo.description,
  );
  TestValidator.equals(
    "todo state must remain unchanged between creation and retrieval",
    fetchedTodo.state,
    createdTodo.state,
  );

  TestValidator.equals(
    "due_date must remain unchanged between creation and retrieval",
    fetchedTodo.due_date,
    createdTodo.due_date,
  );
  TestValidator.equals(
    "created_at must remain consistent between creation and retrieval",
    fetchedTodo.created_at,
    createdTodo.created_at,
  );
  TestValidator.equals(
    "updated_at must remain consistent between creation and retrieval",
    fetchedTodo.updated_at,
    createdTodo.updated_at,
  );
  TestValidator.equals(
    "completed_at must remain consistent between creation and retrieval",
    fetchedTodo.completed_at,
    createdTodo.completed_at,
  );
  TestValidator.equals(
    "deleted_at must remain consistent between creation and retrieval",
    fetchedTodo.deleted_at,
    createdTodo.deleted_at,
  );

  TestValidator.predicate(
    "fetched todo should not be soft-deleted",
    fetchedTodo.deleted_at === null || fetchedTodo.deleted_at === undefined,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate ownership-based access control for todo detail retrieval.
 *
 * Business objectives:
 *
 * - A member user must not be able to retrieve another member user’s todo details
 *   via GET /todoApp/memberUser/todos/{todoId}, even when guessing a valid
 *   todoId.
 * - A member user must still be able to retrieve their own todo details
 *   successfully.
 *
 * High-level steps
 *
 * 1. Admin bootstrap and system settings creation (admin-only context).
 * 2. Member A: join and create a todo (todoA).
 * 3. Member B: join (switch authentication context).
 * 4. Negative case: Member B tries to GET Member A’s todoA by id and must fail
 *    without leaking ITodoAppTodo data.
 * 5. Control case: Member B creates their own todoB and successfully retrieves it
 *    by id.
 */
export async function test_api_todo_detail_ownership_enforcement(
  connection: api.IConnection,
) {
  // 1. Admin bootstrap and system setting creation
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todoapp.local/join",
    referrer: "https://admin.todoapp.local/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  const systemSettingBody = {
    key: "todo.max_active_per_user",
    value: "100",
    type: "int",
    description: "Maximum number of active todos per member user for tests.",
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const systemSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: systemSettingBody,
    });
  typia.assert(systemSetting);

  // 2. Member A: join and create a todo
  const memberAEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const memberAJoinBody = {
    email: memberAEmail,
    password: typia.random<string & tags.Format<"password">>(),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://app.todoapp.local/signup",
    referrer: "https://app.todoapp.local/landing",
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberAAuth: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberAJoinBody,
    });
  typia.assert(memberAAuth);

  const todoABody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
    due_date: RandomGenerator.date(
      new Date(),
      7 * 24 * 60 * 60 * 1000,
    ).toISOString(),
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const todoA: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoABody,
    });
  typia.assert(todoA);

  TestValidator.equals(
    "created todoA should belong to member A",
    todoA.memberUser.id,
    memberAAuth.id,
  );

  const todoId_A: string & tags.Format<"uuid"> = todoA.id;

  // 3. Member B: join (switches authentication context)
  const memberBEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const memberBJoinBody = {
    email: memberBEmail,
    password: typia.random<string & tags.Format<"password">>(),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://app.todoapp.local/signup",
    referrer: "https://app.todoapp.local/landing",
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberBAuth: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberBJoinBody,
    });
  typia.assert(memberBAuth);

  // 4. Negative case: Member B attempts to read Member A's todo
  await TestValidator.error(
    "member B cannot retrieve member A's todo details",
    async () => {
      await api.functional.todoApp.memberUser.todos.at(connection, {
        todoId: todoId_A,
      });
    },
  );

  // 5. Control case: Member B creates and retrieves their own todo
  const todoBBody = {
    title: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    due_date: null,
    state: "active",
  } satisfies ITodoAppTodo.ICreate;

  const todoB: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoBBody,
    });
  typia.assert(todoB);

  TestValidator.equals(
    "created todoB should belong to member B",
    todoB.memberUser.id,
    memberBAuth.id,
  );

  const todoId_B: string & tags.Format<"uuid"> = todoB.id;

  const todoBDetail: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.at(connection, {
      todoId: todoId_B,
    });
  typia.assert(todoBDetail);

  TestValidator.equals(
    "member B can retrieve their own todo by id",
    todoBDetail.id,
    todoId_B,
  );
  TestValidator.equals(
    "todoB detail should belong to member B",
    todoBDetail.memberUser.id,
    memberBAuth.id,
  );
  TestValidator.equals(
    "todoB detail title should match creation",
    todoBDetail.title,
    todoBBody.title,
  );
  TestValidator.equals(
    "todoB detail state should match creation",
    todoBDetail.state,
    todoBBody.state,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Ensure todo detail reflects latest updated state for a member user's todo.
 *
 * Business context:
 *
 * - Admin users can configure system-level settings for the todo application.
 * - Member users own personal todos; they can create and update them.
 * - The detail endpoint should always reflect the most recently persisted state
 *   of a todo right after an update.
 *
 * Steps:
 *
 * 1. Admin joins (self-register) and becomes authenticated adminUser.
 * 2. Admin creates a system setting to simulate required configuration.
 * 3. Member joins (self-register) and becomes authenticated memberUser.
 * 4. Member creates an initial todo.
 * 5. Member updates multiple fields of that todo (title, description, state,
 *    due_date).
 * 6. Immediately fetch the todo detail by id.
 * 7. Assert that detail response matches the updated state from the update
 *    response, and that identity/ownership and created_at remain stable, with
 *    consistent lifecycle fields (completed_at, deleted_at).
 */
export async function test_api_todo_detail_consistency_after_update(
  connection: api.IConnection,
) {
  // 1. Admin joins and becomes authenticated
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12) as string &
      tags.Format<"password">,
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todo-app.test/join",
    referrer: "https://admin.todo-app.test/landing",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminAuthorized);

  // 2. Admin creates a system setting (dummy but realistic)
  const systemSettingBody = {
    key: "max_active_todos_per_user",
    value: "100",
    type: "int",
    description:
      "Maximum number of active todos a single member can have before creation is blocked.",
    group: "limits",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const systemSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: systemSettingBody,
    });
  typia.assert<ITodoAppSystemSetting>(systemSetting);

  // 3. Member joins and becomes authenticated
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12) as string &
      tags.Format<"password">,
    displayName: RandomGenerator.name(),
    ip: "127.0.0.1",
    href: "https://member.todo-app.test/join",
    referrer: "https://member.todo-app.test/landing",
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberAuthorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert<ITodoAppMemberUser.IAuthorized>(memberAuthorized);

  // 4. Member creates an initial todo
  const initialTodoBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
    state: "active",
    due_date: RandomGenerator.date(
      new Date(),
      1000 * 60 * 60 * 24 * 7,
    ).toISOString(),
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: initialTodoBody,
    });
  typia.assert<ITodoAppTodo>(createdTodo);

  // Snapshot immutable identity fields and initial timestamps
  const createdTodoId = createdTodo.id;
  const createdOwner = createdTodo.memberUser;
  const createdAt = createdTodo.created_at;

  // 5. Member updates multiple fields on that todo
  const updatedTitle = RandomGenerator.paragraph({ sentences: 2 });
  const updatedDescription = RandomGenerator.paragraph({ sentences: 4 });
  const updatedState = "completed";
  const updatedDueDate = RandomGenerator.date(
    new Date(),
    1000 * 60 * 60 * 24 * 14,
  ).toISOString();

  const updateBody = {
    title: updatedTitle,
    description: updatedDescription,
    state: updatedState,
    due_date: updatedDueDate,
  } satisfies ITodoAppTodo.IUpdate;

  const updatedTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.update(connection, {
      todoId: createdTodoId as string & tags.Format<"uuid">,
      body: updateBody,
    });
  typia.assert<ITodoAppTodo>(updatedTodo);

  // 6. Immediately fetch todo detail by id
  const detailedTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.at(connection, {
      todoId: createdTodoId,
    });
  typia.assert<ITodoAppTodo>(detailedTodo);

  // 7. Assertions: identity and ownership stability
  TestValidator.equals(
    "todo id remains stable across create, update, and detail",
    updatedTodo.id,
    createdTodoId,
  );
  TestValidator.equals(
    "detail id equals updated todo id",
    detailedTodo.id,
    updatedTodo.id,
  );

  TestValidator.equals(
    "member ownership remains same between create and update",
    updatedTodo.memberUser.id,
    createdOwner.id,
  );
  TestValidator.equals(
    "member ownership remains same between update and detail",
    detailedTodo.memberUser.id,
    updatedTodo.memberUser.id,
  );

  // created_at should never change
  TestValidator.equals(
    "created_at timestamp remains unchanged after update",
    updatedTodo.created_at,
    createdAt,
  );
  TestValidator.equals(
    "detail created_at matches original creation time",
    detailedTodo.created_at,
    createdAt,
  );

  // updated_at should change from initial, and detail should match update's updated_at
  TestValidator.predicate("updated_at changes after update", () => {
    return createdTodo.updated_at !== updatedTodo.updated_at;
  });

  TestValidator.equals(
    "detail updated_at matches updated todo updated_at",
    detailedTodo.updated_at,
    updatedTodo.updated_at,
  );

  // Updated fields consistency
  TestValidator.equals(
    "updated title is reflected in detail endpoint",
    detailedTodo.title,
    updatedTitle,
  );
  TestValidator.equals(
    "updated description is reflected in detail endpoint",
    detailedTodo.description,
    updatedDescription,
  );
  TestValidator.equals(
    "updated state is reflected in detail endpoint",
    detailedTodo.state,
    updatedState,
  );
  TestValidator.equals(
    "updated due_date is reflected in detail endpoint",
    detailedTodo.due_date,
    updatedDueDate,
  );

  // Lifecycle fields consistency: completed_at & deleted_at
  TestValidator.equals(
    "completed_at is consistent between updated and detail todo",
    detailedTodo.completed_at,
    updatedTodo.completed_at,
  );
  TestValidator.equals(
    "deleted_at is consistent between updated and detail todo",
    detailedTodo.deleted_at,
    updatedTodo.deleted_at,
  );

  // Also the full objects except possibly for nested memberUser equality
  TestValidator.equals(
    "detail todo matches updated todo for core scalar fields",
    {
      id: detailedTodo.id,
      title: detailedTodo.title,
      description: detailedTodo.description,
      state: detailedTodo.state,
      due_date: detailedTodo.due_date,
      created_at: detailedTodo.created_at,
      updated_at: detailedTodo.updated_at,
      completed_at: detailedTodo.completed_at,
      deleted_at: detailedTodo.deleted_at,
    },
    {
      id: updatedTodo.id,
      title: updatedTodo.title,
      description: updatedTodo.description,
      state: updatedTodo.state,
      due_date: updatedTodo.due_date,
      created_at: updatedTodo.created_at,
      updated_at: updatedTodo.updated_at,
      completed_at: updatedTodo.completed_at,
      deleted_at: updatedTodo.deleted_at,
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate that a member user's todo detail endpoint reflects lifecycle
 * transitions when a todo is completed and then reopened.
 *
 * Business goal:
 *
 * - Ensure that when a member completes a todo and later reopens it, the GET
 *   /todoApp/memberUser/todos/{todoId} endpoint always returns a representation
 *   consistent with the last lifecycle mutation.
 * - Verify that completion sets a completed state and completion timestamp, and
 *   that reopening moves the todo back to an active state while keeping a
 *   consistent view between mutation responses and subsequent detail fetches.
 *
 * High level steps:
 *
 * 1. Admin bootstrap & configuration
 *
 *    - Join as an admin user.
 *    - Create a simple system setting related to todos, to exercise
 *         /todoApp/adminUser/systemSettings. The specific key/value is
 *         arbitrary because behavior is not further specified; we only need the
 *         call to succeed.
 * 2. Member registration & authentication
 *
 *    - Join as a member user via /auth/memberUser/join. The SDK will automatically
 *         attach the access token to the connection.
 * 3. Todo creation as member user
 *
 *    - Call POST /todoApp/memberUser/todos with ITodoAppTodo.ICreate, using a
 *         realistic title and description and an initial state such as
 *         "active".
 *    - Capture the returned ITodoAppTodo and its id as the baseline active
 *         representation.
 * 4. Completion lifecycle transition
 *
 *    - Call PUT /todoApp/memberUser/todos/{todoId}/complete and capture the returned
 *         ITodoAppTodo (completedTodo).
 *    - Assert via typia.assert that the structure matches ITodoAppTodo.
 *    - Assert business expectations: state has changed from its initial value (e.g.,
 *         to something different) and completed_at is non-null.
 * 5. Detail verification after completion
 *
 *    - Call GET /todoApp/memberUser/todos/{todoId} (detailAfterComplete).
 *    - Use typia.assert on the response.
 *    - Use TestValidator.equals to assert that key lifecycle fields (state,
 *         completed_at, and content fields) are identical between completedTodo
 *         and detailAfterComplete, proving that the detail view mirrors the
 *         latest lifecycle mutation.
 * 6. Reopen lifecycle transition
 *
 *    - Call PUT /todoApp/memberUser/todos/{todoId}/reopen and capture the returned
 *         ITodoAppTodo (reopenedTodo).
 *    - Assert via typia.assert.
 *    - Assert business expectations: state differs from the completed state and
 *         updated_at is not older than the completed entity.
 * 7. Detail verification after reopen
 *
 *    - Call GET /todoApp/memberUser/todos/{todoId} again (detailAfterReopen).
 *    - Assert via typia.assert.
 *    - Use TestValidator.equals to verify that state, completed_at, and other stable
 *         fields match between reopenedTodo and detailAfterReopen, ensuring
 *         that the detail endpoint reflects the reopened state.
 */
export async function test_api_todo_detail_reflects_completion_and_reopen_lifecycle(
  connection: api.IConnection,
) {
  // 1. Admin bootstrap & configuration
  const adminJoinBody = {
    email: `admin+${RandomGenerator.alphaNumeric(8)}@example.com`,
    password: "Admin#1234",
    display_name: RandomGenerator.name(),
    status: "active",
    ip: "127.0.0.1",
    href: "https://admin.todo-app.example.com/join",
    referrer: "https://admin.todo-app.example.com/",
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminAuthorized);

  // Create a simple system setting to exercise the admin systemSettings API.
  const systemSettingCreateBody = {
    key: `todo_lifecycle_behavior_${RandomGenerator.alphaNumeric(6)}`,
    value: "default",
    type: "string",
    description: "E2E test setting for todo lifecycle behavior",
    group: "e2e",
    enabled: true,
  } satisfies ITodoAppSystemSetting.ICreate;

  const createdSetting: ITodoAppSystemSetting =
    await api.functional.todoApp.adminUser.systemSettings.create(connection, {
      body: systemSettingCreateBody,
    });
  typia.assert<ITodoAppSystemSetting>(createdSetting);

  // 2. Member registration & authentication
  const memberJoinBody = {
    email: `member+${RandomGenerator.alphaNumeric(8)}@example.com`,
    password: "Member#1234",
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.example.com/join",
    referrer: "https://todo-app.example.com/",
  } satisfies ITodoAppMemberUserJoin.ICreate;

  const memberAuthorized: ITodoAppMemberUser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert<ITodoAppMemberUser.IAuthorized>(memberAuthorized);

  // 3. Todo creation as member user
  const initialState = "active";
  const createTodoBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
    due_date: null,
    state: initialState,
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: createTodoBody,
    });
  typia.assert<ITodoAppTodo>(createdTodo);

  // 4. Completion lifecycle transition
  const completedTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.complete(connection, {
      todoId: createdTodo.id,
    });
  typia.assert<ITodoAppTodo>(completedTodo);

  // Basic business assertions after completion
  TestValidator.notEquals(
    "todo state should change after completion",
    completedTodo.state,
    createdTodo.state,
  );
  TestValidator.predicate(
    "completed_at should be non-null after completion",
    completedTodo.completed_at !== null &&
      completedTodo.completed_at !== undefined,
  );

  // 5. Detail verification after completion
  const detailAfterComplete: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.at(connection, {
      todoId: createdTodo.id,
    });
  typia.assert<ITodoAppTodo>(detailAfterComplete);

  TestValidator.equals(
    "detail state matches completed state",
    detailAfterComplete.state,
    completedTodo.state,
  );
  TestValidator.equals(
    "detail completed_at matches completed response",
    detailAfterComplete.completed_at,
    completedTodo.completed_at ?? null,
  );
  TestValidator.equals(
    "detail title remains unchanged after completion",
    detailAfterComplete.title,
    createdTodo.title,
  );
  TestValidator.equals(
    "detail description remains unchanged after completion",
    detailAfterComplete.description ?? null,
    createdTodo.description ?? null,
  );

  // 6. Reopen lifecycle transition
  const reopenedTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.reopen(connection, {
      todoId: createdTodo.id,
    });
  typia.assert<ITodoAppTodo>(reopenedTodo);

  TestValidator.notEquals(
    "todo state should change after reopen compared to completed",
    reopenedTodo.state,
    completedTodo.state,
  );
  TestValidator.predicate(
    "updated_at after reopen must be >= updated_at after completion",
    reopenedTodo.updated_at >= completedTodo.updated_at,
  );

  // 7. Detail verification after reopen
  const detailAfterReopen: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.at(connection, {
      todoId: createdTodo.id,
    });
  typia.assert<ITodoAppTodo>(detailAfterReopen);

  TestValidator.equals(
    "detail state matches reopened state",
    detailAfterReopen.state,
    reopenedTodo.state,
  );
  TestValidator.equals(
    "detail completed_at after reopen matches reopened entity",
    detailAfterReopen.completed_at ?? null,
    reopenedTodo.completed_at ?? null,
  );
  TestValidator.equals(
    "detail title remains consistent after reopen",
    detailAfterReopen.title,
    reopenedTodo.title,
  );
  TestValidator.equals(
    "detail description remains consistent after reopen",
    detailAfterReopen.description ?? null,
    reopenedTodo.description ?? null,
  );
}

