import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import { AdminuserPayload } from "../decorators/payload/AdminuserPayload";

export async function getTodoAppAdminUserMemberUsersMemberUserId(props: {
  adminUser: AdminuserPayload;
  memberUserId: string;
}): Promise<ITodoAppMemberUser> {
  // Fetch the member user record from Prisma using the provided identifier.
  // Authorization for adminUser is handled by surrounding decorators/middleware.

  let memberUserRecord: {
    id: string;
    email: string;
    password_hash: string;
    display_name: string | null;
    status: string;
    created_at: unknown;
    updated_at: unknown;
  } | null = null;

  try {
    memberUserRecord = await MyGlobal.prisma.todo_app_memberusers.findUnique({
      where: {
        id: props.memberUserId,
      },
    });
  } catch (error) {
    // If Prisma throws due to an invalid identifier format or other query issue,
    // surface this as a 400 Bad Request consistent with the spec's guidance
    // about distinguishing malformed identifiers.
    throw new HttpException("Invalid memberUserId format", 400);
  }

  if (memberUserRecord === null) {
    throw new HttpException("Member user not found", 404);
  }

  const displayNameValue: string | null | undefined =
    memberUserRecord.display_name === null
      ? null
      : memberUserRecord.display_name;

  const createdAtValue = toISOStringSafe(
    memberUserRecord.created_at as string & tags.Format<"date-time">,
  );
  const updatedAtValue = toISOStringSafe(
    memberUserRecord.updated_at as string & tags.Format<"date-time">,
  );

  const result: ITodoAppMemberUser = {
    id: memberUserRecord.id,
    email: memberUserRecord.email,
    display_name: displayNameValue,
    status: memberUserRecord.status,
    created_at: createdAtValue,
    updated_at: updatedAtValue,
  };

  return result;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import { IPageITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppAdminUser";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminuserPayload } from "../decorators/payload/AdminuserPayload";

export async function patchTodoAppAdminUserAdminUsers(props: {
  adminUser: AdminuserPayload;
  body: ITodoAppAdminUser.IRequest;
}): Promise<IPageITodoAppAdminUser.ISummary> {
  const body = props.body;

  const rawPage = body.page !== undefined ? body.page : 1;
  const rawLimit = body.limit !== undefined ? body.limit : 20;

  const page = rawPage < 1 ? 1 : rawPage;
  const limit = rawLimit < 1 ? 20 : rawLimit > 100 ? 100 : rawLimit;

  const skip = (page - 1) * limit;

  const whereCreatedAt = ((): { gte?: string; lte?: string } | undefined => {
    const hasFrom = body.createdFrom !== undefined;
    const hasTo = body.createdTo !== undefined;

    if (!hasFrom && !hasTo) return undefined;

    const range: { gte?: string; lte?: string } = {};

    if (hasFrom) {
      range.gte = body.createdFrom!;
    }

    if (hasTo) {
      range.lte = body.createdTo!;
    }

    return range;
  })();

  const where = {
    ...(body.email !== undefined &&
      body.email !== "" && {
        email: {
          contains: body.email,
          mode: "insensitive" as const,
        },
      }),
    ...(body.status !== undefined &&
      body.status !== "" && {
        status: body.status,
      }),
    ...(whereCreatedAt !== undefined && {
      created_at: whereCreatedAt,
    }),
  };

  const orderByDirection = body.orderByCreatedAt === "asc" ? "asc" : "desc";

  const [rows, total] = await Promise.all([
    MyGlobal.prisma.todo_app_adminusers.findMany({
      where,
      orderBy: {
        created_at: orderByDirection,
      },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.todo_app_adminusers.count({
      where,
    }),
  ]);

  const data: ITodoAppAdminUser.ISummary[] = rows.map((row) => {
    return {
      id: row.id,
      email: row.email,
      display_name: row.display_name,
      status: row.status,
      created_at: toISOStringSafe(row.created_at),
      updated_at: toISOStringSafe(row.updated_at),
    };
  });

  const pages = limit === 0 ? 0 : Math.ceil(total / limit);

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages,
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSession";
import { IPageITodoAppSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppSession";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { MemberuserPayload } from "../decorators/payload/MemberuserPayload";

export async function patchTodoAppMemberUserActorsCurrentSessions(props: {
  memberUser: MemberuserPayload;
  body: ITodoAppSession.IRequest;
}): Promise<IPageITodoAppSession.ISummary> {
  const memberUserId = props.memberUser.id;
  const page = props.body.page;
  const limit = props.body.limit;

  const skip = page * limit;
  const take = limit;

  const where = (() => {
    const base: Prisma.todo_app_memberuser_sessionsWhereInput = {
      todo_app_memberuser_id: memberUserId,
    };

    if (props.body.ip !== undefined && props.body.ip !== null) {
      base.ip = props.body.ip;
    }

    if (
      (props.body.createdFrom !== undefined &&
        props.body.createdFrom !== null) ||
      (props.body.createdTo !== undefined && props.body.createdTo !== null)
    ) {
      base.created_at = {};
      if (
        props.body.createdFrom !== undefined &&
        props.body.createdFrom !== null
      ) {
        base.created_at.gte = props.body.createdFrom;
      }
      if (props.body.createdTo !== undefined && props.body.createdTo !== null) {
        base.created_at.lte = props.body.createdTo;
      }
    }

    const hasExpiredRangeFilter =
      (props.body.expiredFrom !== undefined &&
        props.body.expiredFrom !== null) ||
      (props.body.expiredTo !== undefined && props.body.expiredTo !== null);

    if (hasExpiredRangeFilter) {
      base.expired_at = {};
      if (
        props.body.expiredFrom !== undefined &&
        props.body.expiredFrom !== null
      ) {
        base.expired_at.gte = props.body.expiredFrom;
      }
      if (props.body.expiredTo !== undefined && props.body.expiredTo !== null) {
        base.expired_at.lte = props.body.expiredTo;
      }
    } else if (props.body.activeOnly === true) {
      // Active sessions: interpret as expired_at is null when no explicit expired range is given.
      base.expired_at = null;
    }

    return base;
  })();

  const [sessions, total] = await Promise.all([
    MyGlobal.prisma.todo_app_memberuser_sessions.findMany({
      where,
      skip,
      take,
      orderBy: { created_at: "desc" },
    }),
    MyGlobal.prisma.todo_app_memberuser_sessions.count({
      where,
    }),
  ]);

  const data: ITodoAppSession.ISummary[] = sessions.map((session) => {
    const createdAt = toISOStringSafe(session.created_at);
    const expiredAt =
      session.expired_at !== null ? toISOStringSafe(session.expired_at) : null;

    const summary: ITodoAppSession.ISummary = {
      id: session.id,
      actor_type: "member",
      actor_id: session.todo_app_memberuser_id,
      ip: session.ip,
      href: session.href,
      referrer: session.referrer,
      created_at: createdAt,
      expired_at: expiredAt,
    };

    return summary;
  });

  const pages = limit === 0 ? 0 : Math.ceil(total / limit);

  const pagination: IPage.IPagination = {
    current: page satisfies number as number,
    limit: limit satisfies number as number,
    records: total,
    pages,
  };

  return {
    pagination,
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import { IPageITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodo";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { MemberuserPayload } from "../decorators/payload/MemberuserPayload";

export async function patchTodoAppMemberUserTodos(props: {
  memberUser: MemberuserPayload;
  body: ITodoAppTodo.IRequest;
}): Promise<IPageITodoAppTodo.ISummary> {
  const page = props.body.page;
  const limit = props.body.limit;
  const skip = page * limit;

  const whereCondition = {
    todo_app_memberuser_id: props.memberUser.id,
    deleted_at: null,
    ...(props.body.state !== undefined && props.body.state !== null
      ? { state: props.body.state }
      : {}),
    ...(() => {
      if (props.body.search === undefined || props.body.search === null)
        return {};
      return {
        OR: [
          {
            title: {
              contains: props.body.search,
              mode: "insensitive" as Prisma.QueryMode,
            },
          },
          {
            description: {
              contains: props.body.search,
              mode: "insensitive" as Prisma.QueryMode,
            },
          },
        ],
      };
    })(),
    ...(() => {
      if (
        props.body.createdFrom === undefined &&
        props.body.createdTo === undefined
      )
        return {};
      return {
        created_at: {
          ...(props.body.createdFrom !== undefined &&
          props.body.createdFrom !== null
            ? { gte: props.body.createdFrom }
            : {}),
          ...(props.body.createdTo !== undefined &&
          props.body.createdTo !== null
            ? { lte: props.body.createdTo }
            : {}),
        },
      };
    })(),
    ...(() => {
      if (props.body.dueFrom === undefined && props.body.dueTo === undefined)
        return {};
      return {
        due_date: {
          ...(props.body.dueFrom !== undefined && props.body.dueFrom !== null
            ? { gte: props.body.dueFrom }
            : {}),
          ...(props.body.dueTo !== undefined && props.body.dueTo !== null
            ? { lte: props.body.dueTo }
            : {}),
        },
      };
    })(),
    ...(() => {
      if (props.body.completed === undefined || props.body.completed === null)
        return {};
      return props.body.completed
        ? { completed_at: { not: null } }
        : { completed_at: null };
    })(),
  } satisfies Prisma.todo_app_todosWhereInput;

  const [rows, total] = await Promise.all([
    MyGlobal.prisma.todo_app_todos.findMany({
      where: whereCondition,
      skip,
      take: limit,
      orderBy: {
        created_at: "desc",
      },
    }),
    MyGlobal.prisma.todo_app_todos.count({
      where: whereCondition,
    }),
  ]);

  const data: ITodoAppTodo.ISummary[] = rows.map((row) => {
    const dueDateValue =
      row.due_date === null ? null : toISOStringSafe(row.due_date);
    const completedAtValue =
      row.completed_at === null ? null : toISOStringSafe(row.completed_at);

    return {
      id: row.id,
      title: row.title,
      state: row.state,
      due_date: dueDateValue,
      created_at: toISOStringSafe(row.created_at),
      updated_at: toISOStringSafe(row.updated_at),
      completed_at: completedAtValue,
    };
  });

  const pages = limit === 0 ? 0 : Math.ceil(total / limit);

  return {
    pagination: {
      current: page satisfies number as number,
      limit: limit satisfies number as number,
      records: total satisfies number as number,
      pages: pages satisfies number as number,
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import { IPageITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppMemberUser";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminuserPayload } from "../decorators/payload/AdminuserPayload";

export async function patchTodoAppAdminUserMemberUsers(props: {
  adminUser: AdminuserPayload;
  body: ITodoAppMemberUser.IRequest;
}): Promise<IPageITodoAppMemberUser.ISummary> {
  // Pagination parameters with defaults
  const rawPage = props.body.page;
  const rawLimit = props.body.limit;

  const page = rawPage !== undefined && rawPage !== null ? rawPage : 1;
  const limit = rawLimit !== undefined && rawLimit !== null ? rawLimit : 20;

  const safePage = page < 1 ? 1 : page;
  const safeLimit = limit < 1 ? 20 : limit;

  const skip = (safePage - 1) * safeLimit;

  // Build where condition based on filters
  const where = {
    ...(props.body.status !== undefined && props.body.status !== null
      ? { status: props.body.status }
      : {}),
    ...(() => {
      const createdFrom = props.body.created_from;
      const createdTo = props.body.created_to;

      if (createdFrom === undefined && createdTo === undefined) return {};

      return {
        created_at: {
          ...(createdFrom !== undefined && createdFrom !== null
            ? { gte: createdFrom }
            : {}),
          ...(createdTo !== undefined && createdTo !== null
            ? { lte: createdTo }
            : {}),
        },
      };
    })(),
    ...(() => {
      const search = props.body.search;
      if (search === undefined || search === null || search === "") return {};

      return {
        OR: [
          {
            email: {
              contains: search,
              mode: "insensitive" as Prisma.QueryMode,
            },
          },
          {
            display_name: {
              contains: search,
              mode: "insensitive" as Prisma.QueryMode,
            },
          },
        ],
      };
    })(),
  } satisfies Prisma.todo_app_memberusersWhereInput;

  // Determine sorting
  const orderByField = (() => {
    const orderBy = props.body.order_by;
    if (orderBy === "status") return "status" as const;
    if (orderBy === "created_at") return "created_at" as const;
    return "created_at" as const;
  })();

  const orderDirection = (() => {
    const dir = props.body.order_direction;
    if (dir === "asc" || dir === "ASC") return "asc" as const;
    if (dir === "desc" || dir === "DESC") return "desc" as const;
    return "desc" as const;
  })();

  const [rows, total] = await Promise.all([
    MyGlobal.prisma.todo_app_memberusers.findMany({
      where,
      skip,
      take: safeLimit,
      orderBy: {
        [orderByField]: orderDirection,
      },
    }),
    MyGlobal.prisma.todo_app_memberusers.count({
      where,
    }),
  ]);

  const data = rows.map((row) => ({
    id: row.id,
    email: row.email,
    display_name: row.display_name,
    status: row.status,
    created_at: toISOStringSafe(row.created_at),
  }));

  const pagination: IPage.IPagination = {
    current: safePage,
    limit: safeLimit,
    records: total,
    pages: Math.ceil(total / safeLimit),
  };

  return {
    pagination,
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthGuestUserJoin(props: {
  body: ITodoAppGuestUser.IJoinRequest;
}): Promise<ITodoAppGuestUser.IAuthorized> {
  const nowMillis = Date.now();
  const nowIso = toISOStringSafe(new Date(nowMillis));

  const accessTtlMillis = 60 * 60 * 1000; // 1 hour
  const refreshTtlMillis = 7 * 24 * 60 * 60 * 1000; // 7 days

  const accessExpiredAtIso = toISOStringSafe(
    new Date(nowMillis + accessTtlMillis),
  );
  const refreshableUntilIso = toISOStringSafe(
    new Date(nowMillis + refreshTtlMillis),
  );

  const guestId = v4();
  const sessionId = v4();

  try {
    const createdGuest = await MyGlobal.prisma.todo_app_guestusers.create({
      data: {
        id: guestId,
        external_ref:
          props.body.external_ref !== undefined
            ? props.body.external_ref
            : null,
        created_at: nowIso,
        updated_at: nowIso,
      },
    });

    const accessToken = jwt.sign(
      {
        type: "guestUser",
        id: guestId,
        session_id: sessionId,
        created_at: nowIso,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    );

    const refreshToken = jwt.sign(
      {
        type: "guestUser",
        id: guestId,
        session_id: sessionId,
        tokenType: "refresh",
        created_at: nowIso,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    );

    const token: IAuthorizationToken = {
      access: accessToken,
      refresh: refreshToken,
      expired_at: accessExpiredAtIso,
      refreshable_until: refreshableUntilIso,
    };

    const response: ITodoAppGuestUser.IAuthorized = {
      id: createdGuest.id,
      external_ref:
        createdGuest.external_ref !== null ? createdGuest.external_ref : null,
      created_at: toISOStringSafe(createdGuest.created_at),
      updated_at: toISOStringSafe(createdGuest.updated_at),
      accessToken,
      refreshToken,
      token,
    };

    return response;
  } catch (error) {
    // In a real system, we would log `error` with a proper logger
    throw new HttpException("Failed to register guest user", 500);
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthGuestUserRefresh(props: {
  body: ITodoAppGuestUser.IRefreshRequest;
}): Promise<ITodoAppGuestUser.IAuthorized> {
  // 1. Decode and verify the incoming refresh token
  let decoded: unknown;
  try {
    decoded = jwt.verify(props.body.refreshToken, MyGlobal.env.JWT_SECRET_KEY, {
      issuer: "autobe",
    });
  } catch (_error) {
    throw new HttpException("Invalid or expired refresh token", 401);
  }

  // 2. Validate decoded payload shape for guestUser refresh tokens
  if (!decoded || typeof decoded !== "object") {
    throw new HttpException("Invalid token payload", 401);
  }

  const decodedPayload = decoded as {
    id?: string;
    session_id?: string;
    type?: string;
    tokenType?: string;
  };

  if (decodedPayload.type !== "guestUser") {
    throw new HttpException("Invalid token type", 403);
  }

  if (decodedPayload.tokenType && decodedPayload.tokenType !== "refresh") {
    throw new HttpException("Invalid token type", 403);
  }

  if (!decodedPayload.id || !decodedPayload.session_id) {
    throw new HttpException("Invalid token payload", 401);
  }

  const guestId = decodedPayload.id;
  const sessionId = decodedPayload.session_id;

  // 3. Load current guest state from database
  const guest = await MyGlobal.prisma.todo_app_guestusers.findUnique({
    where: {
      id: guestId,
    },
  });

  if (!guest) {
    // Guest record removed or never existed: treat as expired/revoked
    throw new HttpException("Guest session expired or revoked", 401);
  }

  // 4. Prepare new token expiry timestamps as ISO strings (no Date type annotations)
  const nowMillis = Date.now();
  const accessExpiryMillis = nowMillis + 60 * 60 * 1000; // 1 hour
  const refreshExpiryMillis = nowMillis + 7 * 24 * 60 * 60 * 1000; // 7 days

  const accessExpiresAt = toISOStringSafe(new Date(accessExpiryMillis));
  const refreshExpiresAt = toISOStringSafe(new Date(refreshExpiryMillis));

  const createdAtForToken = toISOStringSafe(new Date(nowMillis));

  // 5. Generate new access and refresh JWTs, preserving guest id and session id
  const accessToken = jwt.sign(
    {
      type: decodedPayload.type,
      id: guestId,
      session_id: sessionId,
      created_at: createdAtForToken,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );

  const refreshToken = jwt.sign(
    {
      type: decodedPayload.type,
      id: guestId,
      session_id: sessionId,
      tokenType: "refresh",
      created_at: createdAtForToken,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  // 6. Update guest.updated_at to reflect latest interaction
  const updatedGuest = await MyGlobal.prisma.todo_app_guestusers.update({
    where: {
      id: guest.id,
    },
    data: {
      updated_at: new Date(nowMillis),
    },
  });

  // 7. Build IAuthorizationToken structure
  const token: IAuthorizationToken = {
    access: accessToken,
    refresh: refreshToken,
    expired_at: accessExpiresAt,
    refreshable_until: refreshExpiresAt,
  };

  // 8. Map DB guest record to ITodoAppGuestUser.IAuthorized
  return {
    id: updatedGuest.id,
    external_ref: updatedGuest.external_ref ?? null,
    created_at: toISOStringSafe(updatedGuest.created_at),
    updated_at: toISOStringSafe(updatedGuest.updated_at),
    accessToken,
    refreshToken,
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthMemberUserJoin(props: {
  body: ITodoAppMemberUserJoin.ICreate;
}): Promise<ITodoAppMemberUser.IAuthorized> {
  // 1. Check for duplicate email based on unique index
  const existing = await MyGlobal.prisma.todo_app_memberusers.findUnique({
    where: { email: props.body.email },
  });

  if (existing !== null) {
    throw new HttpException("Email already registered", 409);
  }

  // 2. Prepare timestamps using millisecond arithmetic
  const nowMs = Date.now();
  const accessExpiresMs = nowMs + 60 * 60 * 1000; // +1 hour
  const refreshExpiresMs = nowMs + 7 * 24 * 60 * 60 * 1000; // +7 days

  const nowIso = toISOStringSafe(new Date(nowMs));
  const accessExpiresIso = toISOStringSafe(new Date(accessExpiresMs));
  const refreshExpiresIso = toISOStringSafe(new Date(refreshExpiresMs));

  // 3. Hash password
  const hashedPassword = await PasswordUtil.hash(props.body.password);

  // 4. Create member user and session records inside a try/catch
  try {
    const memberId = v4();

    const createdMember = await MyGlobal.prisma.todo_app_memberusers.create({
      data: {
        id: memberId,
        email: props.body.email,
        password_hash: hashedPassword,
        display_name: props.body.displayName ?? null,
        status: "active",
        created_at: nowIso,
        updated_at: nowIso,
      },
    });

    const sessionId = v4();
    const sessionIp = props.body.ip ?? "";

    const createdSession =
      await MyGlobal.prisma.todo_app_memberuser_sessions.create({
        data: {
          id: sessionId,
          todo_app_memberuser_id: createdMember.id,
          ip: sessionIp,
          href: props.body.href,
          referrer: props.body.referrer,
          created_at: nowIso,
          expired_at: accessExpiresIso,
        },
      });

    // 5. Generate JWT access and refresh tokens
    const accessToken = jwt.sign(
      {
        type: "memberuser",
        id: createdMember.id,
        session_id: createdSession.id,
        created_at: nowIso,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    );

    const refreshToken = jwt.sign(
      {
        type: "memberuser",
        id: createdMember.id,
        session_id: createdSession.id,
        tokenType: "refresh",
        created_at: nowIso,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    );

    const token: IAuthorizationToken = {
      access: accessToken,
      refresh: refreshToken,
      expired_at: accessExpiresIso,
      refreshable_until: refreshExpiresIso,
    };

    // 6. Map database entity to authorized DTO
    const result: ITodoAppMemberUser.IAuthorized = {
      id: createdMember.id,
      email: createdMember.email,
      display_name: createdMember.display_name ?? null,
      status: createdMember.status,
      created_at: toISOStringSafe(createdMember.created_at),
      updated_at: toISOStringSafe(createdMember.updated_at),
      token,
    };

    return result;
  } catch (error) {
    // Handle potential race-condition duplicate email via unique constraint
    if (
      error instanceof Prisma.PrismaClientKnownRequestError &&
      error.code === "P2002"
    ) {
      throw new HttpException("Email already registered", 409);
    }

    throw error;
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthMemberUserLogin(props: {
  body: ITodoAppMemberUserLogin.ICreate;
}): Promise<ITodoAppMemberUser.IAuthorized> {
  // 1. Find member by email
  const member = await MyGlobal.prisma.todo_app_memberusers.findFirst({
    where: {
      email: props.body.email,
    },
  });

  if (!member) {
    // Do not reveal whether email exists
    throw new HttpException("Invalid credentials", 401);
  }

  // 2. Check account status
  if (member.status === "blocked" || member.status === "disabled") {
    // Business rule: blocked/disabled accounts cannot login
    throw new HttpException("Account is not allowed to login", 403);
  }

  // 3. Verify password
  const passwordValid = await PasswordUtil.verify(
    props.body.password,
    member.password_hash,
  );

  if (!passwordValid) {
    throw new HttpException("Invalid credentials", 401);
  }

  // 4. Compute expiry timestamps as ISO strings
  const now = new Date();
  const accessExpires = new Date(now.getTime() + 60 * 60 * 1000);
  const refreshExpires = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);

  const nowIso = toISOStringSafe(now);
  const accessExpiresIso = toISOStringSafe(accessExpires);
  const refreshExpiresIso = toISOStringSafe(refreshExpires);

  // 5. Create new session record with expired_at = null at login time
  const session = await MyGlobal.prisma.todo_app_memberuser_sessions.create({
    data: {
      id: v4(),
      todo_app_memberuser_id: member.id,
      ip:
        props.body.ip !== undefined && props.body.ip !== null
          ? props.body.ip
          : "",
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: nowIso,
      expired_at: null,
    },
  });

  // 6. Generate JWT tokens
  const accessToken = jwt.sign(
    {
      type: "memberuser",
      id: member.id,
      session_id: session.id,
      created_at: nowIso,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );

  const refreshToken = jwt.sign(
    {
      type: "memberuser",
      id: member.id,
      session_id: session.id,
      tokenType: "refresh",
      created_at: nowIso,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  const token: IAuthorizationToken = {
    access: accessToken,
    refresh: refreshToken,
    expired_at: accessExpiresIso,
    refreshable_until: refreshExpiresIso,
  };

  // 7. Build response DTO, mapping DB fields to API contract
  return {
    id: member.id,
    email: member.email,
    display_name:
      member.display_name !== null && member.display_name !== undefined
        ? member.display_name
        : undefined,
    status: member.status,
    created_at: toISOStringSafe(member.created_at),
    updated_at: toISOStringSafe(member.updated_at),
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppMemberUserRefresh } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserRefresh";
import { ITodoAppMemberUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthMemberUserRefresh(props: {
  body: ITodoAppMemberUserRefresh.ICreate;
}): Promise<ITodoAppMemberUser.IAuthorized> {
  // Step 1: verify and decode refresh token
  let decoded: any;

  try {
    decoded = jwt.verify(
      props.body.refresh_token,
      MyGlobal.env.JWT_SECRET_KEY,
      {
        issuer: "autobe",
      },
    );
  } catch (_error) {
    throw new HttpException("Invalid or expired refresh token", 401);
  }

  // Ensure token has expected shape and actor type
  const decodedId = decoded && decoded.id;
  const decodedSessionId = decoded && decoded.session_id;
  const decodedType = decoded && decoded.type;

  if (typeof decodedId !== "string" || typeof decodedSessionId !== "string") {
    throw new HttpException("Malformed refresh token payload", 401);
  }

  if (decodedType !== "memberuser") {
    throw new HttpException("Invalid token type", 403);
  }

  // Step 2: load member user from DB
  const member = await MyGlobal.prisma.todo_app_memberusers.findUnique({
    where: {
      id: decodedId,
    },
  });

  if (!member) {
    throw new HttpException("Member not found for refresh token", 401);
  }

  // Enforce acceptable status (only "active" is allowed)
  if (member.status !== "active") {
    throw new HttpException("Account status does not allow refresh", 403);
  }

  // Step 3: determine and validate session id
  const effectiveSessionId =
    props.body.session_id !== undefined
      ? props.body.session_id
      : decodedSessionId;

  if (effectiveSessionId !== decodedSessionId) {
    throw new HttpException("Session mismatch for refresh token", 401);
  }

  // Step 4: load session and validate it is active
  const session = await MyGlobal.prisma.todo_app_memberuser_sessions.findFirst({
    where: {
      id: effectiveSessionId,
      todo_app_memberuser_id: decodedId,
    },
  });

  if (!session) {
    throw new HttpException("Session expired or revoked", 401);
  }

  const nowMs = Date.now();
  if (session.expired_at !== null) {
    const expiredAtMs = session.expired_at.getTime();
    if (expiredAtMs <= nowMs) {
      throw new HttpException("Session has been expired", 401);
    }
  }

  // Step 5: generate new access and refresh tokens using same session
  const accessExpiresMs = nowMs + 60 * 60 * 1000; // 1 hour
  const refreshExpiresMs = nowMs + 7 * 24 * 60 * 60 * 1000; // 7 days

  const accessExpiresIso = toISOStringSafe(new Date(accessExpiresMs));
  const refreshExpiresIso = toISOStringSafe(new Date(refreshExpiresMs));

  const accessToken = jwt.sign(
    {
      type: decodedType,
      id: decodedId,
      session_id: decodedSessionId,
      created_at: toISOStringSafe(new Date()),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );

  const refreshToken = jwt.sign(
    {
      type: decodedType,
      id: decodedId,
      session_id: decodedSessionId,
      tokenType: "refresh",
      created_at: toISOStringSafe(new Date()),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  // Step 6: update session expiration and metadata
  await MyGlobal.prisma.todo_app_memberuser_sessions.update({
    where: {
      id: decodedSessionId,
    },
    data: {
      expired_at: new Date(refreshExpiresMs),
      ...(props.body.ip !== undefined && {
        ip: props.body.ip,
      }),
      ...(props.body.href !== undefined && {
        href: props.body.href,
      }),
      ...(props.body.referrer !== undefined && {
        referrer: props.body.referrer,
      }),
    },
  });

  // Step 7: build response DTO
  return {
    id: member.id,
    email: member.email,
    display_name: member.display_name === null ? null : member.display_name,
    status: member.status,
    created_at: toISOStringSafe(member.created_at),
    updated_at: toISOStringSafe(member.updated_at),
    token: {
      access: accessToken,
      refresh: refreshToken,
      expired_at: accessExpiresIso,
      refreshable_until: refreshExpiresIso,
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthAdminUserJoin(props: {
  body: ITodoAppAdminUser.IJoin;
}): Promise<ITodoAppAdminUser.IAuthorized> {
  const { body } = props;

  // 1. Check for duplicate email
  const existingAdmin = await MyGlobal.prisma.todo_app_adminusers.findFirst({
    where: {
      email: body.email,
    },
  });

  if (existingAdmin) {
    throw new HttpException("Admin email already registered", 409);
  }

  // 2. Hash password
  const passwordHash = await PasswordUtil.hash(body.password);

  // 3. Compute current timestamp and token expiry timestamps as ISO strings
  const now = toISOStringSafe(new Date());

  const accessExpiryDate = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpiryDate = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
  const accessExpiredAt = toISOStringSafe(accessExpiryDate);
  const refreshableUntil = toISOStringSafe(refreshExpiryDate);

  // 4. Create admin user and session within a single transaction callback
  const { adminUser, adminSession } = await MyGlobal.prisma.$transaction(
    async (tx) => {
      const createdAdminUser = await tx.todo_app_adminusers.create({
        data: {
          id: v4(),
          email: body.email,
          password_hash: passwordHash,
          display_name:
            body.display_name === undefined ? undefined : body.display_name,
          status: body.status,
          created_at: now,
          updated_at: now,
        },
      });

      const createdAdminSession = await tx.todo_app_adminuser_sessions.create({
        data: {
          id: v4(),
          todo_app_adminuser_id: createdAdminUser.id,
          ip: body.ip,
          href: body.href,
          referrer: body.referrer,
          created_at: now,
          expired_at: null,
        },
      });

      return {
        adminUser: createdAdminUser,
        adminSession: createdAdminSession,
      };
    },
  );

  // 5. Generate JWT tokens for the newly created admin user and session
  const tokenCreatedAt = toISOStringSafe(new Date());

  const accessToken = jwt.sign(
    {
      type: "adminUser",
      id: adminUser.id,
      session_id: adminSession.id,
      created_at: tokenCreatedAt,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );

  const refreshToken = jwt.sign(
    {
      type: "adminUser",
      id: adminUser.id,
      session_id: adminSession.id,
      tokenType: "refresh",
      created_at: tokenCreatedAt,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  const token: IAuthorizationToken = {
    access: accessToken,
    refresh: refreshToken,
    expired_at: accessExpiredAt,
    refreshable_until: refreshableUntil,
  };

  // 6. Build response conforming to ITodoAppAdminUser.IAuthorized
  return {
    id: adminUser.id,
    email: adminUser.email,
    display_name:
      adminUser.display_name === undefined ? undefined : adminUser.display_name,
    status: adminUser.status,
    created_at: toISOStringSafe(adminUser.created_at),
    updated_at: toISOStringSafe(adminUser.updated_at),
    token,
  };
}

