export async function postAuthAdminUserLogin(props: {
  body: ITodoAppAdminUser.ILogin;
}): Promise<ITodoAppAdminUser.IAuthorized> {
  const email = props.body.email;

  const admin = await MyGlobal.prisma.todo_app_adminusers.findFirst({
    where: { email },
  });

  if (!admin) {
    throw new HttpException("Invalid credentials", 401);
  }

  if (admin.status !== "active") {
    throw new HttpException("Invalid credentials", 401);
  }

  const passwordValid = await PasswordUtil.verify(
    props.body.password,
    admin.password_hash,
  );

  if (!passwordValid) {
    throw new HttpException("Invalid credentials", 401);
  }

  const nowMs = Date.now();
  const accessExpireMs = nowMs + 60 * 60 * 1000;
  const refreshExpireMs = nowMs + 7 * 24 * 60 * 60 * 1000;

  const createdAtIso = toISOStringSafe(new Date(nowMs));
  const accessExpiredAtIso = toISOStringSafe(new Date(accessExpireMs));
  const refreshExpiredAtIso = toISOStringSafe(new Date(refreshExpireMs));

  const ipValue =
    props.body.ip !== undefined && props.body.ip !== null ? props.body.ip : "";

  const session = await MyGlobal.prisma.todo_app_adminuser_sessions.create({
    data: {
      id: v4(),
      todo_app_adminuser_id: admin.id,
      ip: ipValue,
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: createdAtIso,
      expired_at: null,
    },
  });

  const accessToken = jwt.sign(
    {
      type: "adminUser",
      id: admin.id,
      session_id: session.id,
      created_at: createdAtIso,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );

  const refreshToken = jwt.sign(
    {
      type: "adminUser",
      id: admin.id,
      session_id: session.id,
      tokenType: "refresh",
      created_at: createdAtIso,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  const token: IAuthorizationToken = {
    access: accessToken,
    refresh: refreshToken,
    expired_at: accessExpiredAtIso,
    refreshable_until: refreshExpiredAtIso,
  };

  const createdAtAdminIso = toISOStringSafe(admin.created_at);
  const updatedAtAdminIso = toISOStringSafe(admin.updated_at);

  return {
    id: admin.id,
    email: admin.email,
    display_name: admin.display_name === null ? null : admin.display_name,
    status: admin.status,
    created_at: createdAtAdminIso,
    updated_at: updatedAtAdminIso,
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthAdminUserRefresh(props: {
  body: ITodoAppAdminUser.IRefresh;
}): Promise<ITodoAppAdminUser.IAuthorized> {
  const verified = jwt.verify(
    props.body.refresh_token,
    MyGlobal.env.JWT_SECRET_KEY,
    {
      issuer: "autobe",
    },
  );

  const decoded: {
    id: string;
    session_id: string;
    type: string;
  } = verified as {
    id: string;
    session_id: string;
    type: string;
  };

  if (decoded.type !== "adminUser") {
    throw new HttpException("Invalid token type", 403);
  }

  const session = await MyGlobal.prisma.todo_app_adminuser_sessions.findFirst({
    where: {
      id: decoded.session_id,
      todo_app_adminuser_id: decoded.id,
    },
    include: {
      adminUser: true,
    },
  });

  if (!session || !session.adminUser) {
    throw new HttpException("Session expired or revoked", 401);
  }

  if (session.expired_at !== null) {
    const nowMillis = Date.now();
    const expiredMillis = session.expired_at.getTime();
    if (expiredMillis <= nowMillis) {
      throw new HttpException("Session expired or revoked", 401);
    }
  }

  const admin = session.adminUser;

  if (admin.status !== "active") {
    throw new HttpException("Administrative account is not active", 403);
  }

  const nowMillis = Date.now();
  const accessExpiresMillis = nowMillis + 60 * 60 * 1000;
  const refreshExpiresMillis = nowMillis + 7 * 24 * 60 * 60 * 1000;

  const nowIso: string & tags.Format<"date-time"> = toISOStringSafe(
    new Date(nowMillis),
  );
  const accessExpiresIso: string & tags.Format<"date-time"> = toISOStringSafe(
    new Date(accessExpiresMillis),
  );
  const refreshExpiresIso: string & tags.Format<"date-time"> = toISOStringSafe(
    new Date(refreshExpiresMillis),
  );

  const accessToken = jwt.sign(
    {
      type: decoded.type,
      id: decoded.id,
      session_id: decoded.session_id,
      created_at: nowIso,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );

  const refreshToken = jwt.sign(
    {
      type: decoded.type,
      id: decoded.id,
      session_id: decoded.session_id,
      tokenType: "refresh",
      created_at: nowIso,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  await MyGlobal.prisma.todo_app_adminuser_sessions.update({
    where: {
      id: decoded.session_id,
    },
    data: {
      expired_at: new Date(refreshExpiresMillis),
    },
  });

  return {
    id: admin.id,
    email: admin.email,
    display_name: admin.display_name,
    status: admin.status,
    created_at: toISOStringSafe(admin.created_at),
    updated_at: toISOStringSafe(admin.updated_at),
    token: {
      access: accessToken,
      refresh: refreshToken,
      expired_at: accessExpiresIso,
      refreshable_until: refreshExpiresIso,
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemSetting";
import { IPageITodoAppSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppSystemSetting";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminuserPayload } from "../decorators/payload/AdminuserPayload";

export async function patchTodoAppAdminUserSystemSettings(props: {
  adminUser: AdminuserPayload;
  body: ITodoAppSystemSetting.IRequest;
}): Promise<IPageITodoAppSystemSetting.ISummary> {
  const body = props.body;

  // Pagination with sensible defaults and upper bounds
  const maxPageSize = 100;

  const rawPage = body.page === undefined ? 1 : body.page;
  const rawPageSize = body.pageSize === undefined ? 50 : body.pageSize;

  const page = rawPage < 1 ? 1 : rawPage;
  const pageSize =
    rawPageSize < 1 ? 1 : rawPageSize > maxPageSize ? maxPageSize : rawPageSize;

  const skip = (page - 1) * pageSize;
  const take = pageSize;

  // Base where: exclude soft-deleted settings
  const whereBase: Prisma.todo_app_system_settingsWhereInput = {
    deleted_at: null,
  };

  // Key filter (partial match when non-empty string provided)
  const whereKey: Prisma.todo_app_system_settingsWhereInput =
    body.key !== undefined && body.key !== ""
      ? { key: { contains: body.key } }
      : {};

  // Group filter (exact match when non-empty string provided)
  const whereGroup: Prisma.todo_app_system_settingsWhereInput =
    body.group !== undefined && body.group !== "" ? { group: body.group } : {};

  // Enabled tri-state filter
  const whereEnabled: Prisma.todo_app_system_settingsWhereInput =
    body.enabled !== undefined && body.enabled !== null
      ? { enabled: body.enabled }
      : {};

  // Created_at range filter
  let whereCreatedAt: Prisma.todo_app_system_settingsWhereInput = {};
  if (body.createdFrom !== undefined || body.createdTo !== undefined) {
    const createdRange: { gte?: string; lte?: string } = {};
    if (body.createdFrom !== undefined) createdRange.gte = body.createdFrom;
    if (body.createdTo !== undefined) createdRange.lte = body.createdTo;
    whereCreatedAt = { created_at: createdRange };
  }

  // Updated_at range filter
  let whereUpdatedAt: Prisma.todo_app_system_settingsWhereInput = {};
  if (body.updatedFrom !== undefined || body.updatedTo !== undefined) {
    const updatedRange: { gte?: string; lte?: string } = {};
    if (body.updatedFrom !== undefined) updatedRange.gte = body.updatedFrom;
    if (body.updatedTo !== undefined) updatedRange.lte = body.updatedTo;
    whereUpdatedAt = { updated_at: updatedRange };
  }

  const where: Prisma.todo_app_system_settingsWhereInput = {
    ...whereBase,
    ...whereKey,
    ...whereGroup,
    ...whereEnabled,
    ...whereCreatedAt,
    ...whereUpdatedAt,
  };

  // Sorting: whitelist allowed fields, default to updated_at desc
  const sortBy = body.sortBy === undefined ? "updated_at" : body.sortBy;
  const sortDirection =
    body.sortDirection === undefined ? "desc" : body.sortDirection;

  const direction: Prisma.SortOrder = sortDirection === "asc" ? "asc" : "desc";

  let orderBy: Prisma.todo_app_system_settingsOrderByWithRelationInput;
  if (
    sortBy === "key" ||
    sortBy === "group" ||
    sortBy === "enabled" ||
    sortBy === "created_at" ||
    sortBy === "updated_at"
  ) {
    orderBy = { [sortBy]: direction };
  } else {
    // Fallback ordering when unsupported sort field requested
    orderBy = { updated_at: "desc" };
  }

  const [rows, totalCount] = await Promise.all([
    MyGlobal.prisma.todo_app_system_settings.findMany({
      where,
      orderBy,
      skip,
      take,
    }),
    MyGlobal.prisma.todo_app_system_settings.count({
      where,
    }),
  ]);

  const data: ITodoAppSystemSetting.ISummary[] = rows.map((row) => {
    const summary: ITodoAppSystemSetting.ISummary = {
      id: row.id,
      key: row.key,
      value: row.value,
      type: row.type,
      enabled: row.enabled,
    };

    // Optional nullable metadata fields
    if (row.description !== null) {
      summary.description = row.description;
    } else {
      summary.description = null;
    }

    if (row.group !== null) {
      summary.group = row.group;
    } else {
      summary.group = null;
    }

    return summary;
  });

  const pagination: IPage.IPagination = {
    current: page,
    limit: pageSize,
    records: totalCount,
    pages: pageSize === 0 ? 0 : Math.ceil(totalCount / pageSize),
  };

  return {
    pagination,
    data,
  };
}

